loadstring(game:HttpGet("https://raw.githubusercontent.com/ook314745-svg/INTRO_ANIME2/refs/heads/main/raw_video_intro_modified.txt"))()


local function _r(n)
    local c="abcdefghijklmnopqrstuvwxyz"; local s=""
    for i=1,n do local x=math.random(1,26); s=s..c:sub(x,x) end
    return s
end
local _AV_ATT_NM = _r(2)   
local _AV_NM     = _r(2)   


local _hCache = setmetatable({}, {__mode="k"})
local _vCache = setmetatable({}, {__mode="k"})

local function _destroyH(part)
    local c = _hCache[part]
    if c then
        pcall(function() if c[1] and c[1].Parent then c[1]:Destroy() end end)
        pcall(function() if c[2] and c[2].Parent then c[2]:Destroy() end end)
        _hCache[part] = nil
    end
end

local function _destroyV(part)
    local c = _vCache[part]
    if c then
        pcall(function() if c[1] and c[1].Parent then c[1]:Destroy() end end)
        pcall(function() if c[2] and c[2].Parent then c[2]:Destroy() end end)
        _vCache[part] = nil
    end
end

local function _destroyLV(part)
    _destroyH(part)
    _destroyV(part)
end

local _yCache = setmetatable({}, {__mode="k"})
local function _destroyYV(part)
    local c = _yCache[part]
    if c then
        pcall(function() if c[1] and c[1].Parent then c[1]:Destroy() end end)
        pcall(function() if c[2] and c[2].Parent then c[2]:Destroy() end end)
        _yCache[part] = nil
    end
end
local function _setYV(part, ySpeed)
    if not part or not part.Parent then return end
    local c = _yCache[part]
    local lv = c and c[1]
    if lv and lv.Parent == part then lv.LineVelocity = ySpeed; return end
    _destroyYV(part)
    local att = Instance.new("Attachment"); att.Name = _AV_ATT_NM; att.Parent = part
    lv = Instance.new("LinearVelocity")
    lv.Name = _AV_NM
    lv.Attachment0 = att
    lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Line
    lv.LineDirection = Vector3.new(0, 1, 0)
    lv.LineVelocity = ySpeed
    lv.MaxForce = math.huge
    lv.RelativeTo = Enum.ActuatorRelativeTo.World
    lv.Parent = part
    _yCache[part] = {lv, att}
end

local function _getHLV(part)
    local c = _hCache[part]
    local lv = c and c[1]
    if lv and lv.Parent == part then return lv end
    _destroyH(part)
    local att = Instance.new("Attachment"); att.Name = _AV_ATT_NM; att.Parent = part
    lv = Instance.new("LinearVelocity")
    lv.Name                   = _AV_NM
    lv.Attachment0            = att
    lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
    lv.PrimaryTangentAxis     = Vector3.new(1, 0, 0)
    lv.SecondaryTangentAxis   = Vector3.new(0, 0, 1)
    lv.MaxForce               = math.huge
    lv.RelativeTo             = Enum.ActuatorRelativeTo.World
    lv.PlaneVelocity          = Vector2.zero
    lv.Parent                 = part
    _hCache[part]             = {lv, att}
    return lv
end

local function _getVLV(part)
    local c = _vCache[part]
    local lv = c and c[1]
    if lv and lv.Parent == part then return lv end
    _destroyV(part)
    local att = Instance.new("Attachment"); att.Name = _AV_ATT_NM; att.Parent = part
    lv = Instance.new("LinearVelocity")
    lv.Name                   = _AV_NM
    lv.Attachment0            = att
    lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
    lv.MaxForce               = math.huge
    lv.RelativeTo             = Enum.ActuatorRelativeTo.World
    lv.VectorVelocity         = Vector3.zero
    lv.Parent                 = part
    _vCache[part]             = {lv, att}
    return lv
end

local function _setV(part, vec)
    if not part or not part.Parent then return end
    if vec.Magnitude < 0.01 then
        _destroyLV(part)
        return
    end
    if math.abs(vec.Y) < 0.01 then
        local ch = _hCache[part]
        local lh = ch and ch[1]
        if lh and lh.Parent == part then
            lh.PlaneVelocity = Vector2.new(vec.X, vec.Z)
            return
        end
        _destroyV(part)
        local lv = _getHLV(part)
        lv.PlaneVelocity = Vector2.new(vec.X, vec.Z)
    else
        local cv = _vCache[part]
        local lv2 = cv and cv[1]
        if lv2 and lv2.Parent == part then
            lv2.VectorVelocity = vec
            return
        end
        _destroyH(part)
        local lv = _getVLV(part)
        lv.VectorVelocity = vec
    end
end

local function _getV(part)
    if not part or not part.Parent then return Vector3.zero end
    return part.AssemblyLinearVelocity
end

task.spawn(function()
local Players = game:GetService("Players")

local LocalPlayer = Players.LocalPlayer

local Beams = {}

local function getRoot(character)
    return character and character:FindFirstChild("HumanoidRootPart")
end

local function createAttachment(parent, name, position)
    local att = Instance.new("Attachment")
    att.Name = name
    att.Position = position or Vector3.zero
    att.Parent = parent
    return att
end

local function removeBeam(player)
    if Beams[player] then
        for _, obj in pairs(Beams[player]) do
            if obj then
                obj:Destroy()
            end
        end
        Beams[player] = nil
    end
end

local function createBeam(player)
    if player == LocalPlayer then return end
    
    removeBeam(player)

    local myChar = LocalPlayer.Character
    local targetChar = player.Character

    local myRoot = getRoot(myChar)
    local targetRoot = getRoot(targetChar)

    if not myRoot or not targetRoot then return end

    local start = createAttachment(myRoot, "BodyBeamStart", Vector3.new(0, -0.5, 0))
    local finish = createAttachment(targetRoot, "PlayerBeamEnd")

    local beam = Instance.new("Beam")
    beam.Name = "PurplePlayerBeam"
    beam.Attachment0 = start
    beam.Attachment1 = finish

    beam.Color = ColorSequence.new(Color3.fromRGB(255, 109, 25))
    beam.Transparency = NumberSequence.new(0.45)
    beam.Width0 = 0.12
    beam.Width1 = 0.12
    beam.FaceCamera = true

    beam.Parent = myRoot

    Beams[player] = {
        beam,
        start,
        finish
    }
end

local function setupPlayer(player)
    if player == LocalPlayer then return end

    player.CharacterAdded:Connect(function()
        task.wait(1)
        createBeam(player)
    end)

    if player.Character then
        task.wait(1)
        createBeam(player)
    end
end

LocalPlayer.CharacterAdded:Connect(function()
    task.wait(1)

    for player in pairs(Beams) do
        createBeam(player)
    end
end)

Players.PlayerAdded:Connect(setupPlayer)

Players.PlayerRemoving:Connect(function(player)
    removeBeam(player)
end)

for _, player in ipairs(Players:GetPlayers()) do
    setupPlayer(player)
end
end)

do
    local ir_Players    = game:GetService("Players")
