    local function ir_StopReset()
        ir_stopFlag = true
        if ir_thread then pcall(function() task.cancel(ir_thread) end) ir_thread = nil end
        ir_cooldown = false
        ir_currentCh = nil
        _G.FRHUB_INSTA_RESET_ACTIVE = false
        local c = ir_lp.Character
        if c then
            local h = c:FindFirstChildOfClass("Humanoid")
            if h then
                pcall(function()
                    h.HipHeight = 2
