                    if r then r.CanCollide = true end
                    for _, p in ipairs(c:GetChildren()) do
                        if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" then p.CanCollide = true end
                    end
                end)
            end
        end
    end
    _G.FRHUB_INSTA_RESET_TOGGLE = function()
        if ir_cooldown then return end
        ir_cooldown = true
        ir_stopFlag = false
        local character = ir_lp.Character
        if not character then ir_cooldown = false return end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid then ir_cooldown = false return end
