            MobileButtons.Buttons.instaReset(true)
        end
        ir_thread = task.spawn(function()
            local attempts = 0
            local maxAttempts = 40
            local isRespawning = false
            while character and character.Parent and humanoid and humanoid.Health > 0 and not isRespawning and not ir_stopFlag do
                if ir_lp.Character ~= character then isRespawning = true break end
                pcall(function()
                    humanoid.HipHeight = 1e30
                    humanoid.AutoRotate = true
                    local rootPart = character:FindFirstChild("HumanoidRootPart")
                    if rootPart then rootPart.CanCollide = false end
                    for _, part in ipairs(character:GetChildren()) do
                        if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" then
                            part.CanCollide = false
                        end
                    end
                end)
                if not character or not character.Parent or not humanoid or humanoid.Health <= 0 or ir_lp.Character ~= character then
                    break
                end
                attempts = attempts + 1
                if attempts >= maxAttempts then break end
                task.wait(0.05)
            end
            if character and character.Parent and humanoid and humanoid.Health > 0 and not isRespawning then
                pcall(function() humanoid.Health = 0 end)
