task.spawn(function() pcall(function()
local Players      = game:GetService("Players")
local RunService   = game:GetService("RunService")
local UIS         = game:GetService("UserInputService")
local LP          = Players.LocalPlayer

local AIMBOT_V5_CFG = { speed = 50, keybind = "V" }
local v5Enabled     = false
local v5Target      = nil
local v5TargetPlr   = nil
local v5Conn        = nil
local v5TpConn      = nil
local v5GuardConn   = nil
local v5SwingCD     = false
local v5Equipped    = false

local TARGET_PARTS  = {"HumanoidRootPart","Torso","UpperTorso","Head","LowerTorso"}

local function getHRP(c) return c and c:FindFirstChild("HumanoidRootPart") end
local function getHum(c) return c and c:FindFirstChildOfClass("Humanoid") end

local function findV5Bat()
    local char = LP.Character
    if not char then return nil end
    for _, t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") and (t.Name:lower():find("bat") or t.Name:lower():find("slap")) then return t end
    end
    local bp = LP:FindFirstChildOfClass("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") and (t.Name:lower():find("bat") or t.Name:lower():find("slap")) then return t end
        end
    end
    return nil
end

local function equipV5Bat()
    if v5Equipped then return end
    v5Equipped = true
    local char = LP.Character; local hum = getHum(char)
    if not char or not hum then return end
    if char:FindFirstChildOfClass("Tool") then return end
    local bat = findV5Bat()
    if bat then pcall(function() hum:EquipTool(bat) end) end
end

local function getV5Speed()
    local st = _G.FRHUB_STATE
    if st and (st.laggerCarryActive or st.laggerActive) then
        return _G.AIMBOT_V3_LAGGER_SPEED or 40
    end
    return _G.AIMBOT_V3_SPEED or AIMBOT_V5_CFG.speed
end

local function findV5Target(myHRP)
    local bestHRP, bestPart, bestPlr = nil, nil, nil
    local bestD = math.huge
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local eh  = getHRP(p.Character)
            local hum = getHum(p.Character)
            if eh and hum and hum.Health > 0 then
                local d = (eh.Position - myHRP.Position).Magnitude
                if d < bestD then
                    bestD = d; bestHRP = eh; bestPlr = p
                    local cp, cd = eh, d
                    for _, pn in ipairs(TARGET_PARTS) do
                        local part = p.Character:FindFirstChild(pn)
                        if part and part:IsA("BasePart") then
                            local pd = (part.Position - myHRP.Position).Magnitude
                            if pd < cd then cd = pd; cp = part end
                        end
                    end
                    bestPart = cp
                end
            end
        end
    end
    return bestHRP, bestPart, bestPlr, bestD
end

local _mtTracked = nil; local _mtPrevY = nil; local _mtLast = 0
local function updateMirrorTPDown(target)
    if not target then _mtTracked = nil; _mtPrevY = nil; return end
    if _mtTracked ~= target then _mtTracked = target; _mtPrevY = target.Position.Y; return end
    local y = target.Position.Y; local drop = _mtPrevY - y; _mtPrevY = y
    local tVelY = target.Velocity.Y
    if drop > 20 or (drop > 8 and tVelY < -80) then
        _mtLast = tick()
        local myChar = LP.Character; local myRoot = myChar and getHRP(myChar)
        if myRoot then
            local _, yaw = myRoot.CFrame:ToEulerAnglesYXZ()
            myRoot.CFrame = CFrame.new(myRoot.Position.X, -7.00, myRoot.Position.Z) * CFrame.Angles(0, yaw, 0)
            myRoot.Velocity = Vector3.zero
        end
    end
end

local function executeTPCounterV5()
    local char = LP.Character; local hrp = getHRP(char)
    if not hrp then return end
    local filter = {}
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr.Character then table.insert(filter, plr.Character) end
    end
    local rp = RaycastParams.new()
    rp.FilterDescendantsInstances = filter
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.IgnoreWater = false
    local rr = workspace:Raycast(hrp.Position, Vector3.new(0, -1000, 0), rp)
    if rr then
        hrp.Velocity = Vector3.zero
        hrp.AssemblyAngularVelocity = Vector3.zero
        hrp.CFrame = CFrame.new(rr.Position + Vector3.new(0, 3, 0))
    end
end

local function startV5()
    if v5Conn     then v5Conn:Disconnect();     v5Conn = nil end
    if v5TpConn   then v5TpConn:Disconnect();   v5TpConn = nil end
    if v5GuardConn then v5GuardConn:Disconnect(); v5GuardConn = nil end

    v5TpConn = RunService.Heartbeat:Connect(function()
        if not v5Enabled then return end
        if not v5Target then return end
        updateMirrorTPDown(v5Target)
        if tick() < _mtLast + 0.43 and tick() > _mtLast - 0.05 then
            executeTPCounterV5()
        end
    end)

    v5Conn = RunService.RenderStepped:Connect(function()
        if not v5Enabled then return end
        local char = LP.Character; local hum = getHum(char); local root = getHRP(char)
        if not root or not hum then return end

        equipV5Bat()

        local target, part, plr, dist = findV5Target(root)
        if not target then
            v5Target = nil; v5TargetPlr = nil
            hum.AutoRotate = true
            root.AssemblyAngularVelocity = Vector3.zero
            root.Velocity = Vector3.new(0, root.Velocity.Y, 0)
            return
        end
        v5Target = target; v5TargetPlr = plr

        hum.AutoRotate = false

        local myPos = root.Position
        local aimPart = part or target
        local targetPos = aimPart.Position
        local targetVel = aimPart.Velocity
        local predictPos = targetPos + targetVel*0.14 + target.CFrame.LookVector*0.3
        local direction  = predictPos - myPos
        if direction.Magnitude < 0.01 then return end
        local flatDir = Vector3.new(direction.X, 0, direction.Z)
        if flatDir.Magnitude < 0.01 then return end
        flatDir = flatDir.Unit

        local chaseSpeed = getV5Speed()
        local desiredHeight = targetPos.Y + 3.7
        local yVel = (desiredHeight - myPos.Y)*19.5 + targetVel.Y*0.8
        if hum.FloorMaterial ~= Enum.Material.Air then yVel = math.max(yVel, 13) end
        yVel = math.clamp(yVel, -70, 110)

        local cur = root.Velocity
        local desired = Vector3.new(flatDir.X*chaseSpeed, yVel, flatDir.Z*chaseSpeed)
        root.Velocity = cur:Lerp(desired, 0.8)

        local predictTime = math.clamp(targetVel.Magnitude/150, 0.05, 0.2)
        local predictedPos = targetPos + targetVel*predictTime
        local toPredict = predictedPos - myPos
        if toPredict.Magnitude > 0.1 then
            local goalCF = CFrame.lookAt(myPos, Vector3.new(predictedPos.X, predictedPos.Y, predictedPos.Z))
            local diffCF = root.CFrame:Inverse() * goalCF
            local rx, ry, rz = diffCF:ToEulerAnglesXYZ()
            rx = math.clamp(rx, -2.5, 2.5)
            ry = math.clamp(ry, -2.5, 2.5)
            rz = math.clamp(rz, -2.5, 2.5)
            root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(rx*42, ry*42, rz*42))
        end

        local autoSwing = false
        pcall(function()
            local st = _G.FRHUB_STATE
            if st and st.autoBatToggled then autoSwing = true end
        end)
        local bat = char:FindFirstChildOfClass("Tool") or findV5Bat()
        if (autoSwing or autoSwingV3Enabled) and bat and not v5SwingCD and dist <= 7 then
            v5SwingCD = true
            pcall(function()
                bat:Activate()
                local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
                if ev then ev:FireServer() end
            end)
            task.delay(0.08, function() v5SwingCD = false end)
        end
    end)

    v5GuardConn = RunService.RenderStepped:Connect(function()
        if not v5Enabled then return end
        local char = LP.Character; local root = getHRP(char)
        if not root then return end
        local v = root.Velocity
        if math.abs(v.X) > 350 or math.abs(v.Z) > 350 then
            root.Velocity = Vector3.new(0, v.Y, 0)
        end
    end)
end

local function stopV5()
    if v5Conn      then v5Conn:Disconnect();      v5Conn = nil end
    if v5TpConn    then v5TpConn:Disconnect();    v5TpConn = nil end
    if v5GuardConn then v5GuardConn:Disconnect(); v5GuardConn = nil end
end

local function restoreWalkAfterAimbot()
    local char = LP.Character; local myHRP = getHRP(char); local hum = getHum(char)
    if myHRP then
        pcall(function()
            myHRP.Velocity = Vector3.zero
            myHRP.AssemblyAngularVelocity = Vector3.zero
        end)
        pcall(function()
            for _, obj in ipairs(myHRP:GetChildren()) do
                if (obj:IsA("LinearVelocity") or obj:IsA("BodyVelocity")
                or obj:IsA("BodyAngularVelocity") or obj:IsA("BodyPosition") or obj:IsA("BodyGyro")
                or obj:IsA("AngularVelocity")) and not (obj.Name and string.sub(obj.Name, 1, 5) == "FRHUB") then
                    obj:Destroy()
                end
            end
        end)
        pcall(function()
            local pos = myHRP.Position
            local look = myHRP.CFrame.LookVector
            local flat = Vector3.new(look.X, 0, look.Z)
            if flat.Magnitude < 0.05 then flat = Vector3.new(0, 0, -1) else flat = flat.Unit end
            myHRP.CFrame = CFrame.lookAt(pos, pos + flat)
        end)
    end
    if hum then
        hum.AutoRotate = true
        hum.PlatformStand = false
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
    end
    local animate = char and char:FindFirstChild("Animate")
    if animate then
        pcall(function() animate.Disabled = true end)
        task.delay(0.05, function()
            local c = LP.Character
            if not c then return end
            local a = c:FindFirstChild("Animate")
            if a then pcall(function() a.Disabled = false end) end
            local h2 = getHum(c)
            if h2 and h2.Parent then
                pcall(function()
                    h2.PlatformStand = false
                    h2.AutoRotate = true
                    h2:ChangeState(Enum.HumanoidStateType.Landed)
                    h2:ChangeState(Enum.HumanoidStateType.Running)
                end)
            end
        end)
    end
end

local function enableV5()
    if _G.FRHUBSafeModeIsLocked and _G.FRHUBSafeModeIsLocked() then return end
    if _G.FRHUB_BYPASS_AIMBOT and _G.FRHUB_BYPASS_AIMBOT.enabled() then
        pcall(_G.FRHUB_BYPASS_AIMBOT.disable)
    end
    v5Enabled = true
    _G.FRHUB_AIMBOT_V4_ACTIVE = true
    v5Equipped = false
    _mtTracked = nil; _mtPrevY = nil; _mtLast = 0
    local char = LP.Character; local myHRP = getHRP(char); local hum = getHum(char)
    if myHRP then
        pcall(function()
            for _, obj in ipairs(myHRP:GetChildren()) do
                if (obj:IsA("LinearVelocity") or obj:IsA("BodyVelocity")
                or obj:IsA("BodyAngularVelocity") or obj:IsA("BodyPosition") or obj:IsA("BodyGyro")
                or obj:IsA("AngularVelocity")) and not (obj.Name and string.sub(obj.Name, 1, 5) == "FRHUB") then
                    obj:Destroy()
                end
            end
        end)
        myHRP.Velocity = Vector3.zero
        myHRP.AssemblyAngularVelocity = Vector3.zero
    end
    if hum then
        hum.AutoRotate = false
        pcall(function() hum:Move(Vector3.zero, false) end)
    end
    pcall(function()
        if _G.FRHUB_STATE then _G.FRHUB_STATE.lastMoveDir = Vector3.zero end
    end)
    startV5()
end

local function disableV5()
    v5Enabled = false
    _G.FRHUB_AIMBOT_V4_ACTIVE = false
    stopV5()
    local char = LP.Character; local myHRP = getHRP(char); local hum = getHum(char)
    if myHRP then
        pcall(function()
            for _, obj in ipairs(myHRP:GetChildren()) do
                if (obj:IsA("LinearVelocity") or obj:IsA("BodyVelocity")
                or obj:IsA("BodyAngularVelocity") or obj:IsA("BodyPosition") or obj:IsA("BodyGyro")
                or obj:IsA("AngularVelocity")) and not (obj.Name and string.sub(obj.Name, 1, 5) == "FRHUB") then
                    obj:Destroy()
                end
            end
        end)
        myHRP.AssemblyAngularVelocity = Vector3.zero
    end
    if hum then hum.AutoRotate = true end
    v5Target = nil; v5TargetPlr = nil
    v5Equipped = false; v5SwingCD = false
    restoreWalkAfterAimbot()
end

_G.FRHUB_AIMBOT_V4 = {
    enabled    = function() return v5Enabled end,
    enable     = function()
        if _G.FRHUBSafeModeIsLocked and _G.FRHUBSafeModeIsLocked() then return end
        enableV5()
    end,
    disable    = function() disableV5() end,
    toggle     = function()
        if v5Enabled then disableV5()
        else
            if _G.FRHUBSafeModeIsLocked and _G.FRHUBSafeModeIsLocked() then return v5Enabled end
            enableV5()
        end
        return v5Enabled
    end,
    setSpeed   = function(v)
        if type(v) == "number" then AIMBOT_V5_CFG.speed = math.clamp(v, 1, 200) end
    end,
    setKeybind = function(k)
        if type(k) == "string" and k ~= "" then AIMBOT_V5_CFG.keybind = k end
    end,
    getSpeed   = function() return AIMBOT_V5_CFG.speed end,
    getKeybind = function() return AIMBOT_V5_CFG.keybind end,
    getTarget  = function() return v5Target, v5TargetPlr end,
    cfg        = AIMBOT_V5_CFG,
}
_G.FRHUB_AIMBOT_V4.ace = nil

local frhubSafeModeEnabled = true
_G.FRHUBSafeModeBlockedTools = {
    bat=true,slap=true,sword=true,gun=true,pistol=true,rifle=true,
    medusa=true,hammer=true,axe=true,knife=true,katana=true,blade=true,fist=true,
}
function _G.FRHUBSafeModeIsCarryableTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local name = tool.Name:lower()
    for word in pairs(_G.FRHUBSafeModeBlockedTools) do
        if name:find(word,1,true) then return false end
    end
    return true
end
function _G.FRHUBSafeModeGetCountdownLabel()
    local ok, label = pcall(function()
        return LP.PlayerGui
            and LP.PlayerGui:FindFirstChild("DuelsMachineTopFrame")
            and LP.PlayerGui.DuelsMachineTopFrame:FindFirstChild("DuelsMachineTopFrame")
            and LP.PlayerGui.DuelsMachineTopFrame.DuelsMachineTopFrame:FindFirstChild("Timer")
            and LP.PlayerGui.DuelsMachineTopFrame.DuelsMachineTopFrame.Timer:FindFirstChild("Label")
    end)
    return (ok and label) or nil
end
function _G.FRHUBSafeModeCountdownNumber(text)
    local t = tostring(text or ""):upper():gsub("^%s+",""):gsub("%s+$","")
    if t=="GO" or t=="START" or t=="READY" then return true end
    local n = tonumber(t)
    return n ~= nil and n >= 0 and n <= 10
end
function _G.FRHUBSafeModeInDuelCountdown()
    local label = _G.FRHUBSafeModeGetCountdownLabel()
    return label and _G.FRHUBSafeModeCountdownNumber(label.Text) or false
end
function _G.FRHUBSafeModeIsLocked()
    if not frhubSafeModeEnabled then return false end
    return _G.FRHUBSafeModeInDuelCountdown()
end
function _G.FRHUBSafeModeForceStop()
    if v5Enabled then disableV5() end
    if _G.FRHUB_BYPASS_AIMBOT and _G.FRHUB_BYPASS_AIMBOT.enabled and _G.FRHUB_BYPASS_AIMBOT.enabled() then
        pcall(_G.FRHUB_BYPASS_AIMBOT.disable)
    end
end
function _G.FRHUBSafeModeTryStart()
    if _G.FRHUBSafeModeIsLocked and _G.FRHUBSafeModeIsLocked() then
        _G.FRHUBSafeModeForceStop(); return false
    end
    return true
end
_G.FRHUBSafeModeMonitorStarted = _G.FRHUBSafeModeMonitorStarted or false
if not _G.FRHUBSafeModeMonitorStarted then
    _G.FRHUBSafeModeMonitorStarted = true
    RunService.Heartbeat:Connect(function()
        if frhubSafeModeEnabled and _G.FRHUBSafeModeIsLocked and _G.FRHUBSafeModeIsLocked() then
            _G.FRHUBSafeModeForceStop()
        end
    end)
end
_G.FRHUB_SAFE_MODE = {
    enabled  = function() return frhubSafeModeEnabled end,
    enable   = function() frhubSafeModeEnabled = true end,
    disable  = function() frhubSafeModeEnabled = false end,
    toggle   = function() frhubSafeModeEnabled = not frhubSafeModeEnabled; return frhubSafeModeEnabled end,
    tryStart = function() return _G.FRHUBSafeModeTryStart() end,
    isLocked = function() return _G.FRHUBSafeModeIsLocked() end,
}



LP.CharacterAdded:Connect(function(char)
    task.wait(0.5)
    v5Equipped = false
    _mtTracked = nil; _mtPrevY = nil
    if v5Enabled then
        local hum = getHum(char)
        if hum then hum.AutoRotate = false end
        local root = getHRP(char)
        if root then
            pcall(function()
                for _, obj in ipairs(root:GetChildren()) do
                    if (obj:IsA("LinearVelocity") or obj:IsA("BodyVelocity")
                    or obj:IsA("BodyAngularVelocity") or obj:IsA("BodyPosition") or obj:IsA("BodyGyro")
                    or obj:IsA("AngularVelocity")) and not (obj.Name and string.sub(obj.Name, 1, 5) == "FRHUB") then
                        obj:Destroy()
                    end
                end
            end)
            root.Velocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
    end
end)
end) end)



task.spawn(function() pcall(function()
local Players    = game:GetService("Players")
local RunService = game:GetService("RunService")
local UIS       = game:GetService("UserInputService")
local LP        = Players.LocalPlayer

local BYPASS_CFG = { speed = 56, keybind = "V" }
local bypassEnabled = false
local bypassConn    = nil
local bypassSwingCD = false
local bypassPrevAutoRot = nil
local bypassBatEquipped = false

local CARRY_DROP_ANIM_ID      = "71186871415348"
local carryDropWasPlaying     = false
local carryDropSequenceActive = false
local carryDropLastTrigger    = 0

local _bpHist      = {}
local _bpHistN     = 6
local _bpStrafeT   = 0
local _bpLastTarget= nil
local _bpTPUntil   = 0
local _bpTPY       = -7

local function _bpRecord(target)
    if not target or not target.Parent then _bpHist = {}; return end
    local entry = {p = target.Position, t = tick()}
    if not _bpHist[target] then _bpHist[target] = {} end
    local h = _bpHist[target]
    table.insert(h, entry)
    while #h > _bpHistN do table.remove(h, 1) end
    if #h >= 2 then
        local a = h[#h-1]; local b = h[#h]
        local dy = a.p.Y - b.p.Y
        local dt = math.max(b.t - a.t, 0.001)
        if dy > 12 and (dy/dt) > 200 then
            _bpTPUntil = tick() + 0.5
            _bpTPY = b.p.Y - 1.0
        end
    end
end

local function _bpEstimate(target)
    local h = _bpHist[target]
    if not h or #h < 3 then return Vector3.zero, Vector3.zero end
    local dxs, dzs, dys = {}, {}, {}
    for i = 2, #h do
        local dt = math.max(h[i].t - h[i-1].t, 0.001)
        local dp = h[i].p - h[i-1].p
        if math.abs(dp.X)/dt < 500 and math.abs(dp.Z)/dt < 500 and math.abs(dp.Y)/dt < 500 then
            table.insert(dxs, dp.X/dt)
            table.insert(dzs, dp.Z/dt)
            table.insert(dys, dp.Y/dt)
        end
    end
    if #dxs == 0 then return Vector3.zero, Vector3.zero end
    table.sort(dxs); table.sort(dzs); table.sort(dys)
    local mi = math.floor(#dxs/2)+1
    local v = Vector3.new(dxs[mi], dys[mi], dzs[mi])
    local flat = Vector3.new(v.X, 0, v.Z)
    local dir = flat.Magnitude > 2 and flat.Unit or Vector3.zero
    return v, dir
end

local function hrpOf(c) return c and c:FindFirstChild("HumanoidRootPart") end
local function humOf(c) return c and c:FindFirstChildOfClass("Humanoid") end

local function findBypassBat()
    local char = LP.Character
    if not char then return nil end
    for _, t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") and (t.Name:lower():find("bat") or t.Name:lower():find("slap")) then return t end
    end
    local bp = LP:FindFirstChildOfClass("Backpack")
    if bp then
        for _, t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") and (t.Name:lower():find("bat") or t.Name:lower():find("slap")) then return t end
        end
    end
    return nil
end

local function bypassSwing()
    if bypassSwingCD then return end
    local char = LP.Character
    if not char then return end
    local bat = findBypassBat()
    if bat and bat.Parent == char then
        bypassSwingCD = true
        pcall(function()
            bat:Activate()
            local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
            if ev then ev:FireServer() end
        end)
        task.delay(0.08, function() bypassSwingCD = false end)
    end
end

local function getBypassSpeed()
    local st = _G.FRHUB_STATE
    if st and (st.laggerCarryActive or st.laggerActive) then
        return _G.AIMBOT_V3_LAGGER_SPEED or 40
    end
    return _G.AIMBOT_V3_SPEED or BYPASS_CFG.speed
end

local function findBypassTarget(myHRP)
    local TARGET_PARTS = {"HumanoidRootPart","Torso","UpperTorso","Head","LowerTorso"}
    local best, bestD, bestPart = nil, math.huge, nil
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local t = hrpOf(p.Character)
            local h = humOf(p.Character)
            if t and h and h.Health > 0 then
                local d = (t.Position - myHRP.Position).Magnitude
                local cp, cd = t, d
                for _, pn in ipairs(TARGET_PARTS) do
                    local part = p.Character:FindFirstChild(pn)
                    if part and part:IsA("BasePart") then
                        local pd = (part.Position - myHRP.Position).Magnitude
                        if pd < cd then cd = pd; cp = part end
                    end
                end
                if cd < bestD then bestD = cd; best = cp; bestPart = cp end
            end
        end
    end
    return best, bestD
end

local function startBypass()
    if bypassConn then bypassConn:Disconnect(); bypassConn = nil end
    bypassConn = RunService.Heartbeat:Connect(function()
        if not bypassEnabled then return end
        if carryDropSequenceActive then
            local c2 = LP.Character
            local r2 = c2 and hrpOf(c2)
            if r2 then
                pcall(function() r2.Velocity = Vector3.new(0, r2.Velocity.Y, 0) end)
                pcall(function() r2.AssemblyAngularVelocity = Vector3.zero end)
            end
            return
        end
        local char = LP.Character
        local root = hrpOf(char)
        local hum  = humOf(char)
        if not root or not hum then return end

        if not bypassBatEquipped then
            local curTool = char:FindFirstChildOfClass("Tool")
            if curTool then
                bypassBatEquipped = true
            else
                local bat = findBypassBat()
                if bat then
                    pcall(function() hum:EquipTool(bat) end)
                    bypassBatEquipped = true
                end
            end
        end

        local target, dist = findBypassTarget(root)
        if not target then
            _bpHist = {}; _bpLastTarget = nil; _bpTPUntil = 0
            hum.AutoRotate = true
            pcall(function() root.Velocity = Vector3.new(0, root.Velocity.Y, 0) end)
            pcall(function() root.AssemblyAngularVelocity = Vector3.zero end)
            return
        end
        if target ~= _bpLastTarget then _bpHist = {}; _bpLastTarget = target; _bpTPUntil = 0 end
        _bpRecord(target)

        hum.AutoRotate = false

        local myPos = root.Position
        local tPos  = target.Position

        local estVel, moveDir = _bpEstimate(target)
        local estSpd = Vector3.new(estVel.X, 0, estVel.Z).Magnitude

        local leadT = math.clamp(dist / math.max(getBypassSpeed()*1.3, 1), 0.04, 0.18)
        leadT = leadT + math.clamp(estSpd/500, 0, 0.08)
        local predicted = tPos + Vector3.new(estVel.X*leadT, 0, estVel.Z*leadT)

        _bpStrafeT = _bpStrafeT + 0.016*4.5
        local right = Vector3.new(-moveDir.Z, 0, moveDir.X)
        local sway  = math.sin(_bpStrafeT)*0.8
        local swayLat = math.cos(_bpStrafeT*0.6)*0.35
        local aimPoint = predicted + moveDir*(math.clamp(estSpd/60,0.2,1.0) + sway*0.25) + right*swayLat

        local flatDir = Vector3.new(aimPoint.X - myPos.X, 0, aimPoint.Z - myPos.Z)
        if flatDir.Magnitude < 0.1 then
            pcall(function() root.Velocity = Vector3.new(0, root.Velocity.Y, 0) end)
        else
            local udir = flatDir.Unit
            local spd  = getBypassSpeed()
            local aimY = tPos.Y + 3.7
            if tick() < _bpTPUntil then
                aimY = _bpTPY + 2.5
            end
            local yDiff = aimY - myPos.Y
            local yv
            if hum.FloorMaterial ~= Enum.Material.Air then
                yv = (yDiff > 0) and math.max(yDiff*22, 13) or -25
            else
                if yDiff < -3 then
                    yv = -90
                elseif yDiff > 3 then
                    yv = math.min(yDiff*22, 110)
                else
                    yv = root.Velocity.Y
                end
            end
            yv = math.clamp(yv, -120, 110)

            pcall(function() root.Velocity = Vector3.new(udir.X*spd, yv, udir.Z*spd) end)
        end

        local lookPos = predicted + Vector3.new(0, 1.0, 0)
        local toT = lookPos - myPos
        if toT.Magnitude > 0.1 then
            local goal = CFrame.lookAt(myPos, lookPos)
            local diff = root.CFrame:Inverse() * goal
            local rx, ry, rz = diff:ToEulerAnglesXYZ()
            rx = math.clamp(rx, -2.0, 2.0)
            ry = math.clamp(ry, -2.0, 2.0)
            rz = math.clamp(rz, -2.0, 2.0)
            root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(rx*42, ry*42, rz*42))
        end

        local realDist = (tPos - myPos).Magnitude
        local bat = char:FindFirstChildOfClass("Tool")
        if bat and not (bat.Name:lower():find("bat") or bat.Name:lower():find("slap")) then
            bat = nil
        end
        if not bat then bat = findBypassBat() end
        if bat and bat.Parent ~= char then
            if not char:FindFirstChildOfClass("Tool") then
                pcall(function() hum:EquipTool(bat) end)
                bypassBatEquipped = true
            end
        end
        local autoSwing = false
        pcall(function()
            local st = _G.FRHUB_STATE
            if st and st.autoBatToggled then autoSwing = true end
        end)
        if bat and bat.Parent == char and (autoSwing or autoSwingV3Enabled) and realDist <= 8 and not bypassSwingCD then
            bypassSwingCD = true
            pcall(function()
                bat:Activate()
                local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
                if ev then ev:FireServer() end
            end)
            task.delay(0.06, function() bypassSwingCD = false end)
        end
    end)
end

local function stopBypass()
    if bypassConn then bypassConn:Disconnect(); bypassConn = nil end
    local char = LP.Character
    local root = hrpOf(char)
    local hum  = humOf(char)
    if root then
        pcall(function() root.Velocity = Vector3.zero end)
        pcall(function() root.AssemblyAngularVelocity = Vector3.zero end)
        pcall(function()
            for _, obj in ipairs(root:GetChildren()) do
                if (obj:IsA("LinearVelocity") or obj:IsA("BodyVelocity") or obj:IsA("BodyAngularVelocity")) and not (obj.Name and string.sub(obj.Name, 1, 5) == "FRHUB") then
                    obj:Destroy()
                end
            end
        end)
    end
    if hum then
        hum.AutoRotate = true
        hum.PlatformStand = false
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
    end
    bypassPrevAutoRot = nil
    bypassBatEquipped = false
    _bpHist = {}; _bpLastTarget = nil; _bpStrafeT = 0; _bpTPUntil = 0
end

local function enableBypass()
    if _G.FRHUBSafeModeIsLocked and _G.FRHUBSafeModeIsLocked() then return end
    if _G.FRHUB_AIMBOT_V4 and _G.FRHUB_AIMBOT_V4.enabled() then
        pcall(_G.FRHUB_AIMBOT_V4.disable)
    end
    bypassEnabled = true
    _G.FRHUB_BYPASS_AIMBOT_ACTIVE = true
    _bpHist = {}; _bpLastTarget = nil; _bpStrafeT = 0; _bpTPUntil = 0
    local char = LP.Character
    local hum  = humOf(char)
    local root = hrpOf(char)
    if hum then
        if bypassPrevAutoRot == nil then bypassPrevAutoRot = hum.AutoRotate end
        hum.AutoRotate = false
    end
    if root then
        pcall(function()
            for _, obj in ipairs(root:GetChildren()) do
                if (obj:IsA("LinearVelocity") or obj:IsA("BodyVelocity") or obj:IsA("BodyAngularVelocity")) and not (obj.Name and string.sub(obj.Name, 1, 5) == "FRHUB") then
                    obj:Destroy()
                end
            end
        end)
        pcall(function() root.Velocity = Vector3.zero end)
        root.AssemblyAngularVelocity = Vector3.zero
    end
    bypassBatEquipped = false
    startBypass()
end

local function disableBypass()
    bypassEnabled = false
    _G.FRHUB_BYPASS_AIMBOT_ACTIVE = false
    stopBypass()
end

_G.FRHUB_BYPASS_AIMBOT = {
    enabled = function() return bypassEnabled end,
    enable  = function() enableBypass() end,
    disable = function() disableBypass() end,
    toggle  = function()
        if bypassEnabled then disableBypass() else enableBypass() end
        return bypassEnabled
    end,
    setSpeed = function(v)
        if type(v) == "number" then BYPASS_CFG.speed = math.clamp(v, 1, 200) end
    end,
    setKeybind = function(k)
        if type(k) == "string" and k ~= "" then BYPASS_CFG.keybind = k end
    end,
    getSpeed   = function() return BYPASS_CFG.speed end,
    getKeybind = function() return BYPASS_CFG.keybind end,
}

local _mbTracked = nil
local _mbPrevY   = nil
local _mbLastTP  = 0
RunService.Heartbeat:Connect(function()
    local st = _G.FRHUB_STATE
    if not (st and st.mirrorTPDownEnabled and (bypassEnabled or _G.FRHUB_AIMBOT_V6_ACTIVE == true or _G.FRHUB_AIMBOT_V8_ACTIVE == true or _G.FRHUB_AIMBOT_V9_ACTIVE == true or _G._FRHUBV11EngineActive == true)) then return end
    local myChar = LP.Character
    local myRoot = myChar and hrpOf(myChar)
    if not myRoot then return end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local t = hrpOf(p.Character)
            if t then
                local curY = t.Position.Y
                local prevY = _mbTracked == t and _mbPrevY or nil
                if prevY and prevY - curY >= 3 and tick() - _mbLastTP > 0.08 then
                    _mbLastTP = tick()
                    local _, yaw = myRoot.CFrame:ToEulerAnglesYXZ()
                    myRoot.CFrame = CFrame.new(myRoot.Position.X, -7.00, myRoot.Position.Z) * CFrame.Angles(0, yaw, 0)
                    myRoot.Velocity = Vector3.zero
                end
                _mbTracked = t
                _mbPrevY   = curY
                return
            end
        end
    end
end)

LP.CharacterAdded:Connect(function(c)
    task.wait(0.5)
    bypassBatEquipped = false
    if bypassEnabled then
        local h = humOf(c)
        if h then h.AutoRotate = false end
        local r = hrpOf(c)
        if h and r then
            local curTool = c:FindFirstChildOfClass("Tool")
            if not curTool then
                local bat = findBypassBat()
                if bat then pcall(function() h:EquipTool(bat) end) end
            end
            bypassBatEquipped = true
        end
    end
end)

do
    local function isCarryDropAimAnimationPlaying()
        local character = LP.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not animator then return false end

        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            local animation = track.Animation
            local animationId = animation and animation.AnimationId or ""
            if string.find(animationId, CARRY_DROP_ANIM_ID, 1, true) then
                return true
            end
        end
        return false
    end

    local function recentlyRagdolled()
        local st = _G.FRHUB_STATE
        if not st then return false end
        if st.ragdollKilledCarry == true then return true end
        if st.lastRagdollTick and st.lastRagdollTick > 0 and (tick() - st.lastRagdollTick) <= 1.5 then return true end
        return false
    end

    local function stopCarryAnimNow()
        local character = LP.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not animator then return end
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            local animation = track.Animation
            local animationId = animation and animation.AnimationId or ""
            if string.find(animationId, CARRY_DROP_ANIM_ID, 1, true) then
                track:Stop(0)
            end
        end
    end

    local function hasDetectedCarryState()
        local character = LP.Character
        if not character then return false end
        for _, name in ipairs({"Carrying", "IsCarrying", "Grabbed", "Holding", "StealHold", "HasGrab"}) do
            local v = character:FindFirstChild(name, true)
            if v then
                if v:IsA("BoolValue") and v.Value then return true end
                if v:IsA("ObjectValue") and v.Value then return true end
                if v:IsA("StringValue") and v.Value ~= "" then return true end
            end
        end
        return false
    end

    local function runDropAction()
        if type(_G.FRHUB_DROP_BR_DISPATCH) == "function" then
            pcall(_G.FRHUB_DROP_BR_DISPATCH)
        elseif runDropBrainrot then
            pcall(runDropBrainrot)
        end
    end

    local DROP_CONFIRM_STABLE_HEARTBEATS = 3
    local DROP_RETRY_INTERVAL = 0.75
    local DROP_SEQUENCE_MAX_TIME = 4

    local function triggerDropThenBypass()
        local now = tick()
        if carryDropSequenceActive then return end
        if now - carryDropLastTrigger < 0.75 then return end
        carryDropLastTrigger = now
        carryDropSequenceActive = true

        local st0 = _G.FRHUB_STATE
        if st0 then st0.autoBatToggled = false end
        if bypassEnabled then
            pcall(disableBypass)
        end

        local requireCarryStateClear = hasDetectedCarryState()

        runDropAction()

        task.spawn(function()
            local stableClearHeartbeats = 0
            local lastDropAttemptAt = tick()
            local sequenceStartedAt = tick()
            while carryDropSequenceActive do
                RunService.Heartbeat:Wait()

                if recentlyRagdolled() then
                    carryDropSequenceActive = false
                    bypassBatEquipped = false
                    break
                end

                if tick() - sequenceStartedAt > DROP_SEQUENCE_MAX_TIME then
                    carryDropSequenceActive = false
                    bypassBatEquipped = false
                    break
                end

                local dropMotionFinished = not (_G.FRHUB_DROP_BR_ACTIVE == true)
                local carryAnimationCleared = not isCarryDropAimAnimationPlaying()
                local carryStateCleared = not requireCarryStateClear or not hasDetectedCarryState()

                if dropMotionFinished and carryAnimationCleared and carryStateCleared then
                    stableClearHeartbeats = stableClearHeartbeats + 1
                else
                    stableClearHeartbeats = 0
                end

                if stableClearHeartbeats >= DROP_CONFIRM_STABLE_HEARTBEATS then
                    carryDropSequenceActive = false
                    bypassBatEquipped = false
                    break
                end

                local now2 = tick()
                if dropMotionFinished and now2 - lastDropAttemptAt >= DROP_RETRY_INTERVAL then
                    lastDropAttemptAt = now2
                    runDropAction()
                end
            end

            local st1 = _G.FRHUB_STATE
            if st1 then st1.autoBatToggled = true end
            pcall(enableBypass)
        end)
    end

    local carryDropAimWasPlaying = false
    local carryAnimPrev = false

    RunService.Heartbeat:Connect(function()
        if not bypassEnabled then
            carryDropAimWasPlaying = false
            return
        end

        if recentlyRagdolled() then
            stopCarryAnimNow()
            if carryDropSequenceActive then
                carryDropSequenceActive = false
                bypassBatEquipped = false
            end
            local st = _G.FRHUB_STATE
            if st then st.ragdollKilledCarry = false end
            carryDropAimWasPlaying = false
            carryAnimPrev = false
            return
        end

        if carryDropSequenceActive then
            carryDropAimWasPlaying = isCarryDropAimAnimationPlaying()
            carryAnimPrev = carryDropAimWasPlaying
            return
        end

        local isPlaying = isCarryDropAimAnimationPlaying()

        if isPlaying and not carryAnimPrev then
            local st = _G.FRHUB_STATE
            if st then st.ragdollKilledCarry = false end
        end
        carryAnimPrev = isPlaying

        if isPlaying and not carryDropAimWasPlaying then
            triggerDropThenBypass()
        end
        carryDropAimWasPlaying = isPlaying
    end)
end
end) end)

TP_DOWN_V3_INTERVAL_MS = 273

task.spawn(function()
    local RunService = game:GetService("RunService")
    local lastTick = 0
    local function getInterval()
        local ms = TP_DOWN_V3_INTERVAL_MS
        if type(ms) ~= "number" or ms <= 0 then ms = 273 end
        return ms / 1000
    end
    local function isAimbotActive()
        if _G.FRHUB_AIMBOT_V4_ACTIVE then return true end
        if _G.FRHUB_BYPASS_AIMBOT_ACTIVE then return true end
        if _G.FRHUB_AIMBOT_V6_ACTIVE then return true end
        if _G.FRHUB_AIMBOT_V8_ACTIVE then return true end
        if _G.FRHUB_AIMBOT_V9_ACTIVE then return true end
        if _G._FRHUBV11EngineActive == true then return true end
        if _G.FRHUB_AIMBOT_V4 and _G.FRHUB_AIMBOT_V4.enabled and _G.FRHUB_AIMBOT_V4.enabled() then return true end
        if _G.FRHUB_BYPASS_AIMBOT and _G.FRHUB_BYPASS_AIMBOT.enabled and _G.FRHUB_BYPASS_AIMBOT.enabled() then return true end
        return false
    end
    RunService.Heartbeat:Connect(function()
        local st = _G.FRHUB_STATE
        if not (st and st.tpDownV3Enabled) then return end
        if not isAimbotActive() then return end
        local now = tick()
        if now - lastTick < getInterval() then return end
        lastTick = now
        pcall(function()
            local char = game.Players.LocalPlayer.Character
            if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end
            local _, yaw = hrp.CFrame:ToEulerAnglesYXZ()
            hrp.CFrame = CFrame.new(hrp.Position.X, -7.00, hrp.Position.Z) * CFrame.Angles(0, yaw, 0)
            hrp.Velocity = Vector3.new(hrp.Velocity.X * 0.5, -50, hrp.Velocity.Z * 0.5)
        end)
    end)
end)

_G.FRHUB_AIMBOT_V6_ACTIVE     = false

FRHUB_AIMBOT_V6       = { conn = nil, target = nil, lastScan = 0 }
FRHUB_AIMBOT_BYPASS   = { conn = nil, swingCooldown = false, prevAutoRotate = nil }
FRHUB_BYPASS_SETTINGS = { VERT_SPEED = 52, DISTANCE = -2.8, HEIGHT = 4.75, V_OFFSET = 1, MAX_TURN_RATE = 28 }

local _frhV6Players = game:GetService("Players")
local _frhV6Run     = game:GetService("RunService")
local _frhV6LP      = _frhV6Players.LocalPlayer

local function frhubV6AimbotSpeed()
    local st = _G.FRHUB_STATE
    if st and (st.laggerActive == true or st.laggerCarryActive == true) then
        return tonumber(_G.AIMBOT_V3_LAGGER_SPEED) or 40
    end
    return tonumber(_G.AIMBOT_V3_SPEED) or 58
end

local function frhubV6AutoSwing()
    return autoSwingV3Enabled == true
end


local function frhubV6FindBat()
    local char = _frhV6LP.Character
    if not char then return nil end
    for _, tool in ipairs(char:GetChildren()) do
        if tool:IsA("Tool") and (tool.Name:lower():find("bat") or tool.Name:lower():find("slap")) then
            return tool
        end
    end
    local bp = _frhV6LP:FindFirstChild("Backpack")
    if bp then
        for _, tool in ipairs(bp:GetChildren()) do
            if tool:IsA("Tool") and (tool.Name:lower():find("bat") or tool.Name:lower():find("slap")) then
                return tool
            end
        end
    end
    return nil
end

local function frhubV6BypassFindBat()
    local char = _frhV6LP.Character
    if not char then return nil end
    for _, tool in ipairs(char:GetChildren()) do
        if tool:IsA("Tool") then
            local name = tool.Name:lower()
            if name:find("bat") or name:find("slap") then return tool end
        end
    end
    local bp = _frhV6LP:FindFirstChildOfClass("Backpack")
    if bp then
        for _, tool in ipairs(bp:GetChildren()) do
            if tool:IsA("Tool") then
                local name = tool.Name:lower()
                if name:find("bat") or name:find("slap") then return tool end
            end
        end
    end
    return nil
end

local function frhubV6BypassEnsureBat()
    local char = _frhV6LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not char or not hum then return nil end
    local equipped = char:FindFirstChildOfClass("Tool")
    if equipped then return equipped end
    local bat = frhubV6BypassFindBat()
    if bat then pcall(function() hum:EquipTool(bat) end) end
    return bat
end

local function frhubV6BypassTrySwing()
    local S = FRHUB_AIMBOT_BYPASS
    if S.swingCooldown then return end
    S.swingCooldown = true
    pcall(function()
        local bat = frhubV6BypassEnsureBat()
        if bat and bat:IsA("Tool") then bat:Activate() end
    end)
    task.delay(0.3, function()
        FRHUB_AIMBOT_BYPASS.swingCooldown = false
    end)
end

local function frhubV6BypassGetClosest()
    local char = _frhV6LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return nil, math.huge end
    local closest, minDist = nil, math.huge
    for _, plr in ipairs(_frhV6Players:GetPlayers()) do
        if plr ~= _frhV6LP and plr.Character then
            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character:FindFirstChildOfClass("Humanoid")
            if tRoot and hum and hum.Health > 0 then
                local dist = (tRoot.Position - root.Position).Magnitude
                if dist < minDist then minDist, closest = dist, tRoot end
            end
        end
    end
    return closest, minDist
end

_G.FRHUBStartAimbotV6 = function()
    _G.FRHUB_AIMBOT_V6_ACTIVE = true
    FRHUB_AIMBOT_V6.target = nil
    FRHUB_AIMBOT_V6.lastScan = 0
    local hum = _frhV6LP.Character and _frhV6LP.Character:FindFirstChildOfClass("Humanoid")
    if hum then hum.AutoRotate = false end
    if _G.FRHUB_STATE then _G.FRHUB_STATE.aimbotV6Enabled = true end
end

_G.FRHUBStopAimbotV6 = function()
    _G.FRHUB_AIMBOT_V6_ACTIVE = false
    FRHUB_AIMBOT_V6.target = nil
    FRHUB_AIMBOT_V6.lastScan = 0
    local char = _frhV6LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if root then
        _setV(root, Vector3.zero)
        root.AssemblyAngularVelocity = Vector3.zero
    end
    if hum then hum.AutoRotate = true end
    if _G.FRHUB_STATE then _G.FRHUB_STATE.aimbotV6Enabled = false end
end

_frhV6Run.Heartbeat:Connect(function()
    if not _G.FRHUB_AIMBOT_V6_ACTIVE then return end
    local char = _frhV6LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not char or not hum or not root or hum.Health <= 0 then return end

    local _isBypassMode = (_G.FRHUB_STATE and _G.FRHUB_STATE.v6AimbotMode == "bypass") == true
    if _isBypassMode then
        if FRHUB_AIMBOT_V6.lastMode ~= "bypass" then
            _setV(root, Vector3.zero)
            FRHUB_AIMBOT_V6.lastMode = "bypass"
        end
        local S = FRHUB_BYPASS_SETTINGS
        hum.AutoRotate = false
        frhubV6BypassEnsureBat()
        local target, targetDist = frhubV6BypassGetClosest()
        if not target then
            _setV(root, Vector3.zero)
            root.AssemblyAngularVelocity = Vector3.zero
            return
        end
        local aimTargetPos = target.Position + Vector3.new(0, S.V_OFFSET, 0)
        local look = aimTargetPos - root.Position
        local flatLook = Vector3.new(look.X, 0, look.Z)
        if flatLook.Magnitude > 0.01 then
            local targetYaw = math.deg(math.atan2(-flatLook.X, -flatLook.Z))
            local yawDelta = (targetYaw - root.Orientation.Y + 180) % 360 - 180
            local yawRate = math.clamp(yawDelta * 8, -S.MAX_TURN_RATE, S.MAX_TURN_RATE)
            root.AssemblyAngularVelocity = Vector3.new(0, yawRate, 0)
        else
            root.AssemblyAngularVelocity = Vector3.zero
        end
        if look.Magnitude > 0.01 then
            local dir = look.Unit
            local standPos = aimTargetPos - (dir * S.DISTANCE) + Vector3.new(0, S.HEIGHT, 0)
            local moveDir = standPos - root.Position
            local hDir = Vector3.new(moveDir.X, 0, moveDir.Z)
            local hVel = hDir.Magnitude > 0.1 and hDir.Unit * frhubV6AimbotSpeed() or Vector3.zero
            local vVel = Vector3.new(0, math.clamp(moveDir.Y * 3, -S.VERT_SPEED, S.VERT_SPEED), 0)
            _setV(root, hVel + vVel)
            if hDir.Magnitude > 0.5 then
                pcall(function() hum:Move(hDir.Unit, false) end)
            end
        end
        if frhubV6AutoSwing() and targetDist < 5 then frhubV6BypassTrySwing() end
        return
    end

    if FRHUB_AIMBOT_V6.lastMode ~= "normal" then
        _setV(root, Vector3.zero)
        FRHUB_AIMBOT_V6.lastMode = "normal"
    end

    if not char:FindFirstChildOfClass("Tool") then
        local bat = frhubV6FindBat()
        if bat then
            pcall(function() hum:EquipTool(bat) end)
        end
    end

    local S = FRHUB_AIMBOT_V6
    local now = tick()
    local target = S.target
    if now - (S.lastScan or 0) > 0.1 or not target or not target.Parent then
        S.lastScan = now
        local closest, minDist = nil, math.huge
        for _, plr in ipairs(_frhV6Players:GetPlayers()) do
            if plr ~= _frhV6LP and plr.Character then
                local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
                local th = plr.Character:FindFirstChildOfClass("Humanoid")
                if tRoot and th and th.Health > 0 then
                    local dist = (tRoot.Position - root.Position).Magnitude
                    if dist < minDist then
                        minDist = dist
                        closest = tRoot
                    end
                end
            end
        end
        target = closest
        S.target = target
    end

    if not target then
        hum.AutoRotate = true
        root.AssemblyAngularVelocity = Vector3.zero
        _setV(root, Vector3.zero)
        return
    end

    local targetHum = target.Parent and target.Parent:FindFirstChildOfClass("Humanoid")
    if not targetHum or targetHum.Health <= 0 then
        S.target = nil
        _setV(root, Vector3.zero)
        return
    end

    hum.AutoRotate = false

    local targetVel = target.AssemblyLinearVelocity
    local aimTargetPos =
        target.Position
        + (targetVel * math.clamp(targetVel.Magnitude / 130, 0.05, 0.15))
        + Vector3.new(0, 1, 0)

    local look = aimTargetPos - root.Position
    local flatLook = Vector3.new(look.X, 0, look.Z)

    if look.Magnitude > 0.01 and flatLook.Magnitude > 0.01 then
        local targetYaw = math.deg(math.atan2(-flatLook.X, -flatLook.Z))
        local yawDelta = (targetYaw - root.Orientation.Y + 180) % 360 - 180
        local targetPitch = math.deg(math.atan2(look.Y, flatLook.Magnitude))
        local pitchDelta = (targetPitch - root.Orientation.X + 180) % 360 - 180
        local yawRate = math.clamp(math.rad(yawDelta) * 285, -28, 28)
        local pitchRate = math.clamp(math.rad(pitchDelta) * 285, -28, 28)
        local yawRad = math.rad(root.Orientation.Y)
        local rightAxis = Vector3.new(math.cos(yawRad), 0, -math.sin(yawRad))
        root.AssemblyAngularVelocity = Vector3.new(0, yawRate, 0) + (rightAxis * pitchRate)
    else
        root.AssemblyAngularVelocity = Vector3.zero
    end

    local dir = look.Magnitude > 0.01 and look.Unit or Vector3.zero
    local standPos = aimTargetPos - (dir * -2.8) + Vector3.new(0, 4.75, 0)
    local moveDir = standPos - root.Position
    local hDir = Vector3.new(moveDir.X, 0, moveDir.Z)

    local selectedSpeed = frhubV6AimbotSpeed()
    local hVel = hDir.Magnitude > 0.1 and (hDir.Unit * selectedSpeed) or Vector3.zero
    local vVel = math.abs(moveDir.Y) > 0.1
        and Vector3.new(0, math.sign(moveDir.Y) * 52, 0)
        or Vector3.new(0, -2, 0)

    _setV(root, hVel + vVel)

    if hDir.Magnitude > 0.5 then
        pcall(function() hum:Move(hDir.Unit, false) end)
    end

    if frhubV6AutoSwing() then
        local bat = char:FindFirstChildOfClass("Tool") or frhubV6FindBat()
        if bat and bat:IsA("Tool") then
            pcall(function() bat:Activate() end)
        end

    end
end)




local PlayersBTP    = game:GetService("Players")
local RunServiceBTP = game:GetService("RunService")
local LP_BTP        = PlayersBTP.LocalPlayer

_G.FRHUB_BATTP_ACTIVE       = false
_G.FRHUB_SMART_BATTP_ACTIVE = false

local FRHUB_BATTP = {
    conn = nil, loopToken = 0, target = nil, nextSwingAt = 0,
    prevAutoRotate = nil, batRemote = nil, batRemoteBat = nil,
    smartToken = 0, smartMover = nil, smartAttach = nil,
    smartAnchor = nil, smartDriving = false,
}

local function btpState()
    return _G.FRHUB_STATE
end

local function btpStuds()
    local st = btpState()
    return math.clamp(tonumber(st and st.batTpStuds) or 8, 1, 20)
end

local function btpRestoreAutoRotate(humanoid)
    if FRHUB_BATTP.prevAutoRotate ~= nil then
        local prev = FRHUB_BATTP.prevAutoRotate
        FRHUB_BATTP.prevAutoRotate = nil
        if humanoid and humanoid.Parent then pcall(function() humanoid.AutoRotate = prev end) end
    elseif humanoid and humanoid.Parent then
        pcall(function() humanoid.AutoRotate = true end)
    end
end

local function btpGetBat()
    local char = LP_BTP.Character
    if not char then return nil end
    local bat = char:FindFirstChild("Bat")
    if bat then return bat end
    local backpack = LP_BTP:FindFirstChildOfClass("Backpack")
    if backpack then
        bat = backpack:FindFirstChild("Bat")
        if bat then pcall(function() bat.Parent = char end) return bat end
    end
    return nil
end

local function btpFindClosest(position, prefer)
    local st = btpState()
    local maxRange = math.max(tonumber(st and st.batTpMaxRange) or 350, 25)
    local best, bestDist = nil, math.huge
    for _, plr in ipairs(PlayersBTP:GetPlayers()) do
        if plr ~= LP_BTP and plr.Character then
            local root = plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character:FindFirstChildOfClass("Humanoid")
            if root and hum and hum.Health > 0 then
                local d = (position - root.Position).Magnitude
                if d <= maxRange and d < bestDist then best, bestDist = plr, d end
            end
        end
    end
    if prefer and prefer ~= best and prefer.Parent == PlayersBTP and prefer.Character then
        local root = prefer.Character:FindFirstChild("HumanoidRootPart")
        local hum = prefer.Character:FindFirstChildOfClass("Humanoid")
        if root and hum and hum.Health > 0 then
            local d = (position - root.Position).Magnitude
            if d <= maxRange * 1.15 and d <= bestDist * 1.35 then return prefer, d end
        end
    end
    return best, bestDist
end

local function btpSwing()
    local now = os.clock()
    if now < (FRHUB_BATTP.nextSwingAt or 0) then return end
    FRHUB_BATTP.nextSwingAt = now + 0.04
    pcall(function()
        local bat = btpGetBat()
        if not bat then return end
        if FRHUB_BATTP.batRemoteBat ~= bat or (FRHUB_BATTP.batRemote and not FRHUB_BATTP.batRemote.Parent) then
            FRHUB_BATTP.batRemoteBat = bat
            FRHUB_BATTP.batRemote = bat:FindFirstChildWhichIsA("RemoteEvent", true)
        end
        bat:Activate()
        if FRHUB_BATTP.batRemote and FRHUB_BATTP.batRemote.Parent then
            FRHUB_BATTP.batRemote:FireServer()
        end
    end)
end

local function btpV2Update()
    local st = btpState()
    if not st then return end
    if not st.batTpEnabled and not FRHUB_BATTP.smartDriving then return end
    local char = LP_BTP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end
    local hState = hum:GetState()
    if hum.PlatformStand or hState == Enum.HumanoidStateType.Physics
        or hState == Enum.HumanoidStateType.Ragdoll or hState == Enum.HumanoidStateType.FallingDown then
        return
    end
    if FRHUB_BATTP.prevAutoRotate == nil then FRHUB_BATTP.prevAutoRotate = hum.AutoRotate end
    hum.AutoRotate = false
    if not char:FindFirstChildOfClass("Tool") then btpGetBat() end

    local target = FRHUB_BATTP.target
    local tChar = target and target.Parent == PlayersBTP and target.Character
    local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
    local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
    if not tRoot or not tHum or tHum.Health <= 0 then
        target = btpFindClosest(hrp.Position, FRHUB_BATTP.target)
        FRHUB_BATTP.target = target
        tChar = target and target.Character
        tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
        tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
    end
    if not tRoot or not tHum or tHum.Health <= 0 then return end

    local targetPos = tRoot.Position + Vector3.new(0, 0.9, 0)
    local flat = Vector3.new(targetPos.X - hrp.Position.X, 0, targetPos.Z - hrp.Position.Z)
    local tState = tHum:GetState()
    local targetAirborne = tHum.FloorMaterial == Enum.Material.Air
        or tState == Enum.HumanoidStateType.Jumping or tState == Enum.HumanoidStateType.Freefall
    local wasAbove = targetPos.Y > hrp.Position.Y + 1
    local needsTp = (hrp.Position - targetPos).Magnitude > btpStuds()
    local targetCFrame
    if flat.Magnitude > 0.05 then
        targetCFrame = CFrame.lookAt(targetPos, targetPos + flat.Unit)
    else
        local look = Vector3.new(tRoot.CFrame.LookVector.X, 0, tRoot.CFrame.LookVector.Z)
        if look.Magnitude >= 0.01 then
            targetCFrame = CFrame.lookAt(targetPos, targetPos + look.Unit)
        else
            local _, yaw = hrp.CFrame:ToEulerAnglesYXZ()
            targetCFrame = CFrame.new(targetPos) * CFrame.Angles(0, yaw, 0)
        end
    end
    if needsTp then
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            hrp.CFrame = targetCFrame
            if wasAbove and targetAirborne then
                hrp.AssemblyLinearVelocity = Vector3.new(0, math.clamp(tRoot.AssemblyLinearVelocity.Y, 0, 55), 0)
            else
                hrp.AssemblyLinearVelocity = Vector3.zero
            end
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    else
        if hrp.CFrame.LookVector:Dot(targetCFrame.LookVector) < 0.985 then
            pcall(function() hrp.CFrame = targetCFrame end)
        end
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    local cam = workspace.CurrentCamera
    if cam then
        pcall(function() cam.CFrame = CFrame.new(cam.CFrame.Position, tRoot.Position) end)
    end
    btpSwing()
end

local function btpStartLoop()
    FRHUB_BATTP.loopToken = FRHUB_BATTP.loopToken + 1
    if FRHUB_BATTP.conn then pcall(function() FRHUB_BATTP.conn:Disconnect() end) FRHUB_BATTP.conn = nil end
    FRHUB_BATTP.target = nil
    FRHUB_BATTP.nextSwingAt = 0
    FRHUB_BATTP.conn = RunServiceBTP.Heartbeat:Connect(btpV2Update)
end

local function btpStopLoop()
    FRHUB_BATTP.loopToken = FRHUB_BATTP.loopToken + 1
    if FRHUB_BATTP.conn then pcall(function() FRHUB_BATTP.conn:Disconnect() end) FRHUB_BATTP.conn = nil end
    FRHUB_BATTP.target = nil
    FRHUB_BATTP.nextSwingAt = 0
    FRHUB_BATTP.batRemote = nil
    FRHUB_BATTP.batRemoteBat = nil
    local char = LP_BTP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hrp then
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    btpRestoreAutoRotate(hum)
end

local function smartClearMover(root)
    if FRHUB_BATTP.smartMover then pcall(function() FRHUB_BATTP.smartMover:Destroy() end) FRHUB_BATTP.smartMover = nil end
    if FRHUB_BATTP.smartAttach then pcall(function() FRHUB_BATTP.smartAttach:Destroy() end) FRHUB_BATTP.smartAttach = nil end
    if root and root.Parent then
        pcall(function()
            local v = root.AssemblyLinearVelocity
            local flat = Vector3.new(v.X, 0, v.Z)
            if flat.Magnitude > 24 then flat = flat.Unit * 24 end
            root.AssemblyLinearVelocity = Vector3.new(flat.X, v.Y, flat.Z)
        end)
    end
end

local function smartEnsureMover(root, speed)
    if FRHUB_BATTP.smartMover and FRHUB_BATTP.smartMover.Parent == root and FRHUB_BATTP.smartMover:IsA("LinearVelocity") then
        return FRHUB_BATTP.smartMover
    end
    smartClearMover(root)
    FRHUB_BATTP.smartAttach = Instance.new("Attachment")
    FRHUB_BATTP.smartAttach.Name = "FRHUBSmartBatTpAttachment"
    FRHUB_BATTP.smartAttach.Parent = root
    FRHUB_BATTP.smartMover = Instance.new("LinearVelocity")
    FRHUB_BATTP.smartMover.Name = "FRHUBSmartBatTpVelocity"
    FRHUB_BATTP.smartMover.Attachment0 = FRHUB_BATTP.smartAttach
    FRHUB_BATTP.smartMover.RelativeTo = Enum.ActuatorRelativeTo.World
    FRHUB_BATTP.smartMover.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
    FRHUB_BATTP.smartMover.ForceLimitsEnabled = true
    FRHUB_BATTP.smartMover.ForceLimitMode = Enum.ForceLimitMode.PerAxis
    local maxForce = math.clamp(root.AssemblyMass * math.max(speed * 110, 3200), 300000, 10000000)
    FRHUB_BATTP.smartMover.MaxAxesForce = Vector3.new(maxForce, 0, maxForce)
    FRHUB_BATTP.smartMover.VectorVelocity = root.AssemblyLinearVelocity
    FRHUB_BATTP.smartMover.Enabled = true
    FRHUB_BATTP.smartMover.Parent = root
    return FRHUB_BATTP.smartMover
end

local function smartApplyMove(root, velocity, speed, dt, vertical)
    local char = root and root.Parent
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health <= 0 then return false end
    local hState = hum:GetState()
    if hum.PlatformStand or hState == Enum.HumanoidStateType.Physics
        or hState == Enum.HumanoidStateType.Ragdoll or hState == Enum.HumanoidStateType.FallingDown then
        smartClearMover(root)
        return false
    end
    local mover = smartEnsureMover(root, speed)
    local maxForce = mover.MaxAxesForce.X
    mover.MaxAxesForce = Vector3.new(maxForce, vertical and maxForce or 0, maxForce)
    local alpha = 1 - math.exp(-math.max(dt or 0.0166, 0) * 12)
    mover.VectorVelocity = mover.VectorVelocity:Lerp(velocity, alpha)
    return true
end

local function smartClosestRoot(position)
    local plr = btpFindClosest(position, nil)
    if not plr or not plr.Character then return nil end
    return plr.Character:FindFirstChild("HumanoidRootPart")
end

local function smartStop(returnToAnchor, syncVisual)
    FRHUB_BATTP.smartToken = FRHUB_BATTP.smartToken + 1
    local st = btpState()
    if st then st.smartBatTpEnabled = false end
    _G.FRHUB_SMART_BATTP_ACTIVE = false
    local char = LP_BTP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    smartClearMover(hrp)
    if FRHUB_BATTP.smartDriving then
        FRHUB_BATTP.smartDriving = false
        _G.FRHUB_BATTP_ACTIVE = false
        btpStopLoop()
    end
    if hrp and FRHUB_BATTP.smartAnchor and returnToAnchor then
        pcall(function() hrp.CFrame = FRHUB_BATTP.smartAnchor end)
    end
    if hum then
        btpRestoreAutoRotate(hum)
        pcall(function() hum:Move(Vector3.zero, false) end)
    end
    FRHUB_BATTP.smartAnchor = nil
    if syncVisual and st then
        if st.setSmartBatTpVisual then pcall(st.setSmartBatTpVisual, false) end
        if st.syncSmartFloatBtn then pcall(st.syncSmartFloatBtn, false) end
    end
end

_G.FRHUBStartBatTp = function()
    local st = btpState()
    if st and st.smartBatTpEnabled then
        st.smartBatTpEnabled = false
        if st.setSmartBatTpVisual then pcall(st.setSmartBatTpVisual, false) end
        smartStop(false, false)
    end
    if st then st.batTpEnabled = true end
    _G.FRHUB_BATTP_ACTIVE = true
    btpStartLoop()
end

_G.FRHUBStopBatTp = function()
    local st = btpState()
    if st then st.batTpEnabled = false end
    _G.FRHUB_BATTP_ACTIVE = false
    btpStopLoop()
end

_G.FRHUBStartSmartBatTp = function()
    local st = btpState()
    if st and st.batTpEnabled then
        st.batTpEnabled = false
        if st.setBatTpVisual then pcall(st.setBatTpVisual, false) end
        _G.FRHUB_BATTP_ACTIVE = false
        btpStopLoop()
    end
    smartStop(false, false)
    if st then st.smartBatTpEnabled = true end
    _G.FRHUB_SMART_BATTP_ACTIVE = true
    FRHUB_BATTP.smartToken = FRHUB_BATTP.smartToken + 1
    local token = FRHUB_BATTP.smartToken
    task.spawn(function()
        local lastEquipAt = 0
        local lastTick = os.clock()
        local chaseRoot, chaseDir = nil, nil
        while token == FRHUB_BATTP.smartToken and btpState() and btpState().smartBatTpEnabled do
            local char = LP_BTP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then
                local now = os.clock()
                if not char:FindFirstChildOfClass("Tool") and now - lastEquipAt > 0.4 then
                    btpGetBat()
                    lastEquipAt = now
                end
                local targetRoot = smartClosestRoot(hrp.Position)
                if targetRoot and chaseRoot and chaseRoot.Parent and chaseRoot ~= targetRoot then
                    local oldDist = (chaseRoot.Position - hrp.Position).Magnitude
                    if (targetRoot.Position - hrp.Position).Magnitude > oldDist * 0.65 then targetRoot = chaseRoot end
                end
                if targetRoot then
                    if targetRoot ~= chaseRoot then chaseRoot, chaseDir = targetRoot, nil end
                    local tHum = targetRoot.Parent and targetRoot.Parent:FindFirstChildOfClass("Humanoid")
                    local tVel = targetRoot.AssemblyLinearVelocity
                    local tFlat = Vector3.new(tVel.X, 0, tVel.Z)
                    if tFlat.Magnitude > 90 then tFlat = tFlat.Unit * 90 end
                    local now = os.clock()
                    local dt = math.max(now - lastTick, 1 / 240)
                    local desired
                    if tFlat.Magnitude > 0.75 then
                        desired = tFlat.Unit
                    else
                        local moveDir = tHum and tHum.MoveDirection or Vector3.zero
                        moveDir = Vector3.new(moveDir.X, 0, moveDir.Z)
                        if moveDir.Magnitude > 0.05 then desired = moveDir.Unit end
                    end
                    if desired then
                        if chaseDir then
                            if chaseDir:Dot(desired) < 0 then
                                chaseDir = desired
                            else
                                local blended = chaseDir:Lerp(desired, 0.38)
                                chaseDir = blended.Magnitude > 0.05 and blended.Unit or desired
                            end
                        else
                            chaseDir = desired
                        end
                    end
                    if not chaseDir then
                        local toTarget = targetRoot.Position - hrp.Position
                        local flatTo = Vector3.new(toTarget.X, 0, toTarget.Z)
                        chaseDir = flatTo.Magnitude > 0.001 and flatTo.Unit or Vector3.zero
                    end
                    if chaseDir then
                        local separation = hrp.Position - targetRoot.Position
                        local dist = separation.Magnitude
                        local st2 = btpState()
                        local stopDist = math.clamp(tonumber(st2 and st2.smartBatTpDistance) or 9, 1, 100)
                        if dist <= stopDist then
                            FRHUB_BATTP.smartAnchor = hrp.CFrame
                            smartClearMover(hrp)
                            pcall(function() hum:Move(Vector3.zero, false) end)
                            lastTick = now
                            if st2 and st2.smartBatTpAuto == false then
                                smartStop(true, true)
                                return
                            end
                            FRHUB_BATTP.smartDriving = true
                            _G.FRHUB_BATTP_ACTIVE = true
                            btpStartLoop()
                            return
                        end
                        local approach = dist > 0.001 and separation.Unit or Vector3.new(0, 1, 0)
                        local goal = targetRoot.Position + approach * stopDist
                        local toGoal = goal - hrp.Position
                        local flatGoal = Vector3.new(toGoal.X, 0, toGoal.Z)
                        local horiz = flatGoal.Magnitude > 0.001 and flatGoal.Unit or Vector3.zero
                        local dy = goal.Y - hrp.Position.Y
                        local vertical = math.abs(dy) > 0.75
                        local speed = math.clamp(tonumber(st2 and st2.smartBatTpSpeed) or 42, 15, 80)
                        local vy = vertical
                            and math.clamp(dy * 8 + math.clamp(hrp.AssemblyLinearVelocity.Y, -55, 55) * 0.65, -48, 62)
                            or 0
                        if smartApplyMove(hrp, Vector3.new(horiz.X * speed, vy, horiz.Z * speed), speed, dt, vertical) and horiz.Magnitude > 0 then
                            hum:Move(horiz, false)
                        end
                    end
                    lastTick = now
                end
            end
            RunServiceBTP.Heartbeat:Wait()
        end
        local char = LP_BTP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        smartClearMover(hrp)
        if hum then pcall(function() hum:Move(Vector3.zero, false) end) end
    end)
end

_G.FRHUBStopSmartBatTp = function()
    smartStop(false, true)
end

_G.FRHUB_AIMBOT_V8_ACTIVE = false
FRHUB_AIMBOT_V8 = { target = nil, targetPlayer = nil, swingCooldown = false, lastMode = nil, lastScan = 0, scanInterval = 0.12 }

local _frhV8Players = game:GetService("Players")
local _frhV8Run     = game:GetService("RunService")
local _frhV8LP      = _frhV8Players.LocalPlayer

local function frhubV8AimbotSpeed()
    local st = _G.FRHUB_STATE
    if st and (st.laggerActive == true or st.laggerCarryActive == true) then
        return tonumber(_G.AIMBOT_V3_LAGGER_SPEED) or 40
    end
    return tonumber(_G.AIMBOT_V3_SPEED) or 58
end

local function frhubV8AutoSwing()
    return autoSwingV3Enabled == true
end

local function frhubV8IsBypassMode()
    return (_G.FRHUB_STATE and _G.FRHUB_STATE.v8AimbotMode == "bypass") == true
end

local function frhubV8FindBat()
    local char = _frhV8LP.Character
    if not char then return nil end
    local equipped = char:FindFirstChildOfClass("Tool")
    if equipped then return equipped end
    for _, tool in ipairs(char:GetChildren()) do
        if tool:IsA("Tool") then
            local n = tool.Name:lower()
            if n:find("bat") or n:find("slap") then return tool end
        end
    end
    local bp = _frhV8LP:FindFirstChild("Backpack")
    if bp then
        for _, tool in ipairs(bp:GetChildren()) do
            if tool:IsA("Tool") then
                local n = tool.Name:lower()
                if n:find("bat") or n:find("slap") then return tool end
            end
        end
    end
    return nil
end

local function frhubV8EnsureBat(hum)
    local char = _frhV8LP.Character
    if not char or not hum then return nil end
    local equipped = char:FindFirstChildOfClass("Tool")
    if equipped then return equipped end
    local bat = frhubV8FindBat()
    if bat and bat.Parent ~= char then pcall(function() hum:EquipTool(bat) end) end
    return bat
end

local function frhubV8TargetPosition(player, part)
    local pos = part and part.Position
    if not pos then return nil, false end
    if _G.AmbitiousAntiVoid and player then
        local ok, gp, isGhost = pcall(function()
            return _G.AmbitiousAntiVoid.posFor(player, pos)
        end)
        if ok and typeof(gp) == "Vector3" then return gp, isGhost == true end
    end
    return pos, false
end

local function frhubV8ValidTarget(player, part)
    if not player or not part or not part.Parent then return false end
    local ch = player.Character
    if not ch or part.Parent ~= ch then return false end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    return hum and hum.Health > 0
end

local function frhubV8ScanClosest(root)
    if not root then return nil, nil, math.huge end
    local closest, closestPlayer, minDist = nil, nil, math.huge
    local myPos = root.Position
    for _, plr in ipairs(_frhV8Players:GetPlayers()) do
        if plr ~= _frhV8LP then
            local ch = plr.Character
            local tRoot = ch and ch:FindFirstChild("HumanoidRootPart")
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if tRoot and hum and hum.Health > 0 then
                local tPos = frhubV8TargetPosition(plr, tRoot)
                if tPos then
                    local dist = (tPos - myPos).Magnitude
                    if dist < minDist then
                        minDist, closest, closestPlayer = dist, tRoot, plr
                    end
                end
            end
        end
    end
    return closest, closestPlayer, minDist
end

local function frhubV8TrySwing(bat)
    if not frhubV8AutoSwing() or not bat or not bat:IsA("Tool") then return end
    local S = FRHUB_AIMBOT_V8
    if S.swingCooldown then return end
    S.swingCooldown = true
    pcall(function() bat:Activate() end)
    task.delay(0.08, function()
        if FRHUB_AIMBOT_V8 then FRHUB_AIMBOT_V8.swingCooldown = false end
    end)
end

_G.FRHUBStartAimbotV8 = function()
    pcall(function()
        if _G.FRHUB_AIMBOT_V4 and _G.FRHUB_AIMBOT_V4.enabled and _G.FRHUB_AIMBOT_V4.enabled() then _G.FRHUB_AIMBOT_V4.disable() end
        if _G.FRHUB_BYPASS_AIMBOT and _G.FRHUB_BYPASS_AIMBOT.enabled and _G.FRHUB_BYPASS_AIMBOT.enabled() then _G.FRHUB_BYPASS_AIMBOT.disable() end
