_frhV8Run.Heartbeat:Connect(function()
    if not _G.FRHUB_AIMBOT_V8_ACTIVE then return end
    if not FRHUB_AIMBOT_V8 then return end
    local char = _frhV8LP.Character
    if not char then return end
    local root = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not root or not hum or hum.Health <= 0 then return end

    local S = FRHUB_AIMBOT_V8
    local mode = frhubV8IsBypassMode() and "bypass" or "normal"
    if S.lastMode ~= mode then
        S.lastMode = mode
        S.target = nil
        S.targetPlayer = nil
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        pcall(function() _setV(root, Vector3.zero) end)
    end

    local now = os.clock()
    if (now - (S.lastScan or 0) >= (S.scanInterval or 0.12)) or not frhubV8ValidTarget(S.targetPlayer, S.target) then
        S.lastScan = now
        S.target, S.targetPlayer = frhubV8ScanClosest(root)
    end

    local target, targetPlayer = S.target, S.targetPlayer
    if not frhubV8ValidTarget(targetPlayer, target) then
        hum.AutoRotate = true
        root.AssemblyAngularVelocity = Vector3.zero
        root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(Vector3.zero, 0.35)
        return
    end

    hum.AutoRotate = false
    local bat = frhubV8EnsureBat(hum)
    local myPos = root.Position
    local targetPos, isGhost = frhubV8TargetPosition(targetPlayer, target)
    if not targetPos then return end
    local targetVel = isGhost and Vector3.zero or target.AssemblyLinearVelocity

    if mode == "bypass" then
        local direction = targetPos - myPos
        local flatDir = Vector3.new(direction.X, 0, direction.Z)
        flatDir = flatDir.Magnitude > 0 and flatDir.Unit or Vector3.zero
        local yVel = (targetPos.Y + 3.7 - myPos.Y) * 19.5
        if hum.FloorMaterial ~= Enum.Material.Air then yVel = math.max(yVel, 13) end
        yVel = math.clamp(yVel, -70, 110)
        root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(Vector3.new(flatDir.X * frhubV8AimbotSpeed(), yVel, flatDir.Z * frhubV8AimbotSpeed()), 0.8)
        local toTarget = targetPos - myPos
        if toTarget.Magnitude > 0.1 then
            local diffCF = root.CFrame:Inverse() * CFrame.lookAt(myPos, targetPos)
            local rx, ry, rz = diffCF:ToEulerAnglesXYZ()
            root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(math.clamp(rx, -2.5, 2.5) * 42, math.clamp(ry, -2.5, 2.5) * 42, math.clamp(rz, -2.5, 2.5) * 42))
        else
            root.AssemblyAngularVelocity = Vector3.zero
        end
        if flatDir.Magnitude > 0.1 then pcall(function() hum:Move(flatDir, false) end) end
        frhubV8TrySwing(bat)
        return
    end

    local predictPos = targetPos + targetVel * 0.14 + target.CFrame.LookVector * 0.3
    local direction = predictPos - myPos
    if direction.Magnitude < 0.01 then return end
    local flatDir = Vector3.new(direction.X, 0, direction.Z)
    if flatDir.Magnitude < 0.01 then return end
    flatDir = flatDir.Unit

    local yVel = (targetPos.Y + 3.7 - myPos.Y) * 19.5 + targetVel.Y * 0.8
    if hum.FloorMaterial ~= Enum.Material.Air then yVel = math.max(yVel, 13) end
    yVel = math.clamp(yVel, -70, 110)
    local speed = frhubV8AimbotSpeed()
    root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(Vector3.new(flatDir.X * speed, yVel, flatDir.Z * speed), 0.8)

    local predictedPos = targetPos + targetVel * math.clamp(targetVel.Magnitude / 150, 0.05, 0.2)
    local toPredict = predictedPos - myPos
    if toPredict.Magnitude > 0.1 then
        local diffCF = root.CFrame:Inverse() * CFrame.lookAt(myPos, predictedPos)
        local rx, ry, rz = diffCF:ToEulerAnglesXYZ()
        root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(math.clamp(rx, -2.5, 2.5) * 42, math.clamp(ry, -2.5, 2.5) * 42, math.clamp(rz, -2.5, 2.5) * 42))
    else
        root.AssemblyAngularVelocity = Vector3.zero
    end

    if flatDir.Magnitude > 0.1 then pcall(function() hum:Move(flatDir, false) end) end
    frhubV8TrySwing(bat)
end)

_G.FRHUB_AIMBOT_V9_ACTIVE = false
FRHUB_AIMBOT_V9 = { target = nil, targetPlayer = nil, swingCooldown = false, lastMode = nil, lastScan = 0, scanInterval = 0.12, previousAutoRotate = nil }

local _frhV9Players = game:GetService("Players")
local _frhV9Run     = game:GetService("RunService")
local _frhV9LP      = _frhV9Players.LocalPlayer

local function frhubV9AimbotSpeed()
    local st = _G.FRHUB_STATE
    if st and (st.laggerActive == true or st.laggerCarryActive == true) then
        return tonumber(_G.AIMBOT_V3_LAGGER_SPEED) or 40
    end
    return tonumber(_G.AIMBOT_V3_SPEED) or 58
end

local function frhubV9AutoSwing()
    return autoSwingV3Enabled == true
end

local function frhubV9IsBypassMode()
    return (_G.FRHUB_STATE and _G.FRHUB_STATE.v9AimbotMode == "bypass") == true
end

local function frhubV9FindBat()
    local char = _frhV9LP.Character
    if not char then return nil end
    local equipped = char:FindFirstChildOfClass("Tool")
    if equipped then return equipped end
    for _, tool in ipairs(char:GetChildren()) do
        if tool:IsA("Tool") then
            local n = tool.Name:lower()
            if n:find("bat") or n:find("slap") then return tool end
        end
    end
    local bp = _frhV9LP:FindFirstChild("Backpack")
    if bp then
        for _, tool in ipairs(bp:GetChildren()) do
            if tool:IsA("Tool") then
                local n = tool.Name:lower()
                if n:find("bat") or n:find("slap") then return tool end
            end
        end
    end
    return nil
end

local function frhubV9EnsureBat(hum)
    local char = _frhV9LP.Character
    if not char or not hum then return nil end
    local equipped = char:FindFirstChildOfClass("Tool")
    if equipped then return equipped end
    local bat = frhubV9FindBat()
    if bat and bat.Parent ~= char then pcall(function() hum:EquipTool(bat) end) end
    return bat
end

local function frhubV9ScanClosest(root)
    if not root then return nil, nil end
    local closest, closestPlayer, minDist = nil, nil, math.huge
    local myPos = root.Position
    for _, plr in ipairs(_frhV9Players:GetPlayers()) do
        if plr ~= _frhV9LP then
            local ch = plr.Character
            local tRoot = ch and ch:FindFirstChild("HumanoidRootPart")
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if tRoot and hum and hum.Health > 0 then
                local dist = (tRoot.Position - myPos).Magnitude
                if dist < minDist then
                    minDist, closest, closestPlayer = dist, tRoot, plr
                end
            end
        end
    end
    return closest, closestPlayer
end

local function frhubV9TrySwing(bat)
    if not frhubV9AutoSwing() or not bat or not bat:IsA("Tool") then return end
    local S = FRHUB_AIMBOT_V9
    if S.swingCooldown then return end
    S.swingCooldown = true
    pcall(function() bat:Activate() end)
    task.delay(0.08, function()
        if FRHUB_AIMBOT_V9 then FRHUB_AIMBOT_V9.swingCooldown = false end
    end)
end

_G.FRHUBStartAimbotV9 = function()
    pcall(function()
        if _G.FRHUB_AIMBOT_V4 and _G.FRHUB_AIMBOT_V4.enabled and _G.FRHUB_AIMBOT_V4.enabled() then _G.FRHUB_AIMBOT_V4.disable() end
        if _G.FRHUB_BYPASS_AIMBOT and _G.FRHUB_BYPASS_AIMBOT.enabled and _G.FRHUB_BYPASS_AIMBOT.enabled() then if not (State.aimbotV10Enabled == true) then _G.FRHUB_BYPASS_AIMBOT.disable() end end
        if _G.FRHUBStopAimbotV8 then pcall(_G.FRHUBStopAimbotV8) end if _G.FRHUBSyncFloatBtn then pcall(_G.FRHUBSyncFloatBtn, "aimbotV8", false) end
        if _G.FRHUBStopAimbotV6 then pcall(_G.FRHUBStopAimbotV6) end
    end)
    _G.FRHUB_AIMBOT_V9_ACTIVE = true
    if not FRHUB_AIMBOT_V9 then FRHUB_AIMBOT_V9 = { target = nil, targetPlayer = nil, swingCooldown = false, lastMode = nil, lastScan = 0, scanInterval = 0.12, previousAutoRotate = nil } end
    FRHUB_AIMBOT_V9.target = nil
    FRHUB_AIMBOT_V9.targetPlayer = nil
    FRHUB_AIMBOT_V9.swingCooldown = false
    FRHUB_AIMBOT_V9.lastMode = nil
    FRHUB_AIMBOT_V9.lastScan = 0
    FRHUB_AIMBOT_V9.previousAutoRotate = nil
    local hum = _frhV9LP.Character and _frhV9LP.Character:FindFirstChildOfClass("Humanoid")
    pcall(function()
        if hum then
            FRHUB_AIMBOT_V9.previousAutoRotate = hum.AutoRotate
            hum.AutoRotate = false
        end
    end)
    if _G.FRHUB_STATE then _G.FRHUB_STATE.aimbotV9Enabled = true end
    local st9 = _G.FRHUB_STATE
    if st9 then
        if st9.setAimbotV9Visual then pcall(st9.setAimbotV9Visual, true) end
    end
    if _G.FRHUBSyncFloatBtn then pcall(_G.FRHUBSyncFloatBtn, "aimbotV9", true) end
end

_G.FRHUBStopAimbotV9 = function()
    _G.FRHUB_AIMBOT_V9_ACTIVE = false
    FRHUB_AIMBOT_V9.target = nil
    FRHUB_AIMBOT_V9.targetPlayer = nil
    FRHUB_AIMBOT_V9.swingCooldown = false
    FRHUB_AIMBOT_V9.lastMode = nil
    local char = _frhV9LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if root then
        pcall(function() _setV(root, Vector3.zero) end)
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
        pcall(function()
            local cf0 = root.CFrame
            local lv = cf0.LookVector
            local flat = Vector3.new(lv.X, 0, lv.Z)
            local face = flat.Magnitude >= 0.01 and flat.Unit or Vector3.new(0, 0, -1)
            root.CFrame = CFrame.lookAt(cf0.Position, cf0.Position + face)
        end)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end
    if hum then
        hum.AutoRotate = FRHUB_AIMBOT_V9.previousAutoRotate ~= false
        hum.PlatformStand = false
        pcall(function() hum:Move(Vector3.zero, false) end)
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
    end
    FRHUB_AIMBOT_V9.previousAutoRotate = nil
    local st = _G.FRHUB_STATE
    if st then
        st.aimbotV9Enabled = false
        if st.setAimbotV9Visual then pcall(st.setAimbotV9Visual, false) end
        if _G.FRHUBSyncFloatBtn then pcall(_G.FRHUBSyncFloatBtn, "aimbotV9", false) end
    end
end


