                if _G.FRHUBSyncFloatBtn then pcall(_G.FRHUBSyncFloatBtn, "aimbotV9", false) end
            end)
        end
    end
    if _G.FRHUB_STATE then _G.FRHUB_STATE.aimbotV9Enabled = (_G.FRHUB_AIMBOT_V9_ACTIVE == true) end
    return _G.FRHUB_AIMBOT_V9_ACTIVE == true
end

