local mainGui = Instance.new("ScreenGui")
mainGui.Name = "FR_HUB_SPEED_OVERLAY"
mainGui.ResetOnSpawn = false
mainGui.Parent = game:GetService("CoreGui") 


local playerData = {}


local function createBillboard(player)
        if player == LocalPlayer then return end 
        
        local character = player.Character
        if not character then return end
        
        local head = character:WaitForChild("Head", 2)
        if not head then return end
        
        
        if playerData[player] and playerData[player].billboard then
                playerData[player].billboard:Destroy()
        end
        
        local bb = Instance.new("BillboardGui")
        bb.Name = "SpeedDisplay_" .. player.Name
        bb.Adornee = head
        bb.Size = UDim2.new(0, 200, 0, 50)
        bb.StudsOffset = Vector3.new(0, 2.8, 0)
        bb.AlwaysOnTop = true
        bb.MaxDistance = 200
        bb.Parent = mainGui
        
        local label = Instance.new("TextLabel")
        label.Size = UDim2.new(1, 0, 1, 0)
        label.BackgroundTransparency = 1
        label.Text = "SPEED: 0"
        label.TextColor3 = Color3.fromRGB(255, 255, 255)
        label.Font = Enum.Font.GothamBold
        label.TextSize = 9
        label.TextScaled = true
        label.TextStrokeTransparency = 0.5
        label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        label.Parent = bb
        
        
        local gradient = Instance.new("UIGradient")
        gradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 109, 25)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 109, 25))
        })
        gradient.Parent = label
        
        
        playerData[player] = {
                billboard = bb,
                label = label,
                gradient = gradient
        }
end


local function setupPlayer(player)
        if player == LocalPlayer then return end
        
        
        player.CharacterAdded:Connect(function(char)
                task.delay(0.3, function()
                        createBillboard(player)
                end)
        end)
        
        
        player.CharacterRemoving:Connect(function()
                if playerData[player] and playerData[player].billboard then
                        playerData[player].billboard:Destroy()
                        playerData[player] = nil
                end
        end)
        
        
        if player.Character then
                createBillboard(player)
        end
end


for _, player in ipairs(Players:GetPlayers()) do
        setupPlayer(player)
end


Players.PlayerAdded:Connect(setupPlayer)


Players.PlayerRemoving:Connect(function(player)
        if playerData[player] and playerData[player].billboard then
                playerData[player].billboard:Destroy()
        end
        playerData[player] = nil
end)



RunService.RenderStepped:Connect(function(dt)
        _frhubSpdAcc = (_frhubSpdAcc or 0) + (dt or 1/60)
        if _frhubSpdAcc < 0.085 then return end
        local acc = _frhubSpdAcc
        _frhubSpdAcc = 0
        for player, data in pairs(playerData) do
                if not data or not data.label then continue end
                
                local character = player.Character
                if not character then continue end
                
                local hrp = character:FindFirstChild("HumanoidRootPart")
                if not hrp then continue end
                
                
                local velocity = hrp.Velocity
                local horizontalSpeed = math.floor((velocity * Vector3.new(1, 0, 1)).Magnitude + 0.5)
                
                if data.lastSpeed ~= horizontalSpeed then
                        data.lastSpeed = horizontalSpeed
                        data.label.Text = tostring(horizontalSpeed) .. " :SPEED"
                end
                
                
                if data.gradient then
                        data.gradient.Rotation = (data.gradient.Rotation + 90 * acc) % 360
                end
        end
end)
end) end) 


