local function _alCleanChar(char)
    if not char then return end
    pcall(function()
        for _,child in ipairs(char:GetChildren()) do
            if child:IsA("Accessory") or child:IsA("Hat") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") or child:IsA("BodyColors") or child:IsA("CharacterMesh") then child:Destroy() end
        end
        for _,child in ipairs(char:GetDescendants()) do
            pcall(function()
                if child:IsA("ParticleEmitter") or child:IsA("Trail") or child:IsA("Beam") or child:IsA("PointLight") or child:IsA("SpotLight") or child:IsA("SurfaceLight") or child:IsA("Fire") or child:IsA("Smoke") or child:IsA("Sparkles") then child:Destroy()
                elseif child:IsA("BasePart") then child.CastShadow=false;child.Material=Enum.Material.Plastic;child.Reflectance=0 end
            end)
        end
    end)
    _alCleanedChars[char]=true
end
