local function findBestPart(myHRP)
    local TARGET_PARTS = {"HumanoidRootPart","Torso","UpperTorso","Head","LowerTorso"}
    local nearestHRP, nearestDist, bestPart = nil, math.huge, nil
    for _, p in Players:GetPlayers() do
        if p ~= LP and p.Character then
            local eh  = p.Character:FindFirstChild("HumanoidRootPart")
            local hum = p.Character:FindFirstChildOfClass("Humanoid")
            if eh and hum and hum.Health > 0 then
                local d = (eh.Position - myHRP.Position).Magnitude
                if d < nearestDist then
                    nearestDist = d; nearestHRP = eh
                    local closestPart, closestD = eh, d
                    for _, pName in ipairs(TARGET_PARTS) do
                        local part = p.Character:FindFirstChild(pName)
                        if part and part:IsA("BasePart") then
                            local pd = (part.Position - myHRP.Position).Magnitude
                            if pd < closestD then closestD = pd; closestPart = part end
                        end
                    end
                    bestPart = closestPart
                end
            end
        end
    end
    return nearestHRP, nearestDist, bestPart
end

local function _findBatV2()
    local char=LP.Character;if not char then return nil end
    for _,tool in ipairs(char:GetChildren()) do
        if tool:IsA("Tool") and (tool.Name:lower():find("bat") or tool.Name:lower():find("slap")) then return tool end
    end
    return nil
end
local function _getClosestTargetV2()
    local root=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart");if not root then return nil end
    local closest,minDist=nil,math.huge
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LP and plr.Character then
            local tRoot=plr.Character:FindFirstChild("HumanoidRootPart");local hum=plr.Character:FindFirstChildOfClass("Humanoid")
            if tRoot and hum and hum.Health>0 then local dist=(tRoot.Position-root.Position).Magnitude;if dist<minDist then minDist=dist;closest=tRoot end end
        end
    end
    return closest
end
local function startLock()
    local mode = (_G.FRHUB_STATE and _G.FRHUB_STATE.aimbotMode == "bypass") and "bypass" or "normal"
    if mode == "bypass" then
        if not _G.FRHUB_BYPASS_AIMBOT then return end
        if _G.FRHUB_AIMBOT_V4 and _G.FRHUB_AIMBOT_V4.enabled() then
            pcall(_G.FRHUB_AIMBOT_V4.disable)
        end
        if _G.FRHUB_BYPASS_AIMBOT.enabled() then
            _G.FRHUB_BYPASS_AIMBOT.disable()
        else
            _G.FRHUB_BYPASS_AIMBOT.enable()
        end
        Enabled_Lock = _G.FRHUB_BYPASS_AIMBOT.enabled()
    else
        if not _G.FRHUB_AIMBOT_V4 then return end
        if _G.FRHUB_BYPASS_AIMBOT and _G.FRHUB_BYPASS_AIMBOT.enabled() then
            pcall(_G.FRHUB_BYPASS_AIMBOT.disable)
        end
        if _G.FRHUB_AIMBOT_V4.enabled() then
            _G.FRHUB_AIMBOT_V4.disable()
        else
            _G.FRHUB_AIMBOT_V4.enable()
        end
        Enabled_Lock = _G.FRHUB_AIMBOT_V4.enabled()
    end
end
local function stopLock()
    if _G.FRHUB_AIMBOT_V4 then _G.FRHUB_AIMBOT_V4.disable() end
    if _G.FRHUB_BYPASS_AIMBOT then _G.FRHUB_BYPASS_AIMBOT.disable() end
    Enabled_Lock = false
end

do
    local MIRROR_TP_DROP_THRESHOLD = 3
    local MIRROR_TP_DOWN_Y = -7.00
    local mirrorTPTrackedRoot = nil
    local mirrorTPPreviousY = nil
    local mirrorTPLastTeleport = 0

    local function clearMirrorTPTracking()
        mirrorTPTrackedRoot = nil
        mirrorTPPreviousY = nil
    end

    local function getAimbotV4Target()
        local api = _G.FRHUB_AIMBOT_V4
        if api and api.enabled and api.getTarget and api.enabled() then
            local ok, target = pcall(api.getTarget)
            if ok and target and target.Parent then
                local targetHumanoid = target.Parent:FindFirstChildOfClass("Humanoid")
                if targetHumanoid and targetHumanoid.Health > 0 then return target end
            end
        end
        if _G.FRHUB_BYPASS_AIMBOT and _G.FRHUB_BYPASS_AIMBOT.enabled and _G.FRHUB_BYPASS_AIMBOT.enabled() then
            local myHRP = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if myHRP then
                local closest, minD = nil, math.huge
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP and p.Character then
                        local t = p.Character:FindFirstChild("HumanoidRootPart")
                        local h = p.Character:FindFirstChildOfClass("Humanoid")
                        if t and h and h.Health > 0 then
                            local d = (t.Position - myHRP.Position).Magnitude
                            if d < minD then minD = d; closest = t end
                        end
                    end
                end
                return closest
            end
        end
        return nil
    end

    local function mirrorTPTeleportDown()
        local character = LP.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if not root or not humanoid or humanoid.Health <= 0 then return end
        local now = tick()
        if now - mirrorTPLastTeleport < 0.08 then return end
        mirrorTPLastTeleport = now

        local _, yaw = root.CFrame:ToEulerAnglesYXZ()
        root.CFrame = CFrame.new(root.Position.X, MIRROR_TP_DOWN_Y, root.Position.Z)
            * CFrame.Angles(0, yaw, 0)

        root.Velocity = Vector3.zero
    end

    State.setMirrorTPDownEnabled = function(on)
        State.mirrorTPDownEnabled = on == true
        if not State.mirrorTPDownEnabled then clearMirrorTPTracking() end
        if State.setMirrorTPDownVisual then State.setMirrorTPDownVisual(State.mirrorTPDownEnabled) end
    end

    RunService.Heartbeat:Connect(function()
        if not State.mirrorTPDownEnabled then
            clearMirrorTPTracking()
            return
        end

        local target = getAimbotV4Target()
        if not target then
            clearMirrorTPTracking()
            return
        end

        local currentY = target.Position.Y
        if target ~= mirrorTPTrackedRoot then
            mirrorTPTrackedRoot = target
            mirrorTPPreviousY = currentY
            return
        end

        local previousY = mirrorTPPreviousY
        mirrorTPPreviousY = currentY
        if previousY and previousY - currentY >= MIRROR_TP_DROP_THRESHOLD then
            mirrorTPTeleportDown()
            mirrorTPPreviousY = target.Parent and target.Position.Y or nil
        end
    end)

    LP.CharacterAdded:Connect(clearMirrorTPTracking)
end

local function equipBatOnce()
    local char=LP.Character; if not char then return end
    local humanoid=char:FindFirstChildOfClass("Humanoid"); if not humanoid then return end
    if char:FindFirstChildOfClass("Tool") then return end
    local bat=char:FindFirstChild("bat") or char:FindFirstChild("Bat")
    if not bat then
        for _,tool in pairs(LP.Backpack:GetChildren()) do
            if tool:IsA("Tool") and tool.Name:lower()=="bat" then bat=tool; break end
        end
    end
    if bat then humanoid:EquipTool(bat) end
end



local function startBatSpam()
    BatSpamEnabled = true
    if SpamThread then return end
    local function _runSpamLoop()
        SpamThread = task.spawn(function()
            while BatSpamEnabled do
                pcall(function()
                    local char=LP.Character
                    if char then

                        local bat=char:FindFirstChild("bat") or char:FindFirstChild("Bat")
                        if bat and bat:IsA("Tool") and bat.Parent==char then
                            bat:Activate()
                            local hh=char:FindFirstChild("HumanoidRootPart")
                            if hh then
                                local _,nd,_=findBestPart(hh)
                                if nd and nd<6 then task.wait(0.02); if bat.Parent==char then bat:Activate() end end
                            end
                        end
                    end
                end)
                task.wait(SpamDelay/1000)
            end
            SpamThread=nil
        end)
    end
    _runSpamLoop()

    task.spawn(function()
        while BatSpamEnabled do
            task.wait(0.6)
            if BatSpamEnabled and not SpamThread then
                _runSpamLoop()
            end
        end
    end)
end

local function stopBatSpam()
    BatSpamEnabled=false
    if SpamThread then pcall(function() task.cancel(SpamThread) end); SpamThread=nil end
    if setBatSpam then setBatSpam(false) end
end

local function getCurrentSpeed()
    if State.laggerCarryActive then return State.laggerCarrySpeed
    elseif State.laggerActive  then return State.laggerSpeed
    else return State.speedType=="normal" and State.normalSpeed or State.carrySpeed end
end

local function getAutoMoveSpeed()
    local r3 = _G.Round3SpeedBooster
    if r3 and r3.Enabled then
        local useCarry = r3.ForceCarry == true or r3.CarryMode == true
        if useCarry then
            return tonumber(r3.CarrySpeed) or State.r3CarrySpeed or State.carrySpeed
        end
        return tonumber(r3.NormalSpeed) or State.r3NormalSpeed or State.normalSpeed
    end

    if State.laggerCarryActive then return State.normalSpeed
    elseif State.laggerActive  then return State.laggerSpeed
    else return State.normalSpeed end
end

refreshUIToggles = function()
    if setSpeedToggleUI then setSpeedToggleUI(State.speedType=="carry") end
    if setLaggerToggleUI then setLaggerToggleUI(State.laggerActive) end
    if modeValLbl then
        if State.laggerCarryActive then modeValLbl.Text="Lagger Carry"
        elseif State.laggerActive  then modeValLbl.Text="Lagger Normal"
        else modeValLbl.Text=(State.speedType=="normal") and "Normal" or "Carry" end
    end
end

