    while task.wait(5) do autoSaveConfig() end
end)

local function deactivateAllSpeedModes()
    if State.speedType=="carry" then
        State.speedType="normal"
        if MobileButtons.Buttons.carrySpeed then MobileButtons.Buttons.carrySpeed(false) end
        if setCarrySpeed then setCarrySpeed(false) end
    end
    if State.laggerActive then
        State.laggerActive=false
        if MobileButtons.Buttons.lagger then MobileButtons.Buttons.lagger(false) end
        if setLaggerNorm then setLaggerNorm(false) end
    end
    if State.laggerCarryActive then
        State.laggerCarryActive=false
        if MobileButtons.Buttons.laggerCarry then MobileButtons.Buttons.laggerCarry(false) end
        if setLaggerCarry then setLaggerCarry(false) end
    end
end

local function toggleSpeedType()
    if State.speedType=="carry" then
        State.speedType="normal"; refreshUIToggles(); autoSaveConfig()
        if MobileButtons.Buttons.carrySpeed then MobileButtons.Buttons.carrySpeed(false) end
        if setCarrySpeed then setCarrySpeed(false) end; return
    end
    deactivateAllSpeedModes(); State.speedType="carry"
    refreshUIToggles(); autoSaveConfig()
    if MobileButtons.Buttons.carrySpeed then MobileButtons.Buttons.carrySpeed(true) end
    if setCarrySpeed then setCarrySpeed(true) end
end

local function toggleLagger()
    if State.laggerActive then
        State.laggerActive=false
        refreshUIToggles(); autoSaveConfig()
        if MobileButtons.Buttons.lagger then MobileButtons.Buttons.lagger(false) end
        if setLaggerNorm then setLaggerNorm(false) end; return
    end
    deactivateAllSpeedModes(); State.laggerActive=true
    refreshUIToggles(); autoSaveConfig()
    if MobileButtons.Buttons.lagger then MobileButtons.Buttons.lagger(true) end
    if setLaggerNorm then setLaggerNorm(true) end
end

