do
local AutoSwitchV2 = {
    applied = false,
    graceUntil = 0,
    returnMode = nil,
}
local _autoSwitchV2NearAt = 0
local _autoSwitchV2NearValue = false
local _autoSwitchV2StealAttrWasActive = false

local function autoSwitchV2IsCarryName(name)
    local n = tostring(name or ""):lower()
    return n:find("brainrot") or n:find("animal") or n:find("carry")
        or n:find("grab") or n:find("steal") or n:find("hold")
end

local function autoSwitchV2IsIgnoredTool(name)
    local n = tostring(name or ""):lower()
    return n:find("bat") or n:find("slap") or n:find("medusa")
        or n:find("head") or n:find("stone")
end

local function autoSwitchV2IsCarrying(char)
    if not char then return false end
    for _, name in ipairs({"Carrying", "IsCarrying", "Grabbed", "Holding", "StealHold", "HasGrab"}) do
        local v = char:FindFirstChild(name, true)
        if v then
            if v:IsA("BoolValue") and v.Value then return true end
            if v:IsA("ObjectValue") and v.Value then return true end
            if v:IsA("StringValue") and v.Value ~= "" then return true end
        end
    end
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Model") and child:FindFirstChildWhichIsA("BasePart", true) then
            if child:FindFirstChildOfClass("Humanoid") and child:FindFirstChild("HumanoidRootPart") then
                return true
            end
            if autoSwitchV2IsCarryName(child.Name) then return true end
        elseif child:IsA("Tool") and not autoSwitchV2IsIgnoredTool(child.Name) then
            return true
        end
    end
    return false
end

local function autoSwitchV2IsNearBrainrot(char)
    if tick() - _autoSwitchV2NearAt < 0.15 then return _autoSwitchV2NearValue end
    _autoSwitchV2NearAt = tick()
    _autoSwitchV2NearValue = false
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("ProximityPrompt") then
            local holder = obj.Parent
            local part = holder and (holder:IsA("BasePart") and holder or holder:FindFirstAncestorWhichIsA("BasePart"))
            if part and (part.Position - root.Position).Magnitude <= 11 then
                _autoSwitchV2NearValue = true
                return true
            end
        end
    end
    return false
end

local function autoSwitchV2IsRagdolled(hum)
    if not hum then return true end
    local st = hum:GetState()
    return hum.PlatformStand
        or st == Enum.HumanoidStateType.Physics
        or st == Enum.HumanoidStateType.Ragdoll
        or st == Enum.HumanoidStateType.FallingDown
end

local function autoSwitchV2RefreshUI()
    refreshUIToggles()
    if setCarrySpeed then setCarrySpeed(State.speedType == "carry") end
    if setLaggerNorm then setLaggerNorm(State.laggerActive) end
    if setLaggerCarry then setLaggerCarry(State.laggerCarryActive) end
    if MobileButtons and MobileButtons.Buttons then
        if MobileButtons.Buttons.carrySpeed then MobileButtons.Buttons.carrySpeed(State.speedType == "carry") end
        if MobileButtons.Buttons.lagger then MobileButtons.Buttons.lagger(State.laggerActive) end
        if MobileButtons.Buttons.laggerCarry then MobileButtons.Buttons.laggerCarry(State.laggerCarryActive) end
    end
end

local function autoSwitchV2SetMode(mode)
    State.speedType = "normal"
    State.laggerActive = false
    State.laggerCarryActive = false
    if mode == "Carry" then
        State.speedType = "carry"
    elseif mode == "Lagger Normal" then
        State.laggerActive = true
    elseif mode == "Lagger Carry" then
        State.laggerCarryActive = true
    end
    autoSwitchV2RefreshUI()
end

local function autoSwitchV2EnableCarry()
    if not AutoSwitchV2.applied then
        if State.laggerCarryActive then
            AutoSwitchV2.returnMode = "Lagger Carry"
        elseif State.laggerActive then
            AutoSwitchV2.returnMode = "Lagger Normal"
        elseif State.speedType == "carry" then
            AutoSwitchV2.returnMode = "Carry"
        else
            AutoSwitchV2.returnMode = "Normal"
        end
    end
    AutoSwitchV2.applied = true
    AutoSwitchV2.graceUntil = tick() + 0.75
    if AutoSwitchV2.returnMode == "Lagger Normal" or AutoSwitchV2.returnMode == "Lagger Carry" then
        autoSwitchV2SetMode("Lagger Carry")
    else
        autoSwitchV2SetMode("Carry")
    end
end

local function autoSwitchV2DisableCarry()
    if not AutoSwitchV2.applied then return end
    local returnMode = AutoSwitchV2.returnMode or "Normal"
    AutoSwitchV2.applied = false
    AutoSwitchV2.graceUntil = 0
    AutoSwitchV2.returnMode = nil
    autoSwitchV2SetMode(returnMode)
end

State.stopAutoSwitchV2 = function()
    _autoSwitchV2StealAttrWasActive = false
    autoSwitchV2DisableCarry()
end

task.spawn(function()
    while true do
        task.wait(0.1)
        pcall(function()
            if not State.autoSwitchV2Enabled then return end
            local char = LP.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not char or not hum then return end

            if autoSwitchV2IsRagdolled(hum) then
                autoSwitchV2DisableCarry()
                return
            end

            local stealingAttr = LP:GetAttribute("Stealing") == true
            local nearBrainrot = autoSwitchV2IsNearBrainrot(char)
            local carryingBrainrot = autoSwitchV2IsCarrying(char) or nearBrainrot

            if nearBrainrot and not AutoSwitchV2.applied then
                autoSwitchV2EnableCarry()
            end
            if stealingAttr and not _autoSwitchV2StealAttrWasActive then
                autoSwitchV2EnableCarry()
            end
            _autoSwitchV2StealAttrWasActive = stealingAttr

            if carryingBrainrot and not AutoSwitchV2.applied then
                autoSwitchV2EnableCarry()
            end

            if AutoSwitchV2.applied then
                if tick() > AutoSwitchV2.graceUntil and not carryingBrainrot and not stealingAttr then
                    autoSwitchV2DisableCarry()
                end
            end
        end)
    end
end)

end

local function tpToGround(savedY)
    local char=LP.Character; if not char then return end
    local hrp=char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
    _G.FRHUB_TP_DOWN_UNTIL = os.clock() + 0.5
    local finalY = savedY or -7.00
    hrp.CFrame = CFrame.new(hrp.Position.X, finalY, hrp.Position.Z) * CFrame.Angles(0, select(2, hrp.CFrame:ToEulerAnglesYXZ()), 0)
    hrp.Velocity = Vector3.zero
end

function runDropBrainrot()
    if State.dropBrainrotActive then return end
    local char=LP.Character; if not char then return end
    local root=char:FindFirstChild("HumanoidRootPart"); if not root then return end
    State.dropBrainrotActive=true; _G.FRHUB_DROP_BR_ACTIVE = true; local t0=tick(); local dc
    dc=RunService.Heartbeat:Connect(function()
        local r=char and char:FindFirstChild("HumanoidRootPart")
        if not r then dc:Disconnect(); State.dropBrainrotActive=false; _G.FRHUB_DROP_BR_ACTIVE = false; return end
        if tick()-t0>=DROP_ASCEND_DURATION then
            dc:Disconnect()
            local rp=RaycastParams.new(); rp.FilterDescendantsInstances={char}; rp.FilterType=Enum.RaycastFilterType.Exclude
            local rr=workspace:Raycast(r.Position,Vector3.new(0,-2000,0),rp)
            if rr then
                local hum2=char:FindFirstChildOfClass("Humanoid")
                local off=(hum2 and hum2.HipHeight or 2)+(r.Size.Y/2)
                r.CFrame=CFrame.new(r.Position.X,rr.Position.Y+off,r.Position.Z); r.AssemblyLinearVelocity=Vector3.new(0,0,0)
            end
            State.dropBrainrotActive=false; _G.FRHUB_DROP_BR_ACTIVE = false; return
        end
        r.AssemblyLinearVelocity=Vector3.new(r.AssemblyLinearVelocity.X,DROP_ASCEND_SPEED,r.AssemblyLinearVelocity.Z)
    end)
end

local Anims={idle1="rbxassetid://133806214992291",idle2="rbxassetid://94970088341563",walk="rbxassetid://707897309",run="rbxassetid://707861613",jump="rbxassetid://116936326516985",fall="rbxassetid://116936326516985",climb="rbxassetid://116936326516985",swim="rbxassetid://116936326516985",swimidle="rbxassetid://116936326516985"}
