local AntiRagdollConns = {}
local function enableAntiRagdoll()
    for _, c in pairs(AntiRagdollConns) do c:Disconnect() end
    AntiRagdollConns = {}
    local char     = LP.Character or LP.CharacterAdded:Wait()
    local humanoid = char:WaitForChild("Humanoid")
    local root     = char:WaitForChild("HumanoidRootPart")
    local animator = humanoid:WaitForChild("Animator")
    pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,     false) end)
    pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown,  false) end)
    pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.GettingUp,    false) end)
    local recovering   = false
    local lastVelocity = Vector3.zero
    local lastMoveDir  = Vector3.zero
    local BAD_STATES = {
        [Enum.HumanoidStateType.Physics]     = true,
        [Enum.HumanoidStateType.Ragdoll]     = true,
        [Enum.HumanoidStateType.FallingDown] = true,
        [Enum.HumanoidStateType.GettingUp]   = true,
    }
    local function isRagdollState() return BAD_STATES[humanoid:GetState()] == true end
    local CARRY_ANIM_ID = "71186871415348"
    local function stopCarryAnim()
        for _, track in pairs(animator:GetPlayingAnimationTracks()) do
            local id = track.Animation and track.Animation.AnimationId or ""
            if id:find(CARRY_ANIM_ID, 1, true) then
                track:Stop(0)
            end
        end
    end
    local function cleanConstraints()
        for _, obj in pairs(char:GetDescendants()) do
            if obj:IsA("BallSocketConstraint") or obj:IsA("NoCollisionConstraint") or obj:IsA("HingeConstraint") then
                obj:Destroy()
            elseif obj:IsA("Attachment") and (obj.Name == "A" or obj.Name == "B") then
                obj:Destroy()
            elseif obj:IsA("BodyVelocity") or obj:IsA("BodyPosition") or obj:IsA("BodyGyro") then
                obj:Destroy()
            elseif obj:IsA("Motor6D") then
                obj.Enabled = true
            end
        end
        for _, track in pairs(animator:GetPlayingAnimationTracks()) do
            local name = (track.Animation and track.Animation.Name or ""):lower()
            if name:find("rag") or name:find("fall") or name:find("hurt") or name:find("down") then
                track:Stop(0)
            end
        end
        stopCarryAnim()
    end
    local function reEnableControls()
        pcall(function()
            local ctrl = require(LP:WaitForChild("PlayerScripts"):WaitForChild("PlayerModule")):GetControls()
            ctrl.Disable = function() end  
            ctrl:Enable()
        end)
    end
    local function startRecovery()
        if recovering then return end
        recovering = true
        task.spawn(function()
            local endTime = tick() + 0.5
            while tick() < endTime do
                if lastMoveDir.Magnitude > 0 then
                    pcall(function() humanoid:Move(lastMoveDir, false) end)
                end
                if isRagdollState() or humanoid:GetState() == Enum.HumanoidStateType.GettingUp then
                    cleanConstraints()
                    pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Running) end)
                    local _rv = root.AssemblyLinearVelocity
                    if _rv.Y > 2 then root.AssemblyLinearVelocity = Vector3.new(_rv.X, 0, _rv.Z) end
                    workspace.CurrentCamera.CameraSubject = humanoid
                end
                pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,    false) end)
                pcall(function() humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end)
                task.wait(0.02)
            end
            recovering = false
            if lastMoveDir.Magnitude > 0 then
                pcall(function() humanoid:Move(lastMoveDir, false) end)
            end
        end)
    end
    table.insert(AntiRagdollConns, humanoid.StateChanged:Connect(function(_, newState)
        if BAD_STATES[newState] then
            State.lastRagdollTick = tick()
            State.ragdollKilledCarry = true
            stopCarryAnim()
            startRecovery()
        end
    end))
    table.insert(AntiRagdollConns, RunService.Heartbeat:Connect(function()
        if isRagdollState() then
            State.lastRagdollTick = tick()
            State.ragdollKilledCarry = true
            startRecovery()
            local vel = root.AssemblyLinearVelocity
            if vel.Y > 10 then
                root.AssemblyLinearVelocity = Vector3.new(vel.X, 0, vel.Z)
            end
        else
            if humanoid.MoveDirection.Magnitude > 0 then
                lastMoveDir = humanoid.MoveDirection
            end
        end
        if recovering and lastMoveDir.Magnitude > 0 then
            pcall(function() humanoid:Move(lastMoveDir, false) end)
        end
        lastVelocity = root.AssemblyLinearVelocity
    end))
    table.insert(AntiRagdollConns, char.DescendantAdded:Connect(function(obj)
        if obj:IsA("BallSocketConstraint") or obj:IsA("NoCollisionConstraint")
        or obj:IsA("HingeConstraint") or obj:IsA("BodyVelocity")
        or obj:IsA("BodyPosition") or obj:IsA("BodyGyro") then
            task.defer(function() if obj and obj.Parent then obj:Destroy() end end)
        elseif obj:IsA("Motor6D") then
            task.defer(function() if obj and obj.Parent then obj.Enabled = true end end)
        end
    end))
    table.insert(AntiRagdollConns, LP.CharacterAdded:Connect(function(newChar)
        char      = newChar
        humanoid  = newChar:WaitForChild("Humanoid")
        root      = newChar:WaitForChild("HumanoidRootPart")
        animator  = humanoid:WaitForChild("Animator")
        lastVelocity = Vector3.zero
        recovering   = false
        reEnableControls()
        cleanConstraints()
        enableAntiRagdoll()
    end))
    reEnableControls()
    cleanConstraints()
end
enableAntiRagdoll()

local BAT_COUNTER_SLAP_LIST = {"Bat","Slap","Iron Slap","Gold Slap","Diamond Slap","Emerald Slap","Ruby Slap","Dark Matter Slap","Flame Slap","Nuclear Slap","Galaxy Slap","Glitched Slap"}
local batCounterConn = nil
local function findBatForCounter()
    local c = LP.Character; if not c then return nil end
    local bp = LP:FindFirstChildOfClass("Backpack")
    for _, name in ipairs(BAT_COUNTER_SLAP_LIST) do
        local t = c:FindFirstChild(name) or (bp and bp:FindFirstChild(name))
        if t then return t end
    end
    for _, ch in ipairs(c:GetChildren()) do if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end end
    if bp then for _, ch in ipairs(bp:GetChildren()) do if ch:IsA("Tool") and ch.Name:lower():find("bat") then return ch end end end
    return nil
end
local function swingBatForCounter(bat, char)
    local hum2 = char:FindFirstChildOfClass("Humanoid")
    if bat.Parent ~= char then if hum2 then pcall(function() hum2:EquipTool(bat) end) end; task.wait(0.05) end
    local remote = bat:FindFirstChildOfClass("RemoteEvent") or bat:FindFirstChildOfClass("RemoteFunction")
    if remote and remote:IsA("RemoteEvent") then
        pcall(function() remote:FireServer() end); task.wait(0.15); pcall(function() remote:FireServer() end)
    else pcall(function() bat:Activate() end); task.wait(0.15); pcall(function() bat:Activate() end) end
end
local function startBatCounter()
    if batCounterConn then return end
    batCounterConn = RunService.Heartbeat:Connect(function()
        if not State.batCounterEnabled then return end
        if State.batCounterDebounce then return end
        local char = LP.Character; if not char then return end
        local hum2 = char:FindFirstChildOfClass("Humanoid"); if not hum2 then return end
        local st = hum2:GetState()
        local isRag = st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.FallingDown
        if isRag then
            State.batCounterDebounce = true
            task.spawn(function()
                pcall(function()
                    local h2 = char:FindFirstChild("HumanoidRootPart")
                    if h2 then
                        local bn, bd2 = nil, math.huge
                        for _, p2 in ipairs(Players:GetPlayers()) do
                            if p2 ~= LP then
                                local pc2 = p2.Character
                                if pc2 then
                                    local ph2 = pc2:FindFirstChild("HumanoidRootPart") or pc2:FindFirstChild("Head")
                                    local pm2 = pc2:FindFirstChildOfClass("Humanoid")
                                    if ph2 and pm2 and pm2.Health > 0 then
                                        local d2 = (ph2.Position - h2.Position).Magnitude
                                        if d2 < bd2 then bd2 = d2; bn = ph2 end
                                    end
                                end
                            end
                        end
                        if bn then
                            local ft2 = Vector3.new(bn.Position.X - h2.Position.X, 0, bn.Position.Z - h2.Position.Z)
                            if ft2.Magnitude > 0.01 then
                                h2.CFrame = CFrame.new(h2.Position, h2.Position + ft2)
                            end
                        end
                    end
                end)
                local bat = findBatForCounter()
                if bat then swingBatForCounter(bat, char) end
                task.wait(0.5); State.batCounterDebounce = false
            end)
        end
    end)
end
local function stopBatCounter()
    if batCounterConn then batCounterConn:Disconnect(); batCounterConn = nil end
    State.batCounterDebounce = false
end

local function findMedusa()
    local char=LP.Character; if not char then return nil end
    for _,tool in ipairs(char:GetChildren()) do if tool:IsA("Tool") then local tn=tool.Name:lower()
        if tn:find("medusa") or tn:find("head") or tn:find("stone") then return tool end end end
    local bp2=LP:FindFirstChild("Backpack")
    if bp2 then for _,tool in ipairs(bp2:GetChildren()) do if tool:IsA("Tool") then local tn=tool.Name:lower()
        if tn:find("medusa") or tn:find("head") or tn:find("stone") then return tool end end end end
    return nil
end
local function useMedusaCounter()
    if State.medusaDebounce then return end; if tick()-State.medusaLastUsed<25 then return end
    local char=LP.Character; if not char then return end; State.medusaDebounce=true
    local med=findMedusa(); if not med then State.medusaDebounce=false; return end
    if med.Parent~=char then local hum2=char:FindFirstChildOfClass("Humanoid"); if hum2 then hum2:EquipTool(med) end end
    pcall(function() med:Activate() end); State.medusaLastUsed=tick(); State.medusaDebounce=false
end
local function onAnchorChanged(part)
    return part:GetPropertyChangedSignal("Anchored"):Connect(function() if part.Anchored and part.Transparency==1 then useMedusaCounter() end end)
end
setupMedusaCounter = function(char)
    stopMedusaCounter(); if not char then return end
    for _,part in ipairs(char:GetDescendants()) do if part:IsA("BasePart") then table.insert(Conns.anchor,onAnchorChanged(part)) end end
    table.insert(Conns.anchor,char.DescendantAdded:Connect(function(part) if part:IsA("BasePart") then table.insert(Conns.anchor,onAnchorChanged(part)) end end))
end
stopMedusaCounter = function() for _,c in pairs(Conns.anchor) do pcall(function() c:Disconnect() end) end; Conns.anchor={} end

local function createShimmerBorder(parent, speed, thickness)
    thickness = thickness or 2.5
    local stroke = Instance.new("UIStroke")
    stroke.Thickness = thickness
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Color = Color3.fromRGB(240, 103, 24)
    stroke.Transparency = 0.35
    stroke.Parent = parent
    return stroke, nil
end

local function createGlassGradient(lbl, speed)
    local grad = Instance.new("UIGradient")
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromRGB(220, 94, 22)),
        ColorSequenceKeypoint.new(0.50, Color3.fromRGB(235,205,255)),
        ColorSequenceKeypoint.new(1,   Color3.fromRGB(220, 94, 22)),
    })
    grad.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.25), NumberSequenceKeypoint.new(0.50, 0.0), NumberSequenceKeypoint.new(1, 0.25),
    })
    grad.Rotation = 90; grad.Parent = lbl
    return grad
end

local function addBgTex(parent, transparency, radius)
    local img=Instance.new("ImageLabel",parent)
    img.Size=UDim2.new(1,0,1,0); img.BackgroundTransparency=1; img.Image=BG_TEX
    img.ImageTransparency=transparency or 0.88; img.ScaleType=Enum.ScaleType.Crop; img.ZIndex=1
    if radius then Instance.new("UICorner",img).CornerRadius=UDim.new(0,radius) end
    return img
end

