    btn.TextSize = 9
    btn.TextWrapped = true
    btn.ZIndex = 5
    tabBtns[name] = btn; createGlassGradient(btn)
end

local function switchTab(name)
    if activeTab == name then return end
    if activeTab then
        tabPages[activeTab].Visible = false
        TweenService:Create(tabBtns[activeTab],
            TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
            {TextColor3 = C_DIM}):Play()
    end
    activeTab = name
    for i, n in ipairs(TAB_NAMES) do
        if n == name then
            local yPos = (i - 1) * TAB_H
            TweenService:Create(tabPill,
                TweenInfo.new(0.28, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                {Position = UDim2.new(0, 3, 0, yPos + 3)}):Play()
            break
        end
    end
    tabPages[name].Visible = true
    TweenService:Create(tabBtns[name],
        TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
        {TextColor3 = C_WHITE}):Play()
end

for _,name in ipairs(TAB_NAMES) do
    local n=name; local _tt=0
    local function _doTab() if tick()-_tt<0.2 then return end; _tt=tick(); switchTab(n) end
    tabBtns[n].Activated:Connect(_doTab); tabBtns[n].MouseButton1Click:Connect(_doTab)
end

local rowOrders={}; for _,n in ipairs(TAB_NAMES) do rowOrders[n]=0 end
local function LO(n) rowOrders[n]=rowOrders[n]+1; return rowOrders[n] end

local function makeRow(tabName, h)
    local row=Instance.new("Frame",tabPages[tabName])
    row.Size=UDim2.new(1,0,0,h or 36); row.BackgroundColor3=C_ROW; row.BorderSizePixel=0; row.LayoutOrder=LO(tabName)
    Instance.new("UICorner",row).CornerRadius=UDim.new(0,7); createShimmerBorder(row,2,1.2); addBgTex(row,0.92,7)
    return row
end

local function makeRowLabel(row, text, widthScale)
    local lbl=Instance.new("TextLabel",row)
    lbl.Size=UDim2.new(widthScale or 0.58,0,1,0); lbl.Position=UDim2.new(0,8,0,0)
    lbl.BackgroundTransparency=1; lbl.Text=text; lbl.TextColor3=C_ACCENT
    lbl.Font=Enum.Font.GothamBold; lbl.TextSize=11; lbl.TextXAlignment=Enum.TextXAlignment.Left; lbl.ZIndex=3
    createGlassGradient(lbl); return lbl
end

local function makePill(row, defOn)
    local PW2,PH2,DW=38,18,13; local DON=-(DW+3); local DOFF=3
    local pill=Instance.new("Frame",row)
    pill.Size=UDim2.new(0,PW2,0,PH2); pill.Position=UDim2.new(1,-(PW2+7),0.5,-PH2/2)
    pill.BackgroundColor3=defOn and C_ON_BG or C_OFF_BG; pill.BorderSizePixel=0; pill.ZIndex=4
    Instance.new("UICorner",pill).CornerRadius=UDim.new(1,0); createShimmerBorder(pill,4,1.0)
    local dot=Instance.new("Frame",pill)
    dot.Size=UDim2.new(0,DW,0,DW); dot.Position=defOn and UDim2.new(1,DON,0.5,-DW/2) or UDim2.new(0,DOFF,0.5,-DW/2)
    dot.BackgroundColor3=defOn and C_WHITE or C_DIM; dot.BorderSizePixel=0; dot.ZIndex=5
    Instance.new("UICorner",dot).CornerRadius=UDim.new(1,0); createShimmerBorder(dot,6,0.8)
    local isOn=defOn or false
    local function setV(on)
        isOn=on
        TweenService:Create(pill,TweenInfo.new(0.18,Enum.EasingStyle.Quad),{BackgroundColor3=on and C_ON_BG or C_OFF_BG}):Play()
        TweenService:Create(dot,TweenInfo.new(0.18,Enum.EasingStyle.Back),{Position=on and UDim2.new(1,DON,0.5,-DW/2) or UDim2.new(0,DOFF,0.5,-DW/2),BackgroundColor3=on and C_WHITE or C_DIM}):Play()
    end
    return setV, pill, dot, function() return isOn end
end

local function makeToggleRow(tabName, label, defOn, onToggle)
    local row=makeRow(tabName,30)
    makeRowLabel(row,label)
    local setV, pill, dot, getIsOn = makePill(row, defOn)
    local _ct=0
    local function _fn()
        if tick()-_ct<0.2 then return end; _ct=tick()
        local newOn=not getIsOn(); setV(newOn)
        if onToggle then pcall(onToggle,newOn) end
        autoSaveConfig()
    end
    row.InputBegan:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.MouseButton1 then
            task.defer(_fn)
        end
    end)
    pill.InputBegan:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
            task.defer(_fn)
        end
    end)
    return setV
end

local function makeToggleRowKB(tabName, label, kbStateKey, defOn, onToggle)
    local row=makeRow(tabName,30)
    makeRowLabel(row,label,0.42)
    local curKey=State[kbStateKey]
    local kbBtn=Instance.new("TextButton",row)
    kbBtn.Size=UDim2.new(0,44,0,16); kbBtn.Position=UDim2.new(1,-100,0.5,-8)
    kbBtn.BackgroundColor3=Color3.fromRGB(65, 27, 6); kbBtn.BorderSizePixel=0
    kbBtn.Text=(curKey and curKey~=Enum.KeyCode.Unknown) and curKey.Name or "-"
    kbBtn.TextColor3=C_ACCENT2; kbBtn.Font=Enum.Font.GothamBold; kbBtn.TextSize=8; kbBtn.AutoButtonColor=false; kbBtn.ZIndex=7
    Instance.new("UICorner",kbBtn).CornerRadius=UDim.new(0,4); createShimmerBorder(kbBtn,3,1.0)
    local kbListening=false; local kbConn=nil
    local function kbStop(key)
        kbListening=false; if kbConn then kbConn:Disconnect(); kbConn=nil end
        kbBtn.TextColor3=C_ACCENT2
        if key then State[kbStateKey]=key; kbBtn.Text=key.Name; autoSaveConfig() end
    end
    local _kbt=0
    kbBtn.MouseButton1Click:Connect(function()
        if tick()-_kbt<0.3 then return end; _kbt=tick()
        if kbListening then kbStop(nil); return end
        kbListening=true; kbBtn.Text="···"; kbBtn.TextColor3=Color3.fromRGB(255,220,0)
        kbConn=UIS.InputBegan:Connect(function(inp,_gp)
            if not kbListening then return end
            if inp.UserInputType==Enum.UserInputType.Keyboard then
                if inp.KeyCode==Enum.KeyCode.Escape then kbStop(nil); return end; kbStop(inp.KeyCode)
            elseif inp.UserInputType==Enum.UserInputType.Gamepad1 then kbStop(inp.KeyCode) end
        end)
    end)
    kbBtn.Activated:Connect(function() end)
    local setV, pill, dot, getIsOn = makePill(row, defOn)
    local _ct=0
    local function _fn()
        if tick()-_ct<0.2 then return end; _ct=tick()
        local newOn=not getIsOn(); setV(newOn)
        if onToggle then pcall(onToggle,newOn) end
        autoSaveConfig()
    end
    row.InputBegan:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.MouseButton1 then
            if inp.Position.X < kbBtn.AbsolutePosition.X - 5 then
                task.defer(_fn)
            end
        end
    end)
    pill.InputBegan:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
            task.defer(_fn)
        end
    end)
    return setV, kbBtn
end

local function makeInputRow(tabName, label, default, onChange)
    local row=makeRow(tabName,27)
    makeRowLabel(row,label,0.55)
    local box=Instance.new("TextBox",row)
    box.Size=UDim2.new(0,68,0,22); box.Position=UDim2.new(1,-74,0.5,-11)
    box.BackgroundColor3=Color3.fromRGB(65, 27, 6); box.BorderSizePixel=0
    box.Text=tostring(default); box.TextColor3=C_ACCENT; box.Font=Enum.Font.GothamBold; box.TextSize=12; box.ClearTextOnFocus=true; box.ZIndex=4
    Instance.new("UICorner",box).CornerRadius=UDim.new(0,5); createShimmerBorder(box,3,1.0)
    box.FocusLost:Connect(function()
        local n=tonumber(box.Text)
        if n then local v=math.clamp(n,0,9999); box.Text=tostring(v); if onChange then pcall(onChange,tostring(v)) end; autoSaveConfig()
        else box.Text=tostring(default) end
    end)
    return box
end

