    createGlassGradient(val); return val
end

local function hitTest(frame, pos)
    if not frame or not frame.Parent then return false end
    if not frame.Visible then return false end
    local ap=frame.AbsolutePosition; local as=frame.AbsoluteSize
    return pos.X>=ap.X and pos.X<=ap.X+as.X and pos.Y>=ap.Y and pos.Y<=ap.Y+as.Y
end

local function makeActionBtn(tabName, label, onClick)
    local btn=Instance.new("Frame",tabPages[tabName])
    btn.Size=UDim2.new(1,0,0,24); btn.BackgroundColor3=C_PANEL; btn.BorderSizePixel=0
    btn.LayoutOrder=LO(tabName)
    Instance.new("UICorner",btn).CornerRadius=UDim.new(0,7); createShimmerBorder(btn,4,1.2); createGlassGradient(btn); addBgTex(btn,0.88,7)
    local lbl2=Instance.new("TextLabel",btn)
    lbl2.Size=UDim2.new(1,0,1,0); lbl2.BackgroundTransparency=1; lbl2.Text=label
    lbl2.TextColor3=C_WHITE; lbl2.Font=Enum.Font.GothamBold; lbl2.TextSize=10; lbl2.ZIndex=3
    local _bt=0
    local function _fn()
        if tick()-_bt<0.05 then return end; _bt=tick()
        TweenService:Create(btn,TweenInfo.new(0.08),{BackgroundColor3=C_BORDER2}):Play()
        task.delay(0.16,function() TweenService:Create(btn,TweenInfo.new(0.12),{BackgroundColor3=C_PANEL}):Play() end)
        if onClick then pcall(onClick) end
    end
    UIS.InputBegan:Connect(function(inp)
        if inp.UserInputType~=Enum.UserInputType.Touch and inp.UserInputType~=Enum.UserInputType.MouseButton1 then return end
        if hitTest(btn, inp.Position) then _fn() end
    end)
    return btn
end

