makeSectionLabel("SPEED","Speed Modes")
task.spawn(function()
    while true do
        task.wait(0.1)
        pcall(function()
            if not State.autoCarrySpdEnabled then _wasCarry=false; return end
            local char=LP.Character; if not char then return end
            local h=char:FindFirstChildOfClass("Humanoid"); if not h then return end
            local isCarry = h.WalkSpeed < 25
            if isCarry == _wasCarry then return end
            _wasCarry = isCarry
            local wantCarry = isCarry
