    end)
    makeSectionLabel("COMBAT","Special")
    do
        local _alvOn = false
        local _alvBAV = nil
        local _alvConn = nil
        local _alvMConns = {}
        local function _alvStop2()
            _alvOn = false
            if _alvConn then pcall(function() _alvConn:Disconnect() end); _alvConn = nil end
            if _alvBAV then pcall(function() _alvBAV:Destroy() end); _alvBAV = nil end
            for _,c in ipairs(_alvMConns) do pcall(function() c:Disconnect() end) end; _alvMConns = {}
        end
        local function _alvStart2()
            local char = LP.Character; if not char then return end
            local hrp = char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
            if _alvBAV then pcall(function() _alvBAV:Destroy() end) end
            _alvBAV = Instance.new("BodyAngularVelocity")
            _alvBAV.MaxTorque = Vector3.new(0, math.huge, 0)
            _alvBAV.AngularVelocity = Vector3.zero
            _alvBAV.P = 1e5
            _alvBAV.Parent = hrp
            if _alvConn then pcall(function() _alvConn:Disconnect() end) end
            _alvConn = RunService.Heartbeat:Connect(function()
                if not _alvOn then return end
                pcall(function()
                    local ch = LP.Character; if not ch then return end
                    local h = ch:FindFirstChild("HumanoidRootPart"); if not h then return end
                    if not _alvBAV or not _alvBAV.Parent then return end
                    local best, bd = nil, math.huge
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= LP then
                            local pc = p.Character
                            if pc then
                                local ph = pc:FindFirstChild("HumanoidRootPart") or pc:FindFirstChild("Head")
                                local pm = pc:FindFirstChildOfClass("Humanoid")
                                if ph and pm and pm.Health > 0 then
                                    local d = (ph.Position - h.Position).Magnitude
                                    if d < bd then bd = d; best = ph end
                                end
                            end
                        end
                    end
                    if not best then _alvBAV.AngularVelocity = Vector3.zero; return end
                    local lv = h.CFrame.LookVector
                    local ft = Vector3.new(best.Position.X - h.Position.X, 0, best.Position.Z - h.Position.Z)
                    if ft.Magnitude < 0.01 then return end
                    local td = ft.Unit
                    local dot = math.clamp(lv:Dot(td), -1, 1)
                    local ang = math.acos(dot)
                    if ang < 0.05 then
                        _alvBAV.AngularVelocity = Vector3.zero
                    elseif ang > 0.001 then
                        local cr = lv:Cross(td)
                        local mg = cr.Magnitude
                        if mg > 0.001 then _alvBAV.AngularVelocity = (cr / mg) * math.min(ang * 10, 30) end
                    else _alvBAV.AngularVelocity = Vector3.zero end
                end)
            end)
            for _,c in ipairs(_alvMConns) do pcall(function() c:Disconnect() end) end; _alvMConns = {}
            local function _alvOnMed(part)
                if part.Anchored and part.Transparency == 1 then
                    pcall(useMedusaCounter)
                    local _unconn
                    _unconn = part:GetPropertyChangedSignal("Anchored"):Connect(function()
                        if not part.Anchored then
                            pcall(function() _unconn:Disconnect() end)
                            if _alvOn then task.defer(_alvStart2) end
                        end
                    end)
                    table.insert(_alvMConns, _unconn)
                end
            end
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") then
                    table.insert(_alvMConns, part:GetPropertyChangedSignal("Anchored"):Connect(function() _alvOnMed(part) end))
                end
            end
            table.insert(_alvMConns, char.DescendantAdded:Connect(function(part)
                if part:IsA("BasePart") then
                    table.insert(_alvMConns, part:GetPropertyChangedSignal("Anchored"):Connect(function() _alvOnMed(part) end))
                end
            end))
        end
        State.alvRestart = function()
            if _alvOn then
                for _,c in ipairs(_alvMConns) do pcall(function() c:Disconnect() end) end; _alvMConns = {}
                task.defer(_alvStart2)
            end
        end
        State.setAlwaysLookEnabled = function(on)
            on = on == true
            State.alwaysLookEnabled = on
            _alvOn = on
            if State.setAlwaysLookVisual then State.setAlwaysLookVisual(on) end
            if on then _alvStart2() else _alvStop2() end
        end
        State.setAlwaysLookVisual = makeToggleRow("COMBAT","ALWAYS LOOK AT VICTIM",State.alwaysLookEnabled,function(on)
            State.setAlwaysLookEnabled(on)
            autoSaveConfig()
        end)
    end
    do
        local _spBAV = nil
        local _spMConns = {}
        local function _spStop()
            if _spBAV then pcall(function() _spBAV:Destroy() end); _spBAV = nil end
            for _,c in ipairs(_spMConns) do pcall(function() c:Disconnect() end) end; _spMConns = {}
        end
        local function _spStart()
            local h = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if not h then return end
            if _spBAV then pcall(function() _spBAV:Destroy() end) end
            _spBAV = Instance.new("BodyAngularVelocity")
            _spBAV.MaxTorque = Vector3.new(0, math.huge, 0)
            _spBAV.AngularVelocity = Vector3.new(0, 25, 0)
            _spBAV.P = 1e5
            _spBAV.Parent = h
            for _,c in ipairs(_spMConns) do pcall(function() c:Disconnect() end) end; _spMConns = {}
            local ch = h.Parent
            if ch then
                local function _spOnMed(part)
                    if part.Anchored and part.Transparency == 1 then
                        pcall(useMedusaCounter)
                        local _unconn
                        _unconn = part:GetPropertyChangedSignal("Anchored"):Connect(function()
                            if not part.Anchored then
                                pcall(function() _unconn:Disconnect() end)
                                if _spBAV then task.defer(_spStart) end
                            end
                        end)
                        table.insert(_spMConns, _unconn)
                    end
                end
                for _, part in ipairs(ch:GetDescendants()) do
                    if part:IsA("BasePart") then
                        table.insert(_spMConns, part:GetPropertyChangedSignal("Anchored"):Connect(function() _spOnMed(part) end))
                    end
                end
                table.insert(_spMConns, ch.DescendantAdded:Connect(function(part)
                    if part:IsA("BasePart") then
                        table.insert(_spMConns, part:GetPropertyChangedSignal("Anchored"):Connect(function() _spOnMed(part) end))
                    end
                end))
            end
        end
        State.spRestart = function()
            if _spBAV then
                _spBAV = nil
                for _,c in ipairs(_spMConns) do pcall(function() c:Disconnect() end) end; _spMConns = {}
                task.defer(_spStart)
            end
        end
        State.setSpinBotEnabled = function(on)
            on = on == true
            State.spinBotEnabled = on
            if State.setSpinBotVisual then State.setSpinBotVisual(on) end
            if on then _spStart() else _spStop() end
        end
        State.setSpinBotVisual = makeToggleRow("COMBAT","SPIN BOT",State.spinBotEnabled,function(on)
            State.setSpinBotEnabled(on)
            autoSaveConfig()
        end)
    end
    local _cc
    _cc = makeToggleRow("COMBAT","CROSSHAIR CUSTOMIZER",false,function(on)
        if not on then return end
        task.spawn(function() pcall(function()
            loadstring(game:HttpGet("https://pastefy.app/jFgJE6JH/raw"))()
        end) end)
        task.delay(0.4, function() if _cc then pcall(_cc, false) end end)
    end)



do
