    local afRoot           = nil
    local afAttachment     = nil
    local afLinearVelocity = nil
    local afFixing         = false
    local afFixUntil       = 0
    local afEnabled        = false
    local afConn           = nil

    local function AntiFlingWhitelisted()
        if _G.FRHUB_INSTA_RESET_ACTIVE == true then return true end
        if _G.FRHUB_DROP_BR_ACTIVE == true then return true end
        if _G.FRHUB_AIMBOT_V4_ACTIVE == true then return true end
        if _G.FRHUB_AIMBOT_V6_ACTIVE == true then return true end
        if _G.FRHUB_SMART_BATTP_ACTIVE == true then return true end
        if _G.FRHUB_BATTP_ACTIVE == true then return true end
        if _G.FRHUB_AUTO_TP_DOWN_ACTIVE == true then return true end
        if _G.FRHUB_AUTO_TP_DOWN_CARRY_ACTIVE == true then return true end
        if (_G.FRHUB_TP_DOWN_UNTIL or 0) > os.clock() then return true end
        return false
    end

    local function AntiFlingWhitelistButtons()
        if State.autoBatToggled == true then return "AIMBOT V4" end
        if State.frhubAimbotPanelEnabled == true then return "ONYX HUB AIMBOT PANEL" end
        if State.tpDownAimbotEnabled == true then return "TP DOWN AIMBOT" end
        if State.oldAimbotEnabled == true then return "OLD AIMBOT" end
        if State.antiBatPanelEnabled == true then return "ANTI BAT UNDETECTED" end
        if _G.FRHUB_ANTI_BAT_ACTIVE == true then return "ANTI BAT (V1-V4)" end
        if State.autoTpDownEnabled == true then return "AUTO TP DOWN" end
        if _G.FRHUB_DROP_BR_NOMOVE_ACTIVE == true then return "DROP BR (NO MOVE)" end
        if _G.FRHUB_DROP_BR_ACTIVE == true then return "DROP BR" end
        if _G.FRHUB_INSTA_RESET_ACTIVE == true then return "INSTA RESET" end
        if (_G.FRHUB_TP_DOWN_UNTIL or 0) > os.clock() then return "TP DOWN" end
        if _G.FRHUB_AIMBOT_V4_ACTIVE == true then return "AIMBOT V4 ENGINE" end
        if _G.FRHUB_AIMBOT_V6_ACTIVE == true then return (_G.FRHUB_STATE and _G.FRHUB_STATE.v6AimbotMode == "bypass") and "AIMBOT V6 (BYPASS MODE)" or "AIMBOT V6 ENGINE" end
        if _G.FRHUB_AIMBOT_V8_ACTIVE == true then return (_G.FRHUB_STATE and _G.FRHUB_STATE.v8AimbotMode == "bypass") and "AIMBOT V8 (BYPASS MODE)" or "AIMBOT V8 ENGINE" end
        if _G.FRHUB_AIMBOT_V9_ACTIVE == true then return (_G.FRHUB_STATE and _G.FRHUB_STATE.v9AimbotMode == "bypass") and "AIMBOT V9 (BYPASS MODE)" or "AIMBOT V9 ENGINE" end
        if _G.FRHUB_SMART_BATTP_ACTIVE == true then return "SMART BAT TP" end
        if _G.FRHUB_BATTP_ACTIVE == true then return "BAT TP" end
        if _G.ZAIROS_AIMBOT_Running == true then return "TP DOWN AIMBOT ENGINE" end
        if _G.FRHUB_Merged_Running == true then return "OLD AIMBOT ENGINE" end
        if _G.FRHUB_AUTO_TP_DOWN_ACTIVE == true then return "AUTO TP DOWN ENGINE" end
        if _G.FRHUB_AUTO_TP_DOWN_CARRY_ACTIVE == true then return "AUTO TP DOWN (CARRY)" end
        return nil
    end

    local function SetupCharacter(char)
        afCharacter = char
        afRoot = char:WaitForChild("HumanoidRootPart", 10)
        if not afRoot then return end

        afAttachment = afRoot:FindFirstChild("AntiFlingAttachment")
        if not afAttachment then
            afAttachment = Instance.new("Attachment")
            afAttachment.Name = "AntiFlingAttachment"
            afAttachment.Parent = afRoot
        end

        afLinearVelocity = afRoot:FindFirstChild("AntiFlingLinearVelocity")
        if not afLinearVelocity then
            afLinearVelocity = Instance.new("LinearVelocity")
            afLinearVelocity.Name = "AntiFlingLinearVelocity"
            afLinearVelocity.Attachment0 = afAttachment
            afLinearVelocity.RelativeTo = Enum.ActuatorRelativeTo.World
            afLinearVelocity.VectorVelocity = Vector3.zero
            afLinearVelocity.MaxForce = math.huge
            afLinearVelocity.Enabled = false
            afLinearVelocity.Parent = afRoot
        end

        afFixing = false
        afFixUntil = 0
    end

    local function StartFix()
        if not afRoot or not afLinearVelocity then return end
        afFixing = true
        afFixUntil = os.clock() + FixTime
        afLinearVelocity.VectorVelocity = Vector3.zero
        afLinearVelocity.Enabled = true
    end

    local function StopFix()
        if afLinearVelocity then afLinearVelocity.Enabled = false end
        afFixing = false
    end

    if af_LP.Character then
        task.spawn(SetupCharacter, af_LP.Character)
    end

    af_LP.CharacterAdded:Connect(function(char)
        task.wait(0.2)
        SetupCharacter(char)
    end)

    afConn = af_RunSvc.Heartbeat:Connect(function()
        if not afEnabled then
            if afFixing then StopFix() end
            return
        end
        if AntiFlingWhitelistButtons() or AntiFlingWhitelisted() then
            if afFixing then StopFix() end
            return
        end
        if not afRoot or not afRoot.Parent or not afLinearVelocity then
            return
        end

        if afFixing then
            if os.clock() >= afFixUntil then
                StopFix()
            else
                afLinearVelocity.VectorVelocity = Vector3.zero
            end
            return
        end

        local LinearSpeed  = afRoot.AssemblyLinearVelocity.Magnitude
        local AngularSpeed = afRoot.AssemblyAngularVelocity.Magnitude

        if LinearSpeed >= LinearThreshold or AngularSpeed >= AngularThreshold then
            StartFix()
        end
    end)

    State.setAntiFlingEnabled = function(on)
        on = on == true
        State.antiFlingEnabled = on
        if State.setAntiFlingVisual then State.setAntiFlingVisual(on) end
        afEnabled = on
        if not on and afFixing then StopFix() end
    end
    State.setAntiFlingVisual = makeToggleRow("MECH","ANTI FLING",State.antiFlingEnabled,function(on)
        State.setAntiFlingEnabled(on)
        autoSaveConfig()
    end)
end
do
    State.setAntiLagBackVisual = makeToggleRow("MECH","ANTI LAG BACK",State.antiLagBackEnabled,function(on)
        if State.setAntiLagBackEnabled then State.setAntiLagBackEnabled(on) else State.antiLagBackEnabled = on == true end
        autoSaveConfig()
    end)
end
