    local function _stopDropBRNoMoveFn()
        _dropBRNoMoveFnDB.A = false
        _G.FRHUB_DROP_BR_NOMOVE_ACTIVE = false
        for _, c in ipairs(_dropBRNoMoveFnDB.X) do
            pcall(function() if typeof(c) == "RBXScriptConnection" then c:Disconnect() end end)
        end
        _dropBRNoMoveFnDB.X = {}
    end
    local function _doDropBRNoMoveFn()
        if _dropBRNoMoveFnDB.A then return end
        _dropBRNoMoveFnDB.A = true
        _G.FRHUB_DROP_BR_NOMOVE_ACTIVE = true
        table.insert(_dropBRNoMoveFnDB.X, RunService.Stepped:Connect(function()
            if not _dropBRNoMoveFnDB.A then return end
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP and p.Character then
                    for _, a in ipairs(p.Character:GetChildren()) do
                        if a:IsA("BasePart") then a.CanCollide = false end
                    end
                end
            end
        end))
        local _nmH = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        task.spawn(function()
            while _dropBRNoMoveFnDB.A do
                RunService.Heartbeat:Wait()
                _nmH = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                if _nmH then
                    local v0 = _nmH.Velocity
                    local dv = v0 * 500 + Vector3.new(0, 2000, 0)
                    if dv.Magnitude > 10000 then dv = dv.Unit * 10000 end
                    _nmH.Velocity = dv
                    RunService.RenderStepped:Wait()
                    if _nmH and _nmH.Parent then _nmH.Velocity = v0 end
                    RunService.Stepped:Wait()
                    if _nmH and _nmH.Parent then _nmH.Velocity = v0 + Vector3.new(0, 0.1, 0) end
                end
            end
        end)
        task.delay(0.4, function()
            _stopDropBRNoMoveFn()
            task.wait(0.15)
            local _nh = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if _nh and _nh.Parent then _nh.Velocity = Vector3.new(0, _nh.Velocity.Y, 0) end
        end)
    end

