    _dBtnNM.Font = Enum.Font.GothamBold
    _dBtnNM.TextSize = 8
    _dBtnNM.AutoButtonColor = false
    _dBtnNM.ZIndex = 4
    Instance.new("UICorner", _dBtnNM).CornerRadius = UDim.new(0, 4)
