    local function _setDropBRMode(mode)
        State.dropBRModeKey = mode
        _dBtnMv.BackgroundColor3  = (mode == "MOVE")   and C_ON_BG or Color3.fromRGB(65, 27, 6)
        _dBtnMv.TextColor3        = (mode == "MOVE")   and C_WHITE or C_DIM
        _dBtnNM.BackgroundColor3  = (mode == "NOMOVE") and C_ON_BG or Color3.fromRGB(65, 27, 6)
        _dBtnNM.TextColor3        = (mode == "NOMOVE") and C_WHITE or C_DIM
