    _dBtnNM.Activated:Connect(function() _setDropBRMode(State.dropBRModeKey == "NOMOVE" and nil or "NOMOVE") end)

    _dropBRDispatch = _doDropBRNoMoveFn

    _G.FRHUB_DROP_BR_DISPATCH = function()
