end

do
    local CARRY_DROP_AIM_ANIM_ID = "71186871415348"
    local carryDropAimWasPlaying = false
    local carryDropAimLastTrigger = 0
    local carryDropAimSequenceActive = false

    local function isCarryDropAimAnimationPlaying()
        local character = LP.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not animator then return false end

        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            local animation = track.Animation
            local animationId = animation and animation.AnimationId or ""
            if string.find(animationId, CARRY_DROP_AIM_ANIM_ID, 1, true) then
                return true
            end
        end
        return false
    end

    local function isAimbotV4ButtonActive()
        if not State.autoBatToggled then return false end
        local api = _G.FRHUB_AIMBOT_V4
        if not api or type(api.enabled) ~= "function" then return false end
        local ok, enabled = pcall(api.enabled)
        return ok and enabled == true
    end

    local function recentlyRagdolled()
        return State.ragdollKilledCarry == true
    end

    local function stopCarryAnimNow()
        local character = LP.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
        if not animator then return end
        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
            local animation = track.Animation
            local animationId = animation and animation.AnimationId or ""
            if string.find(animationId, CARRY_DROP_AIM_ANIM_ID, 1, true) then
                track:Stop(0)
            end
        end
    end

    local function hasDetectedCarryState()
        local character = LP.Character
        if not character then return false end
        for _, name in ipairs({"Carrying", "IsCarrying", "Grabbed", "Holding", "StealHold", "HasGrab"}) do
            local v = character:FindFirstChild(name, true)
            if v then
                if v:IsA("BoolValue") and v.Value then return true end
                if v:IsA("ObjectValue") and v.Value then return true end
                if v:IsA("StringValue") and v.Value ~= "" then return true end
            end
        end
        return false
    end

    local function runDropAction()
        if State.dropBRModeKey == "NOMOVE" and _dropBRDispatch then
            _dropBRDispatch()
        else
            runDropBrainrot()
        end
    end

    local DROP_CONFIRM_STABLE_HEARTBEATS = 3
    local DROP_RETRY_INTERVAL = 0.75

    local function triggerDropThenAimbotV4()
        local now = tick()
        if carryDropAimSequenceActive then return end
        if now - carryDropAimLastTrigger < 0.75 then return end
        carryDropAimLastTrigger = now
        carryDropAimSequenceActive = true

        State.autoBatToggled = false
        if setAutoBat then setAutoBat(false) end
        if MobileButtons.Buttons.autoBat then MobileButtons.Buttons.autoBat(false) end
        Enabled_Lock = false
        pcall(stopLock)

        local requireCarryStateClear = hasDetectedCarryState()

        runDropAction()
        if MobileButtons.Buttons.dropBR then
            MobileButtons.Buttons.dropBR(true)
            task.delay(0.5, function()
                if MobileButtons.Buttons.dropBR then MobileButtons.Buttons.dropBR(false) end
            end)
        end

        task.spawn(function()
            local stableClearHeartbeats = 0
            local lastDropAttemptAt = tick()
            while carryDropAimSequenceActive do
                RunService.Heartbeat:Wait()

                local dropMotionFinished = State.dropBrainrotActive ~= true
                local carryAnimationCleared = not isCarryDropAimAnimationPlaying()
                local carryStateCleared = not requireCarryStateClear or not hasDetectedCarryState()

                if dropMotionFinished and carryAnimationCleared and carryStateCleared then
                    stableClearHeartbeats = stableClearHeartbeats + 1
                else
                    stableClearHeartbeats = 0
                end

                if stableClearHeartbeats >= DROP_CONFIRM_STABLE_HEARTBEATS then
                    State.autoBatToggled = true
                    if setAutoBat then setAutoBat(true) end
                    if MobileButtons.Buttons.autoBat then MobileButtons.Buttons.autoBat(true) end
                    equipBatOnce()
                    Enabled_Lock = true

                    local api = _G.FRHUB_AIMBOT_V4
                    if api and api.enable then
                        pcall(api.enable)
                    else
                        pcall(startLock)
                    end
                    carryDropAimSequenceActive = false
                    autoSaveConfig()
                    return
                end

                local now2 = tick()
                if State.dropBrainrotActive ~= true and now2 - lastDropAttemptAt >= DROP_RETRY_INTERVAL then
                    lastDropAttemptAt = now2
                    runDropAction()
                end
            end
        end)
    end

    local carryAnimPrev = false

    RunService.Heartbeat:Connect(function()
        if carryDropAimSequenceActive then
            carryDropAimWasPlaying = isCarryDropAimAnimationPlaying()
            carryAnimPrev = carryDropAimWasPlaying
            return
        end

        local isPlaying = isCarryDropAimAnimationPlaying()

        if isPlaying and not carryAnimPrev then
            State.ragdollKilledCarry = false
        end
        carryAnimPrev = isPlaying

        if not isAimbotV4ButtonActive() then
            carryDropAimWasPlaying = false
            return
        end

        if recentlyRagdolled() then
            stopCarryAnimNow()
            carryDropAimWasPlaying = false
            return
        end

        if isPlaying and not carryDropAimWasPlaying then
            triggerDropThenAimbotV4()
        end
        carryDropAimWasPlaying = isPlaying
    end)
end

makeSectionLabel("MOVE","Teleport")
_G._FRHUBZigZagSide = _G._FRHUBZigZagSide or 1
_G._FRHUBSlowFallActive = false
_G._FRHUBTPDownJumpLocked = false
State.getGroundTPY = function(char, hrp, hum)
    local MAX_DISTANCE, MAX_STEPS = 4000, 12
    local ws = game:GetService("Workspace")
    local excludeFilter = (function()
        local ok, v = pcall(function() return Enum.RaycastFilterType.Exclude end)
        if ok and v then return v end
        local ok2, v2 = pcall(function() return Enum.RaycastFilterType.Blacklist end)
        if ok2 then return v2 end
        return nil
    end)()
    local function standOffset()
        local half = 1
        pcall(function() half = hrp.Size.Y * 0.5 end)
        if half <= 0 then half = 1 end
        local off = half * 3
        pcall(function()
            if hum and hum.RigType == Enum.HumanoidRigType.R6 then
                off = half * 3
            elseif hum then
                off = half + (hum.HipHeight or (half * 2))
            end
        end)
        if off ~= off or off < 1 or off > 12 then off = half * 3 end
        return off + 0.15
    end
    local function rayDown(fromY, x, z, filter)
        local params = RaycastParams.new()
        params.FilterDescendantsInstances = filter
        if excludeFilter then params.FilterType = excludeFilter end
        params.IgnoreWater = true
        pcall(function() params.RespectCanCollide = true end)
        local res
        pcall(function()
            res = ws:Raycast(Vector3.new(x, fromY, z), Vector3.new(0, -MAX_DISTANCE, 0), params)
        end)
        return res
    end
    char = char or LP.Character
    if not char then return nil end
    hrp = hrp or char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end
    hum = hum or char:FindFirstChildOfClass("Humanoid")
    local filter = {char}
    pcall(function()
        for _, plr in ipairs(game:GetService("Players"):GetPlayers()) do
            if plr ~= LP and plr.Character then
                table.insert(filter, plr.Character)
            end
        end
    end)
    local origin = hrp.Position
    local halfY = 1
    pcall(function() halfY = hrp.Size.Y * 0.5 end)
    local startY = origin.Y - halfY - 0.1
    local groundY = nil
    for _ = 1, MAX_STEPS do
        local res = rayDown(startY, origin.X, origin.Z, filter)
        if not res then break end
        local part = res.Instance
        local skip = false
        if part then
            pcall(function()
                if part:IsA("BasePart") and part.CanCollide == false then skip = true end
                local model = part:FindFirstAncestorOfClass("Model")
                if model and model:FindFirstChildOfClass("Humanoid") then skip = true end
            end)
        else
            skip = true
        end
        if skip then
            if part then table.insert(filter, part) end
            startY = res.Position.Y - 0.05
        else
            groundY = res.Position.Y
            break
        end
    end
    if not groundY then return nil end
    return groundY + standOffset()
end
State.resolveTPDownY = function(char, hrp, hum)
    local ok, y = pcall(State.getGroundTPY, char, hrp, hum)
    if ok and type(y) == "number" then return y end
    return -7.00
end
State.waitGroundUnlockJump = function()
    task.spawn(function()
        local groundDeadline = os.clock() + 8
        while os.clock() < groundDeadline do
            local c2 = LP.Character
            local h2 = c2 and c2:FindFirstChildOfClass("Humanoid")
            if not h2 or h2.Health <= 0 then break end
            if h2.FloorMaterial ~= Enum.Material.Air then break end
            RunService.Heartbeat:Wait()
        end
        _G._FRHUBTPDownJumpLocked = false
    end)
end
State.zigzagFall = function()
    if _G._FRHUBSlowFallActive then return end
    _G._FRHUBSlowFallActive = true
    _G._FRHUBTPDownJumpLocked = true
    local zigVec = nil
    _G._FRHUBZigZagFalling = false
    _G._FRHUBZigZagSide = (_G._FRHUBZigZagSide == -1) and 1 or -1
    local ch = LP.Character
    local hr = ch and ch:FindFirstChild("HumanoidRootPart")
    if hr then
        local rv = hr.CFrame.RightVector
        local flat = Vector3.new(rv.X, 0, rv.Z)
        if flat.Magnitude > 0.001 then
            local spd = getCurrentSpeed() or 16
            zigVec = flat.Unit * spd * _G._FRHUBZigZagSide
            _G._FRHUBZigZagFalling = true
        end
    end
    task.spawn(function()
        local POWER = zigVec and 50 or 115
        local deadline = os.clock() + 6
        local landed = false
        while os.clock() < deadline do
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then break end
            if hum.FloorMaterial ~= Enum.Material.Air then landed = true break end
            local proxy = _G._jumpEnsureProxy and _G._jumpEnsureProxy() or nil
            local part = proxy or hrp
            local v = part.Velocity
            if zigVec then
                part.Velocity = Vector3.new(zigVec.X, -POWER, zigVec.Z)
            else
                part.Velocity = Vector3.new(v.X, -POWER, v.Z)
            end
            RunService.Heartbeat:Wait()
        end
        if not landed then
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local proxy = _G._jumpEnsureProxy and _G._jumpEnsureProxy() or nil
            if proxy then
                local v = proxy.Velocity
                pcall(function() proxy.Velocity = Vector3.new(v.X, 0, v.Z) end)
            elseif hrp then
                local v = hrp.Velocity
                pcall(function() hrp.Velocity = Vector3.new(v.X, 0, v.Z) end)
            end
        end
        _G._FRHUBSlowFallActive = false
        _G._FRHUBZigZagFalling = false
        local groundDeadline = os.clock() + 8
        while os.clock() < groundDeadline do
            local c2 = LP.Character
            local h2 = c2 and c2:FindFirstChildOfClass("Humanoid")
            if not h2 or h2.Health <= 0 then break end
            if h2.FloorMaterial ~= Enum.Material.Air then break end
            RunService.Heartbeat:Wait()
        end
        _G._FRHUBTPDownJumpLocked = false
    end)
end
State.tpDownExecute = function(char, hrp, hum2, force)
    local mode = State.autoTpDownMode
    if mode == "ZIGZAG" or mode == "NORMAL" then
        local targetY = State.resolveTPDownY(char, hrp, hum2)
        if not force and (hrp.Position.Y - targetY) < 0.75 then return end
        if mode == "ZIGZAG" then
            State.zigzagFall()
            return
        end
        hrp.CFrame = CFrame.new(hrp.Position.X, targetY, hrp.Position.Z) * CFrame.Angles(0, select(2, hrp.CFrame:ToEulerAnglesYXZ()), 0)
        hrp.AssemblyLinearVelocity = Vector3.zero
        _G._FRHUBTPDownJumpLocked = true
        State.waitGroundUnlockJump()
        return
    end
    hrp.CFrame=CFrame.new(hrp.Position.X,-7.00,hrp.Position.Z)*CFrame.Angles(0,select(2,hrp.CFrame:ToEulerAnglesYXZ()),0)
    hrp.Velocity = Vector3.zero
end
do
    local function _doATP(force)
        local char=LP.Character; if not char then return end
        local hrp=char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
        local hum2=char:FindFirstChildOfClass("Humanoid"); if not hum2 then return end
        if not force then
            if hum2.FloorMaterial~=Enum.Material.Air then return end
            if not(hrp.Position.Y>=State.autoTpDownY) then return end
        end
        State.tpDownExecute(char, hrp, hum2, force)
    end
    State.startAutoTpDown=function()
        _G.FRHUB_AUTO_TP_DOWN_ACTIVE = true
        if State.autoTpDownConn then pcall(function() task.cancel(State.autoTpDownConn) end); State.autoTpDownConn=nil end
        State.autoTpDownConn=task.spawn(function()
            while State.autoTpDownEnabled do task.wait(0.1); pcall(function() _doATP(false) end) end
        end)
    end
    State.stopAutoTpDown=function()
        State.autoTpDownEnabled=false
        _G.FRHUB_AUTO_TP_DOWN_ACTIVE = false
        if State.autoTpDownConn then pcall(function() task.cancel(State.autoTpDownConn) end); State.autoTpDownConn=nil end
    end
end
setAutoTpDown, _ = makeToggleRowKB("MOVE","Auto TP Down","keyAutoTp",false,function(on)
    State.autoTpDownEnabled=on
    if on then State.startAutoTpDown() else State.stopAutoTpDown() end
end)
autoTpDownYBox = makeInputRow("MOVE","Y Trigger",State.autoTpDownY,function(v) local n=tonumber(v); if n then State.autoTpDownY=n end end)
do
    local function _doATPCarry(force)
        local char=LP.Character; if not char then return end
        local hrp=char:FindFirstChild("HumanoidRootPart"); if not hrp then return end
        local hum2=char:FindFirstChildOfClass("Humanoid"); if not hum2 then return end
        
        local isCarry=false
        local anim=hum2:FindFirstChildOfClass("Animator")
        if anim then for _,t in ipairs(anim:GetPlayingAnimationTracks()) do if t.Animation.AnimationId:find("71186871415348") then isCarry=true;break end end end
        if not isCarry then return end
        if not force then
            if hum2.FloorMaterial~=Enum.Material.Air then return end
            if not(hrp.Position.Y>=State.autoTpDownY) then return end
        end
        State.tpDownExecute(char, hrp, hum2, force)
    end
    local function startATPCarry()
        _G.FRHUB_AUTO_TP_DOWN_CARRY_ACTIVE = true
        if State.autoTpDownCarryConn then pcall(function() task.cancel(State.autoTpDownCarryConn) end); State.autoTpDownCarryConn=nil end
        State.autoTpDownCarryConn=task.spawn(function()
            while State.autoTpDownCarryEnabled do task.wait(0.1); pcall(function() _doATPCarry(false) end) end
        end)
    end
    State.startATPCarry = startATPCarry
    local function stopATPCarry()
        State.autoTpDownCarryEnabled=false
        _G.FRHUB_AUTO_TP_DOWN_CARRY_ACTIVE = false
        if State.autoTpDownCarryConn then pcall(function() task.cancel(State.autoTpDownCarryConn) end); State.autoTpDownCarryConn=nil end
    end
    do
        local row=makeRow("MOVE",30)
        makeRowLabel(row,"Auto TP Down (Carry)",0.70)
        local lbl=row:FindFirstChildOfClass("TextLabel")
        if lbl then lbl.TextSize=8; lbl.TextWrapped=true end
        local setV, pill, dot, getIsOn = makePill(row, State.autoTpDownCarryEnabled)
        local _ct=0
        local function _fn()
            if tick()-_ct<0.2 then return end; _ct=tick()
            local newOn=not getIsOn(); setV(newOn)
            State.autoTpDownCarryEnabled=newOn
            if newOn then startATPCarry() else stopATPCarry() end
            autoSaveConfig()
        end
        row.InputBegan:Connect(function(inp)
            if inp.UserInputType==Enum.UserInputType.MouseButton1 then
                task.defer(_fn)
            end
        end)
        pill.InputBegan:Connect(function(inp)
            if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
                task.defer(_fn)
            end
        end)
        setAutoTpDownCarry = setV
    end
end
State.buildTpDownModeSelector = function()
    local title = Instance.new("TextLabel", tabPages["MOVE"])
    title.Size = UDim2.new(1, 0, 0, 14)
    title.BackgroundTransparency = 1
    title.LayoutOrder = LO("MOVE")
    title.Text = "AUTO TP DOWN & AUTO TP DOWN (CARRY) MODES"
    title.TextColor3 = C_ACCENT
    title.Font = Enum.Font.GothamBold
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextScaled = true
    local sizeLimit = Instance.new("UITextSizeConstraint", title)
    sizeLimit.MaxTextSize = 8
    sizeLimit.MinTextSize = 5
    local row = makeRow("MOVE", 28)
    local modes = {"MAIN", "ZIGZAG", "NORMAL"}
    local texts = {"MAIN", "ZIGZAG", "NORMAL (V4)"}
    local btns = {}
    local function apply(mode)
        for i, m in ipairs(modes) do
            local sel = (m == mode)
            TweenService:Create(btns[i], TweenInfo.new(0.15), {BackgroundColor3 = sel and C_ON_BG or C_OFF_BG, TextColor3 = sel and C_WHITE or C_DIM}):Play()
        end
    end
    for i, m in ipairs(modes) do
        local b = Instance.new("TextButton", row)
        b.Size = UDim2.new(1/3, -6, 1, -8)
        b.Position = UDim2.new((i - 1) / 3, 3, 0, 4)
        b.BackgroundColor3 = C_OFF_BG
        b.BorderSizePixel = 0
        b.AutoButtonColor = false
        b.Text = texts[i]
        b.TextColor3 = C_DIM
        b.Font = Enum.Font.GothamBold
        b.TextSize = 9
        b.ZIndex = 4
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 5)
        btns[i] = b
        b.MouseButton1Click:Connect(function()
            State.autoTpDownMode = m
            apply(m)
            autoSaveConfig()
        end)
    end
    State.applyTpDownModeUI = apply
    apply(State.autoTpDownMode)
end
State.buildTpDownModeSelector()
