    local CZ_current     = "Adidas Sports"
    local CZ_enabled     = false
    local CZ_savedAnim   = nil
    local CZ_applying    = false
    local CZ_wantPack    = nil
    local CZ_headless    = false
    local CZ_korblox     = false
    local CZ_HL_MESH     = "rbxassetid://1095708"
    local CZ_KB_MESH     = "rbxassetid://101851696"
    local CZ_KB_TEX      = "rbxassetid://101851254"
    local CZ_GREY        = Color3.fromRGB(64,64,64)
    local CZ_headConns   = {}

    local function CZ_pick(pack, ...)
        for i=1,select("#",...) do local k=select(i,...); local v=pack[k]; if v~=nil then return v end end
        return nil
    end
    local function CZ_stopTracks(hum)
        if not hum then return end
        for _,t in ipairs(hum:GetPlayingAnimationTracks()) do pcall(function() t:Stop(0) end) end
    end
    local function CZ_ensureAnim(folder,name)
        if not folder then return nil end
        local a=folder:FindFirstChild(name)
        if not a then a=Instance.new("Animation"); a.Name=name; a.Parent=folder end
        return a
    end
    local function CZ_setAnim(obj,id)
        if obj and id then obj.AnimationId="rbxassetid://"..tostring(id) end
    end
    local function CZ_ensureIdleSlots(idleFolder,n)
        if not idleFolder then return end
        n=n or 2
        for i=1,n do CZ_ensureAnim(idleFolder,"Animation"..i) end
    end
    local function CZ_waitAnimate(char)
        for _=1,40 do
            local a=char:FindFirstChild("Animate")
            if a and a:FindFirstChild("idle") and a:FindFirstChild("run") and a:FindFirstChild("walk") then return a end
            task.wait(0.1)
        end
        return nil
    end
    local function CZ_saveOriginal(char)
        if not char or CZ_savedAnim then return end
        local animate=char:FindFirstChild("Animate")
        if animate then CZ_savedAnim=animate:Clone() end
    end
    local function CZ_restoreOriginal(char)
        if not char then return end
        if not CZ_savedAnim then return end
        local hum=char:FindFirstChildOfClass("Humanoid")
        if hum then CZ_stopTracks(hum) end
        local cur=char:FindFirstChild("Animate")
        if cur then pcall(function() cur:Destroy() end) end
        local na=CZ_savedAnim:Clone(); na.Parent=char; na.Disabled=true
        task.wait(0.06); na.Disabled=false
    end
    local function CZ_applyPack(packName)
        if not CZ_enabled then
            local ch=LP.Character
            if ch and CZ_savedAnim then pcall(function() CZ_restoreOriginal(ch) end) end
            return false
        end
        if CZ_applying then return false end
        CZ_applying=true
        local pack=CZ_PACKS[packName]
        if not pack then CZ_applying=false; return false end
        local char=LP.Character or LP.CharacterAdded:Wait()
        CZ_saveOriginal(char)
        local animate=CZ_waitAnimate(char)
        if not animate then CZ_applying=false; return false end
        local hum=char:FindFirstChildOfClass("Humanoid")
        CZ_stopTracks(hum)
        CZ_setAnim(CZ_ensureAnim(animate:FindFirstChild("run"),"RunAnim"), CZ_pick(pack,"RunAnim","Run"))
        CZ_setAnim(CZ_ensureAnim(animate:FindFirstChild("walk"),"WalkAnim"), CZ_pick(pack,"WalkAnim","Walk"))
        CZ_setAnim(CZ_ensureAnim(animate:FindFirstChild("jump"),"JumpAnim"), CZ_pick(pack,"JumpAnim","Jump"))
        CZ_setAnim(CZ_ensureAnim(animate:FindFirstChild("fall"),"FallAnim"), CZ_pick(pack,"FallAnim","Fall"))
        CZ_setAnim(CZ_ensureAnim(animate:FindFirstChild("climb"),"ClimbAnim"), CZ_pick(pack,"ClimbAnim","Climb"))
        CZ_setAnim(CZ_ensureAnim(animate:FindFirstChild("swim"),"Swim"), CZ_pick(pack,"Swim"))
        CZ_setAnim(CZ_ensureAnim(animate:FindFirstChild("swimidle"),"SwimIdle"), CZ_pick(pack,"SwimIdle") or CZ_pick(pack,"Swim"))
        local idleFolder=animate:FindFirstChild("idle")
        if idleFolder then
            local a1=CZ_pick(pack,"Animation1")
            local a2=CZ_pick(pack,"Animation2")
            if a1 or a2 then
                CZ_ensureIdleSlots(idleFolder,2)
                local id1=a1 or a2; local id2=a2 or a1 or id1
                CZ_setAnim(idleFolder:FindFirstChild("Animation1"), id1)
                CZ_setAnim(idleFolder:FindFirstChild("Animation2"), id2)
            elseif pack.Idle and #pack.Idle>0 then
                CZ_ensureIdleSlots(idleFolder, math.max(2,#pack.Idle))
                CZ_setAnim(idleFolder:FindFirstChild("Animation1"), pack.Idle[1])
                CZ_setAnim(idleFolder:FindFirstChild("Animation2"), pack.Idle[2] or pack.Idle[1])
                for i=3,#pack.Idle do
                    local a=idleFolder:FindFirstChild("Animation"..i)
                    if a then CZ_setAnim(a, pack.Idle[i]) end
                end
            end
        end
        animate.Disabled=true; task.wait(0.06); animate.Disabled=false
        if hum then pcall(function()
            hum:ChangeState(Enum.HumanoidStateType.Landed)
            task.wait(0.03)
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end) end
        CZ_current=packName
        CZ_applying=false
        return true
    end

    local function CZ_clearHeadConns(head)
        local list=CZ_headConns[head]
        if list then
            for _,c in ipairs(list) do pcall(function() c:Disconnect() end) end
            CZ_headConns[head]=nil
        end
    end
    local function CZ_removeFace(head)
        local face=head:FindFirstChild("face")
        if face then pcall(function() face:Destroy() end) end
    end
    local function CZ_applyHeadless(char,enabled)
        if not char then return end
        local head=char:FindFirstChild("Head")
        if not head then return end
        CZ_clearHeadConns(head)
        if enabled then
            head.Transparency=1; head.CanCollide=false; CZ_removeFace(head)
            for _,child in ipairs(head:GetChildren()) do
                if child:IsA("SpecialMesh") and child.MeshId==CZ_HL_MESH then pcall(function() child:Destroy() end) end
            end
            local mesh=Instance.new("SpecialMesh")
            mesh.MeshType=Enum.MeshType.FileMesh; mesh.MeshId=CZ_HL_MESH
            mesh.Scale=Vector3.new(0.001,0.001,0.001); mesh.Name="HeadlessMesh"; mesh.Parent=head
            local conns={}
            table.insert(conns, head:GetPropertyChangedSignal("Transparency"):Connect(function()
                if head.Transparency~=1 then head.Transparency=1 end
            end))
            table.insert(conns, head.ChildAdded:Connect(function(child)
                if child.Name=="face" and child:IsA("Decal") then pcall(function() child:Destroy() end) end
            end))
            CZ_headConns[head]=conns
        else
            head.Transparency=0; head.CanCollide=true
            for _,child in ipairs(head:GetChildren()) do
                if child:IsA("SpecialMesh") and child.Name=="HeadlessMesh" then pcall(function() child:Destroy() end) end
            end
            CZ_removeFace(head)
        end
    end
    local function CZ_applyKorblox(char,enabled)
        if not char then return end
        local humanoid=char:FindFirstChildOfClass("Humanoid")
        if not humanoid then return end
        if enabled then
            if humanoid.RigType==Enum.HumanoidRigType.R6 then
                local rightLeg=char:FindFirstChild("Right Leg")
                if rightLeg then
                    for _,child in ipairs(rightLeg:GetChildren()) do
                        if child:IsA("SpecialMesh") or child:IsA("CharacterMesh") then pcall(function() child:Destroy() end) end
                    end
                    rightLeg.Color=CZ_GREY
                    rightLeg:GetPropertyChangedSignal("Color"):Connect(function()
                        if rightLeg.Color~=CZ_GREY then rightLeg.Color=CZ_GREY end
                    end)
                    local mesh=Instance.new("SpecialMesh")
                    mesh.MeshType=Enum.MeshType.FileMesh; mesh.MeshId=CZ_KB_MESH; mesh.TextureId=CZ_KB_TEX
                    mesh.Scale=Vector3.new(1,1,1); mesh.Name="KorbloxMesh"; mesh.Parent=rightLeg
                end
            elseif humanoid.RigType==Enum.HumanoidRigType.R15 then
                local rightUpperLeg=char:FindFirstChild("RightUpperLeg")
                if rightUpperLeg then
                    rightUpperLeg.Transparency=1
                    local rightLowerLeg=char:FindFirstChild("RightLowerLeg")
                    local rightFoot=char:FindFirstChild("RightFoot")
                    if rightLowerLeg then rightLowerLeg.Transparency=1 end
                    if rightFoot then rightFoot.Transparency=1 end
                    local oldKorblox=char:FindFirstChild("KorbloxLeg")
                    if oldKorblox then pcall(function() oldKorblox:Destroy() end) end
                    local korbloxLeg=Instance.new("Part")
                    korbloxLeg.Name="KorbloxLeg"; korbloxLeg.Size=Vector3.new(1,2,1)
                    korbloxLeg.Anchored=false; korbloxLeg.CanCollide=false; korbloxLeg.Color=CZ_GREY
                    korbloxLeg.Parent=char
                    local mesh=Instance.new("SpecialMesh")
                    mesh.MeshType=Enum.MeshType.FileMesh; mesh.MeshId=CZ_KB_MESH; mesh.TextureId=CZ_KB_TEX
                    mesh.Scale=Vector3.new(1,1,1); mesh.Name="KorbloxMesh"; mesh.Parent=korbloxLeg
                    local weld=Instance.new("Weld")
                    weld.Part0=rightUpperLeg; weld.Part1=korbloxLeg; weld.C0=CFrame.new(0,-0.8,0)
                    weld.Name="KorbloxWeld"; weld.Parent=korbloxLeg
                end
            end
        else
            if humanoid.RigType==Enum.HumanoidRigType.R6 then
                local rightLeg=char:FindFirstChild("Right Leg")
                if rightLeg then
                    for _,child in ipairs(rightLeg:GetChildren()) do
                        if child:IsA("SpecialMesh") and child.Name=="KorbloxMesh" then pcall(function() child:Destroy() end) end
                    end
                    rightLeg.Color=Color3.fromRGB(255,255,255)
                end
            elseif humanoid.RigType==Enum.HumanoidRigType.R15 then
                local rightUpperLeg=char:FindFirstChild("RightUpperLeg")
                if rightUpperLeg then
                    rightUpperLeg.Transparency=0
                    local rightLowerLeg=char:FindFirstChild("RightLowerLeg")
                    local rightFoot=char:FindFirstChild("RightFoot")
                    if rightLowerLeg then rightLowerLeg.Transparency=0 end
                    if rightFoot then rightFoot.Transparency=0 end
                    local korbloxLeg=char:FindFirstChild("KorbloxLeg")
                    if korbloxLeg then pcall(function() korbloxLeg:Destroy() end) end
                end
            end
        end
    end
    local function CZ_applyAll(char)
        if not char then return end
        pcall(function() CZ_applyHeadless(char, CZ_headless) end)
        pcall(function() CZ_applyKorblox(char, CZ_korblox) end)
        if CZ_enabled then CZ_requestApply(CZ_current) end
    end

    local function CZ_requestApply(packName)
        CZ_wantPack = packName
    end
    task.spawn(function()
        while true do
            local p = CZ_wantPack
            if p == nil then
                task.wait(0.05)
            else
                CZ_wantPack = nil
                pcall(function() CZ_applyPack(p) end)
            end
        end
    end)

    local names={}
    for k in pairs(CZ_PACKS) do table.insert(names,k) end
    table.sort(names)
    local idx=1
    for i,n in ipairs(names) do if n==CZ_current then idx=i end end

    State.setAnimPacks = function(on)
        CZ_enabled = on==true
        State.animPacksEnabled = CZ_enabled
        if State.setAnimPacksVisual then State.setAnimPacksVisual(CZ_enabled) end
        if CZ_enabled then
            CZ_requestApply(CZ_current)
        else
            local ch=LP.Character
            if ch and CZ_savedAnim then pcall(function() CZ_restoreOriginal(ch) end) end
        end
        autoSaveConfig()
    end
    State.setAnimPacksVisual = makeToggleRow("MISC","ANIMATION PACKS", State.animPacksEnabled~=false, function(on) State.setAnimPacks(on) end)

    State.setAnimPackName = function(nm)
        if CZ_PACKS[nm] then
            CZ_current=nm
            State.animPackName=nm
            if State.setAnimPackNameUI then State.setAnimPackNameUI(nm) end
            if CZ_enabled then CZ_requestApply(CZ_current) end
            autoSaveConfig()
        end
    end
    do
        local row=makeRow("MISC",30)
        makeRowLabel(row,"Pack",0.30)
        local L=Instance.new("TextButton",row)
        L.Size=UDim2.new(0,22,0,22); L.Position=UDim2.new(1,-120,0.5,-11)
        L.BackgroundColor3=Color3.fromRGB(65, 27, 6); L.BorderSizePixel=0
        L.Text="<"; L.TextColor3=C_ACCENT2; L.Font=Enum.Font.GothamBold; L.TextSize=16; L.AutoButtonColor=false; L.ZIndex=7
        Instance.new("UICorner",L).CornerRadius=UDim.new(0,4); createShimmerBorder(L,3,1.0)
        local nameLbl=Instance.new("TextLabel",row)
        nameLbl.Size=UDim2.new(0,64,0,20); nameLbl.Position=UDim2.new(1,-94,0.5,-10)
        nameLbl.BackgroundTransparency=1; nameLbl.Text=CZ_current; nameLbl.TextColor3=C_WHITE
        nameLbl.Font=Enum.Font.GothamBold; nameLbl.TextSize=8; nameLbl.TextWrapped=true
        nameLbl.TextXAlignment=Enum.TextXAlignment.Center; nameLbl.ZIndex=7
        local R=Instance.new("TextButton",row)
        R.Size=UDim2.new(0,22,0,22); R.Position=UDim2.new(1,-28,0.5,-11)
        R.BackgroundColor3=Color3.fromRGB(65, 27, 6); R.BorderSizePixel=0
        R.Text=">"; R.TextColor3=C_ACCENT2; R.Font=Enum.Font.GothamBold; R.TextSize=16; R.AutoButtonColor=false; R.ZIndex=7
        Instance.new("UICorner",R).CornerRadius=UDim.new(0,4); createShimmerBorder(R,3,1.0)
        State.setAnimPackNameUI = function(nm) if nameLbl and nameLbl.Parent then nameLbl.Text=nm end end
        local _lt=0
        local function step(dir)
            if tick()-_lt<0.15 then return end; _lt=tick()
            idx=idx+dir
            if idx<1 then idx=#names end
            if idx>#names then idx=1 end
            CZ_current=names[idx]
            State.animPackName=CZ_current
            if State.setAnimPackNameUI then State.setAnimPackNameUI(CZ_current) end
            if CZ_enabled then CZ_requestApply(CZ_current) end
            autoSaveConfig()
        end
        L.MouseButton1Click:Connect(function() step(-1) end)
        L.Activated:Connect(function() step(-1) end)
        R.MouseButton1Click:Connect(function() step(1) end)
        R.Activated:Connect(function() step(1) end)
    end

    State.setKorblox = function(on)
        CZ_korblox = on==true
        State.korbloxEnabled = CZ_korblox
        if State.setKorbloxVisual then State.setKorbloxVisual(CZ_korblox) end
        pcall(function() CZ_applyKorblox(LP.Character, CZ_korblox) end)
        autoSaveConfig()
    end
    State.setKorbloxVisual = makeToggleRow("MISC","KORBLOX", State.korbloxEnabled==true, function(on) State.setKorblox(on) end)

    State.setHeadless = function(on)
        CZ_headless = on==true
        State.headlessEnabled = CZ_headless
        if State.setHeadlessVisual then State.setHeadlessVisual(CZ_headless) end
        pcall(function() CZ_applyHeadless(LP.Character, CZ_headless) end)
        autoSaveConfig()
    end
    State.setHeadlessVisual = makeToggleRow("MISC","HEADLESS", State.headlessEnabled==true, function(on) State.setHeadless(on) end)

    makeSectionLabel("MISC","Anims")
    setAnimToggle, _ = makeToggleRowKB("MISC","Tryhard Anim","keyAnimToggle",State.animEnabled,function(on) State.animEnabled=on; if on then startAnimToggle() else stopAnimToggle() end end)
    setUnwalkToggle, _ = makeToggleRowKB("MISC","Unwalk","keyUnwalk",State.unwalkEnabled,function(on) if on then startUnwalk() else stopUnwalk() end end)

    LP.CharacterAdded:Connect(function(char)
        task.wait(0.2)
        CZ_applyAll(char)
    end)
    if LP.Character then
        task.spawn(function()
            task.wait(0.2)
            CZ_applyAll(LP.Character)
        end)
    end
    end
    setupCharter()
end


