_setRestartBtnPos = makeToggleRow("MISC","RESET BTNS POSITIONS",false,function(on)
    if not on then return end
    local posFiles = {
        "FRHUBV2_Btn_battpv4.txt","FRHUBV2_Btn_smartbattp.txt","FRHUBV2_Btn_dropbr.txt","FRHUBV2_Btn_autoleft.txt",
