        BtnCarrySpd    = UDim2.new(1,COL2_X2,BASE_Y2,ROW_Y2[3]),
        BtnLaggerCarry = UDim2.new(1,COL1_X2,BASE_Y2,ROW_Y2[4]),
        BtnLaggerNorm  = UDim2.new(1,COL2_X2,BASE_Y2,ROW_Y2[4]),
    }
    local CG2 = game:GetService("CoreGui")
    local panel2 = CG2:FindFirstChild("FRHUBV2_Buttons")
    if not panel2 then
        local pg2 = LP:FindFirstChild("PlayerGui")
        if pg2 then panel2 = pg2:FindFirstChild("FRHUBV2_Buttons") end
    end
    local btnSaveKeys2 = {
        BtnBatTp       = "FRHUBV2_Btn_battpv4.txt",
        BtnSmartBatTp  = "FRHUBV2_Btn_smartbattp.txt",
        BtnAimbotV9    = "FRHUBV2_Btn_aimbotv9.txt",
        BtnDropBR      = "FRHUBV2_Btn_dropbr.txt",
