_G.FRHUB_ANTI_BAT_ACTIVE = false

local CONFIG_FILE = "FRHubAntiBatConfig.json"

local antiBatBind   = { type="keyboard", value=Enum.KeyCode.O }
local antiBatV2Bind = { type="keyboard", value=Enum.KeyCode.P }
local antiBatV3Bind = { type="keyboard", value=Enum.KeyCode.L }
local antiBatV4Bind = { type="keyboard", value=Enum.KeyCode.K }
local infJumpBind   = { type="keyboard", value=Enum.KeyCode.I }

local antiBatV3Power  = 100
local autoBrainrot    = false
local brainrotTarget  = "v1"
local lastBrainrotState = false
local guiScale        = 100

local function saveConfig()
    local data = {
        antiBatKey=tostring(antiBatBind.value), antiBatV2Key=tostring(antiBatV2Bind.value),
        antiBatV3Key=tostring(antiBatV3Bind.value), antiBatV4Key=tostring(antiBatV4Bind.value),
        infJumpKey=tostring(infJumpBind.value), antiBatV3Power=antiBatV3Power,
        autoBrainrot=autoBrainrot, brainrotTarget=brainrotTarget, guiScale=guiScale,
    }
    pcall(function() writefile(CONFIG_FILE, HttpService:JSONEncode(data)) end)
end

local function loadConfig()
    pcall(function()
        if not isfile(CONFIG_FILE) then return end
        local data = HttpService:JSONDecode(readfile(CONFIG_FILE))
        local function tryBind(key)
            if not key then return nil end
            local s = key:gsub("Enum.KeyCode.","")
            local ok, kc = pcall(function() return Enum.KeyCode[s] end)
            if ok and kc then return { type="keyboard", value=kc } end
        end
        antiBatBind   = tryBind(data.antiBatKey)   or antiBatBind
        antiBatV2Bind = tryBind(data.antiBatV2Key) or antiBatV2Bind
        antiBatV3Bind = tryBind(data.antiBatV3Key) or antiBatV3Bind
        antiBatV4Bind = tryBind(data.antiBatV4Key) or antiBatV4Bind
        infJumpBind   = tryBind(data.infJumpKey)   or infJumpBind
        if type(data.antiBatV3Power)=="number" then antiBatV3Power=math.clamp(data.antiBatV3Power,1,100) end
        if type(data.autoBrainrot)=="boolean"   then autoBrainrot=data.autoBrainrot end
        if type(data.guiScale)=="number"         then guiScale=math.clamp(data.guiScale,70,150) end
        if data.brainrotTarget=="v1" or data.brainrotTarget=="v2" then brainrotTarget=data.brainrotTarget end
    end)
end
loadConfig()

local function getKeyName(kc)
    local name = tostring(kc):gsub("Enum.KeyCode.","")
    local map = {LeftControl="LCTRL",RightControl="RCTRL",LeftShift="LSHIFT",RightShift="RSHIFT",
        LeftAlt="LALT",RightAlt="RALT",ButtonA="A",ButtonB="B",ButtonX="X",ButtonY="Y",
        ButtonL1="LB",ButtonR1="RB",ButtonL2="LT",ButtonR2="RT",ButtonStart="START",
        ButtonSelect="SELECT",LeftThumbstick="L3",RightThumbstick="R3",
        DirectionalPadUp="DPAD U",DirectionalPadDown="DPAD D",DirectionalPadLeft="DPAD L",DirectionalPadRight="DPAD R"}
    if map[name] then return map[name] end
    if #name > 6 then name=name:sub(1,6) end
    return name:upper()
end

local antiBatActive=false; local antiBatThread=nil
local antiBatStatusLbl, antiBatSwitchBall, antiBatCard, antiBatKeyBtn, antiBatKeyBtnStroke
local updateAntiBatGlobalFlag

local function toggleAntiBat()
    antiBatActive = not antiBatActive
    updateAntiBatGlobalFlag()
    if antiBatStatusLbl then
        antiBatStatusLbl.Text=antiBatActive and "STATUS: ACTIVE" or "STATUS: DISABLED"
        antiBatStatusLbl.TextColor3=antiBatActive and Color3.fromRGB(255, 109, 25) or Color3.fromRGB(150, 64, 15)
    end
    if antiBatCard then TS:Create(antiBatCard,TweenInfo.new(0.2),{BackgroundColor3=antiBatActive and Color3.fromRGB(65, 27, 6) or Color3.fromRGB(40, 17, 4)}):Play() end
    if antiBatSwitchBall then
        TS:Create(antiBatSwitchBall,TweenInfo.new(0.25,Enum.EasingStyle.Back,Enum.EasingDirection.Out),{Position=antiBatActive and UDim2.new(1,-21,0.5,-9) or UDim2.new(0,3,0.5,-9),BackgroundColor3=antiBatActive and Color3.fromRGB(255,255,255) or Color3.fromRGB(80,80,85)}):Play()
        TS:Create(antiBatSwitchBall.Parent,TweenInfo.new(0.14),{BackgroundColor3=antiBatActive and Color3.fromRGB(160, 68, 16) or Color3.fromRGB(35, 15, 3)}):Play()
    end
    if antiBatActive then
        if antiBatThread then antiBatThread:Disconnect() end
        antiBatThread = RunService.Heartbeat:Connect(function()
            local char=LP.Character; if not char then return end
            local hum=char:FindFirstChildOfClass("Humanoid"); local hrp=char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp then return end
            if hum.MoveDirection.Magnitude<=0 then return end
            local vel=hrp.Velocity
            hrp.Velocity=Vector3.new(vel.X*50,50,vel.Z*50)
            RunService.RenderStepped:Wait()
            hrp.Velocity=vel+Vector3.new(0,0.05,0)
        end)
    else
        if antiBatThread then antiBatThread:Disconnect(); antiBatThread=nil end
    end
end

