            hrp.AssemblyLinearVelocity=Vector3.new(asmVel.X*50,50,asmVel.Z*50)
            RunService.RenderStepped:Wait()
            hrp.Velocity=vel+Vector3.new(0,0.05,0)
            hrp.AssemblyLinearVelocity=asmVel+Vector3.new(0,0.05,0)
        end)
    else
        if antiBatV4Thread then antiBatV4Thread:Disconnect(); antiBatV4Thread=nil end
    end
end

local infJumpActive     = false
local infJumpSession    = 0
local lastBurstTime     = 0
local HOLD_INTERVAL     = 0.055
local infJumpRenderConn = nil
local touchJumpHeld     = false

local infJumpRay = RaycastParams.new()
infJumpRay.FilterType = Enum.RaycastFilterType.Exclude

local function infJumpFloorStandY(r, hum, char)
    infJumpRay.FilterDescendantsInstances = { char }
    local hit = workspace:Raycast(r.Position + Vector3.new(0, 2.25, 0), Vector3.new(0, -200, 0), infJumpRay)
    if not hit then return nil, nil end
    local floorY = hit.Position.Y
    local standY = floorY + hum.HipHeight + r.Size.Y * 0.5 + 0.12
    return standY, floorY
end

local function infJumpCorrectSink(r, hum, _char, floorY, standY)
    if not floorY or not standY then return end
    if r.Position.Y >= floorY + 0.35 then return end
    r.CFrame = CFrame.new(r.Position.X, standY, r.Position.Z) * (r.CFrame - r.CFrame.Position)
    local v = r.Velocity
    r.Velocity = Vector3.new(v.X, math.max(0, v.Y), v.Z)
end

local function isJumpHeld()
    if UIS:IsKeyDown(Enum.KeyCode.Space) then return true end
    local ok, down = pcall(function()
        return UIS:IsGamepadButtonDown(Enum.UserInputType.Gamepad1, Enum.KeyCode.ButtonA)
    end)
    if ok and down then return true end
    return touchJumpHeld
end

local function doInfJumpBurst()
    if not infJumpActive then return end
    if _G._FRHUBTPDownJumpLocked then return end
    local char = LP.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end

    infJumpSession = infJumpSession + 1
    local session = infJumpSession

    local jy = 50
    if hum.UseJumpPower and hum.JumpPower > 0 then
        jy = hum.JumpPower
    else
        local jh = hum.JumpHeight
        if type(jh) == "number" and jh > 0 then
            jy = math.sqrt(math.max(0, 2 * workspace.Gravity * jh))
        end
    end
    jy = math.clamp(jy, 35, 95)

    local standY, floorY = infJumpFloorStandY(hrp, hum, char)
    infJumpCorrectSink(hrp, hum, char, floorY, standY)

    local v0 = hrp.Velocity
    hrp.Velocity = Vector3.new(v0.X, math.max(v0.Y * 0.15, jy), v0.Z)

    local postSim  = RunService.PostSimulation
    local waitPhys = (postSim and function() postSim:Wait() end)
                  or function() RunService.Heartbeat:Wait() end

    task.spawn(function()
        local c = char; local boost = jy
        for i = 1, 10 do
            waitPhys()
            if session ~= infJumpSession or LP.Character ~= c or not infJumpActive then break end
            local r2 = c:FindFirstChild("HumanoidRootPart")
            local h2 = c:FindFirstChildOfClass("Humanoid")
            if not r2 or not h2 or h2.Health <= 0 then break end
            local sy, fy = infJumpFloorStandY(r2, h2, c)
            infJumpCorrectSink(r2, h2, c, fy, sy)
            if i > 2 and h2.FloorMaterial ~= Enum.Material.Air then break end
            local vel = r2.Velocity
            if vel.Y < boost * 0.72 then
                r2.Velocity = Vector3.new(
                    vel.X,
                    math.min(boost, math.max(vel.Y + boost * 0.42, boost * 0.72)),
                    vel.Z
                )
            end
        end
    end)
end

local function startInfJumpHandler()
    if infJumpRenderConn then return end
    infJumpRenderConn = RunService.RenderStepped:Connect(function()
        if not infJumpActive then return end
        if not isJumpHeld() then return end
        local now = tick()
        if now - lastBurstTime < HOLD_INTERVAL then return end
        lastBurstTime = now
        doInfJumpBurst()
    end)
end

local function stopInfJumpHandler()
    if infJumpRenderConn then
        infJumpRenderConn:Disconnect()
        infJumpRenderConn = nil
    end
    infJumpSession = infJumpSession + 1
    lastBurstTime  = 0
    touchJumpHeld  = false
end

task.defer(function()
    local pg = LP:FindFirstChild("PlayerGui")
    if not pg then return end
    local function hookJumpBtn(btn)
        if not btn:IsA("GuiButton") or btn.Name ~= "JumpButton"
        or btn:GetAttribute("FRHUB_AntiPanelJumpHook") then return end
        btn:SetAttribute("FRHUB_AntiPanelJumpHook", true)
        btn.MouseButton1Down:Connect(function() touchJumpHeld = true end)
        btn.MouseButton1Up:Connect(function()   touchJumpHeld = false end)
        btn.MouseLeave:Connect(function()       touchJumpHeld = false end)
    end
    for _, d in ipairs(pg:GetDescendants()) do hookJumpBtn(d) end
    pg.DescendantAdded:Connect(hookJumpBtn)
end)

UIS.JumpRequest:Connect(function()
    if infJumpActive then
        lastBurstTime = tick()
        doInfJumpBurst()
    end
end)

local BRAINROT_ANIM_ID="71186871415348"
RunService.Heartbeat:Connect(function()
    if not autoBrainrot then if lastBrainrotState then lastBrainrotState=false end; return end
    local char=LP.Character; if not char then return end
    local hum=char:FindFirstChild("Humanoid"); if not hum then return end
    local hasBrainrot=false
    local animator=hum:FindFirstChildOfClass("Animator")
    if animator then
        for _,track in ipairs(animator:GetPlayingAnimationTracks()) do
            local anim=track.Animation
            if anim and string.find(anim.AnimationId,BRAINROT_ANIM_ID,1,true) then hasBrainrot=true; break end
        end
    end
    local toggleFn, getActive
    if brainrotTarget=="v1" then toggleFn=toggleAntiBat; getActive=function() return antiBatActive end
    else toggleFn=toggleAntiBatV2; getActive=function() return antiBatV2Active end end
    if hasBrainrot and not lastBrainrotState then lastBrainrotState=true; if not getActive() then toggleFn() end
    elseif not hasBrainrot and lastBrainrotState then lastBrainrotState=false; if getActive() then toggleFn() end end
end)

