local function createShimmerBorder(parent,speed,thickness)
    speed=speed or 6; thickness=thickness or 2.5
    local stroke=Instance.new("UIStroke"); stroke.Thickness=thickness
    stroke.ApplyStrokeMode=Enum.ApplyStrokeMode.Border; stroke.Color=Color3.new(1,1,1); stroke.Transparency=0; stroke.Parent=parent
    local grad=Instance.new("UIGradient")
    grad.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.fromRGB(240, 103, 24)),ColorSequenceKeypoint.new(0.15,Color3.fromRGB(210, 90, 21)),ColorSequenceKeypoint.new(0.30,Color3.fromRGB(255, 109, 25)),ColorSequenceKeypoint.new(0.50,Color3.fromRGB(255, 109, 25)),ColorSequenceKeypoint.new(0.70,Color3.fromRGB(255, 109, 25)),ColorSequenceKeypoint.new(0.85,Color3.fromRGB(210, 90, 21)),ColorSequenceKeypoint.new(1,Color3.fromRGB(240, 103, 24))})
    grad.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,0.85),NumberSequenceKeypoint.new(0.15,0.55),NumberSequenceKeypoint.new(0.30,0.90),NumberSequenceKeypoint.new(0.50,0.05),NumberSequenceKeypoint.new(0.70,0.90),NumberSequenceKeypoint.new(0.85,0.55),NumberSequenceKeypoint.new(1,0.85)})
    grad.Rotation=0; grad.Parent=stroke
    task.spawn(function()
        while parent and parent.Parent do
            grad.Rotation=(grad.Rotation+speed)%360
            local pulse=(math.sin(tick()*2.2)+1)/2
            stroke.Transparency=pulse*0.06; stroke.Thickness=thickness+pulse*0.5; task.wait(0.1)
        end
    end)
    return stroke,grad
end

local function createGlassGradient(obj,speed)
    speed=speed or 0.72
    local grad=Instance.new("UIGradient")
    grad.Color=ColorSequence.new({ColorSequenceKeypoint.new(0,Color3.fromRGB(220, 94, 22)),ColorSequenceKeypoint.new(0.30,Color3.fromRGB(255, 109, 25)),ColorSequenceKeypoint.new(0.50,Color3.fromRGB(235,205,255)),ColorSequenceKeypoint.new(0.70,Color3.fromRGB(255, 109, 25)),ColorSequenceKeypoint.new(1,Color3.fromRGB(220, 94, 22))})
    grad.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,0.25),NumberSequenceKeypoint.new(0.30,0.0),NumberSequenceKeypoint.new(0.50,0.08),NumberSequenceKeypoint.new(0.70,0.0),NumberSequenceKeypoint.new(1,0.25)})
    grad.Rotation=90; grad.Parent=obj
    task.spawn(function() while obj and obj.Parent do grad.Rotation=(grad.Rotation+speed)%360; task.wait(0.016) end end)
    return grad
end

local function makeDraggable(frame,handle)
    handle=handle or frame
    local dragging,dragInput,dragStart,startPos=false,nil,nil,nil
    handle.InputBegan:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.Touch or inp.UserInputType==Enum.UserInputType.MouseButton1 then
            dragging=true; dragStart=inp.Position; startPos=frame.Position
            inp.Changed:Connect(function() if inp.UserInputState==Enum.UserInputState.End then dragging=false end end)
        end
    end)
    handle.InputChanged:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.Touch or inp.UserInputType==Enum.UserInputType.MouseMovement then dragInput=inp end
    end)
    UIS.InputChanged:Connect(function(inp)
        if inp==dragInput and dragging then
            local d=inp.Position-dragStart
            frame.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset+d.X,startPos.Y.Scale,startPos.Y.Offset+d.Y)
        end
    end)
end

