local listeningFor=nil
local function startListen(card,bindTable,accentColor,tag)
    if listeningFor then return end
    listeningFor=tag; card.keyBtn.Text="..."; card.keyBtn.TextColor3=C_ACCENT; card.keyBtnStroke.Color=C_ACCENT
    local conn; conn=UIS.InputBegan:Connect(function(inp,gpe)
        local isKb=inp.UserInputType==Enum.UserInputType.Keyboard
        local isGP=inp.UserInputType==Enum.UserInputType.Gamepad1 or inp.UserInputType==Enum.UserInputType.Gamepad2
        if (isKb or isGP) and inp.KeyCode~=Enum.KeyCode.Unknown then
            conn:Disconnect(); bindTable.type=isKb and "keyboard" or "controller"; bindTable.value=inp.KeyCode
            card.keyBtn.Text=getKeyName(inp.KeyCode); card.keyBtn.TextColor3=accentColor; card.keyBtnStroke.Color=accentColor
            listeningFor=nil; saveConfig()
        end
    end)
end
