UIS.InputBegan:Connect(function(inp,gpe)
    if gpe or listeningFor then return end
    local isKb=inp.UserInputType==Enum.UserInputType.Keyboard
    local isGP=inp.UserInputType==Enum.UserInputType.Gamepad1 or inp.UserInputType==Enum.UserInputType.Gamepad2
    local kc=inp.KeyCode
    if antiBatBind.type=="keyboard"   and isKb and kc==antiBatBind.value   then toggleAntiBat()    end
    if antiBatBind.type=="controller" and isGP and kc==antiBatBind.value   then toggleAntiBat()    end
    if antiBatV2Bind.type=="keyboard"   and isKb and kc==antiBatV2Bind.value then toggleAntiBatV2() end
    if antiBatV2Bind.type=="controller" and isGP and kc==antiBatV2Bind.value then toggleAntiBatV2() end
    if antiBatV3Bind.type=="keyboard"   and isKb and kc==antiBatV3Bind.value then toggleAntiBatV3() end
    if antiBatV3Bind.type=="controller" and isGP and kc==antiBatV3Bind.value then toggleAntiBatV3() end
    if antiBatV4Bind.type=="keyboard"   and isKb and kc==antiBatV4Bind.value then toggleAntiBatV4() end
    if antiBatV4Bind.type=="controller" and isGP and kc==antiBatV4Bind.value then toggleAntiBatV4() end
    if infJumpBind.type=="keyboard"   and isKb and kc==infJumpBind.value   then infJumpActive=not infJumpActive; setIJVisual(infJumpActive); if infJumpActive then startInfJumpHandler() else stopInfJumpHandler() end end
    if infJumpBind.type=="controller" and isGP and kc==infJumpBind.value   then infJumpActive=not infJumpActive; setIJVisual(infJumpActive); if infJumpActive then startInfJumpHandler() else stopInfJumpHandler() end end
end)

