local GOOD_SAVE = "ZairosGood_v2.json"

local function saveNewCfg()
    if not writefile then return end
    pcall(writefile, NEW_SAVE, HS:JSONEncode({speed = NEW_CFG.speed, keybind = NEW_CFG.keybind}))
end
local function loadNewCfg()
    if not readfile or not isfile or not isfile(NEW_SAVE) then return end
    local ok, d = pcall(function() return HS:JSONDecode(readfile(NEW_SAVE)) end)
    if ok and type(d) == "table" then
        if type(d.speed) == "number" then NEW_CFG.speed = math.clamp(d.speed, 1, 200) end
        if type(d.keybind) == "string" then NEW_CFG.keybind = d.keybind end
    end
end
local function saveAntiCfg()
    if not writefile then return end
    pcall(writefile, ANTI_SAVE, HS:JSONEncode({speedLimit = ANTI_CFG.speedLimit, keybind = ANTI_CFG.keybind}))
end
local function loadAntiCfg()
    if not readfile or not isfile or not isfile(ANTI_SAVE) then return end
    local ok, d = pcall(function() return HS:JSONDecode(readfile(ANTI_SAVE)) end)
    if ok and type(d) == "table" then
        if type(d.speedLimit) == "number" then ANTI_CFG.speedLimit = math.clamp(d.speedLimit, 1, 200) end
        if type(d.keybind) == "string" then ANTI_CFG.keybind = d.keybind end
    end
end
local function saveGoodCfg()
    if not writefile then return end
    pcall(writefile, GOOD_SAVE, HS:JSONEncode(GOOD_CFG))
end
local function loadGoodCfg()
    if not readfile or not isfile or not isfile(GOOD_SAVE) then return end
    local ok, d = pcall(function() return HS:JSONDecode(readfile(GOOD_SAVE)) end)
    if ok and type(d) == "table" then
        for k, v in pairs(d) do if GOOD_CFG[k] ~= nil then GOOD_CFG[k] = v end end
    end
end
loadNewCfg()
loadAntiCfg()
loadGoodCfg()

