local function addNumRow(scroll, labelTxt, getVal, setVal)
    local row = Instance.new("Frame", scroll)
    row.Size = UDim2.new(1, 0, 0, 26)
    row.BackgroundColor3 = CARD_COL
    row.BorderSizePixel = 0
    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 5)
    local rs = Instance.new("UIStroke", row); rs.Color = Color3.fromRGB(100, 43, 10); rs.Thickness = 1
    local lbl = Instance.new("TextLabel", row)
    lbl.Size = UDim2.new(0.55, 0, 1, 0); lbl.Position = UDim2.new(0, 6, 0, 0)
    lbl.BackgroundTransparency = 1; lbl.Text = labelTxt
    lbl.TextColor3 = W_COL; lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 8
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    local box = Instance.new("TextBox", row)
    box.Size = UDim2.new(0, 50, 0, 18); box.Position = UDim2.new(1, -56, 0.5, -9)
    box.BackgroundColor3 = INP_COL; box.BorderSizePixel = 0
    box.Text = tostring(getVal()); box.TextColor3 = W_COL
    box.Font = Enum.Font.GothamBold; box.TextSize = 9; box.ClearTextOnFocus = false
    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 3)
    local bs = Instance.new("UIStroke", box); bs.Color = Color3.fromRGB(100, 43, 10); bs.Thickness = 1
    box.Focused:Connect(function() TweenService:Create(bs, TweenInfo.new(0.1), {Color = ORANGE_STR}):Play() end)
    box.FocusLost:Connect(function()
        TweenService:Create(bs, TweenInfo.new(0.1), {Color = Color3.fromRGB(100, 43, 10)}):Play()
        local n = tonumber(box.Text)
        if n then setVal(n) else box.Text = tostring(getVal()) end
    end)
end

local function addKeybindRow(scroll, labelTxt, getKey, setKey)
    local row = Instance.new("Frame", scroll)
    row.Size = UDim2.new(1, 0, 0, 26)
    row.BackgroundColor3 = CARD_COL
    row.BorderSizePixel = 0
    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 5)
    Instance.new("UIStroke", row).Color = Color3.fromRGB(100, 43, 10)
    local lbl = Instance.new("TextLabel", row)
    lbl.Size = UDim2.new(0.55, 0, 1, 0); lbl.Position = UDim2.new(0, 6, 0, 0)
    lbl.BackgroundTransparency = 1; lbl.Text = labelTxt
    lbl.TextColor3 = W_COL; lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 8
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    local kbBtn = Instance.new("TextButton", row)
    kbBtn.Size = UDim2.new(0, 54, 0, 18); kbBtn.Position = UDim2.new(1, -60, 0.5, -9)
    kbBtn.BackgroundColor3 = INP_COL; kbBtn.BorderSizePixel = 0
    kbBtn.Text = "[ " .. getKey() .. " ]"; kbBtn.TextColor3 = W_COL
    kbBtn.Font = Enum.Font.GothamBold; kbBtn.TextSize = 8
    Instance.new("UICorner", kbBtn).CornerRadius = UDim.new(0, 3)
    Instance.new("UIStroke", kbBtn).Color = Color3.fromRGB(100, 43, 10)
    local listening = false; local kbConn = nil
    kbBtn.MouseButton1Click:Connect(function()
        if listening then return end
        listening = true; kbBtn.Text = "[ ... ]"; kbBtn.TextColor3 = ORANGE_ON
        kbConn = UserInputService.InputBegan:Connect(function(inp, _gp)
            if not listening then return end
            local isKb = inp.UserInputType == Enum.UserInputType.Keyboard
            local isGP = inp.UserInputType == Enum.UserInputType.Gamepad1
            if not isKb and not isGP then return end
            if isKb and inp.KeyCode == Enum.KeyCode.Escape then
                listening = false; kbBtn.Text = "[ " .. getKey() .. " ]"; kbBtn.TextColor3 = W_COL
                if kbConn then kbConn:Disconnect(); kbConn = nil end
                return
            end
            local kn = tostring(inp.KeyCode):sub(14)
            if kn and kn ~= "" and kn ~= "Unknown" then
                setKey(kn)
                kbBtn.Text = "[ " .. kn .. " ]"; kbBtn.TextColor3 = W_COL
                listening = false
                if kbConn then kbConn:Disconnect(); kbConn = nil end
            end
        end)
    end)
end

