    local toggleBtn = Instance.new("TextButton", row)
    toggleBtn.Size = UDim2.new(0, 40, 0, 18); toggleBtn.Position = UDim2.new(1, -46, 0.5, -9)
    toggleBtn.BackgroundColor3 = getVal() and ORANGE_ON or ORANGE_OFF
    toggleBtn.BorderSizePixel = 0
