    toggleBtn.Font = Enum.Font.GothamBold; toggleBtn.TextSize = 8
    Instance.new("UICorner", toggleBtn).CornerRadius = UDim.new(0, 3)
    toggleBtn.MouseButton1Click:Connect(function()
        local newVal = not getVal()
        setVal(newVal)
        TweenService:Create(toggleBtn, TweenInfo.new(0.15), {BackgroundColor3 = newVal and ORANGE_ON or ORANGE_OFF}):Play()
        TweenService:Create(toggleBtn, TweenInfo.new(0.15), {TextColor3 = newVal and W_COL or DIM_COL}):Play()
        toggleBtn.Text = newVal and "ON" or "OFF"
    end)
end

