local function keyToEnum(n)
    if not n then return nil end
    local ok, kc = pcall(function() return Enum.KeyCode[n] end)
    return ok and kc or nil
end

UserInputService.InputBegan:Connect(function(inp, _gpe)
    if inp.UserInputType ~= Enum.UserInputType.Keyboard and inp.UserInputType ~= Enum.UserInputType.Gamepad1 then return end
    local nkc = keyToEnum(NEW_CFG.keybind)
    if nkc and inp.KeyCode == nkc then
        if newAimEnabled then disableNewAim(); newAimEnabled = false else enableNewAim() end
        updateNewVisual(); updateAntiVisual(); updateGoodVisual()
    end
    local akc = keyToEnum(ANTI_CFG.keybind)
    if akc and inp.KeyCode == akc then
        if antiEnabled then disableAnti(); antiEnabled = false else enableAnti() end
        updateNewVisual(); updateAntiVisual(); updateGoodVisual()
    end
    local gkc = keyToEnum(GOOD_CFG.keybind)
    if gkc and inp.KeyCode == gkc then
        if goodEnabled then disableGood(); goodEnabled = false else enableGood() end
        updateNewVisual(); updateAntiVisual(); updateGoodVisual()
    end
end)
_G.ZAIROS_MERGED_STOP = function()
    if newAimEnabled then pcall(disableNewAim) end
    if antiEnabled then pcall(disableAnti) end
    if goodEnabled then pcall(disableGood) end
    newAimEnabled=false; antiEnabled=false; goodEnabled=false
end
    end) end)
    end
