local GRAVITY = -196.2
local DETECT_NAMES = {"LockBAV","LockAngVel","LockBodyAtt","BatLock","LockBAVAtt","AutoBatAtt","AutoBatAV","AntiBatDet","AntiAim","VelocityLock"}


local function purgeHRP(hrp)
    if not hrp then return end
    pcall(function()
        for _,n in ipairs(DETECT_NAMES) do local o=hrp:FindFirstChild(n) if o then o:Destroy() end end
        for _,c in ipairs(hrp:GetChildren()) do
            local low=c.Name:lower()
            if c.Name~="_ZA_AngV" and c.Name~="_ZA_Att" and c.Name~="_ZB_AngV" and c.Name~="_ZB_Att"
            and (low:find("lockb") or low:find("lockangv") or low:find("batlock") or low:find("antiaim") or low:find("velocitylock")) then
                pcall(function() c:Destroy() end)
            end
        end
    end)
end

local function setupAngVelc(hrp, prefix)
    pcall(function()
        local o1=hrp:FindFirstChild("_"..prefix.."_AngV")
        local o2=hrp:FindFirstChild("_"..prefix.."_Att")
        if o1 then o1:Destroy() end; if o2 then o2:Destroy() end
    end)
    local att=Instance.new("Attachment"); att.Name="_"..prefix.."_Att"; att.Parent=hrp
    local av=Instance.new("AngularVelocity")
    av.Name="_"..prefix.."_AngV"; av.Attachment0=att
    av.RelativeTo=Enum.ActuatorRelativeTo.World
    av.MaxTorque=math.huge; av.AngularVelocity=Vector3.zero; av.Parent=hrp
    return av, att
end

local function cleanAngVelc(av, att)
    pcall(function() if av and av.Parent then av:Destroy() end end)
    pcall(function() if att and att.Parent then att:Destroy() end end)
end

local function findBat()
    local char=LP.Character; if not char then return nil end
    for _,t in ipairs(char:GetChildren()) do
        if t:IsA("Tool") and (t.Name:lower():find("bat") or t.Name:lower():find("slap")) then return t end
    end
    local bp=LP:FindFirstChild("Backpack")
    if bp then
        for _,t in ipairs(bp:GetChildren()) do
            if t:IsA("Tool") and (t.Name:lower():find("bat") or t.Name:lower():find("slap")) then return t end
        end
    end
    return nil
end

local function getClosestTarget()
    local root=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not root then return nil,nil,math.huge end
    local closest,closestPlr,minDist=nil,nil,math.huge
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LP and plr.Character then
            local tr=plr.Character:FindFirstChild("HumanoidRootPart")
            local hum=plr.Character:FindFirstChildOfClass("Humanoid")
            if tr and hum and hum.Health>0 then
                local d=(tr.Position-root.Position).Magnitude
                if d<minDist then minDist=d; closest=tr; closestPlr=plr end
            end
        end
    end
    return closest,closestPlr,minDist
end

local function getStickyTarget(currentRoot)
    local root=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not root then return nil,nil end
    local newClosest,newPlr,newDist=getClosestTarget()
    if not newClosest then return nil,nil end
    if currentRoot and currentRoot.Parent then
        local currentPlr=Players:GetPlayerFromCharacter(currentRoot.Parent)
        local hum=currentRoot.Parent:FindFirstChildOfClass("Humanoid")
        if currentPlr and hum and hum.Health>0 then
            local currentDist=(currentRoot.Position-root.Position).Magnitude
            if currentPlr==newPlr or newDist>currentDist*0.7 then
                return currentRoot,currentPlr
            end
        end
    end
    return newClosest,newPlr
end

local function swingBat(char)
    local bat=findBat()
    if bat and bat.Parent==char and bat:IsA("Tool") then
        pcall(function() bat:Activate() end)
    end
end


local function detectTPDown(targetHRP)
    if not targetHRP then
        _tpDownLastY=0; _tpDownLastVelY=0; _tpDownLastTime=0
        _tpDownTracked=nil; _tpDownDevHistory={}
        return false
    end
    local now=os.clock()
    if _tpDownTracked~=targetHRP then
        _tpDownTracked=targetHRP
        _tpDownLastY=targetHRP.Position.Y
        _tpDownLastVelY=targetHRP.Velocity.Y
        _tpDownLastTime=now
        _tpDownDevHistory={}
        return false
    end
    local dt=math.clamp(now-_tpDownLastTime,1/144,0.5)
    local y=targetHRP.Position.Y
    local velY=targetHRP.Velocity.Y

    local expectedDelta=((_tpDownLastVelY+velY)*0.5)*dt
    local actualDelta=y-_tpDownLastY
    local deviation=actualDelta-expectedDelta


    local noiseFloor=math.max(0.6, dt*40, math.abs(velY)*dt*0.35)
    local droppedMoreThanPhysics=deviation<-noiseFloor

    table.insert(_tpDownDevHistory, droppedMoreThanPhysics and 1 or 0)
    if #_tpDownDevHistory>4 then table.remove(_tpDownDevHistory,1) end
    local flagged=0
    for _,v in ipairs(_tpDownDevHistory) do flagged=flagged+v end

    _tpDownLastY=y; _tpDownLastVelY=velY; _tpDownLastTime=now
    return flagged>=2
end

local function executeTPDownCounter()
    if _tpDownCooldown then return end
    local char=LP.Character
    local hrp=char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local filterList={}
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr.Character then table.insert(filterList,plr.Character) end
    end
    local rp=RaycastParams.new()
    rp.FilterDescendantsInstances=filterList
    rp.FilterType=Enum.RaycastFilterType.Exclude
    rp.IgnoreWater=false
    local rr=workspace:Raycast(hrp.Position,Vector3.new(0,-1000,0),rp)
    if rr then
        _tpDownCooldown=true
        hrp.Velocity=Vector3.zero
        hrp.AssemblyAngularVelocity=Vector3.zero
        hrp.CFrame=CFrame.new(rr.Position+Vector3.new(0,3,0))
        task.delay(0.05,function() _tpDownCooldown=false end)
    end
end


local function detectInfiniteJump(targetHRP)
    if not targetHRP then
        _infJumpDet=false; _tpDownDet=false; _jumpHistory={}; _peakY=0; _normalTimer=0
        return "normal"
    end
    local velY=targetHRP.Velocity.Y
    local posY=targetHRP.Position.Y
    if posY>_peakY then _peakY=posY end
    table.insert(_jumpHistory,velY)
    if #_jumpHistory>CFG.MAX_JUMP_HISTORY then table.remove(_jumpHistory,1) end
    local upwardSpikes=0
    for i=2,#_jumpHistory do
        if _jumpHistory[i]>CFG.JUMP_DETECT_THRESHOLD and _jumpHistory[i-1]<CFG.JUMP_DETECT_THRESHOLD*0.3 then
            upwardSpikes=upwardSpikes+1
        end
    end
    if upwardSpikes>=CFG.JUMP_COUNT_TRIGGER and not _infJumpDet then
        _infJumpDet=true; _peakY=posY; _tpDownDet=false
    end
    if _infJumpDet and velY<CFG.TP_DOWN_VEL_THRESHOLD then
        _tpDownDet=true; return "tp_down"
    end
    if _infJumpDet and velY<-20 and (posY<_peakY-5) then return "falling" end
    if _infJumpDet and math.abs(velY)<5 and posY<_lastTargetY+2 then
        _normalTimer=_normalTimer+1
        if _normalTimer>8 then
            _infJumpDet=false; _tpDownDet=false; _peakY=0; _normalTimer=0; _jumpHistory={}
            return "normal"
        end
    else
        _normalTimer=0
    end
    _lastTargetY=posY
    if _infJumpDet then return _tpDownDet and "tp_down" or "infinite_jump" end
    return "normal"
end

local function computePredictedPos(myHRP, targetHRP, mode)
    local curPos=targetHRP.Position
    local rawCurVel=_getV(targetHRP)
    local xzSpikeMag=math.abs(rawCurVel.X)+math.abs(rawCurVel.Z)
    local curVel
    if xzSpikeMag>400 then
        if #_velHistory>0 then
            local safe=_velHistory[#_velHistory]
            curVel=Vector3.new(safe.X,rawCurVel.Y,safe.Z)
        else
            curVel=Vector3.new(0,rawCurVel.Y,0)
        end
    else
        curVel=rawCurVel
    end
    table.insert(_velHistory,curVel)
    if #_velHistory>CFG.VEL_SAMPLES then table.remove(_velHistory,1) end
    table.insert(_posHistory,curPos)
    if #_posHistory>CFG.POS_SAMPLES then table.remove(_posHistory,1) end
    local accel=Vector3.zero
    if #_velHistory>=3 then
        local newest=_velHistory[#_velHistory]
        local oldest=_velHistory[1]
        accel=(newest-oldest)/math.max(#_velHistory*0.016,0.016)
    end
    local wasTeleported=false
    if #_posHistory>=2 then
        local delta=_posHistory[#_posHistory]-_posHistory[#_posHistory-1]
        if delta.Magnitude>12 then
            wasTeleported=true
            _velHistory={}; _posHistory={curPos}
        end
    end
    local targetVelXZ=Vector3.new(curVel.X,0,curVel.Z)
    local targetSpeed=targetVelXZ.Magnitude
    local mySpeed=math.max(CFG.SPEED,1)
    local dXZ=Vector3.new(curPos.X-myHRP.Position.X,0,curPos.Z-myHRP.Position.Z)
    local vv=targetVelXZ:Dot(targetVelXZ)
    local dv=dXZ:Dot(targetVelXZ)
    local dd=dXZ:Dot(dXZ)
    local ia=vv-mySpeed*mySpeed
    local ib=2*dv
    local interceptT
    if math.abs(ia)<0.01 then
        interceptT=dXZ.Magnitude/math.max(mySpeed-targetSpeed*0.5,1)
    else
        local disc=ib*ib-4*ia*dd
        if disc<0 then
            interceptT=dXZ.Magnitude/mySpeed
        else
            local sq=math.sqrt(disc)
            local t1=(-ib-sq)/(2*ia)
            local t2=(-ib+sq)/(2*ia)
            if t1>0.001 and t2>0.001 then interceptT=math.min(t1,t2)
            elseif t1>0.001 then interceptT=t1
            elseif t2>0.001 then interceptT=t2
            else interceptT=dXZ.Magnitude/mySpeed end
        end
    end
    interceptT=math.clamp(interceptT,0.02,1.5)
    local pctMult=math.max(CFG.PREDICT_PCT/100,0.05)
    local leadTime=math.clamp(interceptT*pctMult,0.02,1.5)
    local predictedPos
    local isEmergency=false
    if wasTeleported then
        predictedPos=curPos+curVel*math.min(leadTime,0.08)
    elseif mode=="tp_down" then
        local landX=curPos.X+curVel.X*CFG.TP_DOWN_PREDICT
        local landZ=curPos.Z+curVel.Z*CFG.TP_DOWN_PREDICT
        local rp=RaycastParams.new()
        rp.FilterDescendantsInstances={LP.Character}
        rp.FilterType=Enum.RaycastFilterType.Exclude
        local rr=workspace:Raycast(Vector3.new(landX,curPos.Y,landZ),Vector3.new(0,-200,0),rp)
        local gy=rr and rr.Position.Y or curPos.Y
        predictedPos=Vector3.new(landX,gy+CFG.HEIGHT+3,landZ)
        isEmergency=true
    elseif mode=="infinite_jump" then
        local jt=CFG.JUMP_PREDICT
        predictedPos=curPos+Vector3.new(curVel.X*jt*0.5,-2,curVel.Z*jt*0.5)
    elseif mode=="falling" then
        local deltaY=curVel.Y*0.22
        local disc=curVel.Y*curVel.Y-2*GRAVITY*math.abs(deltaY)
        local ballT=disc>0 and ((-curVel.Y-math.sqrt(disc))/(-GRAVITY)) or 0.18
        ballT=math.clamp(ballT,0.04,0.55)
        local blendT=math.max(leadTime,ballT)
        predictedPos=Vector3.new(
            curPos.X+curVel.X*blendT,
            curPos.Y+curVel.Y*ballT+0.5*GRAVITY*ballT*ballT+2.8,
            curPos.Z+curVel.Z*blendT
        )
    elseif curVel.Y>28 then
        local tPeak=curVel.Y/math.abs(GRAVITY)
        local blendT=math.min(leadTime,tPeak*1.2)
        predictedPos=Vector3.new(
            curPos.X+curVel.X*blendT+accel.X*blendT*blendT*0.5,
            curPos.Y+curVel.Y*blendT+0.5*GRAVITY*blendT*blendT,
            curPos.Z+curVel.Z*blendT+accel.Z*blendT*blendT*0.5
        )
    else

        local speedFactor=math.clamp(curVel.Magnitude/40,0,1.2)
        local distFactor=math.clamp(dXZ.Magnitude/80,0,1)
        local blendTime=0.14+speedFactor*0.12+distFactor*0.08
        blendTime=math.max(blendTime,leadTime*0.5)
        predictedPos=curPos+curVel*blendTime+accel*(blendTime*blendTime*0.5)
        predictedPos=predictedPos+targetHRP.CFrame.LookVector*0.3
    end
    if targetVelXZ.Magnitude>1 and not wasTeleported then
        local fwdDir=targetVelXZ.Unit
        local relToTgt=myHRP.Position-curPos
        local relXZ=Vector3.new(relToTgt.X,0,relToTgt.Z)
        local relDot=relXZ:Dot(fwdDir)
        local minAhead=4
        local catchUp=math.max(minAhead-relDot,0)
        local speedBonus=math.clamp(targetSpeed*0.09,1,5)
        local totalBias=math.clamp(catchUp+speedBonus,2,14)
        predictedPos=predictedPos+Vector3.new(fwdDir.X*totalBias,0,fwdDir.Z*totalBias)
    end
    predictedPos=predictedPos+Vector3.new(0,CFG.V_OFF,0)
    return predictedPos,isEmergency
end


local function startBatSpam()
    if SpamThread then return end
    SpamThread=task.spawn(function()
        while CFG.BatSpam do
            pcall(function()
                local char=LP.Character
                if char then
                    local bat=findBat()
                    if bat and bat:IsA("Tool") then
                        bat:Activate()
                        local hrp=char:FindFirstChild("HumanoidRootPart")
                        if hrp then
                            local _,_,dist=getClosestTarget()
                            if dist and dist<6 then
                                task.wait(0.02)
                                bat:Activate()
                            end
                        end
                    end
                end
            end)
            task.wait(CFG.SpamDelay/1000)
        end
        SpamThread=nil
    end)
end
local function stopBatSpam()
    CFG.BatSpam=false
    SpamThread=nil
end


local function enableSuper()
    if bypassEnabled then
        bypassEnabled=false
        local char=LP.Character; local hrp=char and char:FindFirstChild("HumanoidRootPart"); local hum=char and char:FindFirstChildOfClass("Humanoid")
        if hrp then _destroyLV(hrp); hrp.AssemblyAngularVelocity=Vector3.zero; purgeHRP(hrp) end
        if hum then hum.AutoRotate=true end
        if _bypassAngVelc then pcall(function() _bypassAngVelc.AngularVelocity=Vector3.zero end) end
        cleanAngVelc(_bypassAngVelc,_bypassAngAtt)
    end
    superEnabled=true; batEquipped=false; swingCD=false; _intendedVel=Vector3.zero
    _velHistory={}; _posHistory={}; _jumpHistory={}
    _infJumpDet=false; _tpDownDet=false; _peakY=0; _normalTimer=0; _lastTargetY=0
    _tpDownLastY=0; _tpDownLastVelY=0; _tpDownLastTime=0; _tpDownDevHistory={}; _tpDownTracked=nil
    local char=LP.Character; local hrp=char and char:FindFirstChild("HumanoidRootPart")
    if hrp then purgeHRP(hrp); angVelc,angVelcAtt=setupAngVelc(hrp,"ZA") end
    if CFG.BatSpam then startBatSpam() end
end

local function disableSuper()
    superEnabled=false; batEquipped=false
    stopBatSpam()
    local char=LP.Character
    local hrp=char and char:FindFirstChild("HumanoidRootPart")
    local hum=char and char:FindFirstChildOfClass("Humanoid")
    if hrp then _destroyLV(hrp); hrp.AssemblyAngularVelocity=Vector3.zero; purgeHRP(hrp) end
    if hum then hum.AutoRotate=true end
    if angVelc then pcall(function() angVelc.AngularVelocity=Vector3.zero end) end
    cleanAngVelc(angVelc,angVelcAtt); angVelc=nil; angVelcAtt=nil
end

local function enableBypass()
    if superEnabled then
        superEnabled=false; batEquipped=false
        stopBatSpam()
        local char=LP.Character; local hrp=char and char:FindFirstChild("HumanoidRootPart"); local hum=char and char:FindFirstChildOfClass("Humanoid")
        if hrp then _destroyLV(hrp); hrp.AssemblyAngularVelocity=Vector3.zero; purgeHRP(hrp) end
        if hum then hum.AutoRotate=true end
        if angVelc then pcall(function() angVelc.AngularVelocity=Vector3.zero end) end
        cleanAngVelc(angVelc,angVelcAtt); angVelc=nil; angVelcAtt=nil
    end
    bypassEnabled=true; batEquipped=false; _bypassVel=Vector3.zero
    _tpDownLastY=0; _tpDownLastVelY=0; _tpDownLastTime=0; _tpDownDevHistory={}; _tpDownTracked=nil
    local char=LP.Character; local hrp=char and char:FindFirstChild("HumanoidRootPart")
    if hrp then purgeHRP(hrp); _bypassAngVelc,_bypassAngAtt=setupAngVelc(hrp,"ZB") end
end

local function disableBypass()
    bypassEnabled=false; batEquipped=false
    local char=LP.Character
    local hrp=char and char:FindFirstChild("HumanoidRootPart")
    local hum=char and char:FindFirstChildOfClass("Humanoid")
    if hrp then _destroyLV(hrp); purgeHRP(hrp) end
    if hum then hum.AutoRotate=true end
    if _bypassAngVelc then pcall(function() _bypassAngVelc.AngularVelocity=Vector3.zero end) end
    cleanAngVelc(_bypassAngVelc,_bypassAngAtt); _bypassAngVelc=nil; _bypassAngAtt=nil
end


RunService.Heartbeat:Connect(function()
    if not superEnabled and not bypassEnabled then return end
    local currentTarget = superEnabled and _target or (bypassEnabled and _bypassTarget or nil)
    if detectTPDown(currentTarget) then
        executeTPDownCounter()
    end
end)


RunService.Heartbeat:Connect(function()
    if not superEnabled then return end
    local char=LP.Character
    local hum=char and char:FindFirstChildOfClass("Humanoid")
    local root=char and char:FindFirstChild("HumanoidRootPart")
    if not root or not hum then return end
    purgeHRP(root)
    pcall(function()
        if _G and _G.FR_State then
            _G.FR_State.antiBatEnabled=false; _G.FR_State.bypassAntiBatEnabled=false
        end
    end)
    if not angVelc or not angVelc.Parent then angVelc,angVelcAtt=setupAngVelc(root,"ZA") end
    if not batEquipped then
        batEquipped=true
        if not char:FindFirstChildOfClass("Tool") then
            local bat=findBat()
            if bat then pcall(function() hum:EquipTool(bat) end) end
        end
    end


    local target,targetPlr=getStickyTarget(_target)
    if not target then
        _target=nil; hum.AutoRotate=true
        if angVelc then pcall(function() angVelc.AngularVelocity=Vector3.zero end) end
        swingBat(char); return
    end
    _target=target; _targetPlr=targetPlr

    local mode=detectInfiniteJump(target)
    local predictedPos,isEmergency=computePredictedPos(root,target,mode)


    local effectiveSpeed=CFG.SPEED
    if CFG.antiLaggerMode then
        local targetHorizSpeed=Vector3.new(_getV(target).X,0,_getV(target).Z).Magnitude
        if targetHorizSpeed<30 then
            effectiveSpeed=30
        else
            effectiveSpeed=math.min(CFG.SPEED_LIMIT,targetHorizSpeed)
        end
    end

    hum.AutoRotate=false


    local fp=predictedPos
    local look=fp-root.Position
    local toPredict=predictedPos-root.Position
    if toPredict.Magnitude>0.1 then
        local goalCF=CFrame.lookAt(root.Position,predictedPos)
        local diffCF=root.CFrame:Inverse()*goalCF
        local rx,ry,rz=diffCF:ToEulerAnglesXYZ()
        rx=math.clamp(rx,-2.5,2.5); ry=math.clamp(ry,-2.5,2.5); rz=math.clamp(rz,-2.5,2.5)
        root.AssemblyAngularVelocity=root.CFrame:VectorToWorldSpace(Vector3.new(rx*42,ry*42,rz*42))
    else
        root.AssemblyAngularVelocity=Vector3.zero
    end


    local mDir=predictedPos-root.Position
    local hDir=Vector3.new(mDir.X,0,mDir.Z)
    local hVel=hDir.Magnitude>0.1 and hDir.Unit*effectiveSpeed or Vector3.zero

    local desiredHeight=predictedPos.Y
    if mode=="normal" then
        local jumpOffset=math.max(0,_getV(target).Y*0.18)
        desiredHeight=predictedPos.Y+3.7+jumpOffset
    end
    local yVel=(desiredHeight-root.Position.Y)*22+_getV(target).Y*1.1
    if hum.FloorMaterial~=Enum.Material.Air then yVel=math.max(yVel,13) end
    yVel=math.clamp(yVel,-70,135)

    if isEmergency then
        yVel=math.sign(mDir.Y)*CFG.VERT_SPEED*1.4
    elseif math.abs(mDir.Y)>0.8 then
        yVel=math.sign(mDir.Y)*CFG.VERT_SPEED
    else
        yVel=-2
    end

    local desiredVel=Vector3.new(hVel.X,yVel,hVel.Z)
    _intendedVel=_getV(root):Lerp(desiredVel,0.85)
    _setV(root, _intendedVel)
    if hDir.Magnitude>0.5 then hum:Move(hDir.Unit,false) end

    
    if CFG.autoSwing and not swingCD then
        local bat=findBat()
        if bat and bat:IsA("Tool") then
            swingCD=true
            pcall(function()
                bat:Activate()
                local ev=bat:FindFirstChildWhichIsA("RemoteEvent")
                if ev then ev:FireServer() end
            end)
            task.delay(CFG.SWING_COOLDOWN,function() swingCD=false end)
        end
    end
    swingBat(char)
end)


RunService.Heartbeat:Connect(function()
    if not bypassEnabled then return end
    local char=LP.Character
    local hum=char and char:FindFirstChildOfClass("Humanoid")
    local root=char and char:FindFirstChild("HumanoidRootPart")
    if not root or not hum then return end
    purgeHRP(root)
    pcall(function()
        if _G and _G.FR_State then
            _G.FR_State.antiBatEnabled=false; _G.FR_State.bypassAntiBatEnabled=false
        end
    end)
    if not _bypassAngVelc or not _bypassAngVelc.Parent then
        _bypassAngVelc,_bypassAngAtt=setupAngVelc(root,"ZB")
    end
    if not batEquipped then
        batEquipped=true
        if not char:FindFirstChildOfClass("Tool") then
            local bat=findBat()
            if bat then pcall(function() hum:EquipTool(bat) end) end
        end
    end
    local closestTR,closestDist=nil,math.huge
    for _,plr in ipairs(Players:GetPlayers()) do
        if plr~=LP and plr.Character then
            local tr=plr.Character:FindFirstChild("HumanoidRootPart")
            local h2=plr.Character:FindFirstChildOfClass("Humanoid")
            if tr and h2 and h2.Health>0 then
                local d=(tr.Position-root.Position).Magnitude
                if d<closestDist then closestDist=d; closestTR=tr end
            end
        end
    end
    if closestTR then
        _bypassTarget=closestTR

        local _vXZ=Vector3.new(_getV(closestTR).X,0,_getV(closestTR).Z)
        local _vs=_vXZ.Magnitude
        local _moveDir=_vs>0.5 and _vXZ.Unit or closestTR.CFrame.LookVector
        local _dynOff=_vs<0.1 and 1.5 or BYPASS_CFG.LOOK_OFFSET
        local fp=closestTR.Position+_moveDir*_dynOff
        local look=fp-root.Position
        local flatLook=Vector3.new(look.X,0,look.Z)
        hum.AutoRotate=false
        if look.Magnitude>0.01 and flatLook.Magnitude>0.01 then
            local tYaw=math.deg(math.atan2(-flatLook.X,-flatLook.Z))
            local yawD=(tYaw-root.Orientation.Y+180)%360-180
            local tPit=math.deg(math.atan2(look.Y,flatLook.Magnitude))
            local pitD=(tPit-root.Orientation.X+180)%360-180
            local yawR=math.clamp(math.rad(yawD)*40,-28,28)
            local pitR=math.clamp(math.rad(pitD)*40,-28,28)
            local yRad=math.rad(root.Orientation.Y)
            local rAxis=Vector3.new(math.cos(yRad),0,-math.sin(yRad))
            _bypassAngVelc.AngularVelocity=Vector3.new(0,yawR,0)+(rAxis*pitR)
        else
            _bypassAngVelc.AngularVelocity=Vector3.zero
        end
        local mDir=fp-root.Position
        local hDir=Vector3.new(mDir.X,0,mDir.Z)

        local effectiveSpeed=BYPASS_CFG.SPEED
        if BYPASS_CFG.antiLaggerMode then
            local targetHorizSpeed=Vector3.new(_getV(closestTR).X,0,_getV(closestTR).Z).Magnitude
            if targetHorizSpeed<30 then
                effectiveSpeed=30
            else
                effectiveSpeed=math.min(BYPASS_CFG.SPEED_LIMIT,targetHorizSpeed)
            end
        end

        local hVel=hDir.Magnitude>0.1 and hDir.Unit*effectiveSpeed or Vector3.zero
        local vVel=math.abs(mDir.Y)>0.8
            and Vector3.new(0,math.sign(mDir.Y)*BYPASS_CFG.VERT_SPEED,0)
            or Vector3.new(0,-2,0)
        _bypassVel=hVel+vVel; _setV(root, _bypassVel)
        if hDir.Magnitude>0.5 then hum:Move(hDir.Unit,false) end
        if closestDist<=5 then
            local bat=char:FindFirstChild("Bat")
            if bat and bat:IsA("Tool") then
                pcall(function()
                    bat:Activate()
                    local ev=bat:FindFirstChildWhichIsA("RemoteEvent")
                    if ev then ev:FireServer() end
                end)
            end
        end
    else
        _bypassTarget=nil
        hum.AutoRotate=true
        if _bypassAngVelc then pcall(function() _bypassAngVelc.AngularVelocity=Vector3.zero end) end
    end
end)


RunService.RenderStepped:Connect(function()
    local char=LP.Character
    local root=char and char:FindFirstChild("HumanoidRootPart")
    if not root then return end
    if superEnabled then
        local v=_getV(root)
        if math.abs(v.X)>350 or math.abs(v.Z)>350 then _setV(root, _intendedVel) end
        purgeHRP(root)
    elseif bypassEnabled then
        local v=_getV(root)
        if math.abs(v.X)>350 or math.abs(v.Z)>350 then _setV(root, _bypassVel) end
        purgeHRP(root)
    end
end)


