local function applyShimmer(parent,thickness,spd)
    local s=Instance.new("UIStroke")
    s.Thickness=thickness or 2
    s.ApplyStrokeMode=Enum.ApplyStrokeMode.Border
    s.Parent=parent
    local g=Instance.new("UIGradient")
    g.Color=ColorSequence.new({
        ColorSequenceKeypoint.new(0,Color3.fromRGB(35, 15, 3)),
        ColorSequenceKeypoint.new(0.45,Color3.fromRGB(255,160,255)),
        ColorSequenceKeypoint.new(0.55,Color3.fromRGB(255,160,255)),
        ColorSequenceKeypoint.new(1,Color3.fromRGB(35, 15, 3))
    })
    g.Rotation=90; g.Offset=Vector2.new(-1,0); g.Parent=s
    TS:Create(g,TweenInfo.new(spd or 2.2,Enum.EasingStyle.Linear,Enum.EasingDirection.InOut,-1),{Offset=Vector2.new(1,0)}):Play()
    return s
end

local function makeDraggable(frame,handle)
    local dn,ds,sp,di=false,nil,nil,nil
    handle.InputBegan:Connect(function(i)
        if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then
            dn=true; ds=i.Position; sp=frame.Position
            i.Changed:Connect(function() if i.UserInputState==Enum.UserInputState.End then dn=false end end)
        end
    end)
    handle.InputChanged:Connect(function(i)
        if i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch then di=i end
    end)
    UIS.InputChanged:Connect(function(i)
        if i==di and dn then
            local d=i.Position-ds
            frame.Position=UDim2.new(sp.X.Scale,sp.X.Offset+d.X,sp.Y.Scale,sp.Y.Offset+d.Y)
        end
    end)
end

