local function addKeybindRow(scroll, loRef, labelTxt, getKey, setKey, saveCb)
    loRef[1] = loRef[1] + 1
    local row = Instance.new("Frame", scroll)
    row.Size = UDim2.new(1,0,0,30); row.BackgroundColor3 = CARD_COL
    row.BorderSizePixel = 0; row.LayoutOrder = loRef[1]; row.ZIndex = 2
    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6)
    Instance.new("UIStroke", row).Color = Color3.fromRGB(100, 43, 10)
    local lbl = Instance.new("TextLabel", row)
    lbl.Size = UDim2.new(0.55,0,1,0); lbl.Position = UDim2.new(0,8,0,0)
    lbl.BackgroundTransparency = 1; lbl.Text = labelTxt
    lbl.TextColor3 = W_COL; lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 9
    lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.ZIndex = 3
    local kbBtn = Instance.new("TextButton", row)
    kbBtn.Size = UDim2.new(0,60,0,20); kbBtn.Position = UDim2.new(1,-66,0.5,-10)
    kbBtn.BackgroundColor3 = INP_COL; kbBtn.BorderSizePixel = 0
    kbBtn.Text = "[ "..getKey().." ]"; kbBtn.TextColor3 = W_COL
    kbBtn.Font = Enum.Font.GothamBold; kbBtn.TextSize = 9; kbBtn.ZIndex = 3
    Instance.new("UICorner", kbBtn).CornerRadius = UDim.new(0, 4)
    Instance.new("UIStroke", kbBtn).Color = Color3.fromRGB(100, 43, 10)
    local listening = false
    local kbConn = nil
    kbBtn.MouseButton1Click:Connect(function()
        if listening then return end
        listening = true; kbBtn.Text = "[ ... ]"; kbBtn.TextColor3 = ORANGE_ON
        kbConn = UIS.InputBegan:Connect(function(inp, _gp)
            if not listening then return end
            local isKb = inp.UserInputType == Enum.UserInputType.Keyboard
            local isGP = inp.UserInputType == Enum.UserInputType.Gamepad1
            if not isKb and not isGP then return end
            if isKb and inp.KeyCode == Enum.KeyCode.Escape then
                listening = false; kbBtn.Text = "[ "..getKey().." ]"; kbBtn.TextColor3 = W_COL
                if kbConn then kbConn:Disconnect(); kbConn = nil end
                return
            end
            local kn = tostring(inp.KeyCode):sub(14)
            if kn and kn ~= "" and kn ~= "Unknown" then
                setKey(kn); if saveCb then saveCb() end
                kbBtn.Text = "[ "..kn.." ]"; kbBtn.TextColor3 = W_COL
                listening = false
                if kbConn then kbConn:Disconnect(); kbConn = nil end
            end
        end)
    end)
end

local function addSaveRow(scroll, loRef, saveCb)
    loRef[1] = loRef[1] + 1
    local row = Instance.new("Frame", scroll)
    row.Size = UDim2.new(1,0,0,28); row.BackgroundColor3 = Color3.fromRGB(60, 25, 6)
    row.BorderSizePixel = 0; row.LayoutOrder = loRef[1]; row.ZIndex = 2
    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 6)
    local rs = Instance.new("UIStroke", row); rs.Color = ORANGE_STR; rs.Thickness = 1
    local saveBtn = Instance.new("TextButton", row)
    saveBtn.Size = UDim2.new(1,0,1,0); saveBtn.BackgroundTransparency = 1
    saveBtn.Text = "SAVE CONFIG"; saveBtn.TextColor3 = ORANGE_STR
    saveBtn.Font = Enum.Font.GothamBlack; saveBtn.TextSize = 10; saveBtn.ZIndex = 3
    local savedLbl = Instance.new("TextLabel", row)
    savedLbl.Size = UDim2.new(1,0,1,0); savedLbl.BackgroundTransparency = 1
    savedLbl.Text = "SAVED"; savedLbl.TextColor3 = ORANGE_ON
    savedLbl.Font = Enum.Font.GothamBlack; savedLbl.TextSize = 10
    savedLbl.Visible = false; savedLbl.ZIndex = 3
    saveBtn.MouseButton1Click:Connect(function()
        saveCb(); saveBtn.Visible = false; savedLbl.Visible = true
        task.delay(1.5, function() saveBtn.Visible = true; savedLbl.Visible = false end)
    end)
    saveBtn.MouseEnter:Connect(function() TS:Create(row, TweenInfo.new(0.12), {BackgroundColor3 = Color3.fromRGB(85, 36, 8)}):Play() end)
    saveBtn.MouseLeave:Connect(function() TS:Create(row, TweenInfo.new(0.12), {BackgroundColor3 = Color3.fromRGB(60, 25, 6)}):Play() end)
end

