local function keyToEnum(n)
    if not n then return nil end
    local ok, kc = pcall(function() return Enum.KeyCode[n] end)
    return ok and kc or nil
end

local aimKeyConn = UIS.InputBegan:Connect(function(inp, _gpe)
    local isKb = inp.UserInputType == Enum.UserInputType.Keyboard
    local isGP = inp.UserInputType == Enum.UserInputType.Gamepad1
    if not isKb and not isGP then return end
    local kc = keyToEnum(CFG.keybind)
    if kc and inp.KeyCode == kc then
        if aimEnabled then disableAim(); aimEnabled = false else enableAim() end
        updateStrongVisual(); updateProVisual(); updateGoodVisual(); saveUA()
    end
    local pkc = keyToEnum(PRO_CFG.keybind)
    if pkc and inp.KeyCode == pkc then
        if proEnabled then disablePro(); proEnabled = false else enablePro() end
        updateStrongVisual(); updateProVisual(); updateGoodVisual(); savePro()
    end
    local gkc = keyToEnum(GOOD_CFG.keybind)
    if gkc and inp.KeyCode == gkc then
        if goodEnabled then disableGood(); goodEnabled = false else enableGood() end
        updateStrongVisual(); updateProVisual(); updateGoodVisual(); saveGood()
    end
end)

game:BindToClose(function()
    _G.FRHUB_Merged_Running = false
    disableAim(); disablePro(); disableGood()
end)

_G.FRHUB_AIMBOT_STOP = function()
    _G.FRHUB_Merged_Running = false
    if aimKeyConn then pcall(function() aimKeyConn:Disconnect() end); aimKeyConn = nil end
    pcall(disableAim); pcall(disablePro); pcall(disableGood)
    local _cg = game:GetService("CoreGui")
    local _g = _cg:FindFirstChild("FRHUB_Merged")
    if _g then pcall(function() _g:Destroy() end) end
    pcall(function()
        local _lp = game:GetService("Players").LocalPlayer
        local _pg = _lp and _lp:FindFirstChild("PlayerGui")
        local _g2 = _pg and _pg:FindFirstChild("FRHUB_Merged")
        if _g2 then _g2:Destroy() end
    end)
end

end) end)
end
_G.FRHUB_AIMBOT()
    end) end)
    end
    _settOldAimbot = makeToggleRow("MISC","OLD AIMBOT",false,function(on)
        State.oldAimbotEnabled = on
        if on then
            State.fireOldAimbot()
        else
            pcall(function()
                if _G.FRHUB_AIMBOT_STOP then _G.FRHUB_AIMBOT_STOP() end
                _G.FRHUB_Merged_Running=false
                local _CG=game:GetService("CoreGui"); local _g=_CG:FindFirstChild("FRHUB_Merged")
                if _g then _g:Destroy() end
            end)
        end
        autoSaveConfig()
    end)
    State.setOldAimbot = _settOldAimbot
end

