_G.__frhubLongToggleRow = function(label, labelScale, labelSize, defOn, onToggle)
    local row = makeRow("MISC", 30)
    local lbl = makeRowLabel(row, label, labelScale or 0.78)
    if labelSize then lbl.TextSize = labelSize end
    lbl.TextTruncate = Enum.TextTruncate.AtEnd
    local setV, pill, dot, getIsOn = makePill(row, defOn)
    local _ct = 0
    local function _fn()
        if tick() - _ct < 0.2 then return end; _ct = tick()
        local newOn = not getIsOn(); setV(newOn)
        if onToggle then pcall(onToggle, newOn) end
        autoSaveConfig()
    end
    row.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 then task.defer(_fn) end
    end)
    pill.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
            task.defer(_fn)
        end
    end)
    return setV
end

State.setOpAntiBatRow = _G.__frhubLongToggleRow("ANTI BAT BETTER THAN SPACE/HOOK", 1, 8.3, State.opAntiBatEnabled == true, function(on)
    local visible = on == true
    local gui = _G.FRHUBV67Gui
    if gui == nil or gui.Parent == nil then
        local cg = game:GetService("CoreGui")
        gui = cg and cg:FindFirstChild("FRHUB_ANTIBAT_V67")
        if not gui then
            local pg = LP:FindFirstChild("PlayerGui")
            gui = pg and pg:FindFirstChild("FRHUB_ANTIBAT_V67")
        end
        if not gui and type(gethui) == "function" then
            local ok, h = pcall(gethui)
            if ok and h then gui = h:FindFirstChild("FRHUB_ANTIBAT_V67") end
        end
    end
    if gui then gui.Enabled = visible end
    _G.FRHUBV67Gui = gui
    State.opAntiBatEnabled = visible
    autoSaveConfig()
end)

