                if holder.Transparency < 0.35 then holder.Transparency = 0.35 end
            elseif holder:IsA("TextLabel") or holder:IsA("TextButton") or holder:IsA("TextBox") then
                if c and holder.BackgroundTransparency >= 0.98 then holder.TextColor3 = c end
            elseif holder:IsA("GuiObject") then
