local MusicSound   = nil
local MusicActive  = nil
local MusicSetters = {}

local function stopMusic()
    MusicActive = nil
    if MusicSound then
        pcall(function() MusicSound:Stop(); MusicSound:Destroy() end)
        MusicSound = nil
    end
    for _, s in pairs(MusicSetters) do pcall(s, false) end
end

local function playMusic(idx)
    local prev = MusicActive
    stopMusic()
    if prev == idx then return end
    MusicActive = idx
    if MusicSetters[idx] then pcall(MusicSetters[idx], true) end
    local track = MUSIC_TRACKS[idx]
    task.spawn(function()
        local assetFunc = getsynasset or getcustomasset
        if not assetFunc then
            warn("PLAYLIST: executor does not support custom assets")
            stopMusic(); return
        end

        if not isfolder(MUSIC_FOLDER) then
            local ok = pcall(makefolder, MUSIC_FOLDER)
            if not ok then warn("PLAYLIST: failed to create folder"); stopMusic(); return end
        end

        local path = MUSIC_FOLDER .. "/" .. track.file

        if not isfile(path) then
            local dlOk, dlErr = pcall(function()
                writefile(path, game:HttpGet(track.url))
            end)
            if not dlOk then
                warn("PLAYLIST: download failed for " .. track.name .. " | " .. tostring(dlErr))
                stopMusic(); return
            end
        end

        if MusicActive ~= idx then return end

        local assetId
        local assetOk, assetErr = pcall(function()
            assetId = assetFunc(path)
        end)
        if not assetOk or not assetId then
            warn("PLAYLIST: assetFunc failed for " .. track.name .. " | " .. tostring(assetErr))
            stopMusic(); return
        end

        local snd = Instance.new("Sound")
        snd.Volume = 1
        snd.SoundId = assetId
        snd.Parent = game:GetService("SoundService")
        snd.Looped = true
        MusicSound = snd

        local playOk, playErr = pcall(function() snd:Play() end)
        if not playOk then
            warn("PLAYLIST: play failed | " .. tostring(playErr))
            stopMusic()
        end
    end)
end

makeSectionLabel("PLAYLIST", "Songs")
for i = 1, #MUSIC_TRACKS do
    local _i = i
    MusicSetters[i] = makeToggleRow("PLAYLIST", MUSIC_TRACKS[i].name, false, function(on)
        if on then
            playMusic(_i)
        else
            if MusicActive == _i then stopMusic() end
        end
    end)
end

local function applyMobileBtnVisibility(info)
    local hidden = mobileBtnHidden[info.key]
    pcall(function()
        local gui = game:GetService("CoreGui"):FindFirstChild("FRHUBV2_Buttons")
        if not gui then
            gui = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
                and game:GetService("Players").LocalPlayer.PlayerGui:FindFirstChild("FRHUBV2_Buttons")
        end
        if gui then
            local obj = gui:FindFirstChild(info.containerName)
            if obj then
                obj.Visible = not hidden
            end
        end
    end)
end

local function refreshMobileBtnVisibility()
    for _,info in ipairs(MOBILE_BTN_KEYS) do
        applyMobileBtnVisibility(info)
    end
    if MS_BTN_KEYS then
        for _,info in ipairs(MS_BTN_KEYS) do
            applyMobileBtnVisibility(info)
        end
    end
end

