local function makeSmallToggleRow(tabName, label, defOn, onToggle)
    local row=makeRow(tabName,30)
    makeRowLabel(row,label,0.70)
    local lbl=row:FindFirstChildOfClass("TextLabel")
    if lbl then
        lbl.TextSize=8
        lbl.TextWrapped=true
    end
    local setV, pill, dot, getIsOn = makePill(row, defOn)
    local _ct=0
    local function _fn()
        if tick()-_ct<0.2 then return end; _ct=tick()
        local newOn=not getIsOn(); setV(newOn)
        if onToggle then pcall(onToggle,newOn) end
        autoSaveConfig()
    end
    row.InputBegan:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.MouseButton1 then
            task.defer(_fn)
        end
    end)
    pill.InputBegan:Connect(function(inp)
        if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
            task.defer(_fn)
        end
    end)
    return setV
end

