local function createMobilePanel()
    local panel=Instance.new("ScreenGui"); panel.Name="FRHUBV2_Buttons"
    pcall(function() panel.Parent=CoreGui end)
    if not panel.Parent then panel.Parent=LP:WaitForChild("PlayerGui") end
    panel.ResetOnSpawn=false; panel.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
    MobileButtons.UIScale = Instance.new("UIScale", panel)
    MobileButtons.UIScale.Scale = uiScaleValue / 100

    local BTN_W,BTN_H,CORNER,GAP=54,54,13,10
    local COL1_X=-(BTN_W+GAP+BTN_W+8); local COL2_X=-(BTN_W+8)
    local COL0_X=-(BTN_W+GAP+BTN_W+GAP+BTN_W+8)
    local COL3_X=-(BTN_W+GAP+BTN_W+GAP+BTN_W+GAP+BTN_W+8)
    local BASE_Y=0.30
    local ROW_Y={-((BTN_H*5+GAP*4)/2),
                 -((BTN_H*5+GAP*4)/2)+(BTN_H+GAP),
                 -((BTN_H*5+GAP*4)/2)+(BTN_H+GAP)*2,
                 -((BTN_H*5+GAP*4)/2)+(BTN_H+GAP)*3,
                 -((BTN_H*5+GAP*4)/2)+(BTN_H+GAP)*4}

    local function makeSeparateBtn(name, text, defaultPos, saveKey, onActivate, isToggle, stateKey, noCooldown)
        local container=Instance.new("Frame"); container.Name=name; container.Parent=panel
        container.BackgroundColor3=Color3.fromRGB(40, 17, 4); container.BackgroundTransparency=0
        container.BorderSizePixel=0; container.Size=UDim2.new(0,BTN_W,0,BTN_H); container.Position=defaultPos
        Instance.new("UICorner",container).CornerRadius=UDim.new(0,CORNER)
        createShimmerBorder(container,4,1.2); addBgTex(container,0.85,CORNER)

        local btn=Instance.new("TextButton",container)
        btn.Size=UDim2.new(1,0,1,0); btn.BackgroundTransparency=1; btn.BorderSizePixel=0
        btn.Font=Enum.Font.GothamBlack; btn.Text=text; btn.TextColor3=C_ACCENT; btn.TextSize=10; btn.TextWrapped=true; btn.AutoButtonColor=false; btn.ZIndex=3

        local active=false
        local function setActive(state)
            active=state
            TweenService:Create(container,TweenInfo.new(0.15),{BackgroundColor3=active and C_ON_BG or Color3.fromRGB(40, 17, 4)}):Play()
            btn.TextColor3=active and C_WHITE or C_ACCENT
        end

        local _btnT=0
        btn.MouseButton1Click:Connect(function()
            if drag then return end
            if not noCooldown and tick()-_btnT<0.25 then return end; _btnT=tick()
            if onActivate then onActivate(setActive) end
        end)
        btn.Activated:Connect(function()
            if drag then return end
            if not noCooldown and tick()-_btnT<0.25 then return end; _btnT=tick()
            if onActivate then onActivate(setActive) end
        end)

        
        if stateKey then
            local kbArea=Instance.new("TextButton",container)
            kbArea.Name="KBFrame"
            kbArea.Size=UDim2.new(1,-4,0,13); kbArea.Position=UDim2.new(0,2,1,-15)
            kbArea.BackgroundColor3=Color3.fromRGB(16, 6, 1); kbArea.BorderSizePixel=0
            kbArea.Font=Enum.Font.Gotham; kbArea.TextSize=8; kbArea.AutoButtonColor=false; kbArea.ZIndex=5
            Instance.new("UICorner",kbArea).CornerRadius=UDim.new(0,4)
            local function refreshKB()
                local kc=State[stateKey]
                if kc and kc~=Enum.KeyCode.Unknown then
                    local kn=tostring(kc):sub(14)
                    kbArea.Text="["..kn.."]"; kbArea.TextColor3=C_ACCENT
                else
                    kbArea.Text="[?]"; kbArea.TextColor3=C_DIM
                end
            end
            refreshKB()

            State._keybindRefreshers = State._keybindRefreshers or {}
            State._keybindRefreshers[stateKey] = refreshKB
            local kbListening=false
            local function startListen()
                if kbListening then return end
                kbListening=true; kbArea.Text="[...]"; kbArea.TextColor3=C_ACCENT2
            end
            kbArea.MouseButton1Click:Connect(startListen)
            kbArea.Activated:Connect(startListen)
            UIS.InputBegan:Connect(function(inp,gp)
                if not kbListening then return end
                local isKb2=inp.UserInputType==Enum.UserInputType.Keyboard
                local isGP2=inp.UserInputType==Enum.UserInputType.Gamepad1
                if not isKb2 and not isGP2 then return end
                local kc2=inp.KeyCode
                if kc2==Enum.KeyCode.Unknown then return end
                State[stateKey]=kc2; kbListening=false
                refreshKB(); autoSaveConfig()
            end)
        end

        local drag,ds,sp=false,nil,nil
        local function startDrag(pos)
            if MobileButtons.Locked then return end
            drag=true
            ds=Vector2.new(pos.X,pos.Y)
            sp=container.Position
        end
        local function moveDrag(pos)
            if not drag then return end
            local d=Vector2.new(pos.X,pos.Y)-ds
            container.Position=UDim2.new(sp.X.Scale,sp.X.Offset+d.X,sp.Y.Scale,sp.Y.Offset+d.Y)
        end
        local function endDrag() drag=false end
        btn.InputBegan:Connect(function(inp)
            if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
                startDrag(inp.Position)
            end
        end)
        btn.InputEnded:Connect(function(inp)
            if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
                endDrag()
            end
        end)
        container.InputBegan:Connect(function(inp)
            if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
                startDrag(inp.Position)
            end
        end)
        container.InputEnded:Connect(function(inp)
            if inp.UserInputType==Enum.UserInputType.MouseButton1 or inp.UserInputType==Enum.UserInputType.Touch then
                endDrag()
            end
        end)
        UIS.InputChanged:Connect(function(inp)
            if inp.UserInputType==Enum.UserInputType.MouseMovement or inp.UserInputType==Enum.UserInputType.Touch then
                moveDrag(inp.Position)
            end
        end)
        UIS.TouchMoved:Connect(function(touch,_)
            moveDrag(touch.Position)
        end)

        local savedPos=nil; pcall(function() savedPos=readfile(saveKey) end)
        if savedPos and savedPos~="" then
            local parts={}; for p in string.gmatch(savedPos,"[^,]+") do table.insert(parts,p) end
            if #parts>=4 then container.Position=UDim2.new(tonumber(parts[1]),tonumber(parts[2]),tonumber(parts[3]),tonumber(parts[4])) end
        end
        local _lSave=0
        container:GetPropertyChangedSignal("Position"):Connect(function()
            if tick()-_lSave>0.5 then _lSave=tick()
                local pos=container.Position; pcall(function() writefile(saveKey,string.format("%.3f,%.1f,%.3f,%.1f",pos.X.Scale,pos.X.Offset,pos.Y.Scale,pos.Y.Offset)) end) end
        end)
        container.Visible=MobileButtons.Visible; table.insert(MobileButtons.Containers,container)
        return setActive
    end

