    end
    State.setAimbotV7PanelGhost = function(hidden)
        pcall(function()
            local g = game:GetService("CoreGui"):FindFirstChild("FRHUB6777_AIMBOT_PANEL")
            if not g then
                local pg = LP:FindFirstChild("PlayerGui")
                g = pg and pg:FindFirstChild("FRHUB6777_AIMBOT_PANEL")
            end
            if not g then return end
            if hidden then
                State._v7GhostFrames = {}
                for _, ch in ipairs(g:GetChildren()) do
                    if ch:IsA("GuiObject") and ch.Visible then
                        table.insert(State._v7GhostFrames, ch)
                        ch.Visible = false
                    end
                end
            else
                for _, f in ipairs(State._v7GhostFrames or {}) do pcall(function() f.Visible = true end) end
                State._v7GhostFrames = nil
            end
        end)
    end
    _G.FRHUBSetAimbotV10 = function(on)
        on = on == true
        State.aimbotV10Enabled = on
        if State.aimbotV5BypassApply then pcall(State.aimbotV5BypassApply, on) end
        if _G.FRHUBSetAimbotV7Engine then pcall(_G.FRHUBSetAimbotV7Engine, on) end
        State.aimbotV7Enabled = on
        if State.setAimbotV7Visual then pcall(State.setAimbotV7Visual, on) end
        if State.setAimbotV7PanelGhost then pcall(State.setAimbotV7PanelGhost, on) end
        if State.setAimbotV10Visual then pcall(State.setAimbotV10Visual, on) end
    end
    if _G._FRHUBAimbotV10Pending then
        _G._FRHUBAimbotV10Pending = nil
    task.spawn(function()
        local _v10first = true
        local _v10clean = 0
        for _v10try = 1, 60 do
            if not (State.aimbotV10Enabled == true) then return end
            if _v10first then
                _v10first = false
                if _G.FRHUBSetAimbotV10 then pcall(_G.FRHUBSetAimbotV10, true) end
            else
                task.wait(0.5)
                if not (State.aimbotV10Enabled == true) then return end
            end
            local needBypass = _G.FRHUB_BYPASS_AIMBOT ~= nil and _G.FRHUB_BYPASS_AIMBOT.enabled() ~= true
            local needGhost = State.aimbotV7Enabled == true and State._v7GhostFrames == nil
            local needEngine = State.aimbotV7Enabled == true and _G._FRHUBV7EngineActive ~= true
            if needEngine and _G.FRHUBSetAimbotV7Engine then pcall(_G.FRHUBSetAimbotV7Engine, true) end
            if needBypass and State.aimbotV5BypassApply then pcall(State.aimbotV5BypassApply, true) end
            if needGhost and State.setAimbotV7PanelGhost then pcall(State.setAimbotV7PanelGhost, true) end
            if needBypass or needGhost or needEngine then
                _v10clean = 0
            else
                _v10clean = _v10clean + 1
                if _v10clean >= 6 then return end
            end
        end
    end)
    end

    
    local aimbotV11SA = makeSeparateBtn("BtnAimbotV11","AIMBOT\nV11\nBYPASS",UDim2.new(1,COL3_X,BASE_Y,ROW_Y[3]),"FRHUBV2_Btn_aimbotv11.txt",
