task.spawn(function()
    local Players2=game:GetService("Players"); local RunService2=game:GetService("RunService")
    local TweenService2=game:GetService("TweenService")
    local LP2=Players2.LocalPlayer
    local _carryBB=nil; local _carryBBActive=false; local _carryCountConn=nil
    local CARRY_ANIM_ID="71186871415348"
    local PURPLE_D=Color3.fromRGB(30, 12, 3); local PURPLE_S=Color3.fromRGB(255, 109, 25)
    local PURPLE_A=Color3.fromRGB(240, 103, 24); local PURPLE_SH=Color3.fromRGB(255,180,255)
    local function destroyBB()
        _carryBBActive=false
        if _carryCountConn then pcall(function() task.cancel(_carryCountConn) end); _carryCountConn=nil end
        if _carryBB then pcall(function() _carryBB:Destroy() end); _carryBB=nil end
    end
    local function isInCarry()
        local char=LP2.Character; if not char then return false end
        local hum=char:FindFirstChildOfClass("Humanoid"); if not hum then return false end
        local anim=hum:FindFirstChildOfClass("Animator"); if not anim then return false end
        for _,t in ipairs(anim:GetPlayingAnimationTracks()) do
            if t.Animation.AnimationId:find(CARRY_ANIM_ID) then return true end
        end
        return false
    end
    local function createBB()
        if _carryBBActive then return end
        local char=LP2.Character; if not char then return end
        local head=char:FindFirstChild("Head"); if not head then return end
        destroyBB()
        _carryBBActive=true
        local bb=Instance.new("BillboardGui"); bb.Name="CarryWinBillboard"
        bb.Size=UDim2.new(0,110,0,46); bb.StudsOffset=Vector3.new(-3.5,1.2,0)
        bb.AlwaysOnTop=true; bb.LightInfluence=0; bb.Parent=head; _carryBB=bb
        
        local bg=Instance.new("Frame",bb); bg.Size=UDim2.new(1,0,1,0); bg.Position=UDim2.new(0,0,0,0)
        bg.BackgroundColor3=PURPLE_D; bg.BackgroundTransparency=0.55; bg.BorderSizePixel=0
        Instance.new("UICorner",bg).CornerRadius=UDim.new(0,10)
        local stroke=Instance.new("UIStroke",bg); stroke.Color=PURPLE_S; stroke.Thickness=1.5; stroke.Transparency=0.4
        
        local titleLbl=Instance.new("TextLabel",bg)
        titleLbl.Size=UDim2.new(1,-4,0,16); titleLbl.Position=UDim2.new(0,2,0,2)
        titleLbl.BackgroundTransparency=1; titleLbl.Text="ANTI KICK E01"
        titleLbl.Font=Enum.Font.GothamBold; titleLbl.TextSize=10; titleLbl.TextColor3=PURPLE_SH
        titleLbl.TextStrokeTransparency=0.5; titleLbl.TextXAlignment=Enum.TextXAlignment.Center
        
        local countLbl=Instance.new("TextLabel",bg)
        countLbl.Size=UDim2.new(1,-4,0,26); countLbl.Position=UDim2.new(0,2,0,18)
        countLbl.BackgroundTransparency=1; countLbl.Text="WIN AFTER: 3"
        countLbl.Font=Enum.Font.GothamBold; countLbl.TextSize=15; countLbl.TextColor3=PURPLE_A
        countLbl.TextStrokeTransparency=0.4; countLbl.TextXAlignment=Enum.TextXAlignment.Center
        
        local startT=tick()
        local DURATION=3.1
        _carryCountConn=task.spawn(function()
            while _carryBBActive do
                task.wait(0.05)
                if not isInCarry() then destroyBB(); return end
                local elapsed=tick()-startT
                local remaining=math.max(0,DURATION-elapsed)
                local disp=math.ceil(remaining)
                if countLbl and countLbl.Parent then
                    countLbl.Text="WIN AFTER: "..tostring(disp)
                    local frac=remaining/DURATION
                    countLbl.TextColor3=Color3.fromRGB(
                        math.floor(150+(1-frac)*100),
                        math.floor(90+frac*50),
                        math.floor(240))
                end
                if elapsed>=DURATION then destroyBB(); return end
            end
        end)
    end
    local wasCarry=false
    while true do
        task.wait(0.12)
        pcall(function()
            local nowCarry=isInCarry()
            if nowCarry and not wasCarry then createBB() end
            if not nowCarry and wasCarry then destroyBB() end
            wasCarry=nowCarry
        end)
    end
end)

