task.spawn(function()
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LP = Players.LocalPlayer
    local hooked = setmetatable({}, {__mode = "k"})
    local function disable(part)
        if part:IsA("BasePart") and part.CanCollide ~= false then part.CanCollide = false end
    end
    local function hookPart(part)
        if not part:IsA("BasePart") or hooked[part] then return end
        hooked[part] = true
        disable(part)
        part:GetPropertyChangedSignal("CanCollide"):Connect(function()
            if part.CanCollide then part.CanCollide = false end
        end)
    end
    local function hookChar(char)
        for _, d in ipairs(char:GetChildren()) do hookPart(d) end
        char.ChildAdded:Connect(hookPart)
    end
    local function hookPlayer(p)
        if p == LP then return end
        if p.Character then hookChar(p.Character) end
        p.CharacterAdded:Connect(hookChar)
    end
    for _, p in ipairs(Players:GetPlayers()) do hookPlayer(p) end
    Players.PlayerAdded:Connect(hookPlayer)
    RunService.Heartbeat:Connect(function()
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                for _, part in ipairs(p.Character:GetChildren()) do disable(part) end
            end
        end
    end)
end)

RunService.RenderStepped:Connect(function()
    if _G.Round3SpeedBooster and _G.Round3SpeedBooster.Enabled then return end
    if _G.FRHUB_AIMBOT_V4_ACTIVE or _G.FRHUB_BYPASS_AIMBOT_ACTIVE then
        return
    end
    if _G._FRHUBV11EngineActive then return end
    if _G._FRHUBZigZagFalling then return end
    if not (h and hrp) then return end; if State._tpInProgress then return end
    if State.autoLeftEnabled or State.autoRightEnabled then
        if speedLbl then local hs=Vector3.new(hrp.Velocity.X,0,hrp.Velocity.Z).Magnitude; speedLbl.Text="Speed: "..string.format("%.1f",hs) end; return
    end
    local md=h.MoveDirection; local spd=getCurrentSpeed()
    if md.Magnitude>0 then
        State.lastMoveDir=md; hrp.Velocity = Vector3.new(md.X*spd, hrp.Velocity.Y, md.Z*spd)
    else
        local anyHeld=false; for key in pairs(MOVE_KEYS) do if UIS:IsKeyDown(key) then anyHeld=true; break end end
        if anyHeld and State.lastMoveDir.Magnitude>0 then
            hrp.Velocity = Vector3.new(State.lastMoveDir.X*spd, hrp.Velocity.Y, State.lastMoveDir.Z*spd)
        elseif State.lastMoveDir.Magnitude>0 then
            hrp.Velocity = Vector3.zero
            State.lastMoveDir = Vector3.zero
        end
        
    end
    if speedLbl then local hs=Vector3.new(hrp.Velocity.X,0,hrp.Velocity.Z).Magnitude; speedLbl.Text="Speed: "..string.format("%.1f",hs) end
end)

_G.FRHUB_LBG = {hrp = nil, lastPos = nil, lastVelH = Vector3.zero, boostUntil = 0, lastFix = 0, pauseUntil = 0, abHold = 0, lastCrumb = 0, crumbs = {}, conn = nil}
_G.FRHUB_LBG.step = function(dt)
    local LBG = _G.FRHUB_LBG
    local function reset() LBG.lastPos = nil; LBG.crumbs = {}; LBG.lastCrumb = 0 end
    if State.antiLagBackEnabled ~= true then reset(); return end
    if not (h and hrp) or not hrp.Parent then reset(); return end
    if _G.Round3SpeedBooster and _G.Round3SpeedBooster.Enabled then reset(); return end
    if _G.FRHUB_AIMBOT_V4_ACTIVE or _G.FRHUB_BYPASS_AIMBOT_ACTIVE or _G._FRHUBV11EngineActive or _G._FRHUBZigZagFalling then reset(); return end
    if State._tpInProgress or State.autoLeftEnabled or State.autoRightEnabled then reset(); return end
    local st = h:GetState()
    if st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll or st == Enum.HumanoidStateType.Dead then reset(); return end
    if LBG.hrp ~= hrp then reset(); LBG.hrp = hrp end
    local md = h.MoveDirection
    local now = tick()
    local pos = hrp.Position
    local vel = hrp.AssemblyLinearVelocity
    local spd = getCurrentSpeed()
    local abOn = _G.FRHUB_ANTI_BAT_ACTIVE == true or _G.FRHUBAntiBatV67Enabled == true
    local spiking = _G._FRHUBAntiBatV67Spiking == true
    local rawHs = Vector3.new(vel.X, 0, vel.Z).Magnitude
    local spiked = abOn and rawHs > math.max(spd * 2 + 60, 250)
    if spiking or spiked then LBG.abHold = now + 0.3 end
    local cleanH = (spiking or spiked) and LBG.lastVelH or Vector3.new(vel.X, 0, vel.Z)
    local crumbs = LBG.crumbs
    if LBG.lastPos and dt > 0 and now - LBG.lastFix > 3 and now > LBG.pauseUntil and now > LBG.abHold and _G.FRHUB_LBG_RESTORE ~= false and now - (_G.FRHUB_LAST_TRIGGER or 0) > 3 then
        local step = Vector3.new(pos.X - LBG.lastPos.X, 0, pos.Z - LBG.lastPos.Z).Magnitude
        if step > 12 and step < 500 then
            for k = 1, #crumbs do
                local c = crumbs[k]
                if now - c.t >= 0.4
                    and Vector3.new(pos.X - c.p.X, 0, pos.Z - c.p.Z).Magnitude < 8
                    and Vector3.new(LBG.lastPos.X - c.p.X, 0, LBG.lastPos.Z - c.p.Z).Magnitude > 12 then
                    if LBG.lastFix > 0 and now - LBG.lastFix < 8 then LBG.pauseUntil = now + 15; break end
                    local newPos = Vector3.new(LBG.lastPos.X + LBG.lastVelH.X * dt, pos.Y, LBG.lastPos.Z + LBG.lastVelH.Z * dt)
                    hrp.CFrame = CFrame.new(newPos) * (hrp.CFrame - hrp.CFrame.Position)
                    if not abOn then
                        if md.Magnitude > 0 and spd > 0 then
                            hrp.AssemblyLinearVelocity = Vector3.new(md.X * spd, vel.Y, md.Z * spd)
                        else
                            hrp.AssemblyLinearVelocity = Vector3.new(0, vel.Y, 0)
                        end
                        vel = hrp.AssemblyLinearVelocity
                        cleanH = Vector3.new(vel.X, 0, vel.Z)
                    end
                    LBG.lastFix = now
                    LBG.boostUntil = now + 0.6
                    pos = newPos
                    break
                end
            end
        end
    end
    LBG.lastPos = pos
    LBG.lastVelH = cleanH
    if now - LBG.lastCrumb >= 0.1 then
        LBG.lastCrumb = now
        table.insert(crumbs, {t = now, p = pos})
        while #crumbs > 0 and now - crumbs[1].t > 8 do table.remove(crumbs, 1) end
    end
    if abOn or now < LBG.abHold then return end
    if md.Magnitude <= 0 or spd <= 0 then return end
    if now > LBG.boostUntil and now - (_G.FRHUB_LAST_TRIGGER or 0) > 0.7 then return end
    local hs = Vector3.new(vel.X, 0, vel.Z).Magnitude
    if hs < spd - 1 then
        local nhs = math.min(spd, hs + spd * 0.5)
        hrp.AssemblyLinearVelocity = Vector3.new(md.X * nhs, vel.Y, md.Z * nhs)
    end
end
State.setAntiLagBackEnabled = function(on)
    on = on == true
    State.antiLagBackEnabled = on
    if State.setAntiLagBackVisual then State.setAntiLagBackVisual(on) end
    local LBG = _G.FRHUB_LBG
    if on then
        if not LBG.conn then LBG.conn = RunService.Heartbeat:Connect(LBG.step) end
    else
        if LBG.conn then LBG.conn:Disconnect(); LBG.conn = nil end
        LBG.lastPos = nil; LBG.crumbs = {}; LBG.lastCrumb = 0
    end
end


