local function loadConfig()
    local hasFile=false; pcall(function() hasFile=isfile("FRHUBV2_Config.json") end)
    if not hasFile then return end
    local ok,cfg=pcall(function() return HttpService:JSONDecode(readfile("FRHUBV2_Config.json")) end)
    if not ok or not cfg then return end
    if cfg.normalSpeed     and normalBox     then State.normalSpeed=cfg.normalSpeed;         normalBox.Text=tostring(cfg.normalSpeed) end
    if cfg.carrySpeed      and carryBox      then State.carrySpeed=cfg.carrySpeed;           carryBox.Text=tostring(cfg.carrySpeed) end
    if cfg.laggerSpeed     and laggerBox     then State.laggerSpeed=cfg.laggerSpeed;         laggerBox.Text=tostring(cfg.laggerSpeed) end
    if cfg.laggerCarrySpeed and carryLaggerBox then State.laggerCarrySpeed=cfg.laggerCarrySpeed; carryLaggerBox.Text=tostring(cfg.laggerCarrySpeed) end
    if type(cfg.dropAscendSpeed)=="number" and cfg.dropAscendSpeed>0 then
        DROP_ASCEND_SPEED=cfg.dropAscendSpeed
        if dropSpeedBox then dropSpeedBox.Text=tostring(DROP_ASCEND_SPEED) end
    end
    if type(cfg.dropAscendDuration)=="number" and cfg.dropAscendDuration>0 then
        DROP_ASCEND_DURATION=cfg.dropAscendDuration
        if dropDurationBox then dropDurationBox.Text=tostring(DROP_ASCEND_DURATION) end
    end
    if type(cfg.tpDownV3IntervalMs)=="number" and cfg.tpDownV3IntervalMs>0 then
        TP_DOWN_V3_INTERVAL_MS=math.floor(math.clamp(cfg.tpDownV3IntervalMs,1,9999))
        if tpDownV3PowerBox then tpDownV3PowerBox.Text=tostring(TP_DOWN_V3_INTERVAL_MS) end
    end
    if type(cfg.aimbotV6Enabled) == "boolean" and cfg.aimbotV6Enabled then
        if _G.FRHUBStartAimbotV6 then _G.FRHUBStartAimbotV6() end
        State.aimbotV6Enabled = true
        if State.setAimbotV6Visual then State.setAimbotV6Visual(true) end
    end
    if cfg.v6AimbotMode == "normal" or cfg.v6AimbotMode == "bypass" then
        State.v6AimbotMode = cfg.v6AimbotMode
        if State.setV6ModeNormalVisual then State.setV6ModeNormalVisual(State.v6AimbotMode ~= "bypass") end
        if State.setV6ModeBypassVisual then State.setV6ModeBypassVisual(State.v6AimbotMode == "bypass") end
    end
    if type(cfg.aimbotV8Enabled) == "boolean" and cfg.aimbotV8Enabled then
        if _G.FRHUBStartAimbotV8 then _G.FRHUBStartAimbotV8() end
        State.aimbotV8Enabled = true
        if State.setAimbotV8Visual then State.setAimbotV8Visual(true) end
        if MobileButtons.Buttons.aimbotV8 then MobileButtons.Buttons.aimbotV8(true) end
    end
    if cfg.v8AimbotMode == "normal" or cfg.v8AimbotMode == "bypass" then
        State.v8AimbotMode = cfg.v8AimbotMode
        if State.setV8ModeNormalVisual then State.setV8ModeNormalVisual(State.v8AimbotMode ~= "bypass") end
