end)
local CONFIG_PATH = "FR Hub/wallahi_config.json"
local Radii = {Normal = 60, Semi = 80, SemiV2 = 51, SemiV3 = 60}
local Entry = {Semi = 9, SemiV2 = 9, SemiV3 = 9}
local V3Delay = 0.3
local selectedMode   = "Normal"
local isEnabled      = true
local uiScaleValue   = 100
local mainUIScale    = nil
local PredictAH      = {enabled = false, conn = nil, gen = 0, wasRagdoll = false, blocked = false, paused = false}
local PREDICT_MODES  = {SemiV3 = true}
local function saveConfig()
    pcall(function()
        local data = {
            normalRadius = Radii.Normal,
            semiDetect   = Radii.Semi,
            semiEntry    = Entry.Semi,
            semiV2Entry  = Entry.SemiV2,
            semiV3Entry  = Entry.SemiV3,
            semiV3Delay  = V3Delay,
            semiV2Radius = Radii.SemiV2,
            semiV3Radius = Radii.SemiV3,
            mode         = selectedMode,
            enabled      = isEnabled,
            uiScale      = uiScaleValue,
            predictAfterHit = PredictAH.enabled,
        }
        writefile(CONFIG_PATH, game:GetService("HttpService"):JSONEncode(data))
    end)
end
local function loadConfig()
    pcall(function()
        if not isfile(CONFIG_PATH) then return end
        local raw = readfile(CONFIG_PATH)
        local ok, data = pcall(function() return game:GetService("HttpService"):JSONDecode(raw) end)
        if not ok or type(data) ~= "table" then return end
        if type(data.normalRadius) == "number" then Radii.Normal = data.normalRadius end
        if type(data.semiDetect)  == "number" then Radii.Semi = data.semiDetect end
        if type(data.semiEntry)   == "number" then Entry.Semi = data.semiEntry
        elseif type(data.semiRadius) == "number" then Entry.Semi = data.semiRadius end
        if type(data.semiV2Entry) == "number" then Entry.SemiV2 = data.semiV2Entry end
        if type(data.semiV3Entry) == "number" then Entry.SemiV3 = data.semiV3Entry end
        if type(data.semiV3Delay) == "number" then V3Delay = math.clamp(data.semiV3Delay, 0, 5) end
        if type(data.semiV2Radius) == "number" then Radii.SemiV2 = data.semiV2Radius end
        if type(data.semiV3Radius) == "number" then Radii.SemiV3 = data.semiV3Radius end
        if data.mode == "Semi" or data.mode == "SemiV2" or data.mode == "SemiV3" then
            selectedMode = data.mode
        else
            selectedMode = "Normal"
        end
        if type(data.enabled) == "boolean" then isEnabled = data.enabled end
        if type(data.predictAfterHit) == "boolean" then PredictAH.enabled = data.predictAfterHit end
        if type(data.uiScale) == "number"  then uiScaleValue = math.clamp(math.floor(data.uiScale + 0.5), 50, 200) end
    end)
end
loadConfig()
local ProgressBarFill = nil
local function setProgress(val)
    if ProgressBarFill then
        TweenService:Create(ProgressBarFill, TweenInfo.new(0.05), {
            Size = UDim2.new(math.clamp(val, 0, 1), 0, 1, 0)
        }):Play()
    end
end
local function getHRP()
    local char = LP.Character
    if not char then return nil end
    return char:FindFirstChild("HumanoidRootPart")
        or char:FindFirstChild("Torso")
        or char:FindFirstChild("UpperTorso")
end
local function isMyBase(plotName)
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return false end
    local plot = plots:FindFirstChild(plotName)
    if not plot then return false end
    local sign = plot:FindFirstChild("PlotSign")
    if sign then
        local yb = sign:FindFirstChild("YourBase")
        if yb and yb:IsA("BillboardGui") then return yb.Enabled == true end
    end
    return false
end



local NormalSteal = {conn = nil, isStealing = false}
local NormalCache = {}
local function normalFindPrompt()
    local hrp = getHRP()
    if not hrp then return nil end
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return nil end
    local nearest, dist = nil, math.huge
    for _, plot in ipairs(plots:GetChildren()) do
        if isMyBase(plot.Name) then continue end
        local pods = plot:FindFirstChild("AnimalPodiums")
        if not pods then continue end
        for _, pod in ipairs(pods:GetChildren()) do
            local base  = pod:FindFirstChild("Base")
            if not base then continue end
            local spawn = base:FindFirstChild("Spawn")
            if not spawn then continue end
            local d = (spawn.Position - hrp.Position).Magnitude
            if d <= Radii.Normal and d < dist then
                local att = spawn:FindFirstChild("PromptAttachment")
                if att then
                    for _, p in ipairs(att:GetChildren()) do
                        if p:IsA("ProximityPrompt") and p.ActionText and p.ActionText:find("Steal") then
                            nearest, dist = p, d
                        end
                    end
                end
            end
        end
    end
    return nearest
end
local function normalExecuteSteal(prompt)
    if NormalSteal.isStealing then return end
    if not NormalCache[prompt] then
        NormalCache[prompt] = {hold = {}, trigger = {}, ready = true}
        if getconnections then
            for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
                if c.Function then table.insert(NormalCache[prompt].hold, c.Function) end
            end
            for _, c in ipairs(getconnections(prompt.Triggered)) do
                if c.Function then table.insert(NormalCache[prompt].trigger, c.Function) end
            end
        end
    end
    local data = NormalCache[prompt]
    if not data.ready then return end
    data.ready = false
    NormalSteal.isStealing = true
    local startTime      = tick()
    local STEAL_DURATION = 1.3
    task.spawn(function()
        for _, f in ipairs(data.hold) do pcall(f) end
        while tick() - startTime < STEAL_DURATION do
            local h   = getHRP()
            local att = prompt and prompt.Parent
            if not h or not att or (h.Position - att.WorldPosition).Magnitude > Radii.Normal then
                setProgress(0)
                data.ready = true
                NormalSteal.isStealing = false
                return
            end
            setProgress(math.clamp((tick() - startTime) / STEAL_DURATION, 0, 1))
            task.wait()
        end
        setProgress(1)
        _G.FRHUB_LAST_TRIGGER = tick(); for _, f in ipairs(data.trigger) do pcall(f) end
        task.wait(0.05)
        setProgress(0)
        data.ready = true
        NormalSteal.isStealing = false
    end)
end
local function startNormalMode()
    if NormalSteal.conn then pcall(function() NormalSteal.conn:Disconnect() end); NormalSteal.conn = nil end
    NormalSteal.isStealing = false
    NormalSteal.conn = RunService.Heartbeat:Connect(function()
        if not isEnabled or selectedMode ~= "Normal" then return end
        if NormalSteal.isStealing then return end
        local ok, prompt = pcall(normalFindPrompt)
        if ok and prompt then pcall(normalExecuteSteal, prompt) end
    end)
end
local function stopNormalMode()
    if NormalSteal.conn then pcall(function() NormalSteal.conn:Disconnect() end); NormalSteal.conn = nil end
    NormalSteal.isStealing = false
    setProgress(0)
end



_G.FRHUBSemiSteal = _G.FRHUBSemiSteal or {}
local A = _G.FRHUBSemiSteal
local function semiSetup()
    if A.conn then pcall(function() A.conn:Disconnect() end); A.conn = nil end
    A.enabled       = false
    A.holdMin       = 1.3
    A.holdMax       = 2.6
    A.entryDelay    = 0.3
    A.cooldown      = 0.05
    A.primeRange    = Radii.Semi
    A.radius        = Entry.Semi
    A.plotSync      = A.plotSync or {caches = {}, connections = {}}
    A.animals       = A.animals or {}
    A.promptCache   = A.promptCache or {}
    A.internalCache = A.internalCache or {}
    A.state         = A.state or {active = false, startTime = 0, phase = "idle", label = ""}
    local function splitPath(path)
        if typeof(path) == "table" then return path end
        local out = {}
        for part in string.gmatch(tostring(path), "[^%.]+") do table.insert(out, tonumber(part) or part) end
        return out
    end
    local function resolvePath(path, root)
        local current, parent, key = root, nil, nil
        for _, part in ipairs(splitPath(path)) do parent = current; key = part; current = current and current[part] or nil end
        return current, parent, key
    end
    local function applySyncDiff(channelName, packet)
        local cache = A.plotSync.caches[channelName]
        if typeof(cache) ~= "table" then return end
        local path, action, a, b = packet[1], packet[2], packet[3], packet[4]
        local current, parent, key = resolvePath(path, cache)
        if action == "Changed" then if parent ~= nil then parent[key] = a end
        elseif action == "ArrayInsert" then if current ~= nil then table.insert(current, b, a) end
        elseif action == "ArrayRemoved" then if current ~= nil then table.remove(current, b) end
        elseif action == "DictionaryInsert" then if current ~= nil then current[b] = a end
        elseif action == "DictionaryRemoved" then if current ~= nil then current[b] = nil end end
    end
    local function attachPlotChannel(remote, plots, requestData)
        if A.plotSync.connections[remote] then return end
        local channelName = tostring(remote.Name)
        if not plots:FindFirstChild(channelName) then return end
        if requestData and A.plotSync.caches[channelName] == nil then
            local ok, data = pcall(function() return requestData:InvokeServer(channelName) end)
            A.plotSync.caches[channelName] = (ok and typeof(data) == "table") and data or {}
        elseif A.plotSync.caches[channelName] == nil then A.plotSync.caches[channelName] = {} end
        A.plotSync.connections[remote] = remote.OnClientEvent:Connect(function(queue)
            for _, packet in ipairs(queue) do applySyncDiff(channelName, packet) end
        end)
    end
    local function ensureSync()
        if A.syncReady then return true end
        local ok = pcall(function()
            local rs = ReplicatedStorage
            A.packages = rs:WaitForChild("Packages", 10); A.datas = rs:WaitForChild("Datas", 10); A.plots = workspace:WaitForChild("Plots", 10)
            if not (A.packages and A.datas and A.plots) then return end
            A.animalsData = require(A.datas:WaitForChild("Animals", 10))
            local sync = A.packages:WaitForChild("Synchronizer", 10)
            A.channelFolder = sync:WaitForChild("Channel", 10); A.routeRemote = sync:WaitForChild("CommunicationRoute", 10); A.requestData = sync:FindFirstChild("RequestData")
            for _, child in ipairs(A.channelFolder:GetChildren()) do if child:IsA("RemoteEvent") then attachPlotChannel(child, A.plots, A.requestData) end end
            A.channelFolder.ChildAdded:Connect(function(child) if child:IsA("RemoteEvent") then attachPlotChannel(child, A.plots, A.requestData) end end)
            A.routeRemote.OnClientEvent:Connect(function(actions)
                for _, action in ipairs(actions) do
                    local kind, channelName = action[1], tostring(action[2])
                    if A.plots and A.plots:FindFirstChild(channelName) then
                        if kind == "ListenerAdded" then local remote = A.channelFolder and A.channelFolder:FindFirstChild(channelName); if remote and remote:IsA("RemoteEvent") then attachPlotChannel(remote, A.plots, A.requestData) end
                        elseif kind == "ListenerRemoved" then for remote, conn in pairs(A.plotSync.connections) do if tostring(remote.Name) == channelName then pcall(function() conn:Disconnect() end); A.plotSync.connections[remote] = nil; A.plotSync.caches[channelName] = nil; break end end end
                    end
                end
            end)
            A.syncReady = true
        end)
        return ok and A.syncReady == true
    end
    local function getPlotOwner(plot)
        local sign = plot and plot:FindFirstChild("PlotSign"); local frame = sign and sign:FindFirstChild("SurfaceGui") and sign.SurfaceGui:FindFirstChild("Frame"); local label = frame and frame:FindFirstChild("TextLabel")
        if not label or label.Text == "Empty Base" then return nil end
        return label.Text:gsub("'s [Bb]ase$", ""):gsub("%s+$", "")
    end
    local function isMyBaseAnimal(animalData)
        if not animalData or not animalData.plot or not A.plots then return false end
        local plot = A.plots:FindFirstChild(animalData.plot); if not plot then return false end
        local owner = getPlotOwner(plot); return owner == LP.DisplayName or owner == LP.Name
    end
    local function podiumFor(animalData)
        local plot = A.plots and A.plots:FindFirstChild(animalData.plot); local podiums = plot and plot:FindFirstChild("AnimalPodiums"); return podiums and podiums:FindFirstChild(animalData.slot) or nil
    end
    local function animalPos(animalData) local podium = podiumFor(animalData); return podium and podium:GetPivot().Position or nil end
    local function distToAnimal(animalData) local root = LP.Character and (LP.Character:FindFirstChild("HumanoidRootPart") or LP.Character:FindFirstChild("UpperTorso")); local pos = animalPos(animalData); return root and pos and (root.Position - pos).Magnitude or math.huge end
    local function findPromptForAnimal(animalData)
        if not animalData then return nil end; local cached = A.promptCache[animalData.uid]; if cached and cached.Parent then return cached end
        local podium = podiumFor(animalData); local base = podium and podium:FindFirstChild("Base"); local spawn = base and base:FindFirstChild("Spawn"); local attach = spawn and spawn:FindFirstChild("PromptAttachment"); if not attach then return nil end
        for _, prompt in ipairs(attach:GetChildren()) do if prompt:IsA("ProximityPrompt") then A.promptCache[animalData.uid] = prompt; return prompt end end; return nil
    end
    local function scanAllPlots()
        if not ensureSync() then return end; local newCache = {}
        for _, plot in ipairs(A.plots:GetChildren()) do
            local cache = A.plotSync.caches[plot.Name]; local animalList = cache and cache.AnimalList
            if typeof(animalList) == "table" then
                for slot, animalData in pairs(animalList) do
                    if type(animalData) == "table" then local animalName = animalData.Index; local info = A.animalsData and A.animalsData[animalName]; if info then table.insert(newCache, {name = info.DisplayName or animalName, plot = plot.Name, slot = tostring(slot), uid = plot.Name .. "_" .. tostring(slot)}) end end
                end
            end
        end
        A.animals = newCache
    end
    local function pickClosest()
        local root = LP.Character and (LP.Character:FindFirstChild("HumanoidRootPart") or LP.Character:FindFirstChild("UpperTorso")); if not root then return nil end
        local best, bestDist = nil, math.huge
        for _, animalData in ipairs(A.animals) do
            if not isMyBaseAnimal(animalData) then local pos = animalPos(animalData); local dist = pos and (root.Position - pos).Magnitude or math.huge; if dist <= (A.primeRange or 80) and dist < bestDist then best, bestDist = animalData, dist end end
        end
        return best
    end
    local function buildCallbacks(prompt)
        if A.internalCache[prompt] then return end; local data = {holdCallbacks = {}, triggerCallbacks = {}, ready = true}
        local okHold, holds = pcall(getconnections, prompt.PromptButtonHoldBegan); if okHold and type(holds) == "table" then for _, conn in ipairs(holds) do if type(conn.Function) == "function" then table.insert(data.holdCallbacks, conn.Function) end end end
        local okTrig, trigs = pcall(getconnections, prompt.Triggered); if okTrig and type(trigs) == "table" then for _, conn in ipairs(trigs) do if type(conn.Function) == "function" then table.insert(data.triggerCallbacks, conn.Function) end end end
        if #data.holdCallbacks > 0 or #data.triggerCallbacks > 0 then A.internalCache[prompt] = data end
    end
    local function executeSemi(prompt, animalData)
        if not prompt or not prompt.Parent or not animalData then return false end
        buildCallbacks(prompt); local data = A.internalCache[prompt]; if not data or not data.ready then return false end
        data.ready = false; A.state.active = true; A.state.startTime = tick(); A.state.phase = "holding"; A.state.label = animalData.name or "Animal"
        task.spawn(function()
            for _, fn in ipairs(data.holdCallbacks) do task.spawn(function() pcall(fn) end) end
            local abortedHold = false
            while A.enabled and selectedMode == "Semi" and tick() - A.state.startTime < (A.holdMin or 1.3) do
                if distToAnimal(animalData) > (A.primeRange or 80) then abortedHold = true; break end
                setProgress((tick() - A.state.startTime) / (A.holdMax or 2.6)); task.wait()
            end
            if abortedHold then
                A.state.active = false; A.state.phase = "idle"; data.ready = true; setProgress(0); return
            end
            A.state.phase = "waitingRange"; local alreadyInRange = distToAnimal(animalData) <= (tonumber(A.radius) or 10); local fired = false
            while A.enabled and selectedMode == "Semi" and prompt.Parent do
                local elapsed = tick() - A.state.startTime; if elapsed > (A.holdMax or 2.6) then break end
                if distToAnimal(animalData) > (A.primeRange or 80) then break end
                setProgress(elapsed / (A.holdMax or 2.6))
                if distToAnimal(animalData) <= (tonumber(A.radius) or 10) then
                    if not alreadyInRange then task.wait(A.entryDelay or 0.3) end
                    if A.enabled and selectedMode == "Semi" then _G.FRHUB_LAST_TRIGGER = tick(); for _, fn in ipairs(data.triggerCallbacks) do task.spawn(function() pcall(fn) end) end; fired = true end; break
                end; task.wait()
            end
            A.state.active = false; A.state.phase = "idle"; if fired then setProgress(1) end; task.wait(A.cooldown or 0.05); data.ready = true; setProgress(0)
        end)
        return true
    end
    local function ensureScanThread()
        if A.scanThread then return end
        A.scanThread = task.spawn(function() while _G.FRHUBSemiSteal do if A.enabled or selectedMode == "Semi" then pcall(scanAllPlots) end; task.wait(5) end end)
    end
    A.start = function()
        A.radius = Entry.Semi; A.primeRange = Radii.Semi; A.enabled = true; ensureSync(); ensureScanThread(); pcall(scanAllPlots)
        if A.conn then A.conn:Disconnect(); A.conn = nil end
        A.conn = RunService.Heartbeat:Connect(function()
            if not isEnabled or not A.enabled then return end; if selectedMode ~= "Semi" then A.stop(); return end; if A.state.active then return end
            local target = pickClosest(); if not target then return end; local prompt = findPromptForAnimal(target); if prompt then executeSemi(prompt, target) end
        end)
    end
    A.stop = function()
        A.enabled = false; if A.conn then A.conn:Disconnect(); A.conn = nil end; A.state.active = false; A.state.phase = "idle"; setProgress(0)
    end
end
semiSetup()



local SemiV2 = {conn = nil, isStealing = false, stealGeneration = 0}
local SemiV2Cache    = {}
local SemiV2LastTime = {}
local SemiV2IsRagdolled = false
local SemiV2RagdollEnd  = 0
local SemiV2RdConn1, SemiV2RdConn2
local function sv2TriggerRagdoll()
    SemiV2IsRagdolled = true
    SemiV2RagdollEnd  = tick()
    task.delay(0.05, function() if tick() >= SemiV2RagdollEnd then SemiV2IsRagdolled = false end end)
end
local function sv2SetupRagdoll(char)
    if SemiV2RdConn1 then SemiV2RdConn1:Disconnect(); SemiV2RdConn1 = nil end
    if SemiV2RdConn2 then SemiV2RdConn2:Disconnect(); SemiV2RdConn2 = nil end
    SemiV2IsRagdolled = false
    local humR = char:WaitForChild("Humanoid", 6)
    if not humR then return end
    SemiV2RdConn1 = humR.StateChanged:Connect(function(_, newState)
        if newState == Enum.HumanoidStateType.Physics then sv2TriggerRagdoll() end
    end)
    SemiV2RdConn2 = char.DescendantRemoving:Connect(function(desc)
        if desc:IsA("Motor6D") and humR and humR.Health > 0 then task.wait(0.05); sv2TriggerRagdoll() end
    end)
end
if LP.Character then task.spawn(sv2SetupRagdoll, LP.Character) end
LP.CharacterAdded:Connect(function(char)
    SemiV2.stealGeneration = SemiV2.stealGeneration + 1
    SemiV2.isStealing = false
    for _, data in pairs(SemiV2Cache) do data.ready = true end
    task.spawn(sv2SetupRagdoll, char)
end)
local SemiV2_PAUSE_AT       = 1.0
local SemiV2_PAUSE_TIMEOUT  = 2
local SemiV2_STEAL_COOLDOWN = 0.01
local function sv2FindPrompt(radius)
    local hrp = getHRP()
    if not hrp then return nil end
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return nil end
    local nearest, minDist, nearestPos, nearestUid = nil, math.huge, nil, nil
    for _, plot in ipairs(plots:GetChildren()) do
        if isMyBase(plot.Name) then continue end
        local pods = plot:FindFirstChild("AnimalPodiums")
        if not pods then continue end
        for _, pod in ipairs(pods:GetChildren()) do
            local base  = pod:FindFirstChild("Base")
            if not base then continue end
            local spawn = base:FindFirstChild("Spawn")
            if not spawn then continue end
            local d = (spawn.Position - hrp.Position).Magnitude
            if d <= radius and d < minDist then
                local att = spawn:FindFirstChild("PromptAttachment")
                if att then
                    for _, p in ipairs(att:GetChildren()) do
                        if p:IsA("ProximityPrompt") and p.Enabled and p.ActionText and p.ActionText:find("Steal") then
                            nearest = p; minDist = d; nearestPos = spawn.Position; nearestUid = plot.Name .. "_" .. pod.Name
                        end
                    end
                end
            end
        end
    end
    if not nearest then return nil end
    return {prompt = nearest, worldPosition = nearestPos, uid = nearestUid}
end
local function sv2BuildCallbacks(prompt)
    local existing = SemiV2Cache[prompt]
    if existing and existing.ready and not existing.stale then return end
    local data = {holdCallbacks = {}, triggerCallbacks = {}, ready = true, stale = false}
    if getconnections then
        for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do if c.Function then table.insert(data.holdCallbacks, c.Function) end end
        for _, c in ipairs(getconnections(prompt.Triggered)) do if c.Function then table.insert(data.triggerCallbacks, c.Function) end end
    end
    if (#data.holdCallbacks > 0) or (#data.triggerCallbacks > 0) then SemiV2Cache[prompt] = data end
end
local function sv2AbortSteal(data, uid)
    setProgress(0); data.ready = true; data.stale = true; SemiV2.isStealing = false
    if uid then SemiV2LastTime[uid] = tick() end
end
local function sv2Execute(prompt, animalData, capturedGen, closeDist, fastFire, capturedMode)
    local data = SemiV2Cache[prompt]
    if not data or not data.ready then return false end
    data.ready = false; data.stale = false; SemiV2.isStealing = true
    local duration = 1.3
    task.spawn(function()
        local function abortCheck()
            return capturedGen ~= SemiV2.stealGeneration or selectedMode ~= capturedMode
        end
        if abortCheck() then sv2AbortSteal(data, animalData and animalData.uid); return end
        while true do
            if #data.holdCallbacks > 0 then for _, fn in ipairs(data.holdCallbacks) do pcall(fn) end end
            local startTime   = tick()
            local interrupted = false
            while tick() - startTime < SemiV2_PAUSE_AT do
                if abortCheck() then sv2AbortSteal(data, animalData and animalData.uid); return end
                local h = getHRP()
                if not h or not animalData or (h.Position - animalData.worldPosition).Magnitude > Radii[capturedMode] then interrupted = true; break end
                setProgress((tick() - startTime) / duration)
                task.wait(0.05)
            end
            if interrupted then sv2AbortSteal(data, animalData and animalData.uid); return end
            local pauseStart = tick(); local timedOut = false
            while true do
                if abortCheck() then sv2AbortSteal(data, animalData and animalData.uid); return end
                local h = getHRP()
                if not h or not animalData then sv2AbortSteal(data, animalData and animalData.uid); return end
                if (h.Position - animalData.worldPosition).Magnitude > Radii[capturedMode] then sv2AbortSteal(data, animalData and animalData.uid); return end
                if (h.Position - animalData.worldPosition).Magnitude <= closeDist then break end
                if tick() - pauseStart >= SemiV2_PAUSE_TIMEOUT then timedOut = true; break end
                task.wait(0.01)
            end
            if timedOut then
                setProgress(0); task.wait(0.01)
            else
                if fastFire then
                    if abortCheck() then sv2AbortSteal(data, animalData and animalData.uid); return end
                    setProgress(1)
                    if #data.triggerCallbacks > 0 then _G.FRHUB_LAST_TRIGGER = tick(); for _, fn in ipairs(data.triggerCallbacks) do pcall(fn) end end
                    task.wait(0.01); data.ready = true; task.wait(0.01); setProgress(0); SemiV2.isStealing = false
                    if animalData then SemiV2LastTime[animalData.uid] = tick() end
                    return
                else
                    local resumeStart = tick(); local remaining = duration - SemiV2_PAUSE_AT; local outOfRange = false
                    while tick() - resumeStart < remaining do
                        if abortCheck() then sv2AbortSteal(data, animalData and animalData.uid); return end
                        local h = getHRP()
                        if not h or not animalData or (h.Position - animalData.worldPosition).Magnitude > Radii[capturedMode] then outOfRange = true; break end
                        setProgress(math.min((SemiV2_PAUSE_AT + (tick() - resumeStart)) / duration, 1))
                        task.wait(0.05)
                    end
                    if outOfRange then sv2AbortSteal(data, animalData and animalData.uid); return end
                    if #data.triggerCallbacks > 0 then _G.FRHUB_LAST_TRIGGER = tick(); for _, fn in ipairs(data.triggerCallbacks) do pcall(fn) end end
                    task.wait(0.01); data.ready = true; task.wait(0.01); setProgress(0); SemiV2.isStealing = false
                    if animalData then SemiV2LastTime[animalData.uid] = tick() end
                    return
                end
            end
        end
    end)
    return true
end
local function sv2Attempt(prompt, animalData, closeDist, fastFire, capturedMode)
    if not prompt or not prompt.Parent or not prompt.Enabled then return false end
    if animalData and SemiV2LastTime[animalData.uid] then
        if tick() - SemiV2LastTime[animalData.uid] < SemiV2_STEAL_COOLDOWN then return false end
    end
    sv2BuildCallbacks(prompt)
    if not SemiV2Cache[prompt] then return false end
    return sv2Execute(prompt, animalData, SemiV2.stealGeneration, closeDist, fastFire, capturedMode)
end
local function startSemiV2Mode(modeName, closeDist, fastFire)
    if SemiV2.conn then pcall(function() SemiV2.conn:Disconnect() end); SemiV2.conn = nil end
    SemiV2.isStealing = false
    SemiV2.conn = RunService.Heartbeat:Connect(function()
        if not isEnabled or selectedMode ~= modeName then return end
        if SemiV2.isStealing then return end
        if SemiV2IsRagdolled and tick() < SemiV2RagdollEnd then return end
        local ok, result = pcall(sv2FindPrompt, Radii[modeName] or 51)
        if not ok or not result then return end
        sv2Attempt(result.prompt, result, Entry.SemiV2, fastFire, modeName)
    end)
end
local function stopSemiV2Mode()
    SemiV2.stealGeneration = SemiV2.stealGeneration + 1
    if SemiV2.conn then pcall(function() SemiV2.conn:Disconnect() end); SemiV2.conn = nil end
    SemiV2.isStealing = false
    setProgress(0)
end



local SemiV3State = {
    conn = nil, isStealing = false, stealStartTime = nil, Data = {},
    HalfFireRange = 9, HalfHoldMin = 1.3, HalfHoldMax = 2.6, HalfEntryDelay = 0.3,
}
local function sv3PromptDist(prompt)
    local char = LP.Character
    if not char then return math.huge end
    local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
    if not root then return math.huge end
    local part = prompt.Parent
    if part and part:IsA("Attachment") then part = part.Parent end
    if part and part:IsA("BasePart") then return (part.Position - root.Position).Magnitude end
    local ok, cf = pcall(function() return prompt.Parent and prompt.Parent.WorldPosition end)
    if ok and cf then return (cf - root.Position).Magnitude end
    return math.huge
end
local function sv3FindNearestPrompt()
    local char = LP.Character
    if not char then return nil end
    local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
    if not root then return nil end
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return nil end
    local nearest, dist = nil, math.huge
    for _, plot in ipairs(plots:GetChildren()) do
        if plot:IsA("Model") and not isMyBase(plot.Name) then
            local pods = plot:FindFirstChild("AnimalPodiums")
            if pods then
                for _, pod in ipairs(pods:GetChildren()) do
                    local base = pod:FindFirstChild("Base")
                    local sp = base and base:FindFirstChild("Spawn")
                    if sp then
                        local d = (sp.Position - root.Position).Magnitude
                        if d <= Radii.SemiV3 and d < dist then
                            local found = nil
                            local att = sp:FindFirstChild("PromptAttachment")
                            if att then
                                for _, pr in ipairs(att:GetChildren()) do
                                    if pr:IsA("ProximityPrompt") and pr.ActionText and pr.ActionText:find("Steal") then found = pr end
                                end
                            end
                            if not found then
                                for _, pr in ipairs(sp:GetDescendants()) do
                                    if pr:IsA("ProximityPrompt") and pr.ActionText and pr.ActionText:find("Steal") then found = pr end
                                end
                            end
                            if found then nearest, dist = found, d end
                        end
                    end
                end
            end
        end
    end
    return nearest
end
local function sv3ExecuteSteal(prompt)
    if SemiV3State.isStealing then return end
    if not SemiV3State.Data[prompt] then
        SemiV3State.Data[prompt] = {hold = {}, trigger = {}, ready = true}
        if getconnections then
            for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
                if c.Function then table.insert(SemiV3State.Data[prompt].hold, c.Function) end
            end
            for _, c in ipairs(getconnections(prompt.Triggered)) do
                if c.Function then table.insert(SemiV3State.Data[prompt].trigger, c.Function) end
            end
        end
    end
    local data = SemiV3State.Data[prompt]
    if not data.ready then return end
    data.ready = false
    SemiV3State.isStealing = true
    SemiV3State.HalfFireRange = Entry.SemiV3
    SemiV3State.stealStartTime = tick()
    task.spawn(function()
        for _, fn in ipairs(data.hold) do task.spawn(fn) end
        task.wait(SemiV3State.HalfHoldMin)
        local lastWasInRange = sv3PromptDist(prompt) <= SemiV3State.HalfFireRange
        local fired = false
        while true do
            local el = tick() - SemiV3State.stealStartTime
            if el > SemiV3State.HalfHoldMax or not prompt.Parent or PredictAH.blocked then break end
            setProgress(math.clamp(el / SemiV3State.HalfHoldMax, 0, 1))
            local nowInRange = sv3PromptDist(prompt) <= SemiV3State.HalfFireRange
            if nowInRange then
                if not lastWasInRange then
                    task.wait(V3Delay)
                    if sv3PromptDist(prompt) > SemiV3State.HalfFireRange or not prompt.Parent then
                        lastWasInRange = false
                        task.wait()
                        continue
                    end
                end
                _G.FRHUB_LAST_TRIGGER = tick(); for _, fn in ipairs(data.trigger) do task.spawn(fn) end
                fired = true
                break
            end
            lastWasInRange = nowInRange
            task.wait()
        end
        if fired then setProgress(1) end
        task.wait(0.05)
        setProgress(0)
        data.ready = true
        SemiV3State.isStealing = false
    end)
end
local function startSemiV3Mode()
    if SemiV3State.conn then pcall(function() SemiV3State.conn:Disconnect() end); SemiV3State.conn = nil end
    SemiV3State.isStealing = false
    SemiV3State.conn = RunService.Heartbeat:Connect(function()
        if not isEnabled or selectedMode ~= "SemiV3" then return end
        if SemiV3State.isStealing then return end
        local ok, p = pcall(sv3FindNearestPrompt)
        if ok and p then pcall(sv3ExecuteSteal, p) end
    end)
end
local function stopSemiV3Mode()
    if SemiV3State.conn then pcall(function() SemiV3State.conn:Disconnect() end); SemiV3State.conn = nil end
    SemiV3State.isStealing = false
    setProgress(0)
end



do
    local antiDieConns = {}
    local function enableAntiDie()
        local char = LP.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        local hConn = hum:GetPropertyChangedSignal("Health"):Connect(function()
            if hum.Health <= 0 then hum.Health = hum.MaxHealth end
        end)
        table.insert(antiDieConns, hConn)
        local dConn = hum.Died:Connect(function()
            task.wait()
            pcall(function()
                local newHum = Instance.new("Humanoid")
                newHum.Name = "Humanoid"
                newHum.Parent = char
                if workspace.CurrentCamera then workspace.CurrentCamera.CameraSubject = newHum end
                hum:Destroy()
            end)
        end)
        table.insert(antiDieConns, dConn)
    end
    local function setupAntiDie()
        for _, c in pairs(antiDieConns) do pcall(c.Disconnect, c) end
        antiDieConns = {}
        enableAntiDie()
    end
    setupAntiDie()
    LP.CharacterAdded:Connect(function() task.wait(0.1); setupAntiDie() end)
end



local RadiusValueLabel, EntryValueLabel, RadiusLabelObj = nil, nil, nil
local EntryGroup = {}
local DelayValueLabel = nil
local DelayGroup = {}
local function currentRadius()
    return Radii[selectedMode] or Radii.Normal
end
local function currentEntry()
    return Entry[selectedMode]
end
local function refreshRangeUI()
    local hasEntry = Entry[selectedMode] ~= nil
    if RadiusValueLabel then RadiusValueLabel.Text = tostring(currentRadius()) end
    if EntryValueLabel  then EntryValueLabel.Text  = tostring(Entry[selectedMode] or "") end
    if RadiusLabelObj   then RadiusLabelObj.Text   = hasEntry and "Detect:" or "Range:" end
    for _, o in ipairs(EntryGroup) do o.Visible = hasEntry end
    if DelayValueLabel then DelayValueLabel.Text = tostring(V3Delay) end
    for _, o in ipairs(DelayGroup) do o.Visible = (selectedMode == "SemiV3") end
end
local function setV3Delay(v)
    v = math.clamp(math.floor(v * 100 + 0.5) / 100, 0, 5)
    V3Delay = v
    refreshRangeUI()
    saveConfig()
end
local function setRadius(v)
    v = math.clamp(math.floor(v + 0.5), 1, 1000)
    Radii[selectedMode] = v
    if selectedMode == "Semi" and A then A.primeRange = v end
    refreshRangeUI()
    saveConfig()
end
local function setEntry(v)
    if Entry[selectedMode] == nil then return end
    v = math.clamp(math.floor(v + 0.5), 1, 1000)
    Entry[selectedMode] = v
    if selectedMode == "Semi" and A then A.radius = v end
    refreshRangeUI()
    saveConfig()
end
local NormalBtn, SemiBtn, SemiV2Btn, SemiV3Btn
local ALL_MODE_BTNS = {}
local function refreshModeButtons()
    for mode, btn in pairs(ALL_MODE_BTNS) do
        local active = (mode == selectedMode)
        btn.BackgroundColor3 = active and Color3.fromRGB(180, 77, 18) or Color3.fromRGB(55, 23, 5)
        btn.TextColor3       = active and Color3.fromRGB(255, 255, 255) or Color3.fromRGB(220, 94, 22)
    end
end
local function stopAll()
    stopNormalMode()
    if A and A.stop then A.stop() end
    stopSemiV2Mode()
    stopSemiV3Mode()
    setProgress(0)
end
local function startAll()
    if not isEnabled then return end
    if selectedMode == "Normal" then
        startNormalMode()
    elseif selectedMode == "Semi" then
        if A and A.start then A.start() end
    elseif selectedMode == "SemiV2" then
        startSemiV2Mode("SemiV2", 9, false)
    elseif selectedMode == "SemiV3" then
        startSemiV3Mode()
    end
end
local function applyMode(mode)
    PredictAH.gen = PredictAH.gen + 1; PredictAH.paused = false; PredictAH.blocked = false
    stopAll()
    selectedMode = mode
    refreshRangeUI()
    refreshModeButtons()
    startAll()
    saveConfig()
end



local predictBtn
local function refreshPredictBtn()
    if not predictBtn then return end
    local on = PredictAH.enabled
    predictBtn.Text             = "PREDICT After Hit : " .. (on and "ON" or "OFF")
    predictBtn.BackgroundColor3 = on and Color3.fromRGB(180, 77, 18) or Color3.fromRGB(55, 23, 5)
    predictBtn.TextColor3       = on and Color3.fromRGB(0, 255, 120) or Color3.fromRGB(255, 120, 120)
end
local function predictOnHit()
    if not PREDICT_MODES[selectedMode] then return end
    PredictAH.paused  = true
    PredictAH.blocked = true
    stopAll()
    for _, d in pairs(NormalCache) do d.ready = true end
    for _, d in pairs(SemiV2Cache) do d.ready = true end
    for _, d in pairs(SemiV3State.Data) do d.ready = true end
    local myGen = PredictAH.gen
    local delay = ((tick() - (_G._FRHUBMedusaHitTime or 0)) < 4) and 2.45 or 1.45
    task.delay(delay, function()
        if myGen ~= PredictAH.gen or not PredictAH.paused then return end
        PredictAH.wasRagdoll = false
        PredictAH.paused     = false
        PredictAH.blocked    = false
        if PredictAH.enabled and isEnabled and PREDICT_MODES[selectedMode] then startAll() end
    end)
end
local function predictStart()
    if PredictAH.conn then pcall(function() PredictAH.conn:Disconnect() end); PredictAH.conn = nil end
    PredictAH.wasRagdoll = false
    PredictAH.conn = RunService.Heartbeat:Connect(function()
        if not PredictAH.enabled or not isEnabled then return end
        local char = LP.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return end
        local st = hum:GetState()
        local ragdolled = (st == Enum.HumanoidStateType.Physics or st == Enum.HumanoidStateType.Ragdoll)
        if ragdolled and not PredictAH.wasRagdoll then
            PredictAH.wasRagdoll = true
            PredictAH.gen = PredictAH.gen + 1
            predictOnHit()
        elseif not ragdolled then
            PredictAH.wasRagdoll = false
        end
    end)
end
local function predictStop()
    if PredictAH.conn then pcall(function() PredictAH.conn:Disconnect() end); PredictAH.conn = nil end
    PredictAH.wasRagdoll = false
    PredictAH.gen = PredictAH.gen + 1
    if PredictAH.paused then
        PredictAH.paused  = false
        PredictAH.blocked = false
        if isEnabled then startAll() end
    end
end
_G._FRHUBMedusaHitTime = _G._FRHUBMedusaHitTime or 0
do
    local conns = {}
    local function clearConns()
        for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
        conns = {}
    end
    local function hookPart(part)
        if not part:IsA("BasePart") then return end
        table.insert(conns, part:GetPropertyChangedSignal("Anchored"):Connect(function()
            if part.Anchored and part.Transparency == 1 then
                _G._FRHUBMedusaHitTime = tick()
            end
        end))
    end
    local function attach(char)
        clearConns()
        _G._FRHUBMedusaHitTime = 0
        if not char then return end
        for _, part in ipairs(char:GetDescendants()) do hookPart(part) end
        table.insert(conns, char.DescendantAdded:Connect(hookPart))
    end
    if LP.Character then attach(LP.Character) end
    LP.CharacterAdded:Connect(function(char)
        char:WaitForChild("HumanoidRootPart", 10)
        attach(char)
    end)
end
if PredictAH.enabled then predictStart() end


