local function setUIExpanded(expanded)
    uiExpanded       = expanded
    content.Visible  = expanded
    collapseBtn.Text = expanded and "-" or "+"
    local curPos    = main.Position
    local diff      = H_EXPANDED - H_COLLAPSED
    local targetH   = expanded and H_EXPANDED  or H_COLLAPSED
    local targetYOff = expanded and (curPos.Y.Offset - diff) or (curPos.Y.Offset + diff)
    TweenService:Create(main, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        Size     = UDim2.new(0, W, 0, targetH),
        Position = UDim2.new(curPos.X.Scale, curPos.X.Offset, curPos.Y.Scale, targetYOff),
    }):Play()
end
collapseBtn.MouseButton1Click:Connect(function()
    setUIExpanded(not uiExpanded)
end)

local dragging, dragStart, startPos = false, nil, nil
header.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
    or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true; dragStart = input.Position; startPos = main.Position
    end
end)
UserInputService.InputChanged:Connect(function(input)
    if not dragging or not dragStart then return end
    if input.UserInputType ~= Enum.UserInputType.MouseMovement
    and input.UserInputType ~= Enum.UserInputType.Touch then return end
    local delta = input.Position - dragStart
    main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
end)
UserInputService.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
    or input.UserInputType == Enum.UserInputType.Touch then dragging = false end
end)
