    local function rtp2GetClosest()
        local myChar = LP2.Character
        if not myChar or not myChar:FindFirstChild("HumanoidRootPart") then return nil end
        local myPos = myChar.HumanoidRootPart.Position
        local closest, closestDist = nil, math.huge
        for _, p in ipairs(Players2:GetPlayers()) do
            if p ~= LP2 and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                local hum = p.Character:FindFirstChild("Humanoid")
                if hum and hum.Health > 0 then
                    local d = (p.Character.HumanoidRootPart.Position - myPos).Magnitude
                    if d < closestDist then closestDist = d; closest = p end
                end
            end
        end
        return closest
    end
    local function rtp2Pulse()
        local target = rtp2GetClosest()
        if not target or not target.Character then return end
        local myChar = LP2.Character
        if myChar and myChar:FindFirstChild("HumanoidRootPart") and target.Character:FindFirstChild("HumanoidRootPart") then
            myChar.HumanoidRootPart.CFrame = target.Character.HumanoidRootPart.CFrame * CFrame.new(2,0,0)
        end
    end
    local function rtp2Sequence()
        if rtp2Teleporting then return end
        rtp2Teleporting = true
        task.spawn(function()
            for _ = 1, 20 do
                if not rtp2Teleporting or not rtp2Enabled then break end
                pcall(rtp2Pulse); task.wait(0.1)
            end
            rtp2Teleporting = false
        end)
    end
    local function rtp2SetupChar(character)
        if rtp2Conn1 then rtp2Conn1:Disconnect(); rtp2Conn1 = nil end
        if rtp2Conn2 then rtp2Conn2:Disconnect(); rtp2Conn2 = nil end
        local hrp = character:WaitForChild("HumanoidRootPart", 6)
        local hum = character:WaitForChild("Humanoid", 6)
        if not hrp or not hum then return end
        rtp2Conn1 = hum.StateChanged:Connect(function(_, newState)
            if not rtp2Enabled then return end
            if newState == Enum.HumanoidStateType.Physics then rtp2Sequence() end
        end)
        rtp2Conn2 = character.DescendantRemoving:Connect(function(desc)
            if not rtp2Enabled then return end
            if desc:IsA("Motor6D") and hum and hum.Health > 0 then
                task.wait(0.05); rtp2Sequence()
            end
        end)
    end
    local function startRTP2()
        rtp2Enabled = true; rtp2Teleporting = false
        if LP2.Character then task.spawn(rtp2SetupChar, LP2.Character) end
        rtp2CharConn = LP2.CharacterAdded:Connect(function(char)
            if not rtp2Enabled then return end
            task.wait(0.15); task.spawn(rtp2SetupChar, char)
        end)
    end
    local function stopRTP2()
        rtp2Enabled = false; rtp2Teleporting = false
        if rtp2Conn1    then rtp2Conn1:Disconnect();    rtp2Conn1    = nil end
        if rtp2Conn2    then rtp2Conn2:Disconnect();    rtp2Conn2    = nil end
        if rtp2CharConn then rtp2CharConn:Disconnect(); rtp2CharConn = nil end
    end
    local _ct2 = 0
    local function _fn2()
        if tick()-_ct2 < 0.2 then return end; _ct2 = tick()
        local newOn = not getIsOn2(); setV2(newOn)
        if newOn then startRTP2() else stopRTP2() end
    end
    row2.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 then
            task.defer(_fn2)
        end
    end)
    pill2.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or
           inp.UserInputType == Enum.UserInputType.Touch then
            task.defer(_fn2)
        end
    end)
end)


