    local _b3_BG_TEX   = "rbxassetid://109860380463830"
    local function _b3_shimmer(parent, speed, thickness)
        thickness = thickness or 2.5
        local stroke = Instance.new("UIStroke")
        stroke.Thickness = thickness; stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        stroke.Color = Color3.fromRGB(240, 103, 24); stroke.Transparency = 0.35; stroke.Parent = parent
    end
    local function _b3_bgTex(parent, tr, r)
        local img = Instance.new("ImageLabel", parent)
        img.Size = UDim2.new(1,0,1,0); img.BackgroundTransparency = 1
        img.Image = _b3_BG_TEX; img.ImageTransparency = tr or 0.88
        img.ScaleType = Enum.ScaleType.Crop; img.ZIndex = 1
        if r then Instance.new("UICorner", img).CornerRadius = UDim.new(0, r) end
    end
    local function _b3_glassGrad(lbl)
        local grad = Instance.new("UIGradient")
        grad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0,    Color3.fromRGB(220, 94, 22)),
            ColorSequenceKeypoint.new(0.30, Color3.fromRGB(255, 109, 25)),
            ColorSequenceKeypoint.new(0.50, Color3.fromRGB(235,205,255)),
            ColorSequenceKeypoint.new(0.70, Color3.fromRGB(255, 109, 25)),
            ColorSequenceKeypoint.new(1,    Color3.fromRGB(220, 94, 22)),
        })
        grad.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0,0.25),  NumberSequenceKeypoint.new(0.30,0.0),
            NumberSequenceKeypoint.new(0.50,0.08), NumberSequenceKeypoint.new(0.70,0.0),
            NumberSequenceKeypoint.new(1,0.25),
        })
        grad.Rotation = 90; grad.Parent = lbl
    end
    local function _b3_makePill(parent, defOn)
        local PW, PH, DW = 38, 18, 13
        local DON = -(DW+3); local DOFF = 3
        local pill = Instance.new("Frame", parent)
        pill.Size = UDim2.new(0,PW,0,PH); pill.Position = UDim2.new(1,-(PW+7),0.5,-PH/2)
        pill.BackgroundColor3 = defOn and _b3_C_ON or _b3_C_OFF
        pill.BorderSizePixel = 0; pill.ZIndex = 4
        Instance.new("UICorner", pill).CornerRadius = UDim.new(1,0)
        _b3_shimmer(pill, 4, 1.0)
        local dot = Instance.new("Frame", pill)
        dot.Size = UDim2.new(0,DW,0,DW)
        dot.Position = defOn and UDim2.new(1,DON,0.5,-DW/2) or UDim2.new(0,DOFF,0.5,-DW/2)
        dot.BackgroundColor3 = defOn and _b3_C_WHITE or _b3_C_DIM
        dot.BorderSizePixel = 0; dot.ZIndex = 5
        Instance.new("UICorner", dot).CornerRadius = UDim.new(1,0)
        _b3_shimmer(dot, 6, 0.8)
        local isOn = defOn or false
        local function setV(on)
            isOn = on
            _b3_TS:Create(pill, TweenInfo.new(0.18,Enum.EasingStyle.Quad), {BackgroundColor3 = on and _b3_C_ON or _b3_C_OFF}):Play()
            _b3_TS:Create(dot,  TweenInfo.new(0.18,Enum.EasingStyle.Back), {
                Position         = on and UDim2.new(1,DON,0.5,-DW/2) or UDim2.new(0,DOFF,0.5,-DW/2),
                BackgroundColor3 = on and _b3_C_WHITE or _b3_C_DIM
            }):Play()
        end
        return setV, pill, function() return isOn end
    end
    local _b3_secLbl = Instance.new("TextLabel", _b3_page)
    _b3_secLbl.Size = UDim2.new(1,0,0,16); _b3_secLbl.BackgroundTransparency = 1
    _b3_secLbl.LayoutOrder = 999; _b3_secLbl.ZIndex = 3
    _b3_secLbl.Text = "TP BASE"; _b3_secLbl.TextColor3 = _b3_C_DIM
    _b3_secLbl.Font = Enum.Font.GothamBold; _b3_secLbl.TextSize = 8
