    _b3_lbl.TextSize = 10; _b3_lbl.TextXAlignment = Enum.TextXAlignment.Left; _b3_lbl.ZIndex = 3
    _b3_glassGrad(_b3_lbl)
    local _b3_setV, _b3_pill, _b3_getOn = _b3_makePill(_b3_row, false)
    local _b3_RETURN_R = Vector3.new(-475.22, -6.99, 23.63)
    local _b3_RETURN_L = Vector3.new(-475.27, -6.99, 94.54)
    local _b3_PTS = {
        right = {
            Vector3.new(-474.54, -7.00, 98.63),
            Vector3.new(-473.35, -7.00, 22.91),
            Vector3.new(-484.24, -5.04, 24.58),
        },
        left = {
            Vector3.new(-473.66, -7.00, 22.39),
            Vector3.new(-472.37, -7.00, 96.06),
            Vector3.new(-483.97, -5.04, 95.40),
        },
    }
    local _b3_side  = nil
    local _b3_on    = false
    local _b3_tping = false
    local _b3_c1    = nil
    local _b3_c2    = nil
    local _b3_cc    = nil


    
    local function _b3_watchSide()
        task.spawn(function()
            while _b3_on do
                pcall(function()
                    local plots = workspace:FindFirstChild("Plots")
                    if plots then
                        for _, plot in plots:GetChildren() do
                            local sign = plot:FindFirstChild("PlotSign")
                            if sign then
                                local yb = sign:FindFirstChild("YourBase")
                                if yb and yb:IsA("BillboardGui") and yb.Enabled then
                                    local bp = nil
                                    if plot.PrimaryPart then
                                        bp = plot.PrimaryPart.Position
                                    else
                                        local p = sign:IsA("BasePart") and sign or sign:FindFirstChildWhichIsA("BasePart")
                                        if p then bp = p.Position end
                                    end
                                    if bp then
                                        _b3_side = (bp - _b3_RETURN_R).Magnitude < (bp - _b3_RETURN_L).Magnitude and "right" or "left"
                                    end
                                end
                            end
                        end
                    end
                end)
                task.wait(0.5)
            end
        end)
    end

    local function _b3_pulse(tgt)
        local char = _b3_LP.Character; if not char then return end
        local root = char:FindFirstChild("HumanoidRootPart"); if not root then return end
        root.CFrame = CFrame.new(tgt)
    end
    local function _b3_onRag()
        if not _b3_on or _b3_tping then return end
        _b3_tping = true
        task.spawn(function()
            local side = _b3_side or "left"
            local pts  = _b3_PTS[side]
            for i = 1, #pts do
                if not _b3_tping or not _b3_on then break end
                for _ = 1, 4 do
                    if not _b3_tping or not _b3_on then break end
                    pcall(_b3_pulse, pts[i]); task.wait(0.02)
                end
            end
            _b3_tping = false
        end)
    end
    local function _b3_setupChar(character)
        if _b3_c1 then _b3_c1:Disconnect(); _b3_c1 = nil end
        if _b3_c2 then _b3_c2:Disconnect(); _b3_c2 = nil end
        local hum = character:WaitForChild("Humanoid", 6)
        if not hum then return end
        _b3_c1 = hum.StateChanged:Connect(function(_, ns)
            if not _b3_on then return end
            if ns == Enum.HumanoidStateType.Physics then _b3_onRag() end
        end)
        _b3_c2 = character.DescendantRemoving:Connect(function(desc)
            if not _b3_on then return end
            if desc:IsA("Motor6D") and hum and hum.Health > 0 then
                task.wait(0.05); _b3_onRag()
            end
        end)
    end
    local function _b3_start()
        _b3_on = true; _b3_tping = false; _b3_side = nil
        _b3_watchSide()
        if _b3_LP.Character then task.spawn(_b3_setupChar, _b3_LP.Character) end
        _b3_cc = _b3_LP.CharacterAdded:Connect(function(char)
            if not _b3_on then return end
            task.wait(0.15); task.spawn(_b3_setupChar, char)
        end)
    end
    local function _b3_stop()
        _b3_on = false; _b3_tping = false
        if _b3_c1 then _b3_c1:Disconnect(); _b3_c1 = nil end
        if _b3_c2 then _b3_c2:Disconnect(); _b3_c2 = nil end
        if _b3_cc then _b3_cc:Disconnect(); _b3_cc = nil end
    end
    local _b3_ct = 0
    local function _b3_fn()
        if tick()-_b3_ct < 0.2 then return end; _b3_ct = tick()
        local newOn = not _b3_getOn(); _b3_setV(newOn)
        if newOn then _b3_start() else _b3_stop() end
    end
    _b3_row.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 then
            task.defer(_b3_fn)
        end
    end)
    _b3_pill.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or
           inp.UserInputType == Enum.UserInputType.Touch then
            task.defer(_b3_fn)
        end
    end)
end)

