local Players     = game:GetService("Players")
local RunService  = game:GetService("RunService")
local HttpService = game:GetService("HttpService")
local CoreGui     = game:GetService("CoreGui")
local LP          = Players.LocalPlayer

local desiredRound3State = _G.FRHUB_ROUND3_ENABLED
if _G.Round3SpeedBooster and _G.Round3SpeedBooster.setEnabled then
    pcall(_G.Round3SpeedBooster.setEnabled, false)
end
_G.FRHUB_ROUND3_ENABLED = desiredRound3State
_G.FRHUB_ROUND3_FROM_PANEL = nil
pcall(function()
    local old = CoreGui:FindFirstChild("Round3SpeedBoosterGui")
    if old then old:Destroy() end
end)
pcall(function()
    local playerGui = LP:FindFirstChildOfClass("PlayerGui")
    local old = playerGui and playerGui:FindFirstChild("Round3SpeedBoosterGui")
    if old then old:Destroy() end
end)

local R3Boost = {
    enabled     = false,
    carrySpeed  = 32,
    normalSpeed = 62,
    forceCarry  = false,
    carryMode   = false,
}

pcall(function()
    local raw = readfile("Round3SpeedBooster6_Config.json")
    local cfg = HttpService:JSONDecode(raw)
    if type(cfg) == "table" then
        if type(cfg.carrySpeed) == "number" and cfg.carrySpeed > 0 then R3Boost.carrySpeed = cfg.carrySpeed end
        if type(cfg.normalSpeed) == "number" and cfg.normalSpeed > 0 then R3Boost.normalSpeed = cfg.normalSpeed end
    end
end)
if type(_G.FRHUB_ROUND3_ENABLED) == "boolean" then
    R3Boost.enabled = _G.FRHUB_ROUND3_ENABLED
end

local frStateAtStart = _G.FRHUB_STATE
if type(frStateAtStart) == "table" then
    if type(frStateAtStart.r3NormalSpeed) == "number" and frStateAtStart.r3NormalSpeed > 0 then
        R3Boost.normalSpeed = frStateAtStart.r3NormalSpeed
    end
    if type(frStateAtStart.r3CarrySpeed) == "number" and frStateAtStart.r3CarrySpeed > 0 then
        R3Boost.carrySpeed = frStateAtStart.r3CarrySpeed
    end
    R3Boost.forceCarry = R3Boost.enabled and frStateAtStart.forceCarrySpdEnabled == true
    R3Boost.carryMode = R3Boost.forceCarry
end

local Bridge = {
    Enabled = R3Boost.enabled,
    NormalSpeed = R3Boost.normalSpeed,
    CarrySpeed = R3Boost.carrySpeed,
    CarryMode = false,
    ForceCarry = false,
    Force = true,
}
_G.Round3SpeedBooster = Bridge

local function syncBridge()
    Bridge.Enabled     = R3Boost.enabled
    Bridge.NormalSpeed = R3Boost.normalSpeed
    Bridge.CarrySpeed  = R3Boost.carrySpeed
    Bridge.CarryMode   = R3Boost.carryMode
    Bridge.ForceCarry  = R3Boost.forceCarry
    pcall(function()
        if R3Boost.enabled then
            if _G.FRHUB_STATE then
                _G.FRHUB_STATE.r3NormalSpeed = R3Boost.normalSpeed
                _G.FRHUB_STATE.r3CarrySpeed  = R3Boost.carrySpeed
            end
        end
    end)
end

Bridge.setNormalSpeed = function(value)
    value = tonumber(value)
    if not value or value <= 0 then return end
    R3Boost.normalSpeed = value
    syncBridge()
end

Bridge.setCarrySpeed = function(value)
    value = tonumber(value)
    if not value or value <= 0 then return end
    R3Boost.carrySpeed = value
    syncBridge()
end

Bridge.setForceCarry = function(on)
    R3Boost.forceCarry = on == true
    if not R3Boost.forceCarry then
        R3Boost.carryMode = false
    end
    local frState = _G.FRHUB_STATE
    if type(frState) == "table" then
        frState.forceCarrySpdEnabled = R3Boost.forceCarry
    end
    syncBridge()
end

Bridge.setEnabled = function(on)
    R3Boost.enabled = on == true
    _G.FRHUB_ROUND3_ENABLED = R3Boost.enabled
    if not R3Boost.enabled then
        R3Boost.forceCarry = false
        R3Boost.carryMode  = false
        local frState = _G.FRHUB_STATE
        if type(frState) == "table" then
            frState.forceCarrySpdEnabled = false
        end
    end
    syncBridge()
end
syncBridge()

local function getR3BoostSpeed()
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not R3Boost.enabled then
        R3Boost.carryMode = false
        R3Boost.forceCarry = false
        syncBridge()
        return R3Boost.normalSpeed
    end
    local forceCarry = R3Boost.forceCarry or false
    if forceCarry then
        R3Boost.carryMode = true
    else
        R3Boost.carryMode = false
    end
    syncBridge()
    return R3Boost.carryMode and R3Boost.carrySpeed or R3Boost.normalSpeed
end

local function specialMovementOwnsVelocity()
    if _G._FRHUBZigZagFalling then return true end
    local frState = _G.FRHUB_STATE
    if type(frState) == "table" then
        if frState.autoLeftEnabled or frState.autoRightEnabled or frState._tpInProgress then
            return true
        end
    end

    local aimbot = _G.FRHUB_AIMBOT_V4
    if aimbot and type(aimbot.enabled) == "function" then
        local ok, enabled = pcall(aimbot.enabled)
        if ok and enabled then return true end
    end

    local ba = _G.FRHUB_BYPASS_AIMBOT
    if ba and type(ba.enabled) == "function" then
        local ok, enabled = pcall(ba.enabled)
        if ok and enabled then return true end
    end

    return false
end

RunService.RenderStepped:Connect(function()
    if not R3Boost.enabled then return end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not hrp then return end

    if specialMovementOwnsVelocity() then
        return
    end

    local md = hum.MoveDirection
    local spd = getR3BoostSpeed()
    if md.Magnitude > 0 then
        hrp.Velocity = Vector3.new(md.X * spd, hrp.Velocity.Y, md.Z * spd)
    else
        hrp.Velocity = Vector3.zero
    end
    pcall(function()
        if speedLbl then
            local hs = Vector3.new(hrp.AssemblyLinearVelocity.X, 0, hrp.AssemblyLinearVelocity.Z).Magnitude
            speedLbl.Text = "Speed: " .. string.format("%.1f", hs)
        end
    end)
    pcall(function()
        if MobileButtons and MobileButtons.Buttons and MobileButtons.Buttons.carrySpeed then
            MobileButtons.Buttons.carrySpeed(R3Boost.forceCarry == true)
        end
    end)
end)

task.spawn(function()
	local _rs = game:GetService("RunService")
	local _p = game:GetService("Players")
	local _lp = _p.LocalPlayer

	local _s = 59
	local _a = false
	local _v = Vector3.zero

	local _mt = getrawmetatable(game)
	setreadonly(_mt, false)

	local _oi = _mt.__index
	local _on = _mt.__newindex

	_mt.__index = newcclosure(function(t, k)
		if not checkcaller() then
			local _tk = tostring(k)
			if _tk == "AssemblyLinearVelocity" or _tk == "Velocity" then
				if typeof(t) == "Instance" and t:IsA("BasePart") then
					local _tn = t.Name
					if _tn == "HumanoidRootPart" or _tn == "Torso" or _tn == "UpperTorso" then
						if t:IsDescendantOf(_lp.Character) then
							return _v
						end
					end
				end
			end
		end
		return _oi(t, k)
	end)

	_mt.__newindex = newcclosure(function(t, k, v)
		if not checkcaller() then
			local _tk = tostring(k)
			if _tk == "AssemblyLinearVelocity" or _tk == "Velocity" then
				if typeof(t) == "Instance" and t:IsA("BasePart") then
					local _tn = t.Name
					if _tn == "HumanoidRootPart" or _tn == "Torso" or _tn == "UpperTorso" then
						if t:IsDescendantOf(_lp.Character) then
							_v = v
							return
						end
					end
				end
			end
		end
		return _on(t, k, v)
	end)

	setreadonly(_mt, true)

	local function _gc()
		local c = _lp.Character
		if not c then return nil, nil, nil end
		local h = c:FindFirstChildOfClass("Humanoid")
		local r = c:FindFirstChild("HumanoidRootPart")
		if h and h.Health > 0 and r then return c, h, r end
		return nil, nil, nil
	end

	local _r = Random.new()
	local _t = 0

	_rs.PreSimulation:Connect(function(d)
		_t = _t + d
		if _t < 0.016 then return end
		_t = 0
		if not _a then return end

		local c, h, r = _gc()
		if not c or not h or not r then return end

		local m = h.MoveDirection
		if m.Magnitude > 0.05 then
			pcall(function()
				if r.SetNetworkOwner then
					r:SetNetworkOwner(_lp)
				end
			end)

			local u = m.Unit
			local jx, jz = _r:NextNumber(-0.003, 0.003), _r:NextNumber(-0.003, 0.003)

			_v = Vector3.new(u.X * 16 + jx, r.AssemblyLinearVelocity.Y, u.Z * 16 + jz)
			r.AssemblyLinearVelocity = Vector3.new(u.X * _s + jx, r.AssemblyLinearVelocity.Y, u.Z * _s + jz)
		else
			_v = Vector3.new(0, r.AssemblyLinearVelocity.Y, 0)
		end
	end)
end)


