        local disc   = curVel.Y * curVel.Y - 2 * GRAVITY * math.abs(deltaY)
        local ballT  = disc > 0 and ((-curVel.Y - math.sqrt(disc)) / (-GRAVITY)) or 0.18
        ballT = math.clamp(ballT, 0.04, 0.55)
