    return {t[1], t[2], t[3]}
end
local function rgbColor(t)
    return Color3.fromRGB(t[1], t[2], t[3])
end
local function shiftedColor(t, d)
    return Color3.fromRGB(clampByte(t[1] + d), clampByte(t[2] + d), clampByte(t[3] + d))
end

local function computeColors()
    Colors.bg = rgbColor(BaseColors.bg)
    Colors.headerBg = shiftedColor(BaseColors.bg, 12)
    Colors.closeBg = shiftedColor(BaseColors.bg, 32)
    Colors.kb = shiftedColor(BaseColors.bg, 10)
    Colors.card = rgbColor(BaseColors.card)
    Colors.cardHov = shiftedColor(BaseColors.card, 20)
    Colors.border = rgbColor(BaseColors.border)
    Colors.border2 = shiftedColor(BaseColors.border, 60)
    Colors.accent = rgbColor(BaseColors.accent)
    Colors.dim = shiftedColor(BaseColors.accent, 80)
end
computeColors()

local themeBindings = {}
local function bindTheme(obj, prop, key)
    table.insert(themeBindings, {obj = obj, prop = prop, key = key})
end

local saveDebounce = false
local function saveConfig()
    if destroyed then return end
    pcall(function()
        writefile(CONFIG_FILE, HttpService:JSONEncode({
            autoBatKey = Keys.autoBat.Name,
            autoBatKeyType = Keys.autoBatType,
            mobileMode = State.mobileMode,
            mode = State.mode,
            ragdollMode = State.ragdollMode,
            locked = State.locked,
            uiScale = State.uiScale,
            posXScale = SavedPos.xs,
            posXOffset = SavedPos.xo,
            posYScale = SavedPos.ys,
            posYOffset = SavedPos.yo,
            autoV8Ragdoll = State.autoV8Ragdoll,
            autoV13Ragdoll = State.autoV13Ragdoll,
            colors = {
                bg = copyColor(BaseColors.bg),
                card = copyColor(BaseColors.card),
                border = copyColor(BaseColors.border),
                accent = copyColor(BaseColors.accent),
            },
        }))
    end)
end
local function queueSave()
    if saveDebounce then return end
    saveDebounce = true
    task.delay(0.4, function()
        saveDebounce = false
        saveConfig()
    end)
end

local function loadConfig()
    local ok
    pcall(function() ok = isfile(CONFIG_FILE) end)
    if not ok then return end
    local s, cfg = pcall(function() return HttpService:JSONDecode(readfile(CONFIG_FILE)) end)
    if not s or type(cfg) ~= "table" then return end
    if cfg.autoBatKey and Enum.KeyCode[cfg.autoBatKey] then Keys.autoBat = Enum.KeyCode[cfg.autoBatKey] end
    if cfg.autoBatKeyType then Keys.autoBatType = cfg.autoBatKeyType end
    if cfg.mobileMode ~= nil then State.mobileMode = cfg.mobileMode end
    if cfg.mode == "v8" or cfg.mode == "v11" or cfg.mode == "v13" or cfg.mode == "v14" then State.mode = cfg.mode end
    if cfg.ragdollMode == "v8" or cfg.ragdollMode == "v13" then State.ragdollMode = cfg.ragdollMode end
    if cfg.locked ~= nil then State.locked = cfg.locked end
    if type(cfg.uiScale) == "number" then State.uiScale = math.clamp(cfg.uiScale, 0.5, 2) end
    if type(cfg.posXScale) == "number" and type(cfg.posXOffset) == "number" and type(cfg.posYScale) == "number" and type(cfg.posYOffset) == "number" then
        SavedPos = {xs = cfg.posXScale, xo = cfg.posXOffset, ys = cfg.posYScale, yo = cfg.posYOffset}
    end
    if cfg.autoV8Ragdoll ~= nil then State.autoV8Ragdoll = cfg.autoV8Ragdoll end
    if cfg.autoV13Ragdoll ~= nil then State.autoV13Ragdoll = cfg.autoV13Ragdoll end
    if type(cfg.colors) == "table" then
        for _, k in ipairs({"bg", "card", "border", "accent"}) do
            local c = cfg.colors[k]
            if type(c) == "table" and type(c[1]) == "number" and type(c[2]) == "number" and type(c[3]) == "number" then
                BaseColors[k] = {clampByte(c[1]), clampByte(c[2]), clampByte(c[3])}
            end
        end
    end
    computeColors()
end
loadConfig()

local function getBat()
    local char = LP.Character; if not char then return nil end
    local t = char:FindFirstChild("Bat"); if t then return t end
    local bp = LP:FindFirstChild("Backpack")
    if bp then t = bp:FindFirstChild("Bat"); if t then t.Parent = char; return t end end
    return nil
end
local function getHum(char)
    return char and char:FindFirstChildOfClass("Humanoid")
end
local function getClosestBasic()
    if not hrp then return nil, math.huge end
    local cp, cd = nil, math.huge
    for _, p in pairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            local tr = p.Character:FindFirstChild("HumanoidRootPart")
            if tr then
                local d = (hrp.Position - tr.Position).Magnitude
                if d < cd then cd = d; cp = p end
            end
        end
    end
    return cp, cd
end

local function makeV8()
    local stepping = false
    local anchorConn = nil
    local lastFire = 0
    local tickCount = 0
    local DESYNC_WINDOW = 0.05

    local function tryHitBat()
        if State.hittingCooldown then return end
        State.hittingCooldown = true
        pcall(function()
            local bat = getBat()
            if not bat then return end
            local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
            if ev then
                for _ = 1, 3 do pcall(function() ev:FireServer() end) end
            end
            pcall(function() bat:Activate() end)
        end)
        task.delay(0.06, function() State.hittingCooldown = false end)
    end

    local function fakeRagdollState(char)
        if not char then return end
        local hum = char:FindFirstChild("Humanoid")
        if not hum then return end
        pcall(function()
            local origState = hum:GetState()
            hum:ChangeState(Enum.HumanoidStateType.Running)
            task.delay(0.1, function()
                pcall(function() hum:ChangeState(origState) end)
            end)
        end)
    end

    local function fireInDesyncWindow(fn)
        local now = tick()
        local delta = now - lastFire
        if delta < DESYNC_WINDOW then
            fn()
        else
            task.delay(DESYNC_WINDOW - (delta % DESYNC_WINDOW), fn)
        end
        lastFire = now
    end

    local function anchorAt(pos, duration)
        pcall(function() hrp.CFrame = CFrame.new(pos) end)
        if anchorConn then anchorConn:Disconnect() end
        local t = tick()
        anchorConn = RunService.Heartbeat:Connect(function()
            if tick() - t > duration then
                anchorConn:Disconnect(); anchorConn = nil; return
            end
            pcall(function()
                if hrp then hrp.CFrame = CFrame.new(pos) end
            end)
        end)
    end

    local function smoothStepTo(targetPos, onDone)
        if stepping then return end
        stepping = true
        task.spawn(function()
            if not hrp then stepping = false; return end
            local origin = hrp.Position
            local dist = (targetPos - origin).Magnitude
            if dist < 5 then
                pcall(function() hrp.CFrame = CFrame.new(targetPos) end)
                stepping = false
                if onDone then onDone() end
                return
            end
            local steps = math.clamp(math.floor(dist / 3), 3, 10)
            for i = 1, steps do
                if not hrp or not stepping then break end
                local alpha = i / steps
                local point = origin:Lerp(targetPos, alpha)
                pcall(function()
                    hrp.AssemblyLinearVelocity = (point - hrp.Position) * 60
                end)
                task.wait(0.016)
            end
            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(targetPos)
            end)
            stepping = false
            if onDone then onDone() end
        end)
    end

    local self = {}
    function self.heartbeat()
        if State.mode ~= "v8" then return end
        if not (State.autoBatToggled and h and hrp) then return end
        tickCount = tickCount + 1
        local target, dist = getClosestBasic()
        if not target or not target.Character then return end
        local tr = target.Character:FindFirstChild("HumanoidRootPart")
        if not tr then return end
        local targetPos = tr.Position + Vector3.new(0, 0.9, 0)
        pcall(function()
            workspace.CurrentCamera.CFrame = CFrame.new(workspace.CurrentCamera.CFrame.Position, tr.Position)
        end)
        if dist > 8 then
            smoothStepTo(targetPos, function()
                anchorAt(targetPos, 0.12)
                fakeRagdollState(LP.Character)
                fireInDesyncWindow(tryHitBat)
            end)
        else
            if tickCount % 2 == 0 then
                anchorAt(hrp.Position, 0.04)
                fakeRagdollState(LP.Character)
                fireInDesyncWindow(tryHitBat)
            end
        end
    end
    function self.cleanup()
        stepping = false
        if anchorConn then anchorConn:Disconnect(); anchorConn = nil end
    end
    self.onChar = self.cleanup
    return self
end

local function makeV11()
    local SHP = sethiddenproperty or (syn and syn.sethiddenproperty)
    local resetTimer = 0
    local frameCount = 0
    local jitterConn = nil
    local jitActive = false
    local reequipCD = false
    local hitCD = false

    local function shpTP(targetPos)
        if not hrp then return false end
        local char = LP.Character; if not char then return false end
        if SHP then
            pcall(function()
                SHP(hrp, "CFrame", CFrame.new(targetPos))
                SHP(hrp, "Velocity", Vector3.zero)
            end)
        else
            pcall(function() hrp.CFrame = CFrame.new(targetPos) end)
        end
        return true
    end

    local function grabOwnership()
        pcall(function()
            SHP(hrp, "NetworkOwnershipRule", Enum.NetworkOwnershipRule.Manual)
        end)
    end

    local function writePosition(pos)
        local cf = CFrame.new(pos)
        pcall(function() SHP(hrp, "CFrame", cf) end)
        pcall(function() SHP(hrp, "Velocity", Vector3.zero) end)
        pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero end)
        pcall(function() hrp.CFrame = cf end)
    end

    local function stateExploit()
        local char = LP.Character; if not char then return end
        local hum = getHum(char); if not hum then return end
        pcall(function()
            hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            hum:ChangeState(Enum.HumanoidStateType.Running)
        end)
    end

    local function startJitter()
        if jitterConn then return end
        jitterConn = RunService.Heartbeat:Connect(function()
            pcall(function()
                if hrp and SHP then
                    SHP(hrp, "Velocity", Vector3.new(
                        math.random(-3, 3) * 0.08,
                        math.random(-1, 1) * 0.03,
                        math.random(-3, 3) * 0.08
                    ))
                elseif hrp then
                    hrp.AssemblyLinearVelocity = Vector3.new(
                        math.random(-3, 3) * 0.08,
                        math.random(-1, 1) * 0.03,
                        math.random(-3, 3) * 0.08
                    )
                end
            end)
        end)
    end
    local function stopJitter()
        if jitterConn then jitterConn:Disconnect(); jitterConn = nil end
        pcall(function() if hrp then hrp.AssemblyLinearVelocity = Vector3.zero end end)
    end

    local function reequipReset(bat)
        if reequipCD then return end
        reequipCD = true
        task.spawn(function()
            pcall(function()
                bat.Parent = LP.Backpack
                task.wait()
                bat.Parent = LP.Character
            end)
            task.wait(0.15)
            reequipCD = false
        end)
    end

    local function fireHit()
        if hitCD then return end
        hitCD = true
        pcall(function()
            local bat = getBat(); if not bat then return end
            local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
            if ev then
                for _ = 1, 4 do pcall(function() ev:FireServer() end) end
            end
            pcall(function() bat:Activate() end)
            reequipReset(bat)
        end)
        task.delay(0.05, function() hitCD = false end)
    end

    local function doToggleReset()
        local char = LP.Character; if not char then return end
        local hum = getHum(char); if not hum then return end
        task.spawn(function()
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.Jumping)
                task.wait(0.02)
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end)
        end)
    end

    local self = {}
    function self.heartbeat(dt)
        if State.mode ~= "v11" then
            if jitActive then stopJitter(); jitActive = false end
            return
        end
        if not (State.autoBatToggled and h and hrp) then
            if jitActive then stopJitter(); jitActive = false end
            return
        end
        frameCount = frameCount + 1
        resetTimer = resetTimer + dt
        if not jitActive then startJitter(); jitActive = true end
        if resetTimer >= 1.2 then resetTimer = 0; doToggleReset() end
        local target, dist = getClosestBasic()
        if not target or not target.Character then return end
        local tr = target.Character:FindFirstChild("HumanoidRootPart")
        if not tr then return end
        pcall(function()
            workspace.CurrentCamera.CFrame = CFrame.new(workspace.CurrentCamera.CFrame.Position, tr.Position)
        end)
        local targetPos = tr.Position + Vector3.new(0, 0.9, 0)
        if dist > 8 then
            grabOwnership()
            writePosition(targetPos)
            stateExploit()
            fireHit()
        else
            if frameCount % 2 == 0 then
                stateExploit()
                fireHit()
            end
        end
    end
    function self.cleanup()
        if jitActive then stopJitter(); jitActive = false end
        resetTimer = 0
        frameCount = 0
    end
    function self.onChar()
        resetTimer = 0
        frameCount = 0
    end
    return self
end

local function makeV13()
    local batRemote = nil
    local batRemoteArgs = nil
    local lastHitTime = 0
    local dynamicCooldown = 0.3
    local stepping = false
    local ghostConn = nil
    local ghostActive = false
    local lastFire = 0
    local DESYNC_WINDOW = 0.05
    local posHistory = {}
    local HISTORY_SIZE = 6
    local tickCount = 0
    local getClosestPlayer

    local function interceptBatRemote()
        local bat = getBat()
        if not bat then return end
        for _, child in ipairs(bat:GetDescendants()) do
            if child:IsA("RemoteEvent") and not batRemote then
                local mt = getrawmetatable and getrawmetatable(child)
                if mt then
                    local oldFireServer = mt.FireServer
                    if oldFireServer then
                        pcall(function()
                            local hook
                            hook = hookfunction(oldFireServer, function(self, ...)
                                if self == child then
                                    batRemote = child
                                    batRemoteArgs = {...}
                                end
                                return hook(self, ...)
                            end)
                        end)
                    end
                end
                batRemote = child
            end
        end
    end

    local function simulateToolActivation(bat)
        pcall(function()
            local toolActivated = bat:FindFirstChild("Activated") or bat.Activated
            if toolActivated then
                toolActivated:Fire()
            end
        end)
        if batRemote and batRemoteArgs then
            pcall(function()
                batRemote:FireServer(table.unpack(batRemoteArgs))
            end)
        else
            local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
            if ev then
                local target = getClosestPlayer and getClosestPlayer()
                if target and target.Character then
                    local tr = target.Character:FindFirstChild("HumanoidRootPart")
                    if tr and hrp then
                        local hitCF = CFrame.new(hrp.Position, tr.Position)
                        pcall(function() ev:FireServer(hitCF) end)
                    else
                        pcall(function() ev:FireServer() end)
                    end
                else
                    pcall(function() ev:FireServer() end)
                end
            end
        end
        pcall(function() bat:Activate() end)
    end

    local function tryHitBat()
        local now = tick()
        if now - lastHitTime < dynamicCooldown then return end
        local bat = getBat()
        if not bat then return end
        interceptBatRemote()
        local char = LP.Character
        if not char then return end
        local equippedTool = char:FindFirstChildWhichIsA("Tool")
        if not equippedTool or equippedTool ~= bat then
            pcall(function()
                bat.Parent = char
            end)
            task.wait(0.05)
        end
        simulateToolActivation(bat)
        lastHitTime = now
        task.delay(0.15, function()
            dynamicCooldown = math.max(0.08, dynamicCooldown - 0.01)
        end)
    end

    local function smoothStepTo(targetPos, onDone)
        if stepping then return end
        stepping = true
        task.spawn(function()
            if not hrp then stepping = false; return end
            local origin = hrp.Position
            local dist = (targetPos - origin).Magnitude
            if dist < 5 then
                pcall(function() hrp.CFrame = CFrame.new(targetPos) end)
                stepping = false
                if onDone then onDone() end
                return
            end
            local steps = math.clamp(math.floor(dist / 3), 3, 10)
            for i = 1, steps do
                if not hrp or not stepping then break end
                local alpha = i / steps
                local point = origin:Lerp(targetPos, alpha)
                pcall(function()
                    hrp.AssemblyLinearVelocity = (point - hrp.Position) * 60
                end)
                task.wait(0.016)
            end
            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(targetPos)
            end)
            stepping = false
            if onDone then onDone() end
        end)
    end

    local function stopGhostLock()
        ghostActive = false
        if ghostConn then ghostConn:Disconnect(); ghostConn = nil end
        pcall(function()
            if h then h.PlatformStand = false end
            if hrp then hrp.AssemblyLinearVelocity = Vector3.zero end
        end)
    end

    local function ghostLock(pos, duration)
        if ghostConn then ghostConn:Disconnect(); ghostConn = nil end
        ghostActive = true
        local deadline = tick() + duration
        pcall(function()
            if h then h.PlatformStand = true end
        end)
        ghostConn = RunService.Heartbeat:Connect(function()
            if not ghostActive or tick() > deadline or not hrp then
                ghostActive = false
                if ghostConn then ghostConn:Disconnect(); ghostConn = nil end
                pcall(function()
                    if h then h.PlatformStand = false end
                    if hrp then hrp.AssemblyLinearVelocity = Vector3.zero end
                end)
                return
            end
            pcall(function()
                hrp.AssemblyLinearVelocity = Vector3.zero
                hrp.AssemblyAngularVelocity = Vector3.zero
                hrp.CFrame = CFrame.new(pos) * CFrame.Angles(0, (hrp.CFrame - hrp.CFrame.Position):ToEulerAnglesXYZ())
            end)
        end)
    end

    local function fakeRagdollState(char)
        if not char then return end
        local hum = char:FindFirstChild("Humanoid")
        if not hum then return end
        pcall(function()
            local origState = hum:GetState()
            hum:ChangeState(Enum.HumanoidStateType.Running)
            task.delay(0.1, function()
                pcall(function() hum:ChangeState(origState) end)
            end)
        end)
    end

    local function fireInDesyncWindow(fn)
        local now = tick()
        local delta = now - lastFire
        if delta < DESYNC_WINDOW then
            fn()
        else
            task.delay(DESYNC_WINDOW - (delta % DESYNC_WINDOW), fn)
        end
        lastFire = now
    end

    local function recordPos(player, pos)
        if not posHistory[player] then posHistory[player] = {} end
        local hist = posHistory[player]
        table.insert(hist, {pos = pos, t = tick()})
        if #hist > HISTORY_SIZE then table.remove(hist, 1) end
    end

    local function getVelocity(player)
        local hist = posHistory[player]
        if not hist or #hist < 2 then return Vector3.zero end
        local a = hist[#hist - 1]
        local b = hist[#hist]
        local dt = b.t - a.t
        if dt <= 0 then return Vector3.zero end
        return (b.pos - a.pos) / dt
    end

    local function getAcceleration(player)
        local hist = posHistory[player]
        if not hist or #hist < 3 then return Vector3.zero end
        local t1 = hist[#hist - 2]
        local t2 = hist[#hist - 1]
        local t3 = hist[#hist]
        local dt1 = t2.t - t1.t
        local dt2 = t3.t - t2.t
        if dt1 <= 0 or dt2 <= 0 then return Vector3.zero end
        local v1 = (t2.pos - t1.pos) / dt1
        local v2 = (t3.pos - t2.pos) / dt2
        local avgDt = (dt1 + dt2) / 2
        return (v2 - v1) / avgDt
    end

    local function predictPosition(player, latency)
        local hist = posHistory[player]
        if not hist or #hist < 2 then
            local tr = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
            return tr and tr.Position or Vector3.zero
        end
        local currentPos = hist[#hist].pos
        local vel = getVelocity(player)
        local acc = getAcceleration(player)
        local predicted = currentPos + vel * latency + acc * (0.5 * latency * latency)
        return predicted
    end

    local function getLatency()
        local stats = game:GetService("Stats")
        local ping = 0
        pcall(function()
            ping = stats.Network.ServerStatsItem["Data Ping"]:GetValueString()
            ping = tonumber(ping) or 80
        end)
        if ping == 0 then ping = 80 end
        return ping / 1000
    end

    getClosestPlayer = function()
        if not hrp then return nil, math.huge, nil end
        local cp, cd, cpred = nil, math.huge, nil
        for _, p in pairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local tr = p.Character:FindFirstChild("HumanoidRootPart")
                if tr then
                    recordPos(p, tr.Position)
                    local d = (hrp.Position - tr.Position).Magnitude
                    if d < cd then
                        cd = d
                        cp = p
                        cpred = predictPosition(p, getLatency())
                    end
                end
            end
        end
        return cp, cd, cpred
    end

    local self = {}
    function self.heartbeat()
        if State.mode ~= "v13" then return end
        if not (State.autoBatToggled and h and hrp) then return end
        tickCount = tickCount + 1
        local target, dist, predictedPos = getClosestPlayer()
        if not target or not target.Character then return end
        local tr = target.Character:FindFirstChild("HumanoidRootPart")
        if not tr then return end
        local futurePos = predictedPos or tr.Position
        local targetPos = futurePos + Vector3.new(0, 0.9, 0)
        pcall(function()
            workspace.CurrentCamera.CFrame = CFrame.new(workspace.CurrentCamera.CFrame.Position, tr.Position)
        end)
        if dist > 8 then
            smoothStepTo(targetPos, function()
                ghostLock(targetPos, 0.18)
                fakeRagdollState(LP.Character)
                fireInDesyncWindow(tryHitBat)
            end)
        else
            ghostLock(futurePos + Vector3.new(0, 0.9, 0), 0.06)
            fakeRagdollState(LP.Character)
            fireInDesyncWindow(tryHitBat)
        end
    end
    function self.cleanup()
        stepping = false
        stopGhostLock()
    end
    self.onChar = self.cleanup
    return self
end

local function makeV14()
    local SHP = sethiddenproperty or (syn and syn.sethiddenproperty)
    local hitCD = false
    local tpCD = false
    local stateCD = false
    local jitterConn = nil
    local jitActive = false
    local reequipCD = false
    local frameCount = 0

    local function shpWrite(pos)
        if not State.autoBatToggled then return end
        if not hrp then return end
        local cf = CFrame.new(pos)
        pcall(function()
            SHP(hrp, "CFrame", cf)
            SHP(hrp, "Velocity", Vector3.zero)
        end)
        pcall(function() hrp.CFrame = cf end)
    end

    local function grabOwnership()
        if not State.autoBatToggled then return end
        if not hrp then return end
        pcall(function()
            SHP(hrp, "NetworkOwnershipRule", Enum.NetworkOwnershipRule.Manual)
        end)
    end

    local function maskVelocity()
        if not State.autoBatToggled then return end
        if not hrp then return end
        pcall(function()
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
        if SHP then
            pcall(function()
                SHP(hrp, "Velocity", Vector3.zero)
                SHP(hrp, "AngularVelocity", Vector3.zero)
            end)
        end
    end

    local function stateDesync()
        if not State.autoBatToggled then return end
        if stateCD then return end
        stateCD = true
        task.spawn(function()
            local char = LP.Character
            local hum = char and getHum(char)
            if hum then
                pcall(function()
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                end)
            end
            task.wait(0.02)
            stateCD = false
        end)
    end

    local function startJitter()
        if jitterConn then return end
        jitterConn = RunService.Heartbeat:Connect(function()
            if not State.autoBatToggled then return end
            pcall(function()
                if hrp then
                    local j = Vector3.new(
                        math.random(-3, 3) * 0.06,
                        math.random(-1, 1) * 0.02,
                        math.random(-3, 3) * 0.06
                    )
                    if SHP then
                        SHP(hrp, "Velocity", j)
                    else
                        hrp.AssemblyLinearVelocity = j
                    end
                end
            end)
        end)
    end
    local function stopJitter()
        if jitterConn then jitterConn:Disconnect(); jitterConn = nil end
    end

    local function reequipReset(bat)
        if not State.autoBatToggled then return end
        if reequipCD then return end
        reequipCD = true
        task.spawn(function()
            pcall(function()
                bat.Parent = LP.Backpack
                task.wait()
                bat.Parent = LP.Character
            end)
            task.wait(0.03)
            reequipCD = false
        end)
    end

    local function fireHit()
        if not State.autoBatToggled then return end
        if hitCD then return end
        hitCD = true
        task.spawn(function()
            pcall(function()
                local bat = getBat(); if not bat then return end
                local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
                if ev then
                    for _ = 1, 20 do
                        pcall(function() ev:FireServer() end)
                    end
                end
                pcall(function() bat:Activate() end)
                reequipReset(bat)
            end)
            task.wait(0.01)
            hitCD = false
        end)
    end

    local function cameraDesync(target)
        if not State.autoBatToggled then return end
        pcall(function()
            workspace.CurrentCamera.CFrame = CFrame.new(
                workspace.CurrentCamera.CFrame.Position,
                target.Position
            )
        end)
    end

    local function humanoidDesync(target)
        if not State.autoBatToggled then return end
        local char = LP.Character; if not char then return end
        local hum = getHum(char); if not hum then return end
        pcall(function()
            SHP(hum, "HumanoidRootPart", target)
        end)
    end

    local self = {}
    function self.heartbeat()
        if State.mode ~= "v14" then
            if jitActive then
                stopJitter()
                jitActive = false
            end
            return
        end
        if not State.autoBatToggled then
            if jitActive then
                stopJitter()
                jitActive = false
            end
            return
        end
        if not jitActive then
            startJitter()
            jitActive = true
        end
        if not (h and hrp) then return end
        frameCount = frameCount + 1
        local target, dist = getClosestBasic()
        if not target or not target.Character then return end
        local tr = target.Character:FindFirstChild("HumanoidRootPart")
        if not tr then return end
        cameraDesync(tr)
        humanoidDesync(tr)
        local targetPos = tr.Position + Vector3.new(0, 0.9, 0)
        if dist > 3 then
            if not tpCD then
                tpCD = true
                task.spawn(function()
                    if State.mode ~= "v14" or not State.autoBatToggled then tpCD = false; return end
                    grabOwnership()
                    maskVelocity()
                    shpWrite(targetPos)
                    maskVelocity()
                    stateDesync()
                    fireHit()
                    task.wait(0.01)
                    tpCD = false
                end)
            end
        else
            stateDesync()
            fireHit()
        end
    end
    function self.cleanup()
        if jitActive then
            stopJitter()
            jitActive = false
        end
        tpCD = false
    end
    function self.onChar()
        frameCount = 0
    end
    return self
end

local Engines = {
    v8 = makeV8(),
    v11 = makeV11(),
    v13 = makeV13(),
    v14 = makeV14(),
}
local function cleanupEngines()
    for _, eng in pairs(Engines) do
        if eng.cleanup then pcall(eng.cleanup) end
    end
end

