ragdollActivate = function()
    if State.ragdollActive then return end
    State.ragdollActive = true
    if ragdollBusy and autoPrevMode then
        State.ragdollPrevMode = autoPrevMode
        State.ragdollPrevToggled = autoPrevToggled
    else
        State.ragdollPrevMode = State.mode
        State.ragdollPrevToggled = State.autoBatToggled
    end
    ragdollCycleId = ragdollCycleId + 1
    ragdollBusy = false
    setMode(State.ragdollMode)
    setToggled(true)
    setRagdollVisual(true)
end

ragdollDeactivate = function(restore)
    if not State.ragdollActive then return end
    State.ragdollActive = false
    setRagdollVisual(false)
    if restore then
        setMode(State.ragdollPrevMode)
        setToggled(State.ragdollPrevToggled)
    end
end

userToggleMain = function()
    if State.ragdollActive then
        ragdollDeactivate(false)
        setToggled(false)
    else
        setToggled(not State.autoBatToggled)
    end
end

