local function refreshOptions()
    for m, ref in pairs(optionButtons) do
        if m == State.mode then
            ref.btn.TextColor3 = Colors.accent
            ref.stroke.Color = Colors.accent
            ref.stroke.Thickness = 2
        else
            ref.btn.TextColor3 = Colors.dim
            ref.stroke.Color = Colors.border2
            ref.stroke.Thickness = 1
        end
    end
end

closeDropdown = function()
    dropdown.Visible = false
    dropBlocker.Visible = false
end
openDropdown = function()
    refreshOptions()
    local ap = modeBtn.AbsolutePosition
    local as = modeBtn.AbsoluteSize
    local vw = gui.AbsoluteSize.X
    local vh = gui.AbsoluteSize.Y
    local x = math.clamp(ap.X, 6, math.max(6, vw - 126))
    local y = ap.Y + as.Y + 6
    if y + 120 > vh then y = ap.Y - 126 end
    dropdown.Position = UDim2.fromOffset(x, math.max(6, y))
    dropdown.Visible = true
    dropBlocker.Visible = true
end
dropBlocker.MouseButton1Click:Connect(closeDropdown)

