do
    local dragging, dragInput, dragStart, frmStart = false, nil, nil, nil
    settingsFrame.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
            dragging = true; dragStart = inp.Position; frmStart = settingsFrame.Position
            inp.Changed:Connect(function()
                if inp.UserInputState == Enum.UserInputState.End then
                    dragging = false
                    clampSettingsOnScreen()
                end
            end)
        end
    end)
    settingsFrame.InputChanged:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch then dragInput = inp end
    end)
    UIS.InputChanged:Connect(function(inp)
        if inp == dragInput and dragging then
            settingsFrame.Position = UDim2.new(
                frmStart.X.Scale,
                frmStart.X.Offset + (inp.Position.X - dragStart.X),
                frmStart.Y.Scale,
                frmStart.Y.Offset + (inp.Position.Y - dragStart.Y)
            )
        end
    end)
end

