local function makeSettingToggle(parent, posY, labelText, getOn, setOn)
    local row = Instance.new("Frame", parent)
    row.Size = UDim2.new(1, -14, 0, 28); row.Position = UDim2.new(0, 0, 0, posY)
    row.BackgroundColor3 = Colors.card; row.BorderSizePixel = 0; row.ZIndex = 62
    Instance.new("UICorner", row).CornerRadius = UDim.new(0, 7)
    local rs = Instance.new("UIStroke", row)
    rs.Color = Colors.border
    bindTheme(row, "BackgroundColor3", "card")
    bindTheme(rs, "Color", "border")
    local lbl = Instance.new("TextLabel", row)
    lbl.Size = UDim2.new(0, 175, 1, 0); lbl.Position = UDim2.new(0, 10, 0, 0)
    lbl.BackgroundTransparency = 1; lbl.Text = labelText
    lbl.TextColor3 = Colors.accent; lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 8
    lbl.TextXAlignment = Enum.TextXAlignment.Left; lbl.ZIndex = 63
    bindTheme(lbl, "TextColor3", "accent")
    local pill = Instance.new("Frame", row)
    pill.Size = UDim2.new(0, 30, 0, 16); pill.Position = UDim2.new(1, -38, 0.5, -8)
    pill.BackgroundColor3 = Color3.fromRGB(16, 16, 16); pill.BorderSizePixel = 0; pill.ZIndex = 63
    Instance.new("UICorner", pill).CornerRadius = UDim.new(0, 8)
    local pst = Instance.new("UIStroke", pill)
    pst.Color = Colors.border2; pst.Thickness = 1
    local pdot = Instance.new("Frame", pill)
    pdot.Size = UDim2.new(0, 10, 0, 10); pdot.Position = UDim2.new(0, 2, 0.5, -5)
    pdot.BackgroundColor3 = Color3.fromRGB(45, 45, 45); pdot.BorderSizePixel = 0; pdot.ZIndex = 64
    Instance.new("UICorner", pdot).CornerRadius = UDim.new(0, 3)
    local function vis(on)
        pill.BackgroundColor3 = on and Colors.accent or Color3.fromRGB(16, 16, 16)
        pst.Color = on and Colors.accent or Colors.border2
        pdot.Position = on and UDim2.new(1, -12, 0.5, -5) or UDim2.new(0, 2, 0.5, -5)
        pdot.BackgroundColor3 = on and Colors.bg or Color3.fromRGB(45, 45, 45)
    end
    local clk = Instance.new("TextButton", row)
    clk.Size = UDim2.new(1, 0, 1, 0); clk.BackgroundTransparency = 1
    clk.Text = ""; clk.ZIndex = 65
    clk.MouseButton1Click:Connect(function()
        setOn(not getOn())
        vis(getOn())
    end)
    vis(getOn())
    return {vis = vis}
end

