local function makeSlider(rowParent, xOffset, yOffset, w, role, channel)
    local track = Instance.new("Frame", rowParent)
    track.Size = UDim2.new(0, w, 0, 6); track.Position = UDim2.new(0, xOffset, 0, yOffset)
    track.BackgroundColor3 = Color3.fromRGB(16, 16, 16); track.BorderSizePixel = 0; track.ZIndex = 63
