    bindTheme(tst, "Color", "border2")
    local fill = Instance.new("Frame", track)
    fill.BorderSizePixel = 0; fill.ZIndex = 64
    Instance.new("UICorner", fill).CornerRadius = UDim.new(0, 3)
    local dragging = false
    local function applyValue(v)
        v = clampByte(v)
        BaseColors[role][channel] = v
        fill.Size = UDim2.new(v / 255, 0, 1, 0)
        fill.BackgroundColor3 = sliderTint(channel, v)
        applyTheme()
        queueSave()
    end
    local function setFromX(x)
        local rel = (x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1)
        applyValue(rel * 255)
    end
    track.InputBegan:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            setFromX(inp.Position.X)
            inp.Changed:Connect(function()
                if inp.UserInputState == Enum.UserInputState.End then
                    dragging = false
                    saveConfig()
                end
            end)
        end
    end)
    UIS.InputChanged:Connect(function(inp)
        if dragging and (inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch) then
            setFromX(inp.Position.X)
        end
    end)
    local function refresh()
        local v = BaseColors[role][channel]
        fill.Size = UDim2.new(v / 255, 0, 1, 0)
        fill.BackgroundColor3 = sliderTint(channel, v)
    end
    refresh()
    table.insert(sliderRefs, {refresh = refresh})
end

