local function settingsSize()
    return settingsFrame.Size.X.Offset, settingsFrame.Size.Y.Offset
end

updateSettingsFit = function()
    local vp = gui.AbsoluteSize
    local availW = math.max(vp.X - 12, 120)
    local availH = math.max(vp.Y - 12, 120)
    settingsFrame.Size = UDim2.new(0, math.min(SETTINGS_W, availW), 0, math.min(SETTINGS_H, availH))
end

local function centerSettings()
    local vp = gui.AbsoluteSize
    local w, hh = settingsSize()
    settingsFrame.Position = UDim2.fromOffset((vp.X - w) / 2, (vp.Y - hh) / 2)
end

clampSettingsOnScreen = function()
    local vp = gui.AbsoluteSize
    local w, hh = settingsSize()
    local pos = settingsFrame.Position
    local x = math.clamp(pos.X.Offset, 0, math.max(0, vp.X - w))
    local y = math.clamp(pos.Y.Offset, 0, math.max(0, vp.Y - hh))
    settingsFrame.Position = UDim2.fromOffset(x, y)
end

showSettings = function()
    closeDropdown()
    updateSettingsFit()
    centerSettings()
    settingsFrame.Visible = true
    settingsBlocker.Visible = true
end

hideSettings = function()
    settingsFrame.Visible = false
    settingsBlocker.Visible = false
end

gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
    if settingsFrame.Visible then
        updateSettingsFit()
        clampSettingsOnScreen()
    end
end)

