mainHeartbeatConn = RunService.Heartbeat:Connect(function(dt)
    if destroyed then return end
    local eng = Engines[State.mode]
    if eng then eng.heartbeat(dt) end
end)

local function onRagdollDetected()
    if destroyed or State.ragdollActive then return end
    if ragdollBusy or ragdollImmune then return end
    local target
    if State.autoV13Ragdoll then
        target = "v13"
    elseif State.autoV8Ragdoll then
        target = "v8"
    end
    if not target then return end
    if State.autoBatToggled and State.mode == target then return end
    ragdollBusy = true
    ragdollCycleId = ragdollCycleId + 1
    local myId = ragdollCycleId
    autoPrevMode = State.mode
    autoPrevToggled = State.autoBatToggled
    setMode(target)
    setToggled(true)
    task.delay(4, function()
        if myId ~= ragdollCycleId then return end
        if not destroyed and not State.ragdollActive then
            setToggled(autoPrevToggled)
            setMode(autoPrevMode)
        end
        ragdollBusy = false
        ragdollImmune = true
        task.delay(1.5, function() ragdollImmune = false end)
    end)
end

local function setupRagdollWatch(character)
    if ragdollConn1 then ragdollConn1:Disconnect(); ragdollConn1 = nil end
    if ragdollConn2 then ragdollConn2:Disconnect(); ragdollConn2 = nil end
    local rhrp = character:WaitForChild("HumanoidRootPart", 6)
    local rhum = character:WaitForChild("Humanoid", 6)
    if not rhrp or not rhum then return end
    ragdollConn1 = rhum.StateChanged:Connect(function(_, newState)
        if newState == Enum.HumanoidStateType.Physics then
            onRagdollDetected()
        end
    end)
    ragdollConn2 = character.DescendantRemoving:Connect(function(desc)
        if desc:IsA("Motor6D") and rhum and rhum.Health > 0 then
            task.wait(0.05)
            onRagdollDetected()
        end
    end)
end

local function setupChar(char)
    task.wait(0.1)
    h = char:WaitForChild("Humanoid", 5)
    hrp = char:WaitForChild("HumanoidRootPart", 5)
    if not h or not hrp then return end
    for _, eng in pairs(Engines) do
        if eng.onChar then pcall(eng.onChar) end
    end
    setupRagdollWatch(char)
end
LP.CharacterAdded:Connect(setupChar)
if LP.Character then task.spawn(function() setupChar(LP.Character) end) end

UIS.InputBegan:Connect(function(inp, gp)
    if State.mobileMode then return end
    if gp then return end
    if Keys.autoBatType == "Keyboard" and inp.UserInputType == Enum.UserInputType.Keyboard then
        if inp.KeyCode == Keys.autoBat then
            userToggleMain()
        elseif inp.KeyCode == Keys.guiHide then
            State.guiVisible = not State.guiVisible
            main.Visible = State.guiVisible
            if not State.guiVisible then
                closeDropdown()
                hideSettings()
            end
        end
    elseif Keys.autoBatType == "Gamepad" and inp.UserInputType == Enum.UserInputType.Gamepad1 then
        if inp.KeyCode == Keys.autoBat then
            userToggleMain()
        end
    end
end)
end

