local ATTACK_DISTANCE = 3
local SMOOTHING = 0.3

local heartbeatConnection
local appliedRoot
local appliedTarget

local function getRoot(character)
	return character and character:FindFirstChild("HumanoidRootPart")
end

local function isValidTarget(root)
	if not root or not root.Parent then
		return false
	end
	local humanoid = root.Parent:FindFirstChildOfClass("Humanoid")
	return humanoid ~= nil and humanoid.Health > 0
end

local function getNearestRoot(myRoot)
	local nearest
	local nearestDistance
	for _, player in ipairs(Players:GetPlayers()) do
		if player ~= LocalPlayer then
			local root = getRoot(player.Character)
			if isValidTarget(root) then
				local distance = (root.Position - myRoot.Position).Magnitude
				if not nearestDistance or distance < nearestDistance then
					nearest = root
					nearestDistance = distance
				end
			end
		end
	end
	return nearest
end

local function setRepRoot(part, target)
	local ok = pcall(function()
		part.PhysicsRepRootPart = target
	end)
	if not ok and sethiddenproperty then
		pcall(sethiddenproperty, part, "PhysicsRepRootPart", target)
	end
end

local function findBat(character)
	local equipped = character:FindFirstChildWhichIsA("Tool")
	if equipped and equipped.Name:lower():find("bat") then
		return equipped
	end
	local backpack = LocalPlayer:FindFirstChildOfClass("Backpack")
	if backpack then
		for _, item in ipairs(backpack:GetChildren()) do
			if item:IsA("Tool") and item.Name:lower():find("bat") then
				return item
			end
		end
	end
	return nil
end

local function swing(character, humanoid)
	local bat = findBat(character)
	if not bat then
		return
	end
	if bat.Parent ~= character then
		humanoid:EquipTool(bat)
	end
	bat:Activate()
end

local function startDesync()
	if heartbeatConnection then
		return
	end
	heartbeatConnection = RunService.Heartbeat:Connect(function()
		local character = LocalPlayer.Character
		local myRoot = getRoot(character)
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not myRoot or not humanoid or humanoid.Health <= 0 then
			appliedRoot = nil
			appliedTarget = nil
			return
		end
		if appliedRoot ~= myRoot or not isValidTarget(appliedTarget) then
			local target = getNearestRoot(myRoot)
			if not target then
				return
			end
			setRepRoot(myRoot, target)
			appliedRoot = myRoot
			appliedTarget = target
		end
		local behind = appliedTarget.CFrame * CFrame.new(0, 0, ATTACK_DISTANCE)
		local goal = CFrame.lookAt(behind.Position, appliedTarget.Position)
		myRoot.CFrame = myRoot.CFrame:Lerp(goal, SMOOTHING)
		myRoot.AssemblyLinearVelocity = Vector3.zero
		swing(character, humanoid)
	end)
end

local function stopDesync()
	if heartbeatConnection then
		heartbeatConnection:Disconnect()
		heartbeatConnection = nil
	end
	local myRoot = getRoot(LocalPlayer.Character)
	if myRoot then
		setRepRoot(myRoot, nil)
	end
	appliedRoot = nil
	appliedTarget = nil
end

local enabled = false
local mode = (UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled) and "MOBILE" or "PC"

local function render()
	if enabled then
		tween(track, { BackgroundColor3 = COLORS.ButtonStroke })
		tween(knob, { Position = UDim2.new(1, -16, 0.5, -6), BackgroundColor3 = COLORS.Text })
		tween(mobileButton, { BackgroundColor3 = COLORS.Close })
	else
		tween(track, { BackgroundColor3 = COLORS.SwitchOff })
		tween(knob, { Position = UDim2.new(0, 3, 0.5, -6), BackgroundColor3 = COLORS.KnobOff })
		tween(mobileButton, { BackgroundColor3 = COLORS.Button })
	end
end

local function setEnabled(value)
	enabled = value
	env.FRHUB_AntiDesyncEnabled = value
	if value then
		startDesync()
	else
		stopDesync()
	end
	render()
end

local function setMode(value)
	mode = value
	modeButton.Text = value
	mobileButton.Visible = value == "MOBILE"
end

rowButton.MouseButton1Click:Connect(function()
	setEnabled(not enabled)
end)

mobileButton.MouseButton1Click:Connect(function()
	setEnabled(not enabled)
end)

modeButton.MouseButton1Click:Connect(function()
	setMode(mode == "PC" and "MOBILE" or "PC")
end)

closeButton.MouseEnter:Connect(function()
