_G._FRHUBAntiBatV67SpikeT = 0
_G._FRHUBAntiBatV67GuardT = 0
_G.FRHUBAntiBatV67Enabled = _G.FRHUBAntiBatV67Enabled == true

local function speedValue()
  local fn = _G.FRHUBGetCurrentSpeedValue
  if type(fn) == "function" then
    local ok, v = pcall(fn)
    if ok and tonumber(v) then return tonumber(v) end
  end
  local char = LP.Character
  local hum = char and char:FindFirstChildOfClass("Humanoid")
  return (hum and tonumber(hum.WalkSpeed)) or 0
end

local function speedGuard(hrp)
  if not (hrp and hrp.Parent) then return end
  local now = os.clock()
  if now - (tonumber(_G._FRHUBAntiBatV67GuardT) or 0) < 0.35 then return end
  _G._FRHUBAntiBatV67GuardT = now
  pcall(function()
    for _, n in ipairs({"VelocityLock","SpeedLock","WalkSpeedLock","LockBAV","LockAngVel","LockBodyAtt","BatLock","LockBAVAtt","AutoBatAtt","AutoBatAV","AntiBatDet","AntiAim"}) do
      local o = hrp:FindFirstChild(n)
      if o then o:Destroy() end
    end
    for _, c in ipairs(hrp:GetChildren()) do
      local low = string.lower(c.Name)
      if c:IsA("LinearVelocity") or c:IsA("BodyVelocity")
         or low:find("velocitylock", 1, true) or low:find("speedlock", 1, true) or low:find("antibatdet", 1, true) then
        pcall(function() c:Destroy() end)
      end
    end
  end)
  pcall(function()
    if hrp.SetNetworkOwner and hrp:GetNetworkOwner() ~= LP then hrp:SetNetworkOwner(LP) end
  end)
end

local AntiBatConn = nil
local Speed = 10000
local Angle = 0
local Direction = 1

local function stopAntiBat()
  local c = AntiBatConn or _G._FRHUBAntiBatV67Conn
  if c then
    pcall(function() c:Disconnect() end)
  end
  AntiBatConn = nil
  _G._FRHUBAntiBatV67Conn = nil
  Speed = 10000
  Angle = 0
  Direction = 1
  _G._FRHUBAntiBatV67DesiredXZ = nil
  _G._FRHUBAntiBatV67Spiking = false
end

local function startAntiBat()
  stopAntiBat()
  AntiBatConn = RunService.Heartbeat:Connect(function()
    if not _G.FRHUBAntiBatV67Enabled then return end
    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not root or not root.Parent then return end
    local origXZ = Vector3.new(root.Velocity.X, 0, root.Velocity.Z)
    Speed = Speed + (50 * Direction)
    if Speed >= 20000 then
      Speed = 20000
      Direction = -1
    elseif Speed <= 10000 then
      Speed = 10000
      Direction = 1
    end
    Angle = Angle + (math.random() * 0.5)
    local radius = Speed + math.random(-5000, 5000)
    local newX = math.cos(Angle) * radius
    local newZ = math.sin(Angle) * radius
    _G._FRHUBAntiBatV67Spiking = true
    _G._FRHUBAntiBatV67SpikeT = os.clock()
    root.Velocity = Vector3.new(newX, root.Velocity.Y, newZ)
    RunService.RenderStepped:Wait()
    if root.Parent then
      local want = _G._FRHUBAntiBatV67DesiredXZ or _G._FRHUBAntiBatDesiredXZ
      if want then
        root.Velocity = Vector3.new(want.X, root.Velocity.Y, want.Z)
      else
        local _hb = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
        local _mdr = _hb and _hb.MoveDirection or Vector3.new(0, 0, 0)
        local _spr = speedValue()
        if _spr > 0 and _mdr.Magnitude > 0.05 then
          root.Velocity = Vector3.new(_mdr.X * _spr, root.Velocity.Y, _mdr.Z * _spr)
        else
          root.Velocity = Vector3.new(origXZ.X, root.Velocity.Y, origXZ.Z)
        end
      end
      speedGuard(root)
    end
    _G._FRHUBAntiBatV67Spiking = false
  end)
  _G._FRHUBAntiBatV67Conn = AntiBatConn
end

task.spawn(function()
  while true do
    task.wait(0.5)
    if _G._FRHUBAntiBatV67Token ~= MyToken then break end
    if _G.FRHUBAntiBatV67Enabled then
      if not AntiBatConn then
        pcall(startAntiBat)
      end
    elseif AntiBatConn then
      pcall(stopAntiBat)
    end
    if _G._FRHUBAntiBatV67Spiking == true then
      local ts = tonumber(_G._FRHUBAntiBatV67SpikeT) or 0
      if ts == 0 or (os.clock() - ts) > 0.3 then
        _G._FRHUBAntiBatV67Spiking = false
      end
    end
  end
end)

LP.CharacterAdded:Connect(function()
  if _G.FRHUBAntiBatV67Enabled then
    pcall(startAntiBat)
  else
    pcall(stopAntiBat)
