end)

local SCALE_STEPS = { 0.75, 0.85, 0.925, 1, 1.1, 1.2, 1.35 }
local curScaleIdx = 4
local curScale = SCALE_STEPS[curScaleIdx]

local curBg = DEFAULT_BG
local curTheme = DEFAULT_THEME
