local autoBrainrot = true
local antiDrop = false
local boundKey = DEFAULT_KEYBIND
local boundKeyName = "V"

local WINDOW, HEADER_C, CARD, CARD_HI, CHIP, BORDER, BORDER2, ACCENT, ACCENT_D
local C_KICKER, C_NOTE_EN, C_NOTE_AR, OKG, TXT, MUTED, KNOB_OFF

local function loadThemeColors()
  local T = THEMES[curTheme] or THEMES[1]
  WINDOW   = T.win
  HEADER_C = T.header
  CARD     = T.card
  CARD_HI  = T.cardHi
  CHIP     = T.chip
  BORDER   = T.border
  BORDER2  = T.border2
  ACCENT   = T.accent
  ACCENT_D = T.soft
  C_KICKER = T.kicker
  C_NOTE_EN = T.noteEn
  C_NOTE_AR = T.noteAr
  OKG      = Color3.fromRGB(46, 208, 128)
  TXT      = Color3.fromRGB(245, 243, 246)
  MUTED    = Color3.fromRGB(152, 142, 148)
  KNOB_OFF = Color3.fromRGB(96, 90, 96)
end

local function readConfig()
  local t = {}
  if type(isfile) ~= "function" or type(readfile) ~= "function" then return t end
  local ok, data = pcall(function()
    if isfile(CONFIG_FILE) then return readfile(CONFIG_FILE) end
    return nil
  end)
  if not ok or type(data) ~= "string" then return t end
  for k, v in string.gmatch(data, "([%w_]+)=([^\n]*)") do
    t[k] = v
  end
  return t
end

local function writeConfig()
  if type(writefile) ~= "function" then return false end
  local body = "bg=" .. tostring(curBg)
    .. "\ntheme=" .. tostring(curTheme)
    .. "\nlock=" .. (locked and "1" or "0")
    .. "\nscale=" .. tostring(curScale)
    .. "\nij=" .. (infJump and "1" or "0")
    .. "\ndrop=" .. (antiDrop and "1" or "0")
    .. "\nauto=" .. (autoBrainrot and "1" or "0")
    .. "\nkeybind=" .. tostring(boundKeyName) .. "\n"
  return pcall(writefile, CONFIG_FILE, body)
end

local saved = readConfig()
curBg = tonumber(saved.bg) or DEFAULT_BG
if curBg < 0 or curBg > #BACKGROUNDS then curBg = DEFAULT_BG end
curTheme = tonumber(saved.theme) or DEFAULT_THEME
if curTheme < 1 or curTheme > #THEMES then curTheme = DEFAULT_THEME end
locked = (saved.lock == "1")
if saved.ij ~= nil then infJump = (saved.ij == "1") end
if saved.drop ~= nil then antiDrop = (saved.drop == "1") end
if saved.auto ~= nil then autoBrainrot = (saved.auto == "1") end
do
  local sv = tonumber(saved.scale)
  if sv then
    local best, bestD = 4, math.huge
    for i, step in ipairs(SCALE_STEPS) do
      local d = math.abs(step - sv)
      if d < bestD then best, bestD = i, d end
    end
    curScaleIdx = best
    curScale = SCALE_STEPS[curScaleIdx]
  end
end
boundKey = nil
if type(saved.keybind) == "string" and saved.keybind ~= "" then
  if saved.keybind == "MB3" then
    boundKey = "MB3"
  else
    pcall(function() boundKey = Enum.KeyCode[saved.keybind] end)
  end
end
if boundKey == nil then boundKey = DEFAULT_KEYBIND end
boundKeyName = tostring(boundKey):gsub("Enum.KeyCode.", "")
loadThemeColors()

_G.FRHUBAntiBatV67Bg = curBg
_G.FRHUBAntiBatV67Keybind = boundKey
_G.FRHUBAntiBatV67Theme = curTheme
_G.FRHUBAntiBatV67Locked = locked
_G.FRHUBAntiBatV67Scale = curScale
_G.FRHUBAntiBatV67InfJump = infJump
_G.FRHUBAntiBatV67AutoBrainrot = autoBrainrot
_G.FRHUBAntiBatV67AntiDrop = antiDrop

local BAR_H = 34
local FULL_W, FULL_H = 224, 258
local PANEL_W, PANEL_H = 224, 124
local TILE_W, TILE_H = 46, 32
local SWATCH_W, SWATCH_H = 46, 32

local REG = {}
local applyTheme
local paintState, paintLock
local function reg(obj, field, prop)
  if obj then table.insert(REG, { obj = obj, field = field, prop = prop or "BackgroundColor3" }) end
  return obj
end

local function corner(obj, r)
  local c = Instance.new("UICorner")
  c.CornerRadius = (r == "circle") and UDim.new(1, 0) or UDim.new(0, r or 8)
  c.Parent = obj
  return c
end

local function stroke(obj, color, transparency, thickness)
  local s = Instance.new("UIStroke")
  s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  s.Color = color or BORDER
  s.Transparency = transparency or 0.25
  s.Thickness = thickness or 1
  s.Parent = obj
  return s
end

local function label(parent, text, size, pos, textSize, font, align, color)
  local l = Instance.new("TextLabel")
  l.BackgroundTransparency = 1
  l.BorderSizePixel = 0
  l.Text = text
  l.TextSize = textSize or 10
  l.Font = font or FONT_B
  l.TextColor3 = color or TXT
  l.TextXAlignment = align or Enum.TextXAlignment.Left
  l.TextYAlignment = Enum.TextYAlignment.Center
  l.TextWrapped = true
  l.Size = size
  l.Position = pos
  l.ZIndex = 5
  l.Parent = parent
  return l
end

local function iconButton(parent, text, xOffset, textSize)
  local b = Instance.new("TextButton")
  b.Text = text
  b.Font = FONT_X
  b.TextSize = textSize or 11
  b.TextColor3 = TXT
  b.BackgroundColor3 = HEADER_C
  b.BackgroundTransparency = 0.12
  b.BorderSizePixel = 0
  b.AutoButtonColor = false
  b.Size = UDim2.new(0, 20, 0, 20)
  b.Position = UDim2.new(1, xOffset, 0.5, -10)
  b.ZIndex = 8
  b.Parent = parent
  corner(b, "circle")
  stroke(b, BORDER, 0.4, 1)
  b.MouseEnter:Connect(function()
    TweenService:Create(b, TweenInfo.new(0.12), { BackgroundTransparency = 0, BackgroundColor3 = CARD_HI }):Play()
  end)
  b.MouseLeave:Connect(function()
    TweenService:Create(b, TweenInfo.new(0.12), { BackgroundTransparency = 0.12, BackgroundColor3 = HEADER_C }):Play()
  end)
  reg(b, "header", "BackgroundColor3")
  return b
end

local function card(parent, size, pos, radius, name)
  local f = Instance.new("Frame")
  f.Name = name or "Card"
  f.BackgroundColor3 = CARD
  f.BackgroundTransparency = 0.4
  f.BorderSizePixel = 0
  f.Size = size
  f.Position = pos
  f.ZIndex = 4
  f.Parent = parent
  corner(f, radius or 8)
  reg(f, "card", "BackgroundColor3")
  return f
end

local function chipButton(parent, text, size, pos, textSize, fontSize)
  local b = Instance.new("TextButton")
  b.Text = text
  b.Font = FONT_X
  b.TextSize = textSize or 9
  b.TextColor3 = TXT
  b.BackgroundColor3 = CHIP
  b.BackgroundTransparency = 0.08
  b.BorderSizePixel = 0
