local function gearIcon(parent, size, color)
  local holder = Instance.new("Frame")
  holder.Name = "GearIcon"
  holder.BackgroundTransparency = 1
  holder.BorderSizePixel = 0
  holder.Size = UDim2.new(0, size, 0, size)
  holder.Position = UDim2.new(0.5, -size / 2, 0.5, -size / 2)
  holder.ZIndex = 7
  holder.Parent = parent
  local ring = Instance.new("Frame")
  ring.Name = "Ring"
  ring.BackgroundTransparency = 1
  ring.BorderSizePixel = 0
  ring.Size = UDim2.new(1, 0, 1, 0)
  ring.ZIndex = 7
  ring.Parent = holder
  corner(ring, "circle")
  local rs = stroke(ring, color, 0, 2)
  local t = size / 5
  for i = 1, 4 do
    local tooth = Instance.new("Frame")
    tooth.Name = "Tooth" .. tostring(i)
    tooth.BackgroundColor3 = color
    tooth.BorderSizePixel = 0
    tooth.Size = UDim2.new(0, t, 0, t)
    tooth.ZIndex = 8
    tooth.Parent = holder
    if i == 1 then
      tooth.Position = UDim2.new(0.5, -t / 2, 0, -t / 2)
    elseif i == 2 then
      tooth.Position = UDim2.new(0.5, -t / 2, 1, -t / 2)
    elseif i == 3 then
      tooth.Position = UDim2.new(0, -t / 2, 0.5, -t / 2)
    else
      tooth.Position = UDim2.new(1, -t / 2, 0.5, -t / 2)
    end
  end
  return holder, rs
end

local function wipeOld()
  local function killIn(container)
    if not container then return end
    for _, name in ipairs({"FRHUB_ANTIBAT_V67", "FRHUB_ANTIBAT_V67_BG"}) do
      local old
      local ok = pcall(function() old = container:FindFirstChild(name) end)
      if ok and old then pcall(function() old:Destroy() end) end
    end
  end
  killIn(hiddenParent())
  local ok2, pg = pcall(function() return LP:FindFirstChild("PlayerGui") end)
  if ok2 then killIn(pg) end
end
wipeOld()

