local function buildToggleRow(name, y, text)
  local row = Instance.new("TextButton")
  row.Name = name
  row.Text = ""
  row.AutoButtonColor = false
  row.BackgroundColor3 = CARD
  row.BackgroundTransparency = 0.4
  row.BorderSizePixel = 0
  row.Size = UDim2.new(1, -20, 0, 26)
  row.Position = UDim2.new(0, 10, 0, y)
  row.ZIndex = 4
  row.Parent = Body
  corner(row, 8)
  stroke(row, BORDER, 0.35, 1)
  reg(row, "card", "BackgroundColor3")
  local lbl = label(row, text, UDim2.new(0, 96, 0, 18), UDim2.new(0, 10, 0, 2), 9.5, FONT_X, Enum.TextXAlignment.Left, TXT)
  lbl.ZIndex = 6
  local st = label(row, "OFF", UDim2.new(0, 52, 0, 18), UDim2.new(1, -104, 0, 2), 9, FONT_X, Enum.TextXAlignment.Right, MUTED)
  st.ZIndex = 6
  local pill = Instance.new("Frame")
  pill.Name = name .. "Pill"
  pill.Size = UDim2.new(0, 34, 0, 18)
  pill.Position = UDim2.new(1, -44, 0, 3)
  pill.BackgroundColor3 = CHIP
  pill.BackgroundTransparency = 0.1
  pill.BorderSizePixel = 0
  pill.ZIndex = 7
  pill.Parent = row
  corner(pill, 9)
  local pstroke = stroke(pill, BORDER2, 0.3, 1)
  local knob = Instance.new("Frame")
  knob.Name = name .. "Knob"
  knob.Size = UDim2.new(0, 12, 0, 12)
  knob.Position = UDim2.new(0, 3, 0.5, -6)
  knob.BackgroundColor3 = KNOB_OFF
  knob.BorderSizePixel = 0
  knob.ZIndex = 8
  knob.Parent = pill
  corner(knob, "circle")
  reg(pill, "chip", "BackgroundColor3")
  return { row = row, label = lbl, state = st, pill = pill, stroke = pstroke, knob = knob }
end

function paintToggleRow(r, on, onText)
  if not r then return end
  if on then
    TweenService:Create(r.pill, TweenInfo.new(0.18), { BackgroundColor3 = OKG, BackgroundTransparency = 0.05 }):Play()
    TweenService:Create(r.stroke, TweenInfo.new(0.18), { Color = OKG, Transparency = 0.1 }):Play()
    TweenService:Create(r.knob, TweenInfo.new(0.18, Enum.EasingStyle.Back), {
      Position = UDim2.new(1, -15, 0.5, -6), BackgroundColor3 = Color3.fromRGB(250, 250, 252) }):Play()
    r.state.Text = onText or "ON"
    r.state.TextColor3 = OKG
  else
    TweenService:Create(r.pill, TweenInfo.new(0.18), { BackgroundColor3 = CHIP, BackgroundTransparency = 0.1 }):Play()
    TweenService:Create(r.stroke, TweenInfo.new(0.18), { Color = BORDER2, Transparency = 0.3 }):Play()
    TweenService:Create(r.knob, TweenInfo.new(0.18, Enum.EasingStyle.Quad), {
      Position = UDim2.new(0, 3, 0.5, -6), BackgroundColor3 = KNOB_OFF }):Play()
    r.state.Text = "OFF"
    r.state.TextColor3 = MUTED
  end
  return r
end

