local function keyName(key)
  if key == nil then return "NONE" end
  if key == "MB3" then return "MB3" end
  local name = tostring(key):gsub("Enum.KeyCode.", "")
  name = name:gsub("Button", "BTN ")
  name = name:gsub("DPad", "DPad ")
  return name
end

