local function applyBackground(index)
  index = tonumber(index) or 0
  if index < 0 or index > #BACKGROUNDS then index = DEFAULT_BG end
  curBg = index
  _G.FRHUBAntiBatV67Bg = curBg
  local entry = BACKGROUNDS[curBg]
  if entry then
    BgImage.Image = "rbxassetid://" .. entry.id
    BgImage.Visible = true
    Tint.BackgroundTransparency = 0.7
  else
    BgImage.Image = ""
    BgImage.Visible = false
    Tint.BackgroundTransparency = 1
  end
  writeConfig()
  if _G.FRHUBAntiBatV67RefreshBgTiles then pcall(_G.FRHUBAntiBatV67RefreshBgTiles) end
  if _G.FRHUBAntiBatV67RefreshFooter then pcall(_G.FRHUBAntiBatV67RefreshFooter) end
  return curBg
end

