local TileStrokes = {}
local tileFrames = {}
local function refreshTiles(list, selected, key)
  for index, strokeObj in pairs(list) do
    if strokeObj and strokeObj.Parent then
      local on = (index == selected)
      strokeObj.Color = on and ACCENT or BORDER
      strokeObj.Transparency = on and 0 or 0.45
      local host = strokeObj.Parent
      local lbl = host and host:FindFirstChild("TileNum")
      if lbl then lbl.TextColor3 = on and ACCENT or MUTED end
    end
  end
end

_G.FRHUBAntiBatV67RefreshBgTiles = function()
  refreshTiles(TileStrokes, curBg, "bg")
end

local function tileText(host, text, center)
  local lbl = Instance.new("TextLabel")
  lbl.Name = "TileNum"
  lbl.BackgroundTransparency = 1
  lbl.BorderSizePixel = 0
  lbl.Text = text
  lbl.Font = FONT_X
  lbl.TextSize = 9
  lbl.TextColor3 = MUTED
  lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
  lbl.TextStrokeTransparency = 0.25
  lbl.TextXAlignment = center and Enum.TextXAlignment.Center or Enum.TextXAlignment.Left
  lbl.Position = center and UDim2.new(0, 0, 0, 0) or UDim2.new(0, 4, 1, -13)
  lbl.Size = UDim2.new(1, -8, 0, 12)
  lbl.ZIndex = 7
  lbl.Parent = host
  return lbl
end

local function makeBgTile(index, order)
  local isNone = (index == 0)
  local entry = isNone and nil or BACKGROUNDS[index]
  local tile = Instance.new("ImageButton")
  tile.Name = "BgTile" .. tostring(index)
  tile.LayoutOrder = order
  tile.BackgroundColor3 = CHIP
  tile.BackgroundTransparency = isNone and 0.05 or 0
  tile.BorderSizePixel = 0
  tile.AutoButtonColor = false
  tile.ScaleType = Enum.ScaleType.Crop
  tile.Size = UDim2.new(0, TILE_W, 0, TILE_H)
  tile.ZIndex = 6
  tile.Parent = Grid
  corner(tile, 7)
  if entry then
    tile.Image = "rbxassetid://" .. entry.id
  end
  local strokeObj = stroke(tile, BORDER, 0.45, 2)
  TileStrokes[index] = strokeObj
  reg(tile, "chip", "BackgroundColor3")
  tileText(tile, isNone and "NONE" or tostring(index), isNone)
  tile.MouseEnter:Connect(function()
    TweenService:Create(strokeObj, TweenInfo.new(0.12), { Color = ACCENT_D, Transparency = 0.1 }):Play()
  end)
  tile.MouseLeave:Connect(function()
    _G.FRHUBAntiBatV67RefreshBgTiles()
  end)
  tile.Activated:Connect(function()
    applyBackground(index)
