function applyTheme(index)
  index = tonumber(index) or DEFAULT_THEME
  if index < 1 or index > #THEMES then index = DEFAULT_THEME end
  curTheme = index
  _G.FRHUBAntiBatV67Theme = curTheme
  loadThemeColors()
  for _, e in ipairs(REG) do
    local c = THEMES[curTheme] and THEMES[curTheme][e.field]
    if c and e.obj and e.obj.Parent then
      pcall(function() e.obj[e.prop] = c end)
    end
  end
  SetFooter.Text = "SELECTED " .. tostring(curTheme) .. "  ·  " .. THEMES[curTheme].name
  SetGearStroke.Color = ACCENT
  refreshTiles(SwatchStrokes, curTheme, "theme")
  refreshKeyBtn()
  paintState(_G.FRHUBAntiBatV67Enabled == true)
  paintLock(locked)
  _G.FRHUBAntiBatV67RefreshBgTiles()
  refreshFooter()
  writeConfig()
  return curTheme
end

local function anchorPanels()
  local p = Main.Position
  local y = p.Y.Offset + (Main.Size.Y.Offset * curScale) + 6
  Panel.Position = UDim2.new(p.X.Scale, p.X.Offset, p.Y.Scale, y)
  SettingsPanel.Position = UDim2.new(p.X.Scale, p.X.Offset, p.Y.Scale, y)
end

function applyScale(idx)
  idx = math.clamp(tonumber(idx) or curScaleIdx, 1, #SCALE_STEPS)
  curScaleIdx = idx
  curScale = SCALE_STEPS[idx]
  _G.FRHUBAntiBatV67Scale = curScale
  for _, sc in ipairs({MainScale, PanelScale, SetScale}) do
    if sc and sc.Parent then
      pcall(function() sc.Scale = curScale end)
    end
  end
  anchorPanels()
  writeConfig()
  return curScale
end

local function scaleStep(direction)
  return applyScale(curScaleIdx + (direction or 0))
end

