local INF_BOOST = 50
local INF_HOLD_DELAY = 0.12
local BRAINROT_ANIM = "71186871415348"
local brainrotLast = false
local manualHold = false

local IJ = {
  holdPressed = false, holdActive = false, controllerActive = false,
  mobilePressed = false, mobileActive = false,
  mobileInput = nil, mobileBtn = nil, mobileSince = 0, hooked = {},
}

local function touchOn(btn, pos, shrink)
  if not btn or not pos then return false end
  local ok, ap, as = pcall(function() return btn.AbsolutePosition, btn.AbsoluteSize end)
  if not ok or not ap or not as then return false end
  local cx, cy = ap.X + as.X * 0.5, ap.Y + as.Y * 0.5
  local r = math.min(as.X, as.Y) * (shrink or 0.42)
  if r <= 0 then return false end
  local dx, dy = pos.X - cx, pos.Y - cy
  return (dx * dx + dy * dy) <= (r * r)
end

function infJumpStopHold()
  IJ.holdPressed = false
  IJ.holdActive = false
  IJ.controllerActive = false
  IJ.mobilePressed = false
  IJ.mobileActive = false
  IJ.mobileInput = nil
  IJ.mobileBtn = nil
end

function setInfJump(on)
  infJump = on and true or false
  _G.FRHUBAntiBatV67InfJump = infJump
  if not infJump then
    infJumpStopHold()
    local char = LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if hrp then pcall(function() hrp.Velocity = Vector3.zero end) end
  end
  paintToggleRow(InfRow, infJump)
  writeConfig()
  return infJump
end

local ANTI_DROP_FAKE = 16
local SPOOF_NAMES = { HumanoidRootPart = true }
local spoofedVelocity = Vector3.zero
local spoofInstalled = false

function isSpoofTarget(self)
  if typeof(self) ~= "Instance" then return false end
  if not self:IsA("BasePart") then return false end
  if not SPOOF_NAMES[self.Name] then return false end
  local char = LP.Character
  return char ~= nil and self:IsDescendantOf(char)
end

function installVelocitySpoof()
  if spoofInstalled then return true end
  if not antiDrop then return false end
  if not (getrawmetatable and setreadonly and newcclosure and checkcaller) then return false end
  local ok = pcall(function()
    local mt = getrawmetatable(game)
    setreadonly(mt, false)
    local oldIndex = mt.__index
    mt.__index = newcclosure(function(self, key)
      if antiDrop and not checkcaller() and (key == "AssemblyLinearVelocity" or key == "Velocity") then
        if isSpoofTarget(self) then return spoofedVelocity end
      end
      return oldIndex(self, key)
    end)
    local oldNewIndex = mt.__newindex
    mt.__newindex = newcclosure(function(self, key, value)
      if antiDrop and not checkcaller() and (key == "AssemblyLinearVelocity" or key == "Velocity") then
        if isSpoofTarget(self) then
          spoofedVelocity = value
          return
        end
      end
      return oldNewIndex(self, key, value)
    end)
    setreadonly(mt, true)
  end)
  spoofInstalled = ok and true or false
  return spoofInstalled
end

function updateFakeVelocity()
  if not antiDrop then return end
  local char = LP.Character
  local hum = char and char:FindFirstChildOfClass("Humanoid")
  local root = char and char:FindFirstChild("HumanoidRootPart")
  if not char or not hum or not root or hum.Health <= 0 then return end
  local dir = hum.MoveDirection
  if dir.Magnitude > 0.05 then
    pcall(function() if root.SetNetworkOwner then root:SetNetworkOwner(LP) end end)
    local unit = dir.Unit
    spoofedVelocity = Vector3.new(unit.X * ANTI_DROP_FAKE, root.Velocity.Y, unit.Z * ANTI_DROP_FAKE)
  else
    spoofedVelocity = Vector3.new(0, root.Velocity.Y, 0)
  end
  return spoofedVelocity
end

function setAntiDrop(on)
  antiDrop = on and true or false
  _G.FRHUBAntiBatV67AntiDrop = antiDrop
  if antiDrop then installVelocitySpoof() end
  paintToggleRow(DropRow, antiDrop)
  writeConfig()
  return antiDrop
end

function setAutoBrainrot(on)
  autoBrainrot = on and true or false
  _G.FRHUBAntiBatV67AutoBrainrot = autoBrainrot
  if autoBrainrot then
    paintToggleRow(AutoRow, true, "IDLE")
  else
    brainrotLast = false
    manualHold = false
    paintToggleRow(AutoRow, false)
  end
  writeConfig()
  return autoBrainrot
end

function infJumpInputActive()
  local ok, down = pcall(function() return UserInputService:IsKeyDown(Enum.KeyCode.Space) end)
  if ok and down then return true end
  ok, down = pcall(function() return UserInputService:IsGamepadButtonDown(Enum.UserInputType.Gamepad1, Enum.KeyCode.ButtonA) end)
  if ok and down then return true end
  if IJ.holdActive or IJ.controllerActive then return true end
  local btn, inp = IJ.mobileBtn, IJ.mobileInput
  if btn and inp and IJ.mobilePressed then
    local st = inp.UserInputState
    if st == Enum.UserInputState.Begin or st == Enum.UserInputState.Change then
      if touchOn(btn, inp.Position, 0.42) then return true end
    end
  end
  return false
end

function infJumpBoost(boost)
  if not infJump then return end
  if _G._FRHUBTPDownJumpLocked then return end
  if not infJumpInputActive() then return end
  local char = LP.Character
  if not char then return end
  local hum = char:FindFirstChildOfClass("Humanoid")
  if not hum or hum.Health <= 0 then return end
  local hrp = char:FindFirstChild("HumanoidRootPart")
  if not hrp then return end
  local v = hrp.Velocity
  hrp.Velocity = Vector3.new(v.X, boost or INF_BOOST, v.Z)
  return hrp
end

UserInputService.JumpRequest:Connect(function()
  if not infJump then return end
  infJumpBoost(INF_BOOST)
end)

UserInputService.InputBegan:Connect(function(input, _processed)
  if UserInputService:GetFocusedTextBox() then return end
  if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Space then
    IJ.holdPressed = true
    task.delay(INF_HOLD_DELAY, function()
      if IJ.holdPressed and infJump then
        IJ.holdActive = true
        infJumpBoost(INF_BOOST)
      end
    end)
  elseif input.KeyCode == Enum.KeyCode.ButtonA and input.UserInputType
     and string.match(tostring(input.UserInputType.Name), "^Gamepad") then
    IJ.controllerActive = true
  end
end)

UserInputService.InputEnded:Connect(function(input)
  if input.UserInputType == Enum.UserInputType.Keyboard and input.KeyCode == Enum.KeyCode.Space then
    IJ.holdPressed = false
    IJ.holdActive = false
  end
  if input.KeyCode == Enum.KeyCode.ButtonA and input.UserInputType
     and string.match(tostring(input.UserInputType.Name), "^Gamepad") then
    IJ.controllerActive = false
  end
end)

function infJumpHookJumpButton(obj)
  if not obj or obj.Name ~= "JumpButton" or not obj:IsA("GuiButton") or IJ.hooked[obj] then return end
  IJ.hooked[obj] = true
  obj.InputBegan:Connect(function(input)
    if input.UserInputType ~= Enum.UserInputType.Touch or not infJump then return end
    if not touchOn(obj, input.Position, 0.42) then return end
    IJ.mobilePressed = true
    IJ.mobileInput = input
    IJ.mobileBtn = obj
    IJ.mobileSince = os.clock()
    local mc
    mc = input.Changed:Connect(function()
      local st = input.UserInputState
      if st == Enum.UserInputState.End or st == Enum.UserInputState.Cancel then
        IJ.mobilePressed = false
        IJ.mobileActive = false
        IJ.mobileInput = nil
        if mc then pcall(function() mc:Disconnect() end) mc = nil end
      end
    end)
    task.delay(INF_HOLD_DELAY, function()
      if IJ.mobilePressed and IJ.mobileInput == input and infJump then
        IJ.mobileActive = true
        infJumpBoost(INF_BOOST)
      end
    end)
  end)
  obj.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.Touch then
      IJ.mobilePressed = false
      IJ.mobileActive = false
    end
  end)
  obj.AncestryChanged:Connect(function(_, parent)
    if not parent then
      IJ.hooked[obj] = nil
      IJ.mobilePressed = false
      IJ.mobileActive = false
    end
  end)
end

task.defer(function()
  local pg = LP:FindFirstChild("PlayerGui")
  if not pg then return end
  for _, obj in ipairs(pg:GetDescendants()) do pcall(infJumpHookJumpButton, obj) end
  pg.DescendantAdded:Connect(function(obj)
    task.defer(infJumpHookJumpButton, obj)
  end)
end)

local SpoofSignal = RunService.PreSimulation or RunService.Stepped
if SpoofSignal and SpoofSignal.Connect then
  SpoofSignal:Connect(function() pcall(updateFakeVelocity) end)
end

RunService.Heartbeat:Connect(function()
  if IJ.mobileActive or IJ.mobilePressed then
    local mi = IJ.mobileInput
    local live = mi and (mi.UserInputState == Enum.UserInputState.Begin or mi.UserInputState == Enum.UserInputState.Change)
    if live then live = touchOn(IJ.mobileBtn, mi.Position, 0.42) end
    if (not live) or (os.clock() - (IJ.mobileSince or 0)) > 30 or (not infJump) then
      IJ.mobilePressed = false
      IJ.mobileActive = false
      IJ.mobileInput = nil
      IJ.mobileBtn = nil
    end
  end
  if infJump and (IJ.holdActive or IJ.mobileActive or IJ.controllerActive) then
    infJumpBoost(INF_BOOST)
  end
end)

local BRAINROT_SPEED = 25
local speedPeak = 0

local function brainrotDetected()
  local char = LP.Character
  if not char then return false end
  local hum = char:FindFirstChildOfClass("Humanoid")
  if not hum then return false end
  local ws = tonumber(hum.WalkSpeed) or 16
  if ws > speedPeak then speedPeak = ws end
  if ws < BRAINROT_SPEED and speedPeak >= BRAINROT_SPEED and ws <= speedPeak * 0.85 then
    return true
  end
  local animator = hum:FindFirstChildOfClass("Animator")
  if animator then
    local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
    if ok and tracks then
      for _, track in ipairs(tracks) do
        local anim = track.Animation
        local id = anim and anim.AnimationId
        if type(id) == "string" and string.find(id, BRAINROT_ANIM, 1, true) then return true end
      end
    end
  end
  return false
end

function stepAutoBrainrot()
  if not autoBrainrot then
    if brainrotLast then
      brainrotLast = false
      paintToggleRow(AutoRow, false)
    end
    return false
  end
  local has = brainrotDetected()
  if has then
    if not brainrotLast then
      brainrotLast = true
      manualHold = false
      AutoRow.state.Text = "BRAINROT"
      AutoRow.state.TextColor3 = ACCENT
      if not _G.FRHUBAntiBatV67Enabled then pcall(applyEnabled, true) end
    end
    return true
  elseif brainrotLast then
    brainrotLast = false
    AutoRow.state.Text = "IDLE"
    AutoRow.state.TextColor3 = MUTED
    if not manualHold and _G.FRHUBAntiBatV67Enabled then pcall(applyEnabled, false) end
    manualHold = false
  end
  return false
end

LP.CharacterAdded:Connect(function()
  speedPeak = 0
end)

RunService.Heartbeat:Connect(function() pcall(stepAutoBrainrot) end)

paintToggleRow(InfRow, infJump)
paintToggleRow(AutoRow, autoBrainrot, "IDLE")
paintToggleRow(DropRow, antiDrop)
if antiDrop then pcall(installVelocitySpoof) end

local minimized = false
local animToken = 0

local function setMinimized(min)
  min = min and true or false
  if min == minimized then return minimized end
  minimized = min
  animToken = animToken + 1
  local my = animToken
  if min then
    MinBtn.Text = "+"
    HeaderPatch.Visible = false
    HeaderLine.Visible = false
    setBgOpen(false)
    setSetOpen(false)
    TweenService:Create(Main, TweenInfo.new(0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
      { Size = UDim2.new(0, FULL_W, 0, BAR_H) }):Play()
    task.delay(0.2, function()
      if my == animToken and minimized then Body.Visible = false end
    end)
  else
    Body.Visible = true
    MinBtn.Text = "-"
    HeaderPatch.Visible = true
    HeaderLine.Visible = true
    TweenService:Create(Main, TweenInfo.new(0.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
      { Size = UDim2.new(0, FULL_W, 0, FULL_H) }):Play()
  end
  task.delay(0.22, function()
    if my == animToken then anchorPanels() end
  end)
  return minimized
end

local function closeGui()
  applyEnabled(false)
  _G.FRHUBAntiBatV67Open = false
  setBgOpen(false)
  setSetOpen(false)
  pcall(function() Panel:Destroy() end)
  pcall(function() SettingsPanel:Destroy() end)
  pcall(function() Gui:Destroy() end)
end

local function startListening()
  listening = true
  listenToken = listenToken + 1
  local my = listenToken
  refreshKeyBtn()
  task.spawn(function()
    local started = os.clock()
    while listening and listenToken == my and (os.clock() - started) < 6 do
      task.wait(0.2)
    end
    if listening and listenToken == my then
      listening = false
      refreshKeyBtn()
    end
  end)
end

local function stopListening()
  listening = false
  listenToken = listenToken + 1
  refreshKeyBtn()
end

local function setKeybind(key, name)
  boundKey = key
  boundKeyName = name or tostring(key):gsub("Enum.KeyCode.", "")
  _G.FRHUBAntiBatV67Keybind = key
  writeConfig()
  refreshKeyBtn()
end

MinBtn.Activated:Connect(function()
