UserInputService.InputBegan:Connect(function(input, gameProcessed)
  if _G._FRHUBAntiBatV67Token ~= MyToken then return end
  local pad = false
  pcall(function() pad = (input.UserInputType.Name:match("^Gamepad") ~= nil) end)
  if listening then
    if input.KeyCode == Enum.KeyCode.Escape and not pad then
      stopListening()
      return
    end
    local kb = (input.UserInputType == Enum.UserInputType.Keyboard)
    local mouse3 = (input.UserInputType == Enum.UserInputType.MouseButton3)
    if kb or pad or mouse3 then
      if input.KeyCode == nil or input.KeyCode == Enum.KeyCode.Unknown then
        if not mouse3 then return end
      end
      if mouse3 then
        setKeybind("MB3", "MB3")
      else
        setKeybind(input.KeyCode, tostring(input.KeyCode):gsub("Enum.KeyCode.", ""))
      end
      listening = false
      listenToken = listenToken + 1
      refreshKeyBtn()
    end
    return
  end
  if boundKey == nil then return end
  if gameProcessed then return end
  if UserInputService:GetFocusedTextBox() then return end
  if boundKey == "MB3" then
    if input.UserInputType == Enum.UserInputType.MouseButton3 then
      applyEnabled(not _G.FRHUBAntiBatV67Enabled)
    end
    return
  end
  local kb = (input.UserInputType == Enum.UserInputType.Keyboard)
  if not (kb or pad) then return end
  if input.KeyCode == boundKey then
    applyEnabled(not _G.FRHUBAntiBatV67Enabled)
  end
end)

