function FRHUB.AntiVoid.SaveSafe()
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if not hum or not root or hum.Health <= 0 then return end
    if hum.FloorMaterial ~= Enum.Material.Air then
        FRHUB.AntiVoid.SafeCFrame = root.CFrame
    end
end

function FRHUB.AntiVoid.Stop()
    if FRHUB.AntiVoid.Connection then
        pcall(function() FRHUB.AntiVoid.Connection:Disconnect() end)
        FRHUB.AntiVoid.Connection = nil
    end
end

function FRHUB.AntiVoid.Set(on)
    FRHUB.AntiVoid.Enabled = on == true
    FRHUB.AntiVoid.Stop()
    if not FRHUB.AntiVoid.Enabled then return end

    FRHUB.AntiVoid.SaveSafe()

    FRHUB.AntiVoid.Connection = RunService.Heartbeat:Connect(function()
        local char = LP.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not FRHUB.AntiVoid.Enabled or not hum or not root or hum.Health <= 0 then return end

        local voidY = Workspace.FallenPartsDestroyHeight + 30

        if hum.FloorMaterial ~= Enum.Material.Air and root.Position.Y > voidY + 12 then
            FRHUB.AntiVoid.SaveSafe()
        elseif root.Position.Y <= voidY and FRHUB.AntiVoid.SafeCFrame then
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            root.CFrame = FRHUB.AntiVoid.SafeCFrame + Vector3.new(0, 4, 0)
            hum.PlatformStand = false
            hum.Sit = false
            pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
        end
    end)
end
