    end
    connections = {}
end


local function updateGodMode()
    cleanupConnections()

    if not isGodModeEnabled then
        if currentHumanoid then
            currentHumanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
        end
        return
    end

    local char = player.Character
    if char then
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            currentHumanoid = hum
            applyGodMode(hum)
        end
    end
end


player.CharacterAdded:Connect(function(newChar)
    cleanupConnections()
    currentHumanoid = nil

    local hum = newChar:WaitForChild("Humanoid", 5)
    if hum then
        currentHumanoid = hum
        if isGodModeEnabled then
            applyGodMode(hum)
        end
    end
end)


RunService.Heartbeat:Connect(function()
    if isGodModeEnabled and currentHumanoid and currentHumanoid.Parent then
        if currentHumanoid.Health < currentHumanoid.MaxHealth then
            currentHumanoid.Health = currentHumanoid.MaxHealth
        end
    end
end)


if player.Character then
    local hum = player.Character:FindFirstChildOfClass("Humanoid")
    if hum then
        currentHumanoid = hum
        applyGodMode(hum)
    end
end
end)
